{"command": "$content = @'
#Requires -Version 5.1
<#
.SYNOPSIS
    Audit the workspace against the output storage policy.

.DESCRIPTION
    Checks the machine-readable policy, the category folders, the conversation registry,
    the root folder allow list and folder naming compliance. Exit code 1 when at least one
    FAIL is reported, 0 otherwise (warnings alone do not fail).

.PARAMETER Root
    Workspace root. Defaults to the parent folder of this script.

.PARAMETER Json
    Emit findings as JSON.

.EXAMPLE
    powershell.exe -NoProfile -ExecutionPolicy Bypass -File E:\Deepseek\tools\Test-StoragePolicy.ps1
#>
[CmdletBinding()]
param(
    [string]$Root,
    [switch]$Json
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function Read-Utf8Json {
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path)) { return $null }
    $text = [System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8)
    if ([string]::IsNullOrWhiteSpace($text)) { return $null }
    return ($text | ConvertFrom-Json)
}

function Get-PropertyValue {
    param($Object, [string]$Name, $Default = $null)
    if ($null -eq $Object) { return $Default }
    $prop = $Object.PSObject.Properties[$Name]
    if ($null -eq $prop) { return $Default }
    if ($null -eq $prop.Value) { return $Default }
    return $prop.Value
}

function Test-AsciiName {
    param([string]$Name)
    foreach ($ch in $Name.ToCharArray()) {
        $code = [int][char]$ch
        if ($code -lt 32 -or $code -gt 126) { return $false }
    }
    return $true
}

if ([string]::IsNullOrWhiteSpace($Root)) { $Root = Split-Path -Parent $PSScriptRoot }
if (-not (Test-Path -LiteralPath $Root)) { throw "Workspace root not found: $Root" }
$Root = (Resolve-Path -LiteralPath $Root).Path

$findings = New-Object System.Collections.ArrayList
$failCount = 0
$warnCount = 0

function Add-Finding {
    param([string]$Level, [string]$Message)
    [void]$findings.Add([pscustomobject]@{ level = $Level; message = $Message })
    if ($Level -eq 'FAIL') { $script:failCount++ }
    if ($Level -eq 'WARN') { $script:warnCount++ }
}

# ---- 1. policy file
$policyPath = Join-Path $Root 'policy\storage-policy.json'
$policy = $null
if (-not (Test-Path -LiteralPath $policyPath)) {
    Add-Finding 'FAIL' ("policy file missing: " + $policyPath)
} else {
    try {
        $policy = Read-Utf8Json -Path $policyPath
        Add-Finding 'PASS' ("policy file parses: policy\storage-policy.json (version " + (Get-PropertyValue -Object $policy -Name 'policyVersion') + ")")
    } catch {
        Add-Finding 'FAIL' ("policy file is not valid JSON: " + $_.Exception.Message)
    }
}

# ---- 2. categories
$categories = New-Object System.Collections.ArrayList
$policyCategories = Get-PropertyValue -Object $policy -Name 'categories'
if ($policyCategories) {
    foreach ($c in @($policyCategories)) {
        $folder = Get-PropertyValue -Object $c -Name 'folder'
        if (-not $folder) { $folder = Get-PropertyValue -Object $c -Name 'key' }
        if ($folder) { [void]$categories.Add([string]$folder) }
    }
}
if ($categories.Count -eq 0) {
    foreach ($d in @('deliverables', 'logs', 'scripts', 'workspace', 'data', 'archive')) { [void]$categories.Add($d) }
}
foreach ($category in $categories) {
    $dir = Join-Path $Root $category
    if (Test-Path -LiteralPath $dir) {
        Add-Finding 'PASS' ("category folder exists: " + $category)
    } else {
        Add-Finding 'FAIL' ("category folder missing: " + $category)
    }
    if (-not (Test-AsciiName -Name $category)) {
        Add-Finding 'FAIL' ("category folder name is not ASCII: " + $category)
    }
}

# ---- 3. root allow list
$allow = New-Object System.Collections.ArrayList
$allowList = Get-PropertyValue -Object $policy -Name 'rootAllowList'
if ($allowList) { foreach ($a in @($allowList)) { [void]$allow.Add([string]$a) } }
if ($allow.Count -eq 0) {
    foreach ($a in @('AGENTS.md', 'README.md', 'policy', 'tools')) { [void]$allow.Add($a) }
    foreach ($category in $categories) { if (-not $allow.Contains($category)) { [void]$allow.Add($category) } }
}
$stray = New-Object System.Collections.ArrayList
foreach ($item in Get-ChildItem -LiteralPath $Root -Force) {
    if (-not $allow.Contains($item.Name)) { [void]$stray.Add($item.Name) }
}
if ($stray.Count -eq 0) {
    Add-Finding 'PASS' 'workspace root contains only allow-listed entries'
} else {
    Add-Finding 'WARN' ("workspace root has entries outside the allow list: " + ($stray -join ', '))
}

# ---- 4. registry and conversation folders
$registryPath = Join-Path $Root 'policy\conversation-registry.json'
$registry = $null
if (-not (Test-Path -LiteralPath $registryPath)) {
    Add-Finding 'FAIL' 'conversation registry missing: policy\conversation-registry.json'
} else {
    try {
        $registry = Read-Utf8Json -Path $registryPath
        $conversations = @(Get-PropertyValue -Object $registry -Name 'conversations' -Default @())
        Add-Finding 'PASS' ("conversation registry parses; registered conversations: " + $conversations.Count)
        $regex = [string](Get-PropertyValue -Object $registry -Name 'regex' -Default '^conv-[0-9]{8}-([0-9a-f]{8}|[0-9]{6})(-[a-z0-9]{2,32})?$')
        foreach ($entry in $conversations) {
            $folder = [string](Get-PropertyValue -Object $entry -Name 'folder')
            if (-not $folder) {
                Add-Finding 'FAIL' 'registry entry without a folder name'
                continue
            }
            if ($folder -notmatch $regex) {
                Add-Finding 'FAIL' ("registry folder does not match the pattern: " + $folder)
            }
            $missing = New-Object System.Collections.ArrayList
            foreach ($category in $categories) {
                $dir = Join-Path (Join-Path $Root $category) $folder
                if (-not (Test-Path -LiteralPath $dir)) { [void]$missing.Add($category) }
            }
            if ($missing.Count -eq 0) {
                Add-Finding 'PASS' ("conversation folder present in every category: " + $folder)
            } else {
                Add-Finding 'WARN' ("conversation folder missing in: " + ($missing -join ', ') + " (" + $folder + ")")
            }
        }
    } catch {
        Add-Finding 'FAIL' ("conversation registry is not valid JSON: " + $_.Exception.Message)
    }
}

# ---- 5. naming compliance inside the category folders
$badNames = New-Object System.Collections.ArrayList
foreach ($category in $categories) {
    $dir = Join-Path $Root $category
    if (-not (Test-Path -LiteralPath $dir)) { continue }
    foreach ($child in Get-ChildItem -LiteralPath $dir -Force -Directory) {
        if (-not (Test-AsciiName -Name $child.Name)) { [void]$badNames.Add($category + '\' + $child.Name) }
    }
    foreach ($file in Get-ChildItem -LiteralPath $dir -Force -File -Recurse -ErrorAction SilentlyContinue) {
        if (-not (Test-AsciiName -Name $file.Name)) { [void]$badNames.Add($category + '\...\' + $file.Name) }
    }
}
if ($badNames.Count -eq 0) {
    Add-Finding 'PASS' 'no non-ASCII names found under the category folders'
} else {
    Add-Finding 'WARN' ("non-ASCII names found (compatibility risk): " + (($badNames | Select-Object -First 10) -join '; '))
}

# ---- report
if ($Json) {
    [pscustomobject]@{
        workspaceRoot = $Root
        failCount     = $failCount
        warnCount     = $warnCount
        findings      = @($findings)
    } | ConvertTo-Json -Depth 6
} else {
    Write-Output ("Storage policy audit - " + $Root)
    Write-Output ("Time: " + (Get-Date).ToString('yyyy-MM-dd HH:mm:ss'))
    Write-Output ''
    foreach ($f in $findings) { Write-Output ("[" + $f.level + "] " + $f.message) }
    Write-Output ''
    Write-Output ("Summary: FAIL=" + $failCount + " WARN=" + $warnCount)
}

if ($failCount -gt 0) { exit 1 }
exit 0
'@
$path = 'E:\Deepseek\tools\Test-StoragePolicy.ps1'
$dir = Split-Path -Parent $path
if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
[System.IO.File]::WriteAllText($path, $content, (New-Object System.Text.UTF8Encoding($false)))
Write-Output ("WROTE {0} : {1} bytes" -f $path, (Get-Item $path).Length)
$errors = $null
[System.Management.Automation.Language.Parser]::ParseFile($path, [ref]$null, [ref]$errors) | Out-Null
if ($errors -and $errors.Count) { Write-Output "PARSE ERRORS:"; $errors | ForEach-Object { $_.Message } } else { Write-Output "PARSE OK" }
Write-Output "== user PATH contains nodejs env? =="
$userPath = [Environment]::GetEnvironmentVariable('Path','User'); $machinePath = [Environment]::GetEnvironmentVariable('Path','Machine')
Write-Output ("USER PATH has it: " + ($userPath -like '*program_runtime_environment*'))
Write-Output ("MACHINE PATH has it: " + ($machinePath -like '*program_runtime_environment*'))", "description": "Write policy audit script and check PATH"}

