{"command": "$content = @'
#Requires -Version 5.1
<#
.SYNOPSIS
    Deploy the storage policy: user-global AGENTS.md and/or another workspace copy.

.DESCRIPTION
    Default action copies <root>\policy\deploy\global-agents.md to <DshHome>\AGENTS.md,
    which DSH injects into every conversation in every workspace. An existing file is
    backed up first, and identical content is reported without rewriting.

    With -TargetWorkspace the whole standard (AGENTS.md, policy\, tools\ and the category
    folders) is replicated into another workspace so that workspace follows the same rules.

.PARAMETER Source
    Staged global instruction file. Defaults to <root>\policy\deploy\global-agents.md.

.PARAMETER DshHome
    DSH home directory. Defaults to $env:DSH_HOME, then to ~\.dsh.

.PARAMETER TargetWorkspace
    Replicate the standard into this workspace root instead of deploying globally.

.PARAMETER Force
    Overwrite existing files instead of skipping them.

.PARAMETER DryRun
    Report what would change without writing anything.

.EXAMPLE
    powershell.exe -NoProfile -ExecutionPolicy Bypass -File E:\Deepseek\tools\Install-GlobalPolicy.ps1

.EXAMPLE
    powershell.exe -NoProfile -ExecutionPolicy Bypass -File E:\Deepseek\tools\Install-GlobalPolicy.ps1 -TargetWorkspace E:\OtherWorkspace
#>
[CmdletBinding()]
param(
    [string]$Source,
    [string]$DshHome,
    [string]$TargetWorkspace,
    [switch]$Force,
    [switch]$DryRun
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function Write-Utf8File {
    param([string]$Path, [string]$Text)
    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        New-Item -ItemType Directory -Force -Path $parent | Out-Null
    }
    [System.IO.File]::WriteAllText($Path, $Text, (New-Object System.Text.UTF8Encoding($false)))
}

function Copy-PolicyFile {
    param([string]$From, [string]$To)
    if (-not (Test-Path -LiteralPath $From)) {
        Write-Output ("  SKIP (source missing) " + $From)
        return
    }
    if ((Test-Path -LiteralPath $To) -and (-not $Force)) {
        $oldText = [System.IO.File]::ReadAllText($To, [System.Text.Encoding]::UTF8)
        $newText = [System.IO.File]::ReadAllText($From, [System.Text.Encoding]::UTF8)
        if ($oldText -eq $newText) { Write-Output ("  SAME " + $To); return }
        Write-Output ("  SKIP (exists, use -Force) " + $To)
        return
    }
    if ($DryRun) { Write-Output ("  WOULD COPY " + $From + " -> " + $To); return }
    Write-Utf8File -Path $To -Text ([System.IO.File]::ReadAllText($From, [System.Text.Encoding]::UTF8))
    Write-Output ("  COPIED " + $To)
}

$workspaceRoot = Split-Path -Parent $PSScriptRoot
if ([string]::IsNullOrWhiteSpace($Source)) { $Source = Join-Path $workspaceRoot 'policy\deploy\global-agents.md' }

if (-not [string]::IsNullOrWhiteSpace($TargetWorkspace)) {
    # ---- replicate the whole standard into another workspace
    if (-not (Test-Path -LiteralPath $TargetWorkspace)) {
        if ($DryRun) { Write-Output ("WOULD CREATE " + $TargetWorkspace) }
        else { New-Item -ItemType Directory -Force -Path $TargetWorkspace | Out-Null }
    }
    $target = (Resolve-Path -LiteralPath $TargetWorkspace).Path
    Write-Output ("Replicating the storage policy into " + $target)
    if ($DryRun) { Write-Output "Mode: dry run" }

    Copy-PolicyFile -From (Join-Path $workspaceRoot 'AGENTS.md') -To (Join-Path $target 'AGENTS.md')
    Copy-PolicyFile -From (Join-Path $workspaceRoot 'README.md') -To (Join-Path $target 'README.md')
    Copy-PolicyFile -From (Join-Path $workspaceRoot 'policy\storage-policy.json') -To (Join-Path $target 'policy\storage-policy.json')
    Copy-PolicyFile -From (Join-Path $workspaceRoot 'policy\output-storage-policy.md') -To (Join-Path $target 'policy\output-storage-policy.md')
    Copy-PolicyFile -From (Join-Path $workspaceRoot 'policy\deploy\global-agents.md') -To (Join-Path $target 'policy\deploy\global-agents.md')
    foreach ($script in Get-ChildItem -LiteralPath (Join-Path $workspaceRoot 'tools') -Filter '*.ps1' -File) {
        Copy-PolicyFile -From $script.FullName -To (Join-Path $target ('tools\' + $script.Name))
    }
    Copy-PolicyFile -From (Join-Path $workspaceRoot 'policy\deploy\runtime-environment\README.md') -To (Join-Path $target 'policy\deploy\runtime-environment\README.md')
    Copy-PolicyFile -From (Join-Path $workspaceRoot 'policy\deploy\runtime-environment\registry.json') -To (Join-Path $target 'policy\deploy\runtime-environment\registry.json')
    Copy-PolicyFile -From (Join-Path $workspaceRoot 'policy\deploy\runtime-environment\tools\Add-RuntimeEnvironment.ps1') -To (Join-Path $target 'policy\deploy\runtime-environment\tools\Add-RuntimeEnvironment.ps1')

    foreach ($category in @('deliverables', 'logs', 'scripts', 'workspace', 'data', 'archive')) {
        $dir = Join-Path $target $category
        if ($DryRun) { Write-Output ("  WOULD ENSURE " + $dir) }
        elseif (-not (Test-Path -LiteralPath $dir)) {
            New-Item -ItemType Directory -Force -Path $dir | Out-Null
            Write-Output ("  CREATED " + $dir)
        } else { Write-Output ("  EXISTS " + $dir) }
    }
    Write-Output ""
    Write-Output "Next step in that workspace:"
    Write-Output ("  powershell.exe -NoProfile -ExecutionPolicy Bypass -File " + (Join-Path $target 'tools\New-ConversationWorkspace.ps1'))
    exit 0
}

# ---- deploy the user-global AGENTS.md
if ([string]::IsNullOrWhiteSpace($DshHome)) {
    if (-not [string]::IsNullOrWhiteSpace($env:DSH_HOME)) { $DshHome = $env:DSH_HOME }
    else { $DshHome = Join-Path $env:USERPROFILE '.dsh' }
}
$targetFile = Join-Path $DshHome 'AGENTS.md'

Write-Output "Deploying the user-global instruction file"
Write-Output ("  source: " + $Source)
Write-Output ("  target: " + $targetFile)
if ($DryRun) { Write-Output "  mode  : dry run" }

if (-not (Test-Path -LiteralPath $Source)) { throw ("Source file not found: " + $Source) }
$newText = [System.IO.File]::ReadAllText($Source, [System.Text.Encoding]::UTF8)

if (Test-Path -LiteralPath $targetFile) {
    $oldText = [System.IO.File]::ReadAllText($targetFile, [System.Text.Encoding]::UTF8)
    if ($oldText -eq $newText) {
        Write-Output "  result: already up to date, nothing written"
        exit 0
    }
    Write-Output ("  old size: " + $oldText.Length + " chars / new size: " + $newText.Length + " chars")
    if (-not $DryRun) {
        $backup = $targetFile + '.bak-' + (Get-Date).ToString('yyyyMMdd-HHmmss')
        Write-Utf8File -Path $backup -Text $oldText
        Write-Output ("  backup: " + $backup)
    }
} else {
    Write-Output "  old file: none (first deployment)"
}

if ($DryRun) { Write-Output "  WOULD WRITE the global AGENTS.md"; exit 0 }

try {
    Write-Utf8File -Path $targetFile -Text $newText
} catch {
    Write-Output ("  FAILED: " + $_.Exception.Message)
    Write-Output "  hint: writing outside the workspace needs sandbox approval (danger-full-access);"
    Write-Output "        re-run the same command with that approval."
    exit 2
}
Write-Output "  result: global AGENTS.md deployed; new conversations will load it automatically"
exit 0
'@
$path = 'E:\Deepseek\tools\Install-GlobalPolicy.ps1'
[System.IO.File]::WriteAllText($path, $content, (New-Object System.Text.UTF8Encoding($false)))
Write-Output ("WROTE {0} : {1} bytes" -f $path, (Get-Item $path).Length)
$errors = $null
[System.Management.Automation.Language.Parser]::ParseFile($path, [ref]$null, [ref]$errors) | Out-Null
if ($errors -and $errors.Count) { Write-Output "PARSE ERRORS:"; $errors | ForEach-Object { $_.Message } } else { Write-Output "PARSE OK" }", "description": "Write global policy deployment script"}

