{"command": "$content = @'
#Requires -Version 5.1
<#
.SYNOPSIS
    Register or update an installed runtime environment in registry.json.

.DESCRIPTION
    Creates <Root>\<Category> (and <Root>\<Category>\<Version> with -Versioned), then
    inserts or updates the matching entry in <Root>\registry.json. Use it right after
    installing or extracting a runtime into the categorized environment root.

.PARAMETER Category
    Language/tool family folder, lowercase English, for example:
    nodejs, python, java, dotnet, go, rust, cli, browsers, databases, caches.

.PARAMETER Name
    Environment name. Defaults to the category name.

.PARAMETER Version
    Version string, for example 3.12.7.

.PARAMETER InstallPath
    Install folder. Defaults to <Root>\<Category> (plus \Version with -Versioned).

.PARAMETER BinPaths
    Folders that should be on PATH. Defaults to InstallPath.

.PARAMETER Source
    Where it came from: portable zip, installer, pre-existing, winget, ...

.PARAMETER Notes
    Free text.

.PARAMETER Versioned
    Store the environment in a per-version subfolder (<Category>\<Version>).

.PARAMETER AddToUserPath
    Append the bin paths to the current user PATH when they are missing.

.PARAMETER Root
    Runtime environment root. Defaults to D:\program_runtime_environment.

.PARAMETER DryRun
    Show the resulting entry without writing anything.

.EXAMPLE
    powershell.exe -NoProfile -ExecutionPolicy Bypass -File D:\program_runtime_environment\tools\Add-RuntimeEnvironment.ps1 -Category cli -Name ffmpeg -Version 7.1 -InstallPath D:\program_runtime_environment\cli\ffmpeg -Source "portable zip"

.EXAMPLE
    powershell.exe -NoProfile -ExecutionPolicy Bypass -File D:\program_runtime_environment\tools\Add-RuntimeEnvironment.ps1 -Category python -Name python -Version 3.12.7 -Versioned -AddToUserPath
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)][string]$Category,
    [string]$Name,
    [string]$Version = '',
    [string]$InstallPath,
    [string[]]$BinPaths,
    [string]$Source = 'manual',
    [string]$Notes = '',
    [switch]$Versioned,
    [switch]$AddToUserPath,
    [string]$Root = 'D:\program_runtime_environment',
    [switch]$DryRun
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function Read-Utf8Json {
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path)) { return $null }
    $text = [System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8)
    if ([string]::IsNullOrWhiteSpace($text)) { return $null }
    return ($text | ConvertFrom-Json)
}

function Write-Utf8Json {
    param([string]$Path, $Object)
    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        New-Item -ItemType Directory -Force -Path $parent | Out-Null
    }
    $json = $Object | ConvertTo-Json -Depth 8
    [System.IO.File]::WriteAllText($Path, $json + [Environment]::NewLine, (New-Object System.Text.UTF8Encoding($false)))
}

function Get-PropertyValue {
    param($Object, [string]$PropName, $Default = $null)
    if ($null -eq $Object) { return $Default }
    $prop = $Object.PSObject.Properties[$PropName]
    if ($null -eq $prop) { return $Default }
    if ($null -eq $prop.Value) { return $Default }
    return $prop.Value
}

# ---- validate and normalize the category
$Category = $Category.Trim().ToLowerInvariant()
if ($Category -notmatch '^[a-z0-9][a-z0-9-]{1,31}$') {
    throw ("Invalid category '" + $Category + "': use 2-32 lowercase ASCII letters, digits or '-'.")
}
if ([string]::IsNullOrWhiteSpace($Name)) { $Name = $Category }
$Version = $Version.Trim()

if ([string]::IsNullOrWhiteSpace($InstallPath)) {
    $InstallPath = Join-Path $Root $Category
    if ($Versioned -and $Version) { $InstallPath = Join-Path $InstallPath $Version }
}
if ($null -eq $BinPaths -or $BinPaths.Count -eq 0) { $BinPaths = @($InstallPath) }

Write-Output ("Runtime environment root : " + $Root)
Write-Output ("Category                 : " + $Category)
Write-Output ("Name                     : " + $Name)
Write-Output ("Version                  : " + $Version)
Write-Output ("Install path             : " + $InstallPath)
Write-Output ("Bin paths                : " + ($BinPaths -join '; '))
Write-Output ""

if (-not $DryRun) {
    New-Item -ItemType Directory -Force -Path $InstallPath | Out-Null
    New-Item -ItemType Directory -Force -Path (Join-Path $Root '_downloads') | Out-Null
    New-Item -ItemType Directory -Force -Path (Join-Path $Root '_caches') | Out-Null
    Write-Output ("Ensured folder: " + $InstallPath)
}

# ---- optional user PATH registration
$addedToUserPath = $false
if ($AddToUserPath) {
    $userPath = [Environment]::GetEnvironmentVariable('Path', 'User')
    if ([string]::IsNullOrWhiteSpace($userPath)) { $userPath = '' }
    $parts = @($userPath.Split(';') | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    $missing = @()
    foreach ($binPath in $BinPaths) {
        $hit = $false
        foreach ($part in $parts) {
            if ($part.TrimEnd('\') -ieq $binPath.TrimEnd('\')) { $hit = $true; break }
        }
        if (-not $hit) { $missing += $binPath }
    }
    if ($missing.Count -eq 0) {
        $addedToUserPath = $true
        Write-Output 'User PATH already contains every bin path; nothing changed.'
    } elseif ($DryRun) {
        Write-Output ("WOULD append to the user PATH: " + ($missing -join '; '))
        $addedToUserPath = $true
    } else {
        $newPath = (($parts + $missing) -join ';')
        [Environment]::SetEnvironmentVariable('Path', $newPath, 'User')
        $addedToUserPath = $true
        Write-Output ("Appended to the user PATH: " + ($missing -join '; '))
        Write-Output 'Note: open a new shell (or restart DSH) before the new PATH is visible.'
    }
} else {
    $currentUserPath = [Environment]::GetEnvironmentVariable('Path', 'User')
    if (-not [string]::IsNullOrWhiteSpace($currentUserPath)) {
        foreach ($binPath in $BinPaths) {
            foreach ($part in @($currentUserPath.Split(';'))) {
                if ($part.TrimEnd('\') -ieq $binPath.TrimEnd('\')) { $addedToUserPath = $true }
            }
        }
    }
}

# ---- upsert the registry entry
$registryPath = Join-Path $Root 'registry.json'
$registry = Read-Utf8Json -Path $registryPath
$environments = New-Object System.Collections.ArrayList
$existing = Get-PropertyValue -Object $registry -Name 'environments'
if ($existing) { foreach ($e in @($existing)) { [void]$environments.Add($e) } }

$entry = [pscustomobject]@{
    name            = $Name
    category        = $Category
    version         = $Version
    installPath     = $InstallPath
    binPaths        = @($BinPaths)
    addedToUserPath = $addedToUserPath
    installedAt     = (Get-Date).ToString('yyyy-MM-dd')
    source          = $Source
    notes           = $Notes
}

$matched = $false
for ($i = 0; $i -lt $environments.Count; $i++) {
    $e = $environments[$i]
    $sameCategory = ([string](Get-PropertyValue -Object $e -Name 'category')) -eq $Category
    $sameName = ([string](Get-PropertyValue -Object $e -Name 'name')) -eq $Name
    $sameVersion = ([string](Get-PropertyValue -Object $e -Name 'version')) -eq $Version
    if ($sameCategory -and $sameName -and $sameVersion) {
        $environments[$i] = $entry
        $matched = $true
    }
}
if (-not $matched) { [void]$environments.Add($entry) }

$registryOut = [pscustomobject]@{
    version            = 1
    root               = $Root
    layout             = '<root>\<category>[\<version>]\...'
    categoryRule       = 'one top-level folder per language/tool family; lowercase English; never mix two environments in one folder; never drop loose executables in the root'
    declaredCategories = @('nodejs', 'python', 'java', 'dotnet', 'go', 'rust', 'cli', 'browsers', 'databases', 'caches')
    reservedFolders    = [pscustomobject]@{
        '_downloads' = 'installer and archive staging; safe to clean up'
        '_caches'    = 'package manager caches (npm, pip, cargo, ...)'
        'tools'      = 'runtime environment helper scripts'
    }
    updatedAt          = (Get-Date).ToString('yyyy-MM-dd')
    environments       = @($environments)
}

if ($DryRun) {
    Write-Output ""
    Write-Output 'Dry run - entry that would be written:'
    $entry | ConvertTo-Json -Depth 6
    exit 0
}

try {
    Write-Utf8Json -Path $registryPath -Object $registryOut
} catch {
    Write-Output ("FAILED to write the registry: " + $_.Exception.Message)
    Write-Output 'hint: writing to D: needs danger-full-access approval in the DSH file sandbox.'
    exit 2
}

Write-Output ""
Write-Output ("Registry updated: " + $registryPath)
Write-Output ("Registered environments: " + $environments.Count)
$entry | ConvertTo-Json -Depth 6
exit 0
'@
$path = 'E:\Deepseek\policy\deploy\runtime-environment\tools\Add-RuntimeEnvironment.ps1'
$dir = Split-Path -Parent $path
if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
[System.IO.File]::WriteAllText($path, $content, (New-Object System.Text.UTF8Encoding($false)))
Write-Output ("WROTE {0} : {1} bytes" -f $path, (Get-Item $path).Length)
$errors = $null
[System.Management.Automation.Language.Parser]::ParseFile($path, [ref]$null, [ref]$errors) | Out-Null
if ($errors -and $errors.Count) { Write-Output "PARSE ERRORS:"; $errors | ForEach-Object { $_.Message } } else { Write-Output "PARSE OK" }", "description": "Write runtime environment registration helper"}

