# ---- validate and normalize the category
$Category = $Category.Trim().ToLowerInvariant()
if ($Category -notmatch '^[a-z0-9][a-z0-9-]{1,31}$') {
    throw ("Invalid category '" + $Category + "': use 2-32 lowercase ASCII letters, digits or '-'.")
}
if ([string]::IsNullOrWhiteSpace($Name)) { $Name = $Category }
$Version = $Version.Trim()

if ([string]::IsNullOrWhiteSpace($InstallPath)) {
    $InstallPath = Join-Path $Root $Category
    if ($Versioned -and $Version) { $InstallPath = Join-Path $InstallPath $Version }
}
if ($null -eq $BinPaths -or $BinPaths.Count -eq 0) { $BinPaths = @($InstallPath) }

Write-Output ("Runtime environment root : " + $Root)
Write-Output ("Category                 : " + $Category)
Write-Output ("Name                     : " + $Name)
Write-Output ("Version                  : " + $Version)
Write-Output ("Install path             : " + $InstallPath)
Write-Output ("Bin paths                : " + ($BinPaths -join '; '))
Write-Output ""

if (-not $DryRun) {
    New-Item -ItemType Directory -Force -Path $InstallPath | Out-Null
    New-Item -ItemType Directory -Force -Path (Join-Path $Root '_downloads') | Out-Null
    New-Item -ItemType Directory -Force -Path (Join-Path $Root '_caches') | Out-Null
    Write-Output ("Ensured folder: " + $InstallPath)
}

# ---- optional user PATH registration
$addedToUserPath = $false
if ($AddToUserPath) {
    $userPath = [Environment]::GetEnvironmentVariable('Path', 'User')
    if ([string]::IsNullOrWhiteSpace($userPath)) { $userPath = '' }
    $parts = @($userPath.Split(';') | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    $missing = @()
    foreach ($binPath in $BinPaths) {
        $hit = $false
        foreach ($part in $parts) {
            if ($part.TrimEnd('\') -ieq $binPath.TrimEnd('\')) { $hit = $true; break }
        }
        if (-not $hit) { $missing += $binPath }
    }
    if ($missing.Count -eq 0) {
        $addedToUserPath = $true
        Write-Output 'User PATH already contains every bin path; nothing changed.'
    } elseif ($DryRun) {
        Write-Output ("WOULD append to the user PATH: " + ($missing -join '; '))
        $addedToUserPath = $true
    } else {
        $newPath = (($parts + $missing) -join ';')
        [Environment]::SetEnvironmentVariable('Path', $newPath, 'User')
        $addedToUserPath = $true
        Write-Output ("Appended to the user PATH: " + ($missing -join '; '))
        Write-Output 'Note: open a new shell (or restart DSH) before the new PATH is visible.'
    }
} else {
    $currentUserPath = [Environment]::GetEnvironmentVariable('Path', 'User')
    if (-not [string]::IsNullOrWhiteSpace($currentUserPath)) {
        foreach ($binPath in $BinPaths) {
            foreach ($part in @($currentUserPath.Split(';'))) {
                if ($part.TrimEnd('\') -ieq $binPath.TrimEnd('\')) { $addedToUserPath = $true }
            }
        }
    }
}

# ---- upsert the registry entry
$registryPath = Join-Path $Root 'registry.json'
$registry = Read-Utf8Json -Path $registryPath
$environments = New-Object System.Collections.ArrayList
$existing = Get-PropertyValue -Object $registry -Name 'environments'
if ($existing) { foreach ($e in @($existing)) { [void]$environments.Add($e) } }

$entry = [pscustomobject]@{
    name            = $Name
    category        = $Category
    version         = $Version
    installPath     = $InstallPath
    binPaths        = @($BinPaths)
    addedToUserPath = $addedToUserPath
    installedAt     = (Get-Date).ToString('yyyy-MM-dd')
    source          = $Source
    notes           = $Notes
}

$matched = $false
for ($i = 0; $i -lt $environments.Count; $i++) {
    $e = $environments[$i]
    $sameCategory = ([string](Get-PropertyValue -Object $e -Name 'category')) -eq $Category
    $sameName = ([string](Get-PropertyValue -Object $e -Name 'name')) -eq $Name
    $sameVersion = ([string](Get-PropertyValue -Object $e -Name 'version')) -eq $Version
    if ($sameCategory -and $sameName -and $sameVersion) {
        $environments[$i] = $entry
        $matched = $true
    }
}
if (-not $matched) { [void]$environments.Add($entry) }

$registryOut = [pscustomobject]@{
    version            = 1
    root               = $Root
    layout             = '<root>\<category>[\<version>]\...'
    categoryRule       = 'one top-level folder per language/tool family; lowercase English; never mix two environments in one folder; never drop loose executables in the root'
    declaredCategories = @('nodejs', 'python', 'java', 'dotnet', 'go', 'rust', 'cli', 'browsers', 'databases', 'caches')
    reservedFolders    = [pscustomobject]@{
        '_downloads' = 'installer and archive staging; safe to clean up'
        '_caches'    = 'package manager caches (npm, pip, cargo, ...)'
        'tools'      = 'runtime environment helper scripts'
    }
    updatedAt          = (Get-Date).ToString('yyyy-MM-dd')
    environments       = @($environments)
}

if ($DryRun) {
    Write-Output ""
    Write-Output 'Dry run - entry that would be written:'
    $entry | ConvertTo-Json -Depth 6
    exit 0
}

try {
    Write-Utf8Json -Path $registryPath -Object $registryOut
} catch {
    Write-Output ("FAILED to write the registry: " + $_.Exception.Message)
    Write-Output 'hint: writing to D: needs danger-full-access approval in the DSH file sandbox.'
    exit 2
}

Write-Output ""
Write-Output ("Registry updated: " + $registryPath)
Write-Output ("Registered environments: " + $environments.Count)
$entry | ConvertTo-Json -Depth 6
exit 0
'@
