// Usage: node download-file.js <url> <outputPath> [expectedBytes]
const fs = require('fs');
const https = require('https');
const path = require('path');
const url = process.argv[2];
const out = process.argv[3];
const expected = process.argv[4] ? Number(process.argv[4]) : null;
if (!url || !out) { console.error('usage: node download-file.js <url> <outputPath> [expectedBytes]'); process.exit(2); }
fs.mkdirSync(path.dirname(out), { recursive: true });
