  if (expected !== null && size !== expected) { console.error('SIZE MISMATCH: got ' + size + ', expected ' + expected); process.exit(3); }
  fs.renameSync(tmp, out);
  console.log('downloaded ' + out + ' (' + size + ' bytes, ' + ((Date.now()-started)/1000).toFixed(1) + ' s)');
}
