content.arguments:
{"command": "$wa = 'C:\Users\徐丰哲\AppData\Local\Microsoft\WindowsApps'
Write-Output "=== 1. inspect the stubs before touching them ==="
foreach ($n in 'python.exe','python3.exe') {
  $f = Join-Path $wa $n
  if (-not (Test-Path -LiteralPath $f)) { Write-Output "  $n : absent"; continue }
  $it = Get-Item -LiteralPath $f -Force
  Write-Output ("  {0} : {1} bytes, attributes={2}" -f $n, $it.Length, $it.Attributes)
  $fs = fsutil reparsepoint query $f 2>&1 | Select-Object -First 3
  Write-Output ("     reparse: " + (($fs -join ' | ').Trim()))
}
Write-Output ""
Write-Output "=== 2. disable the aliases by renaming the stubs (reversible) ==="
foreach ($n in 'python.exe','python3.exe') {
  $f = Join-Path $wa $n
  if (-not (Test-Path -LiteralPath $f)) { continue }
  $it = Get-Item -LiteralPath $f -Force
  if ($it.Length -ne 0 -or -not ($it.Attributes -band [IO.FileAttributes]::ReparsePoint)) {
    Write-Output ("  SKIP $n : not a zero-byte reparse point, refusing to touch it")
    continue
  }
  $dst = Join-Path $wa ($n + '.alias-disabled')
  try {
    Move-Item -LiteralPath $f -Destination $dst -Force
    Write-Output ("  DISABLED $n  ->  $(Split-Path -Leaf $dst)")
  } catch {
    Write-Output ("  FAILED to rename $n : " + $_.Exception.Message)
  }
}
Write-Output ""
Write-Output "=== 3. end-to-end check with the PATH a fresh logon would build ==="
$env:PATH = [Environment]::GetEnvironmentVariable('Path','Machine') + ';' + [Environment]::GetEnvironmentVariable('Path','User')
& cmd.exe /c 'where.exe python'
& cmd.exe /c 'python --version'
& cmd.exe /c 'python -c "import sys; print(sys.executable)"'
& cmd.exe /c 'pip --version'
Write-Output "[exit code: $LASTEXITCODE]"", "description": "Disable broken store python aliases", "justification": "python 命令被用户配置目录里的 0 字节 Microsoft Store 别名占位符截获且该占位符本身已损坏，必须停用它才能让刚装好的 Python 3.14.7 生效；该路径在工作区之外，workspace-write 沙箱会拒绝写入。", "sandbox_permissions": "danger-full-access"}

