  Write-Output ("    '保留期' occurrences: " + ([regex]::Matches($t, '保留期')).Count + " ; '5.4 安装包校验' occurrences: " + ([regex]::Matches($t, '5\.4 安装包校验')).Count)
}", "description": "Audit artifacts for duplicated content"}

