content.arguments:
{"command": "$ErrorActionPreference = 'Stop'

# --- generic: collapse any consecutively repeated run of content lines (keeps formatting/blank lines intact)
function Collapse-ConsecutiveDuplicates {
  param([System.Collections.Generic.List[string]]$Lines)
  $removed = 0
  $changed = $true
  while ($changed) {
    $changed = $false
    $maxN = [Math]::Min(25, [int][Math]::Floor($Lines.Count / 2))
    for ($n = $maxN; $n -ge 1 -and -not $changed; $n--) {
      for ($i = 0; $i + 2 * $n -le $Lines.Count; $i++) {
        if ([string]::IsNullOrWhiteSpace($Lines[$i])) { continue }   # never touch blank-line runs
        $same = $true
        for ($k = 0; $k -lt $n; $k++) {
          if ($Lines[$i + $k] -cne $Lines[$i + $n + $k]) { $same = $false; break }
        }
        if ($same) {
          $Lines.RemoveRange($i + $n, $n)
          $removed += $n
          $changed = $true
          break
        }
      }
    }
  }
  return $removed
}

$targets = @(
  'E:\Deepseek\policy\output-storage-policy.md',
  'E:\Deepseek\policy\deploy\runtime-environment\README.md'
)
foreach ($p in $targets) {
  $text = [System.IO.File]::ReadAllText($p, [System.Text.Encoding]::UTF8)
  $nl = "`n"; if ($text.Contains("`r`n")) { $nl = "`r`n" }
  $list = New-Object 'System.Collections.Generic.List[string]'
  foreach ($l in ($text -split "`r?`n")) { [void]$list.Add($l) }
  $before = $list.Count
  $removed = Collapse-ConsecutiveDuplicates -Lines $list
  if ($removed -gt 0) {
    [System.IO.File]::WriteAllText($p, (($list -join $nl)), (New-Object System.Text.UTF8Encoding($false)))
    Write-Output ("FIXED {0}: removed {1} duplicated lines ({2} -> {3})" -f (Split-Path -Leaf $p), $removed, $before, $list.Count)
  } else {
    Write-Output ("clean {0}: no consecutive duplication" -f (Split-Path -Leaf $p))
  }
}

Write-Output ""
Write-Output "=== full duplication re-audit of every artifact ==="
$all = @(
