Write-Output "=== final duplication audit of the deployed copies ==="
foreach ($f in @('D:\program_runtime_environment\README.md','D:\program_runtime_environment\registry.json','D:\program_runtime_environment\tools\Add-RuntimeEnvironment.ps1')) {
  $lines = [System.IO.File]::ReadAllLines($f, [System.Text.Encoding]::UTF8)
  $found = $false
  for ($n = 12; $n -ge 2 -and -not $found; $n--) {
    for ($i = 0; $i + 2*$n -le $lines.Count; $i++) {
      if ([string]::IsNullOrWhiteSpace($lines[$i])) { continue }
      $same = $true
      for ($k = 0; $k -lt $n; $k++) { if ($lines[$i+$k] -cne $lines[$i+$n+$k]) { $same = $false; break } }
