{"command": "$js = @'
// npm-query.js - query the npm registry without relying on Windows schannel.
// usage: node npm-query.js view <pkg> | dl <pkg> [<pkg> ...] | search <text> [size] [nameFilter]
const https = require('https');

function get(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { 'User-Agent': 'dsh-npm-query/1.0', 'Accept': 'application/json' } }, (r) => {
      if (r.statusCode !== 200) { r.resume(); reject(new Error('HTTP ' + r.statusCode)); return; }
      let d = '';
      r.on('data', (c) => { d += c; });
      r.on('end', () => resolve(d));
    }).on('error', reject);
  });
}

(async () => {
  const mode = process.argv[2];
  if (mode === 'view') {
    const name = process.argv[3];
    const json = JSON.parse(await get('https://registry.npmjs.org/' + name.replace('/', '%2F')));
    const latest = (json['dist-tags'] || {}).latest;
    const versions = Object.keys(json.versions || {});
    const v = json.versions[latest] || {};
    const times = json.time || {};
    console.log('name        : ' + json.name);
    console.log('latest      : ' + latest);
    console.log('published   : ' + (times[latest] || '?') + '   (first: ' + (times.created || '?') + ')');
    console.log('versions    : ' + versions.length);
    console.log('license     : ' + (v.license || '?'));
    console.log('dsh field   : ' + (v.dsh ? JSON.stringify(v.dsh).slice(0, 220) : 'NONE (not a DSH plugin manifest)'));
    console.log('description : ' + (json.description || ''));
  } else if (mode === 'dl') {
    for (const name of process.argv.slice(3)) {
      let out = '?';
      try {
        const j = JSON.parse(await get('https://api.npmjs.org/downloads/point/last-week/' + name.replace('/', '%2F')));
        out = String(j.downloads);
      } catch (e) { out = 'n/a (' + e.message + ')'; }
      console.log(String(name).padEnd(38) + ' last-week downloads: ' + out);
    }
  } else if (mode === 'search') {
    const text = process.argv[3];
    const size = process.argv[4] || '250';
    const filter = process.argv[5];
    const json = JSON.parse(await get('https://registry.npmjs.org/-/v1/search?text=' + encodeURIComponent(text) + '&size=' + size));
    console.log('total matches: ' + json.total);
    for (const o of json.objects) {
      const p = o.package;
      if (filter && !new RegExp(filter, 'i').test(p.name)) { continue; }
      console.log(p.name.padEnd(38) + ' @' + String(p.version).padEnd(9) + ' ' + (p.date || '').slice(0, 10) + '  ' + (p.description || '').slice(0, 80));
    }
  } else {
    console.error('usage: node npm-query.js view <pkg> | dl <pkg...> | search <text> [size] [filter]');
    process.exit(2);
  }
})().catch((e) => { console.error('ERROR: ' + e.message); process.exit(1); });
