# literal, interpolation-free replacement (no regex, no $ substitution)
$oldBefore = '$before' + '.dependencies.PSObject.Properties.Name'
$newBefore = 'Get-PropNames -Object ' + '$before' + '.dependencies'
$had = $t.Contains($oldBefore)
$t = $t.Replace($oldBefore, $newBefore)
if (-not $had) { Write-Output 'pattern not found; nothing to fix' } else {
  [System.IO.File]::WriteAllText($p, $t, (New-Object System.Text.UTF8Encoding($false)))
  Write-Output 'before-line fixed'
}
$errors = $null
[System.Management.Automation.Language.Parser]::ParseFile($p, [ref]$null, [ref]$errors) | Out-Null
if ($errors -and $errors.Count) { Write-Output 'PARSE ERRORS:'; $errors | ForEach-Object { $_.Message } } else { Write-Output 'PARSE OK' }
Write-Output ""
Write-Output "=== the three lines that matter now ==="
$lines = [System.IO.File]::ReadAllLines($p, [System.Text.Encoding]::UTF8)
for ($i = 0; $i -lt $lines.Count; $i++) {
  if ($lines[$i] -match 'function Get-PropNames|dependencies before|dependencies after|bundles before|bundles after') { '  {0,4}: {1}' -f ($i+1), $lines[$i] }
}", "description": "Fix remaining replacement in script"}

content.arguments:
{"command": "Write-Output "=== processes hosting the web UI ==="
Get-CimInstance Win32_Process -Filter "Name='node.exe'" -ErrorAction SilentlyContinue |
  Where-Object { $_.CommandLine -match 'dsh' } |
  Select-Object ProcessId, ParentProcessId, CreationDate, @{n='cmd';e={$_.CommandLine.Substring(0,[Math]::Min(160,$_.CommandLine.Length))}} |
  Format-List | Out-String -Width 200
Write-Output "=== parent processes (how it was started) ==="
$hosts = Get-CimInstance Win32_Process -Filter "Name='node.exe'" -ErrorAction SilentlyContinue | Where-Object { $_.CommandLine -match 'dsh' }
foreach ($h in $hosts) {
  $parent = Get-CimInstance Win32_Process -Filter ("ProcessId=" + $h.ParentProcessId) -ErrorAction SilentlyContinue
  if ($parent) { Write-Output ("  pid " + $h.ProcessId + " <- " + $parent.Name + " (pid " + $parent.ProcessId + "): " + ($parent.CommandLine -replace '\s+', ' ').Substring(0, [Math]::Min(140, ($parent.CommandLine -replace '\s+',' ').Length))) }
  else { Write-Output ("  pid " + $h.ProcessId + " <- parent " + $h.ParentProcessId + " (gone)") }
}
Write-Output ""
Write-Output "=== web url from env ==="
Write-Output ("  DSH_WEB_URL = " + $env:DSH_WEB_URL)
Write-Output "=== is the admin/host still the same process as this session? ==="
Write-Output ("  DSH_SESSION_ID = " + $env:DSH_SESSION_ID)", "description": "Find how dsh web is running"}

