content.arguments:
{"command": "Write-Output "=== who listens on 3080 (the web host) ==="
try {
  Get-NetTCPConnection -LocalPort 3080 -State Listen -ErrorAction Stop | Select-Object LocalAddress, LocalPort, OwningProcess, State | Format-Table -AutoSize | Out-String -Width 100
} catch { Write-Output ("  Get-NetTCPConnection failed: " + $_.Exception.Message) }
Write-Output "=== node processes visible to this session ==="
Get-Process -Name node -ErrorAction SilentlyContinue | Select-Object Id, ProcessName, StartTime, @{n='Path';e={$_.Path}} | Format-Table -AutoSize | Out-String -Width 140
Write-Output "=== this session's own process chain ==="
$me = $PID
for ($i = 0; $i -lt 4 -and $me; $i++) {
  $proc = Get-CimInstance Win32_Process -Filter ("ProcessId=" + $me) -ErrorAction SilentlyContinue
  if (-not $proc) { break }
  Write-Output ("  pid " + $proc.ProcessId + " : " + $proc.Name + " : " + ($proc.CommandLine -replace '\s+',' ').Substring(0, [Math]::Min(120, ($proc.CommandLine -replace '\s+',' ').Length)))
  $me = $proc.ParentProcessId
  if ($me -eq 0) { break }
}", "description": "Identify the web host process"}

