content.arguments:
{"command": "$node = 'D:\program_runtime_environment\nodejs\node.exe'
$js = @'
const https = require('https');
function get(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { 'User-Agent': 'dsh-npm-query/1.0', 'Accept': 'application/json' } }, (r) => {
      if (r.statusCode !== 200) { r.resume(); reject(new Error('HTTP ' + r.statusCode)); return; }
      let d = ''; r.on('data', (c) => { d += c; }); r.on('end', () => resolve(d));
    }).on('error', reject);
  });
}
(async () => {
  for (const name of ['@deepseek-ai/dsh', '@deepseek-ai/dsh-base', '@deepseek-ai/dsh-web-app']) {
    for (const reg of ['https://registry.npmjs.org/', 'https://registry.npmmirror.com/']) {
      try {
        const j = JSON.parse(await get(reg + name.replace('/', '%2F')));
        const tags = j['dist-tags'] || {};
        const times = j.time || {};
        const tagKeys = Object.keys(tags);
        console.log('=== ' + name + '  @ ' + (reg.includes('npmmirror') ? 'npmmirror' : 'npmjs') + ' ===');
        for (const k of tagKeys) console.log('    dist-tag ' + k.padEnd(12) + ' -> ' + tags[k] + '   published ' + (times[tags[k]] || '?'));
        const recent = Object.keys(times).filter((v) => v !== 'created' && v !== 'modified').slice(-6);
        console.log('    recent versions: ' + recent.join(', '));
      } catch (e) {
        console.log('=== ' + name + ' @ ' + reg + ' -> ERROR ' + e.message);
      }
    }
  }
})();
'@
$p = 'E:\Deepseek\scripts\conv-20260928-3b54e160\dist-tags.js'
[System.IO.File]::WriteAllText($p, $js, (New-Object System.Text.UTF8Encoding($false)))
& $node $p
Write-Output ""
Write-Output "=== installed layout ==="
$prefix = Join-Path $env:APPDATA 'npm'
Write-Output ("global npm prefix : " + $prefix)
Write-Output ("dsh package       : " + (Test-Path (Join-Path $prefix 'node_modules\@deepseek-ai\dsh')))
$cur = [System.IO.File]::ReadAllText((Join-Path $prefix 'node_modules\@deepseek-ai\dsh\package.json'), [System.Text.Encoding]::UTF8) | ConvertFrom-Json
Write-Output ("installed version : " + $cur.version)
$size = (Get-ChildItem -LiteralPath (Join-Path $prefix 'node_modules\@deepseek-ai\dsh') -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
Write-Output ("dsh dir size      : " + [Math]::Round($size/1MB,1) + " MB")
Write-Output ("global node_modules size: " + [Math]::Round(((Get-ChildItem -LiteralPath (Join-Path $prefix 'node_modules') -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum)/1MB,1) + " MB")
Write-Output ""
Write-Output "=== how do profiles resolve bundles? versions in profiles\node_modules ==="
$pn = 'C:\Users\徐丰哲\.dsh\profiles\node_modules\@deepseek-ai'
Write-Output ("profiles\node_modules\@deepseek-ai packages: " + (Get-ChildItem -LiteralPath $pn -Directory -ErrorAction SilentlyContinue | Measure-Object).Count)
foreach ($n in 'dsh-base','dsh-web-app','dsh') {
  $pp = Join-Path $pn "$n\package.json"
  if (Test-Path -LiteralPath $pp) { $v = ([System.IO.File]::ReadAllText($pp, [System.Text.Encoding]::UTF8) | ConvertFrom-Json).version; Write-Output ("  " + $n + " = " + $v) }
}
Write-Output ("profiles\package.json exists: " + (Test-Path 'C:\Users\徐丰哲\.dsh\profiles\package.json'))
Write-Output ("profiles\package-lock.json exists: " + (Test-Path 'C:\Users\徐丰哲\.dsh\profiles\package-lock.json'))
Write-Output "=== profiles\web\.dsh-module-fallback ==="
Get-ChildItem -LiteralPath 'C:\Users\徐丰哲\.dsh\profiles\web\.dsh-module-fallback' -Force -ErrorAction SilentlyContinue | Select-Object Name | Format-Table -AutoSize | Out-String -Width 80
Write-Output "=== global install tree (top level) ==="
& cmd.exe /c 'npm ls -g --depth=0' 2>&1 | Select-Object -First 10", "description": "Recon dsh versions and install layout", "timeoutMs": 180000}

