{"command": "$upgrade = @'
#Requires -Version 5.1
<#
.SYNOPSIS
    Stage or perform an upgrade of the global @deepseek-ai/dsh installation.

.DESCRIPTION
    Mode Stage (default, safe while dsh is running):
      installs the requested version into a staging prefix under the runtime root and verifies
      that the staged CLI reports the new version. This front-loads the download into the npm
      cache and proves the build works BEFORE the live installation is touched.

    Mode Swap (requires the dsh host to be stopped):
      refuses to run while anything listens on the web port, because the running host keeps
      native modules locked and npm would fail with EBUSY mid-replacement. It then installs the
      version globally and verifies the resulting CLI.

    The profile module fallback (~/.dsh/profiles/node_modules) is a set of links into the
    install anchor; dsh heals it automatically on the next boot, so no manual step is needed.

.PARAMETER Mode
    Stage or Swap.

.PARAMETER Version
    Version to install. Default 0.1.7-rc.2 (npm dist-tags latest and next for @deepseek-ai/dsh).

.PARAMETER Registry
    Registry used for this run only; the user's npm configuration is never modified.

.PARAMETER Port
    Web port checked in Swap mode. Default 3080.

.EXAMPLE
    powershell.exe -NoProfile -ExecutionPolicy Bypass -File upgrade-dsh.ps1 -Mode Stage
.EXAMPLE
    powershell.exe -NoProfile -ExecutionPolicy Bypass -File upgrade-dsh.ps1 -Mode Swap
#>
[CmdletBinding()]
param(
    [ValidateSet('Stage', 'Swap')][string]$Mode = 'Stage',
    [string]$Version = '0.1.7-rc.2',
    [string]$Registry = 'https://registry.npmmirror.com',
    [string]$StagePrefix = 'D:\program_runtime_environment\_downloads\dsh-stage',
    [int]$Port = 3080,
    [switch]$Force,
    [switch]$DryRun
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$nodeDir = 'D:\program_runtime_environment\nodejs'
$npmCmd = Join-Path $nodeDir 'npm.cmd'
$prefix = Join-Path $env:APPDATA 'npm'
$installedManifest = Join-Path $prefix 'node_modules\@deepseek-ai\dsh\package.json'

function Step { param([string]$Text) Write-Output ''; Write-Output ('=== ' + $Text + ' ===') }
function Ok { param([string]$Text) Write-Output ('[OK]   ' + $Text) }
function Warn { param([string]$Text) Write-Output ('[WARN] ' + $Text) }
function Fail { param([string]$Text) Write-Output ('[FAIL] ' + $Text); exit 1 }

function Get-InstalledVersion {
    if (-not (Test-Path -LiteralPath $installedManifest)) { return '(not installed)' }
    return ([System.IO.File]::ReadAllText($installedManifest, [System.Text.Encoding]::UTF8) | ConvertFrom-Json).version
}

Step 'context'
Write-Output ('  mode            : ' + $Mode)
Write-Output ('  target version  : ' + $Version)
Write-Output ('  registry        : ' + $Registry)
Write-Output ('  global prefix   : ' + $prefix)
Write-Output ('  installed now   : ' + (Get-InstalledVersion))
$env:npm_config_cache = 'D:\program_runtime_environment\_caches\npm'
$env:npm_config_registry = $Registry
New-Item -ItemType Directory -Force -Path $env:npm_config_cache | Out-Null
Write-Output ('  npm cache       : ' + $env:npm_config_cache)

if ($Mode -eq 'Stage') {
    Step ('staging @deepseek-ai/dsh@' + $Version + ' into ' + $StagePrefix)
    if ($DryRun) { Write-Output '  dry run: nothing written'; exit 0 }
    New-Item -ItemType Directory -Force -Path $StagePrefix | Out-Null
    & $npmCmd install --prefix $StagePrefix --no-audit --no-fund ('@deepseek-ai/dsh@' + $Version)
    if ($LASTEXITCODE -ne 0) { Fail ('staged install failed with exit code ' + $LASTEXITCODE) }
    $stagedBin = Join-Path $StagePrefix 'node_modules\@deepseek-ai\dsh\lib\bin.js'
    if (-not (Test-Path -LiteralPath $stagedBin)) { Fail ('staged bin not found: ' + $stagedBin) }
    $stagedManifest = Join-Path $StagePrefix 'node_modules\@deepseek-ai\dsh\package.json'
    $stagedVersion = ([System.IO.File]::ReadAllText($stagedManifest, [System.Text.Encoding]::UTF8) | ConvertFrom-Json).version
    Ok ('staged package version: ' + $stagedVersion)
    Step 'verify the staged CLI actually runs'
    $out = & (Join-Path $nodeDir 'node.exe') $stagedBin --version 2>&1 | Out-String
