    $engines = ([System.IO.File]::ReadAllText($stagedManifest, [System.Text.Encoding]::UTF8) | ConvertFrom-Json).engines
    if ($engines) { Write-Output ('  engines declared: ' + ($engines | ConvertTo-Json -Compress)) }
