Step 'pre-flight: the dsh host must be stopped'
$listener = netstat -ano 2>$null | Select-String (':' + $Port + '\s') | Select-String 'LISTENING'
if ($listener -and -not $Force) {
    Write-Output ('  ' + ($listener | ForEach-Object { $_.Line.Trim() }))
