Write-Output ('  dsh --version: ' + $cliOut.Trim())
if ($now -ne $Version) { Warn ('installed version ' + $now + ' differs from the requested ' + $Version) }
Write-Output ''
Write-Output ('Rollback: npm install --global --registry ' + $Registry + ' @deepseek-ai/dsh@0.1.5-rc.3')
Write-Output 'Then start the host again: dsh web'
exit 0
'@
