// verify-package-integrity.js
// usage: node verify-package-integrity.js <pathToNodeModules> [scope]
// Cross-checks dist.integrity for every installed package in a scope between the official
// registry and the mirror actually used, so a mirror cannot silently serve different bytes.
const fs = require('fs');
const path = require('path');
const https = require('https');

const root = process.argv[2];
const scope = process.argv[3] || '@deepseek-ai';
if (!root) { console.error('usage: node verify-package-integrity.js <pathToNodeModules> [scope]'); process.exit(2); }

function get(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { 'User-Agent': 'dsh-integrity-check/1.0', 'Accept': 'application/json' } }, (r) => {
      if (r.statusCode === 404) { r.resume(); resolve(null); return; }
      if (r.statusCode !== 200) { r.resume(); reject(new Error('HTTP ' + r.statusCode)); return; }
      let d = ''; r.on('data', (c) => { d += c; }); r.on('end', () => resolve(JSON.parse(d)));
    }).on('error', reject);
  });
}

async function withLimit(items, limit, worker) {
  const results = [];
  let index = 0;
  const runners = new Array(Math.min(limit, items.length)).fill(0).map(async () => {
    while (index < items.length) {
      const i = index++;
      results[i] = await worker(items[i]);
    }
  });
  await Promise.all(runners);
  return results;
}

(async () => {
  const scopeDir = path.join(root, scope);
  if (!fs.existsSync(scopeDir)) { console.error('scope dir not found: ' + scopeDir); process.exit(2); }
  const names = fs.readdirSync(scopeDir).filter((n) => fs.existsSync(path.join(scopeDir, n, 'package.json')));
  console.log('packages to check: ' + names.length + ' under ' + scopeDir);
  const rows = await withLimit(names, 6, async (shortName) => {
    const full = scope + '/' + shortName;
    const manifest = JSON.parse(fs.readFileSync(path.join(scopeDir, shortName, 'package.json'), 'utf8'));
    const version = manifest.version;
    let official = null, mirror = null, error = null;
    try {
      official = await get('https://registry.npmjs.org/' + full.replace('/', '%2F') + '/' + version);
      mirror = await get('https://registry.npmmirror.com/' + full.replace('/', '%2F') + '/' + version);
    } catch (e) { error = e.message; }
    const oi = official && official.dist ? official.dist.integrity : null;
    const mi = mirror && mirror.dist ? mirror.dist.integrity : null;
