  console.log('checked : ' + rows.length);
  console.log('matched : ' + (rows.length - bad.length));
  console.log('problems: ' + bad.length);
  process.exit(bad.length === 0 ? 0 : 1);
})().catch((e) => { console.error('FATAL: ' + e.message); process.exit(2); });
