{"command": "function Report-Tree {
  param([string]$Label, [string]$Root)
  Write-Output ("=== " + $Label + " ===")
  Write-Output ("  root: " + $Root + " exists=" + (Test-Path -LiteralPath $Root))
  if (-not (Test-Path -LiteralPath $Root)) { return }
  foreach ($rel in 'node-pty', 'koffi', '@deepseek-ai\dsh-subprocess-local') {
    $d = Join-Path $Root $rel
    if (-not (Test-Path -LiteralPath $d)) { Write-Output ("  " + $rel + " : absent at this level"); continue }
    $ver = ([System.IO.File]::ReadAllText((Join-Path $d 'package.json'), [System.Text.Encoding]::UTF8) | ConvertFrom-Json).version
    $nodes = @(Get-ChildItem -LiteralPath $d -Recurse -Force -File -Filter '*.node' -ErrorAction SilentlyContinue)
    Write-Output ("  " + $rel + " v" + $ver + " : .node files = " + $nodes.Count)
    $nodes | Select-Object -First 4 | ForEach-Object { Write-Output ("      " + $_.FullName.Substring($d.Length + 1) + "  " + [Math]::Round($_.Length/1KB) + " KB") }
    $scripts = @(Get-ChildItem -LiteralPath (Join-Path $d 'scripts') -Recurse -Force -File -ErrorAction SilentlyContinue)
    if ($scripts.Count) { Write-Output ("      scripts/: " + (($scripts | Select-Object -First 6 -ExpandProperty Name) -join ', ')) }
  }
  Write-Output ""
}
