Write-Output "=== 1) installed global package version ==="
$mp = Join-Path $prefix 'node_modules\@deepseek-ai\dsh\package.json'
if (Test-Path -LiteralPath $mp) {
  $m = [System.IO.File]::ReadAllText($mp, [System.Text.Encoding]::UTF8) | ConvertFrom-Json
  Write-Output ("  " + $m.name + " = " + $m.version + "   (package.json modified: " + (Get-Item -LiteralPath $mp).LastWriteTime + ")")
} else { Write-Output "  dsh package.json NOT FOUND" }
Write-Output "=== 2) what the CLI itself reports ==="
& cmd.exe /c "`"$prefix\dsh.cmd`" --version" 2>&1 | Select-Object -First 3
Write-Output "=== 3) global install tree ==="
& cmd.exe /c 'npm ls -g --depth=0' 2>&1 | Select-Object -First 8
Write-Output "=== 4) is the host the same process as before? ==="
$net = netstat -ano 2>$null | Select-String ':3080' | Select-String 'LISTENING'
if ($net) { Write-Output ("  LISTENING: " + $net.Line.Trim()) } else { Write-Output "  nothing listening on 3080 (host is down)" }
Get-Process -Name node -ErrorAction SilentlyContinue | Select-Object Id, StartTime, @{n='WS_MB';e={[Math]::Round($_.WorkingSet64/1MB,1)}} | Format-Table -AutoSize | Out-String -Width 100
Write-Output "=== 5) do the profile links now point at 0.1.7-rc.2? ==="
foreach ($n in 'dsh-base','dsh-web-app','dsh') {
  $p = "C:\Users\徐丰哲\.dsh\profiles\node_modules\@deepseek-ai\$n\package.json"
  if (Test-Path -LiteralPath $p) {
    $v = ([System.IO.File]::ReadAllText($p, [System.Text.Encoding]::UTF8) | ConvertFrom-Json).version
    $item = Get-Item -LiteralPath (Split-Path -Parent $p) -Force
    Write-Output ("  " + $n.PadRight(12) + " = " + $v.PadRight(12) + " link=" + $item.LinkType)
  } else { Write-Output ("  " + $n + " : missing") }
}
Write-Output "=== 6) staging tree still present? ==="
$stg = 'D:\program_runtime_environment\_downloads\dsh-stage'
if (Test-Path -LiteralPath $stg) {
  $s = (Get-ChildItem -LiteralPath $stg -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
  Write-Output ("  present: " + [Math]::Round($s/1MB,1) + " MB  (last write: " + (Get-Item -LiteralPath $stg).LastWriteTime + ")")
} else { Write-Output "  staging tree removed (suggests a cleanup after a successful swap)" }
Write-Output "=== 7) swap script artifacts (evidence the swap ran) ==="
Get-ChildItem -LiteralPath $prefix -Filter 'dsh*' -Force | Select-Object Name, Length, LastWriteTime | Format-Table -AutoSize | Out-String -Width 100", "description": "Check whether the harness upgrade happened"}

content.arguments:
{"command": "Write-Output "=== now ==="; Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
Write-Output ""
Write-Output "=== host process 11956: start time vs swap time (14:43) ==="
$h = Get-Process -Id 11956 -ErrorAction SilentlyContinue
if ($h) {
  Write-Output ("  pid " + $h.Id + " start " + $h.StartTime + "  (running for " + [Math]::Round(((Get-Date) - $h.StartTime).TotalMinutes,1) + " min)")
  Write-Output ("  started AFTER the swap: " + ($h.StartTime -gt (Get-Date '2026-09-28 14:43:11')))
} else { Write-Output "  pid 11956 not visible from this sandbox" }
Write-Output ""
Write-Output "=== composed tree file the host writes at boot ==="
$cy = 'C:\Users\徐丰哲\.dsh\profiles\web\cordis.yml'
$i = Get-Item -LiteralPath $cy -ErrorAction SilentlyContinue
if ($i) {
  Write-Output ("  " + $cy)
  Write-Output ("  modified: " + $i.LastWriteTime + "  size: " + $i.Length + " bytes")
  $t = [System.IO.File]::ReadAllText($cy, [System.Text.Encoding]::UTF8)
  Write-Output ("  contains 'dshmarket' : " + ($t -like '*dshmarket*'))
  Write-Output ("  mentions 0.1.7       : " + ($t -like '*0.1.7*'))
  ($t -split "`r?`n") | Where-Object { $_ -match 'dshmarket' } | Select-Object -First 5 | ForEach-Object { Write-Output ("    " + $_.Trim()) }
} else { Write-Output "  not found" }
Write-Output ""
Write-Output "=== profile manifest still intact (bundles + market dependency) ==="
$mp = 'C:\Users\徐丰哲\.dsh\profiles\web\package.json'
$pm = [System.IO.File]::ReadAllText($mp, [System.Text.Encoding]::UTF8) | ConvertFrom-Json
Write-Output ("  dependencies : " + ((@($pm.dependencies.PSObject.Properties) | ForEach-Object { $_.Name + '@' + $_.Value }) -join ', '))
Write-Output ("  bundles      : " + ($pm.dsh.profile.bundles -join ' -> '))
Write-Output ("  install record file time: " + (Get-Item -LiteralPath $mp).LastWriteTime)
Write-Output ""
Write-Output "=== market package still on disk ==="
$mk = 'C:\Users\徐丰哲\.dsh\profiles\web\node_modules\dshmarket\package.json'
if (Test-Path -LiteralPath $mk) { $m = [System.IO.File]::ReadAllText($mk, [System.Text.Encoding]::UTF8) | ConvertFrom-Json; Write-Output ("  dshmarket " + $m.version) } else { Write-Output "  dshmarket MISSING" }
Write-Output ""
Write-Output "=== reclaimable space ==="
foreach ($p in 'D:\program_runtime_environment\_downloads\dsh-stage', 'D:\program_runtime_environment\_caches\npm') {
  if (Test-Path -LiteralPath $p) {
    $s = (Get-ChildItem -LiteralPath $p -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
    Write-Output ("  " + $p + " = " + [Math]::Round($s/1MB,1) + " MB")
  }
}", "description": "Confirm host restart and new version active"}

