content.arguments:
{"command": "$pn = 'C:\Users\徐丰哲\.dsh\profiles\node_modules\@deepseek-ai'
Write-Output "=== profile links: version distribution ==="
$dirs = Get-ChildItem -LiteralPath $pn -Directory -Force -ErrorAction SilentlyContinue
$v = @{}
$stale = New-Object System.Collections.ArrayList
foreach ($d in $dirs) {
  $m = Join-Path $d.FullName 'package.json'
  if (-not (Test-Path -LiteralPath $m)) { continue }
  $ver = ([System.IO.File]::ReadAllText($m, [System.Text.Encoding]::UTF8) | ConvertFrom-Json).version
  if (-not $v.ContainsKey($ver)) { $v[$ver] = 0 }
  $v[$ver]++
  if ($ver -ne '0.1.7-rc.2') { [void]$stale.Add($d.Name + ' = ' + $ver) }
}
Write-Output ("  total linked packages: " + $dirs.Count)
foreach ($k in ($v.Keys | Sort-Object)) { Write-Output ("    " + $k + " : " + $v[$k]) }
if ($stale.Count) { Write-Output "  STALE (not 0.1.7-rc.2):"; $stale | Select-Object -First 15 | ForEach-Object { Write-Output ("    " + $_) } } else { Write-Output "  no stale links — every link resolves to 0.1.7-rc.2" }
Write-Output ""
Write-Output "=== profile-owned fallback dir (bundle-owned packages) ==="
$fb = 'C:\Users\徐丰哲\.dsh\profiles\web\.dsh-module-fallback\node_modules'
$c = @(Get-ChildItem -LiteralPath $fb -Force -ErrorAction SilentlyContinue)
Write-Output ("  entries: " + $c.Count)
$c | Select-Object -First 10 | ForEach-Object { Write-Output ("    " + $_.Name + "  link=" + $_.LinkType) }
Write-Output ""
Write-Output "=== any 0.1.5-rc.3 remnants left in the profile area? ==="
$hits = Get-ChildItem -LiteralPath 'C:\Users\徐丰哲\.dsh\profiles' -Recurse -Force -Filter 'package.json' -Depth 4 -ErrorAction SilentlyContinue |
  Where-Object { $_.FullName -notlike '*dshmarket*' } |
  ForEach-Object { try { $j = [System.IO.File]::ReadAllText($_.FullName, [System.Text.Encoding]::UTF8) | ConvertFrom-Json; if ($j.version -eq '0.1.5-rc.3') { $_.FullName } } catch { } }
if ($hits) { $hits | Select-Object -First 10 | ForEach-Object { Write-Output ("  " + $_) } } else { Write-Output "  none found in the searched depth" }
Write-Output ""
Write-Output "=== host/CLI summary ==="
Write-Output ("  installed package : " + (([System.IO.File]::ReadAllText((Join-Path $env:APPDATA 'npm\node_modules\@deepseek-ai\dsh\package.json'), [System.Text.Encoding]::UTF8) | ConvertFrom-Json).version))
& cmd.exe /c "`"$(Join-Path $env:APPDATA 'npm\dsh.cmd')`" --version" 2>&1 | Select-Object -First 1", "description": "Check for stale old-version links", "timeoutMs": 240000}

