content.arguments:
{"command": "$ErrorActionPreference = 'Stop'
$stg = 'D:\program_runtime_environment\_downloads\dsh-stage'
$prefixNodeModules = Join-Path $env:APPDATA 'npm\node_modules'
$dshVersion = ([System.IO.File]::ReadAllText((Join-Path $prefixNodeModules '@deepseek-ai\dsh\package.json'), [System.Text.Encoding]::UTF8) | ConvertFrom-Json).version

Write-Output '=== guard 1: the harness really is upgraded ==='
Write-Output ("  installed @deepseek-ai/dsh = " + $dshVersion)
if ($dshVersion -ne '0.1.7-rc.2') { Write-Output '  ABORT: refusing to delete staging while the installed version is not the staged one'; exit 1 }
Write-Output '  OK'

Write-Output ''
Write-Output '=== guard 2: no profile link points into the staging tree ==='
$linksChecked = 0
$bad = New-Object System.Collections.ArrayList
$targetKinds = @{}
foreach ($d in Get-ChildItem -LiteralPath (Join-Path $env:DSH_HOME 'profiles\node_modules') -Recurse -Force -Directory -Depth 1 -ErrorAction SilentlyContinue) {
  $it = Get-Item -LiteralPath $d.FullName -Force -ErrorAction SilentlyContinue
  if (-not $it -or -not $it.LinkType) { continue }
  $linksChecked++
  $target = @($it.Target) -join ';'
  if ($target -like "*$stg*") { [void]$bad.Add($d.FullName + ' -> ' + $target) }
  $key = 'other'
  if ($target -like "*$prefixNodeModules*") { $key = 'global npm prefix' }
  elseif ($target -like '*_downloads*') { $key = 'STAGING (_downloads)' }
  elseif ($target -like "*.dsh\profiles*") { $key = 'inside profiles' }
  if (-not $targetKinds.ContainsKey($key)) { $targetKinds[$key] = 0 }
  $targetKinds[$key]++
}
Write-Output ("  links inspected: " + $linksChecked)
foreach ($k in $targetKinds.Keys) { Write-Output ("    target -> " + $k + " : " + $targetKinds[$k]) }
if ($bad.Count -gt 0) { Write-Output '  ABORT: these links point into the staging tree:'; $bad | ForEach-Object { Write-Output ('    ' + $_) }; exit 1 }
Write-Output '  OK — nothing resolves through the staging tree'

Write-Output ''
Write-Output '=== action 1: delete the staging tree ==='
if (Test-Path -LiteralPath $stg) {
  $before = (Get-ChildItem -LiteralPath $stg -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum)
  Write-Output ("  removing " + $before.Count + " files / " + [Math]::Round($before.Sum/1MB,1) + " MB ...")
  Remove-Item -LiteralPath $stg -Recurse -Force
  Write-Output ("  deleted. still present: " + (Test-Path -LiteralPath $stg))
} else { Write-Output '  already gone' }
Write-Output ("  _downloads now contains: " + ((Get-ChildItem -LiteralPath 'D:\program_runtime_environment\_downloads' -Force | Select-Object -ExpandProperty Name) -join ', '))

Write-Output ''
Write-Output '=== action 2: sync the runtime-env README to D: ==='
$src = 'E:\Deepseek\policy\deploy\runtime-environment\README.md'
$dst = 'D:\program_runtime_environment\README.md'
Copy-Item -LiteralPath $src -Destination $dst -Force
$h1 = (Get-FileHash -LiteralPath $src).Hash
$h2 = (Get-FileHash -LiteralPath $dst).Hash
Write-Output ("  copied; hash match = " + ($h1 -eq $h2) + " ; size = " + (Get-Item $dst).Length + " bytes")
$t = [System.IO.File]::ReadAllText($dst, [System.Text.Encoding]::UTF8)
Write-Output ("  snapshot lists pnpm      : " + ($t -like '*| pnpm | 12.6.0*'))
Write-Output ("  wording fix present      : " + ($t -like '*权威来源*'))
Write-Output ("  duplicated blocks present: " + ($t -like '*保留期*保留期*'))

Write-Output ''
Write-Output '=== final D: runtime environment root ==='
Get-ChildItem -LiteralPath 'D:\program_runtime_environment' -Force | ForEach-Object {
  if ($_.PSIsContainer) {
    $s = (Get-ChildItem -LiteralPath $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
    [pscustomobject]@{ Item = $_.Name + '\'; Size = ([Math]::Round($s/1MB,1).ToString() + ' MB') }
  } else { [pscustomobject]@{ Item = $_.Name; Size = ([Math]::Round($_.Length/1KB,1).ToString() + ' KB') } }
} | Format-Table -AutoSize | Out-String -Width 80
