  } else { [pscustomobject]@{ Item = $_.Name; Size = ([Math]::Round($_.Length/1KB,1).ToString() + ' KB') } }
} | Format-Table -AutoSize | Out-String -Width 80
& 'D:\program_runtime_environment\tools\Add-RuntimeEnvironment.ps1' -Category cli -Name pnpm -Version '12.6.0' -InstallPath (Join-Path $env:APPDATA 'npm') -BinPaths @((Join-Path $env:APPDATA 'npm')) -Source 'npm install --global pnpm' -Notes 'Node CLI in the existing global npm prefix (shared with dsh); npm cache redirected to D:\program_runtime_environment\_caches\npm via npm_config_cache.' 2>&1 | Select-Object -Last 4", "description": "Delete staging tree and sync README", "justification": "按你确认清理 D:\program_runtime_environment 下的 454 MB 暂存树并同步运行环境文档，该路径在工作区之外，workspace-write 沙箱会拒绝写入。", "sandbox_permissions": "danger-full-access", "timeoutMs": 420000}

