content.arguments:
{"command": "$pat = '(?i)xiaomi|xiaoai|小爱|小米|miconnect|mishare|mipc|miui|smartshare|hyperos|妙享|mihome|mico'
Write-Output '=== processes whose path or name looks Xiaomi-ish ==='
Get-Process -ErrorAction SilentlyContinue | ForEach-Object {
  $p = $null; try { $p = $_.Path } catch { }
  if ($_.ProcessName -match $pat -or ($p -and $p -match $pat)) {
    [pscustomobject]@{ Id = $_.Id; Name = $_.ProcessName; Path = $p }
  }
} | Format-Table -AutoSize | Out-String -Width 160
Write-Output '=== services ==='
Get-Service -ErrorAction SilentlyContinue | Where-Object { $_.Name -match $pat -or $_.DisplayName -match $pat } | Select-Object Status, Name, DisplayName | Format-Table -AutoSize | Out-String -Width 160
Write-Output '=== all listening ports (with owning pid) ==='
$lines = netstat -ano 2>$null | Select-String 'LISTENING'
$rows = foreach ($l in $lines) {
  $parts = ($l.Line -replace '\s+', ' ').Trim().Split(' ')
  [pscustomobject]@{ Local = $parts[1]; Pid = $parts[-1] }
}
$rows | Sort-Object { [int]$_.Pid } | ForEach-Object {
  $n = (Get-Process -Id $_.Pid -ErrorAction SilentlyContinue).ProcessName
  "{0,-24} pid {1,-7} {2}" -f $_.Local, $_.Pid, $n
}", "description": "Look for Xiaomi processes services and ports", "timeoutMs": 180000}

{"command": "$pat = '(?i)xiaomi|xiaoai|小爱|小米|miconnect|mishare|mipc|miui|smartshare|hyperos|妙享|mihome'
Write-Output '=== installed programs mentioning Xiaomi / 小爱 ==='
$keys = 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*','HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*','HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*'
Get-ItemProperty $keys -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -match $pat } |
  Select-Object DisplayName, DisplayVersion, InstallLocation, Publisher | Format-List | Out-String -Width 200
Write-Output '=== directories in common install locations ==='
$roots = @($env:LOCALAPPDATA, $env:APPDATA, $env:ProgramFiles, ${env:ProgramFiles(x86)}, 'C:\ProgramData', 'D:\Application', 'D:\')
foreach ($r in $roots) {
  if (-not (Test-Path -LiteralPath $r)) { continue }
  $hits = Get-ChildItem -LiteralPath $r -Force -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match $pat }
  if ($hits) { foreach ($h in $hits) { Write-Output ("  " + $h.FullName) } }
}
Write-Output '=== Start menu shortcuts mentioning Xiaomi / 小爱 ==='
foreach ($sm in @("$env:ProgramData\Microsoft\Windows\Start Menu\Programs", "$env:APPDATA\Microsoft\Windows\Start Menu\Programs")) {
  Get-ChildItem -LiteralPath $sm -Recurse -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -match $pat } | Select-Object -First 20 -ExpandProperty FullName | ForEach-Object { Write-Output ("  " + $_) }
}", "description": "Search installed Xiaomi software and folders", "timeoutMs": 240000}

