content.arguments:
{"command": "Write-Output '=== resolve the Xiaomi shortcuts ==='
$sh = New-Object -ComObject WScript.Shell
foreach ($lnk in @(
  'C:\ProgramData\Microsoft\Windows\Start Menu\Programs\小米\超级小爱.lnk',
  'C:\ProgramData\Microsoft\Windows\Start Menu\Programs\小米\小米AI创作.lnk',
  'C:\ProgramData\Microsoft\Windows\Start Menu\Programs\小米\小米云服务.lnk')) {
  if (Test-Path -LiteralPath $lnk) {
    $s = $sh.CreateShortcut($lnk)
    Write-Output ("  " + (Split-Path -Leaf $lnk))
    Write-Output ("     target : " + $s.TargetPath)
    Write-Output ("     workdir: " + $s.WorkingDirectory)
    Write-Output ("     args   : " + $s.Arguments)
  }
}
Write-Output ''
Write-Output '=== what is listening on 127.0.0.1:9528 (pid 4556)? ==='
$cim = Get-CimInstance Win32_Process -Filter "ProcessId=4556" -ErrorAction SilentlyContinue
if ($cim) {
  Write-Output ("  name: " + $cim.Name)
  Write-Output ("  exe : " + $cim.ExecutablePath)
  Write-Output ("  cmd : " + $cim.CommandLine)
} else { Write-Output '  not readable via CIM from this sandbox (likely a service running as another account)' }
Write-Output '=== http probe of that port ==='
try {
  $r = Invoke-WebRequest -Uri 'http://127.0.0.1:9528/' -UseBasicParsing -TimeoutSec 8
  Write-Output ('  HTTP ' + $r.StatusCode + ' ; ' + $r.Content.Length + ' bytes')
  Write-Output ('  headers: ' + (($r.Headers.GetEnumerator() | ForEach-Object { $_.Key + '=' + $_.Value }) -join '; '))
  Write-Output ('  body head: ' + $r.Content.Substring(0, [Math]::Min(300, $r.Content.Length)))
} catch { Write-Output ('  probe failed: ' + $_.Exception.Message) }", "description": "Resolve shortcuts and probe local port", "timeoutMs": 180000}

