content.arguments:
{"command": "$pat = '(?i)^(mi|xiaomi|xiaoai|小爱|小米)|(?i)(xiaomi|xiaoai)'
Write-Output '=== user/app data dirs that could hold the knowledge base ==='
$candidates = @()
foreach ($root in @($env:LOCALAPPDATA, $env:APPDATA, 'C:\ProgramData', $env:USERPROFILE)) {
  if (-not (Test-Path -LiteralPath $root)) { continue }
  $candidates += Get-ChildItem -LiteralPath $root -Force -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match $pat }
  foreach ($sub in 'MI','Xiaomi','Xiaoai','Programs') {
    $p = Join-Path $root $sub
    if (Test-Path -LiteralPath $p) { $candidates += Get-ChildItem -LiteralPath $p -Force -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match $pat } }
  }
}
$candidates | Select-Object -Unique -ExpandProperty FullName | ForEach-Object { Write-Output ('  ' + $_) }
Write-Output ''
Write-Output '=== knowledge-base-ish stores: .db/.sqlite/.index/.faiss/.lance under those + MI dirs ==='
$searchRoots = @(
  (Join-Path $env:LOCALAPPDATA 'MI'), (Join-Path $env:LOCALAPPDATA 'Xiaomi'), (Join-Path $env:APPDATA 'MI'),
  (Join-Path $env:APPDATA 'XiaomiCloud'), (Join-Path $env:APPDATA 'XiaomiCloudStorage'),
  'C:\ProgramData\MI', 'D:\小米云盘'
) | Where-Object { Test-Path -LiteralPath $_ }
foreach ($r in $searchRoots) {
  Write-Output ('  --- ' + $r)
  Get-ChildItem -LiteralPath $r -Recurse -Force -File -ErrorAction SilentlyContinue |
    Where-Object { $_.Extension -match '(?i)\.(db|sqlite|sqlite3|index|faiss|lance|bin|json|leveldb|ldb|vec)$' -or $_.Name -match '(?i)knowledge|kb|vector|embed|rag|记忆|知识' } |
    Sort-Object Length -Descending | Select-Object -First 12 |
    ForEach-Object { Write-Output ('      ' + [Math]::Round($_.Length/1KB) + ' KB  ' + $_.LastWriteTime.ToString('yyyy-MM-dd HH:mm') + '  ' + $_.FullName.Substring($r.Length)) }
}", "description": "Locate local knowledge base data stores", "timeoutMs": 300000}

