$buf = New-Object byte[] 16
[void]$fs.Read($buf, 0, 16)
$fs.Close()
Write-Output ('  hex  : ' + (($buf | ForEach-Object { $_.ToString('x2') }) -join ' '))
Write-Output ('  ascii: ' + (-join ($buf | ForEach-Object { if ($_ -ge 32 -and $_ -lt 127) { [char]$_ } else { '.' } })))
Write-Output '=== rag document cache ==='
$docs = Join-Path $svc 'rag\CacheImage\docs'
if (Test-Path -LiteralPath $docs) {
  $d = Get-ChildItem -LiteralPath $docs -Directory -Force -ErrorAction SilentlyContinue
  Write-Output ('  document folders: ' + $d.Count)
  $d | Select-Object -First 3 | ForEach-Object {
    Write-Output ('  --- ' + $_.Name)
    Get-ChildItem -LiteralPath $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Select-Object -First 8 | ForEach-Object { Write-Output ('      ' + [Math]::Round($_.Length/1KB,1) + ' KB  ' + $_.FullName.Substring($_.FullName.IndexOf($_.Name.Split('\')[0]))) }
  }
} else { Write-Output '  (no rag cache dir)' }", "description": "Inspect AIService knowledge base structure", "timeoutMs": 240000}

