content.arguments:
{"command": "$svc = 'C:\ProgramData\MI\AIService'
Write-Output '=== permissions on the AI service data ==='
foreach ($p in $svc, (Join-Path $svc 'search\cache\ai_database1.db'), (Join-Path $svc 'db_key'), (Join-Path $svc 'rag')) {
  Write-Output ('  --- ' + $p)
  try {
    $acl = Get-Acl -LiteralPath $p -ErrorAction Stop
    Write-Output ('      owner: ' + $acl.Owner)
    $acl.Access | Select-Object -First 6 | ForEach-Object { Write-Output ('      ' + $_.IdentityReference + ' : ' + $_.FileSystemRights + ' (' + $_.AccessControlType + ')') }
  } catch { Write-Output ('      cannot read ACL: ' + $_.Exception.Message) }
}
Write-Output ''
Write-Output '=== can I read db_key at all? ==='
$k = Join-Path $svc 'db_key'
try { $b = [System.IO.File]::ReadAllBytes($k); Write-Output ('  read OK, ' + $b.Length + ' bytes, first bytes: ' + (($b[0..([Math]::Min(15,$b.Length-1))] | ForEach-Object { $_.ToString('x2') }) -join ' ')) } catch { Write-Output ('  read DENIED: ' + $_.Exception.Message) }
Write-Output ''
Write-Output '=== rag cache readability + total size ==='
$docs = Join-Path $svc 'rag\CacheImage\docs'
$d = Get-ChildItem -LiteralPath $docs -Directory -Force
Write-Output ('  document folders: ' + $d.Count)
foreach ($x in $d) {
  $m = Join-Path $x.FullName 'manifest.json'
  $ok = 'no manifest'
  if (Test-Path -LiteralPath $m) { try { $null = [System.IO.File]::ReadAllBytes($m).Length; $ok = 'manifest readable (' + [Math]::Round((Get-Item -LiteralPath $m).Length/1KB) + ' KB)' } catch { $ok = 'manifest DENIED: ' + $_.Exception.Message } }
  $img = (Get-ChildItem -LiteralPath (Join-Path $x.FullName 'images') -File -ErrorAction SilentlyContinue | Measure-Object).Count
  Write-Output ('    ' + $x.Name + ' : ' + $ok + ' ; images=' + $img + ' ; lastWrite=' + $x.LastWriteTime.ToString('yyyy-MM-dd HH:mm'))
}", "description": "Check ACLs and rag cache readability", "timeoutMs": 240000}

