content.arguments:
{"command": "$src = 'C:\ProgramData\MI\AIService\rag\cache'
$dst = 'E:\Deepseek\workspace\conv-20260928-3b54e160\mi-rag-probe'
New-Item -ItemType Directory -Force -Path $dst | Out-Null
Write-Output '=== can I read rag_db.db? ==='
foreach ($f in 'rag_db.db', 'rag_db.db-wal', 'rag_db.db-shm') {
  $s = Join-Path $src $f
  if (-not (Test-Path -LiteralPath $s)) { Write-Output ("  " + $f + " : absent"); continue }
  try {
    Copy-Item -LiteralPath $s -Destination (Join-Path $dst $f) -Force -ErrorAction Stop
    Write-Output ("  " + $f + " : copied (" + [Math]::Round((Get-Item -LiteralPath $s).Length/1MB,1) + " MB)")
  } catch { Write-Output ("  " + $f + " : COPY DENIED — " + $_.Exception.Message) }
}
Write-Output '=== sqlite header of the copy ==='
$db = Join-Path $dst 'rag_db.db'
if (Test-Path -LiteralPath $db) {
