{"command": "$probe = 'E:\Deepseek\workspace\conv-20260928-3b54e160\mi-rag-probe'
if (Test-Path -LiteralPath $probe) { Remove-Item -LiteralPath $probe -Recurse -Force; Write-Output 'removed the 82 MB probe copy (its DB turned out to be encrypted, so the copy is useless)' }
$lib = 'C:\ProgramData\MI\AIService\rag\cache\12354301785645805835\12354301785645805835default'
Write-Output ''
Write-Output '=== do the source PDFs carry a text layer? (heuristic: /Font objects + text-showing operators) ==='
Get-ChildItem -LiteralPath $lib -Force -File -Filter '*.pdf' | ForEach-Object {
  $fs = [System.IO.File]::Open($_.FullName, 'Open', 'Read', 'ReadWrite')
  $len = $fs.Length
  $take = [Math]::Min(4MB, $len)
  $buf = New-Object byte[] $take
  [void]$fs.Read($buf, 0, $take)
  $fs.Close()
  $txt = [System.Text.Encoding]::ASCII.GetString($buf)
  $fonts = ([regex]::Matches($txt, '/Font')).Count
  $tj = ([regex]::Matches($txt, '\bTJ\b|\bTj\b')).Count
  $imgs = ([regex]::Matches($txt, '/Subtype\s*/Image')).Count
  $verdict = 'no text layer (image-only, needs OCR)'
  if ($fonts -gt 2 -and $tj -gt 5) { $verdict = 'has a text layer (extractable)' }
  elseif ($fonts -gt 0) { $verdict = 'mixed / partial text layer' }
  [pscustomobject]@{ MB = [Math]::Round($_.Length/1MB,1); Fonts = $fonts; TjOps = $tj; ImgOps = $imgs; Verdict = $verdict; Name = $_.Name }
} | Format-Table -AutoSize | Out-String -Width 200
Write-Output '=== KB inventory artefact written earlier ==='
Get-Item -LiteralPath 'E:\Deepseek\logs\conv-20260928-3b54e160\mi-kb-inventory.json' | Select-Object FullName, Length | Format-List | Out-String", "description": "Check PDF text layers and clean probe", "timeoutMs": 240000}

