content.arguments:
{"command": "$root = 'C:\Program Files\MI\XiaoaiAgent\3.0.4.289'
Write-Output '=== knowledge-base UI bundle ==='
$kb = Join-Path $root 'dist\iframe-build\ai-knowledge'
if (Test-Path -LiteralPath $kb) { Get-ChildItem -LiteralPath $kb -Recurse -Force -File | Select-Object @{n='KB';e={[Math]::Round($_.Length/1KB,1)}}, Name | Format-Table -AutoSize | Out-String -Width 100 } else { Write-Output '  absent' }
Write-Output '=== keyword scan: does the UI offer export / download / backup? ==='
$keys = '导出','保存到本地','另存','下载','备份','分享','复制链接','上传','移除','删除','export','download','backup','saveAs','save-as'
$files = Get-ChildItem -LiteralPath (Join-Path $root 'dist') -Recurse -Force -File -Include '*.js','*.html','*.json' -ErrorAction SilentlyContinue | Where-Object { $_.Length -lt 8MB }
Write-Output ('  scanning ' + $files.Count + ' files ...')
$hits = 0
foreach ($f in $files) {
  $txt = [System.IO.File]::ReadAllText($f.FullName, [System.Text.Encoding]::UTF8)
  foreach ($k in $keys) {
    $i = $txt.IndexOf($k)
    if ($i -lt 0) { continue }
    $s = [Math]::Max(0, $i - 70); $len = [Math]::Min(160, $txt.Length - $s)
    $win = $txt.Substring($s, $len) -replace '\s+', ' '
    Write-Output ('  [' + $k + '] ' + $f.Name + ' :: ' + $win)
    $hits++
    if ($hits -ge 46) { break }
  }
  if ($hits -ge 46) { break }
}
if ($hits -eq 0) { Write-Output '  no keyword hits in the bundled UI assets' }", "description": "Scan knowledge base UI for export features", "timeoutMs": 300000}

