content.arguments:
{"command": "$kbJs = 'C:\Program Files\MI\XiaoaiAgent\3.0.4.289\dist\iframe-build\ai-knowledge\index.js'
$txt = [System.IO.File]::ReadAllText($kbJs, [System.Text.Encoding]::UTF8)
Write-Output ('=== KB bundle: ' + [Math]::Round($txt.Length/1KB) + ' KB ===')
# extract quoted literals that contain CJK characters
$rx = [regex]'"([^"\\]{2,60})"|''([^''\\]{2,60})'''
$cn = New-Object System.Collections.Generic.HashSet[string]
foreach ($m in $rx.Matches($txt)) {
  $s = if ($m.Groups[1].Success) { $m.Groups[1].Value } else { $m.Groups[2].Value }
  if ($s -match '[\u4e00-\u9fff]') { [void]$cn.Add($s) }
}
Write-Output ('  unique CJK UI strings: ' + $cn.Count)
Write-Output '  --- all of them (action words first) ---'
$list = $cn.ToArray()
$actions = $list | Where-Object { $_ -match '导出|下载|分享|另存|备份|保存|复制|上传|删除|移除|添加|新建|重命名|预览|查看|打开' } | Sort-Object
$others = $list | Where-Object { $_ -notmatch '导出|下载|分享|另存|备份|保存|复制|上传|删除|移除|添加|新建|重命名|预览|查看|打开' } | Sort-Object
foreach ($s in $actions) { Write-Output ('  [ACTION] ' + $s) }
Write-Output '  --- remaining strings ---'
$others | Select-Object -First 70 | ForEach-Object { Write-Output ('           ' + $_) }
Write-Output ''
Write-Output '=== how does the KB UI talk to the backend? (network / bridge patterns) ==='
foreach ($pat in 'postMessage', 'chrome\.webview', 'invoke\(', 'fetch\(', 'XMLHttpRequest', 'WebSocket', 'localhost', '127\.0\.0\.1', '/api/', 'mi-ai', 'i\.ai\.mi\.com') {
  $c = ([regex]::Matches($txt, $pat)).Count
  Write-Output ('  ' + $pat.PadRight(20) + ' x' + $c)
}", "description": "Extract knowledge base UI strings and API hints", "timeoutMs": 240000}

