Get-ChildItem -LiteralPath $kb -Recurse -Force -File | Sort-Object Length -Descending | Select-Object -First 15 @{n='rel';e={$_.FullName.Substring($kb.Length)}}, @{n='KB';e={[Math]::Round($_.Length/1KB,1)}} | Format-Table -AutoSize | Out-String -Width 120
Write-Output '=== JS bundles under it ==='
$js = Get-ChildItem -LiteralPath $kb -Recurse -Force -File -Filter '*.js'
$js | Select-Object @{n='rel';e={$_.FullName.Substring($kb.Length)}}, @{n='KB';e={[Math]::Round($_.Length/1KB,1)}} | Format-Table -AutoSize | Out-String -Width 120
foreach ($f in $js) {
  $txt = [System.IO.File]::ReadAllText($f.FullName, [System.Text.Encoding]::UTF8)
  $rx = [regex]'"([^"\\]{2,60})"|''([^''\\]{2,60})'''
  $cn = New-Object System.Collections.Generic.List[string]
  $seen = New-Object System.Collections.Generic.HashSet[string]
  foreach ($m in $rx.Matches($txt)) {
    $s = if ($m.Groups[1].Success) { $m.Groups[1].Value } else { $m.Groups[2].Value }
    if ($s -match '[\u4e00-\u9fff]' -and $seen.Add($s)) { [void]$cn.Add($s) }
  }
  Write-Output ''
  Write-Output ('=== ' + $f.Name + ' : ' + $cn.Count + ' unique CJK strings ===')
  $actions = @($cn | Where-Object { $_ -match '导出|下载|分享|另存|备份|保存|复制|上传|删除|移除|添加|新建|重命名|预览|查看|打开|生成' })
  Write-Output ('  action-ish (' + $actions.Count + '):')
  $actions | Sort-Object -Unique | Select-Object -First 40 | ForEach-Object { Write-Output ('    ' + $_) }
  Write-Output '  other strings (first 45):'
  @($cn | Where-Object { $_ -notmatch '导出|下载|分享|另存|备份|保存|复制|上传|删除|移除|添加|新建|重命名|预览|查看|打开|生成' }) | Sort-Object -Unique | Select-Object -First 45 | ForEach-Object { Write-Output ('    ' + $_) }
  Write-Output ('  network markers: postMessage=' + ([regex]::Matches($txt,'postMessage')).Count + ' fetch=' + ([regex]::Matches($txt,'fetch\(')).Count + ' http=' + ([regex]::Matches($txt,'https?://')).Count)
}", "description": "Extract CJK strings from knowledge base UI", "timeoutMs": 300000}

