content.arguments:
{"command": "$base = Join-Path $env:LOCALAPPDATA 'MI\XiaoaiAgent\EBWebView\Default'
foreach ($sub in 'IndexedDB', 'Local Storage\leveldb', 'Session Storage', 'databases') {
  $p = Join-Path $base $sub
  Write-Output ('=== ' + $sub + ' ===')
  if (-not (Test-Path -LiteralPath $p)) { Write-Output '  absent'; continue }
  $files = Get-ChildItem -LiteralPath $p -Recurse -Force -File -ErrorAction SilentlyContinue
  Write-Output ('  files: ' + $files.Count + ' ; total: ' + [Math]::Round((($files | Measure-Object Length -Sum).Sum)/1MB,2) + ' MB')
  Get-ChildItem -LiteralPath $p -Force -Directory -ErrorAction SilentlyContinue | Select-Object -First 10 | ForEach-Object {
    $s = (Get-ChildItem -LiteralPath $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
    Write-Output ('    ' + $_.Name + '  (' + [Math]::Round($s/1KB,1) + ' KB)')
  }
}
Write-Output ''
Write-Output '=== does the chat history contain readable text? (CJK probe on the leveldb) ==='
$idb = Join-Path $base 'IndexedDB'
$found = 0
Get-ChildItem -LiteralPath $idb -Recurse -Force -File -ErrorAction SilentlyContinue | Where-Object { $_.Length -gt 0 } | ForEach-Object {
  $bytes = [System.IO.File]::ReadAllBytes($_.FullName)
  $txt = [System.Text.Encoding]::UTF8.GetString($bytes)
  $m = [regex]::Matches($txt, '[\u4e00-\u9fff]{4,}')
  if ($m.Count -gt 0) {
    Write-Output ('  ' + $_.FullName.Substring($idb.Length) + ' -> ' + $m.Count + ' CJK runs; samples:')
    $m | Select-Object -First 6 | ForEach-Object { Write-Output ('      ' + $_.Value.Substring(0, [Math]::Min(60, $_.Value.Length))) }
    $found++
    if ($found -ge 3) { return }
  }
}
if ($found -eq 0) { Write-Output '  no readable CJK text found in IndexedDB blobs' }
Write-Output ''
Write-Output '=== KB-related log tail (does it name any callable route?) ==='
$log = 'C:\ProgramData\MI\AIService\log\ai_rag_business_log.txt'
if (Test-Path -LiteralPath $log) {
  $lines = [System.IO.File]::ReadAllLines($log, [System.Text.Encoding]::UTF8)
  Write-Output ('  lines: ' + $lines.Count + ' ; showing route/endpoint-ish lines:')
  $lines | Where-Object { $_ -match 'route|uri|api|http|handler|request|cmd|method' } | Select-Object -Last 12 | ForEach-Object { Write-Output ('    ' + $_.Substring(0, [Math]::Min(170, $_.Length))) }
}", "description": "Check local chat history and KB routes", "timeoutMs": 300000}

