{"command": "Write-Output '=== do your own originals exist elsewhere (云盘/下载)? ==='
$names = @('Advanced Modern Algebra','Introduction to Modern Algebra','欧姆社','漫画','近世代数')
$roots = @('D:\小米云盘', 'D:\Download', (Join-Path $env:USERPROFILE 'Documents'), (Join-Path $env:USERPROFILE 'Downloads'), 'C:\Users\徐丰哲\Xiaomi Cloud')
foreach ($r in $roots) {
  if (-not (Test-Path -LiteralPath $r)) { Write-Output ('  ' + $r + ' : absent'); continue }
  $hits = Get-ChildItem -LiteralPath $r -Recurse -Force -File -Filter '*.pdf' -ErrorAction SilentlyContinue |
    Where-Object { $n = $_.Name; ($names | Where-Object { $n -like ('*' + $_ + '*') }) }
  Write-Output ('  ' + $r + ' : ' + (@($hits).Count) + ' matching PDFs')
  $hits | Select-Object -First 12 | ForEach-Object { Write-Output ('      ' + [Math]::Round($_.Length/1MB,1) + ' MB  ' + $_.FullName) }
}
Write-Output ''
Write-Output '=== 超级小爱 cache dir listing (the copies) ==='
$lib = 'C:\ProgramData\MI\AIService\rag\cache\12354301785645805835\12354301785645805835default'
Get-ChildItem -LiteralPath $lib -Force -File | Select-Object @{n='MB';e={[Math]::Round($_.Length/1MB,1)}}, Name | Format-Table -AutoSize | Out-String -Width 120", "description": "Find original book files on disk", "timeoutMs": 300000}

