content.arguments:
{"command": "Write-Output '=== is THIS machine one of the two? ==='
try { $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction Stop; Write-Output ('  Manufacturer : ' + $cs.Manufacturer); Write-Output ('  Model        : ' + $cs.Model); Write-Output ('  Name         : ' + $cs.Name) } catch { Write-Output ('  Win32_ComputerSystem blocked: ' + $_.Exception.Message) }
try { $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop; Write-Output ('  Caption      : ' + $os.Caption); Write-Output ('  Version      : ' + $os.Version); Write-Output ('  BuildNumber  : ' + $os.BuildNumber); Write-Output ('  OSArch       : ' + $os.OSArchitecture) } catch { Write-Output ('  Win32_OperatingSystem blocked: ' + $_.Exception.Message) }
Write-Output ('  env OS       : ' + $env:OS)
$cv = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue
if ($cv) {
  Write-Output ('  ProductName  : ' + $cv.ProductName)
  Write-Output ('  DisplayVersion: ' + $cv.DisplayVersion)
  Write-Output ('  ReleaseId    : ' + $cv.ReleaseId)
  Write-Output ('  CurrentBuild : ' + $cv.CurrentBuild + '.' + $cv.UBR)
  Write-Output ('  EditionID    : ' + $cv.EditionID)
  Write-Output ('  InstallationType: ' + $cv.InstallationType)
}
Write-Output '=== hardware / connectivity hints ==='
try { $cs2 = Get-CimInstance Win32_Processor -ErrorAction Stop | Select-Object -First 1; Write-Output ('  CPU: ' + $cs2.Name) } catch { }
Get-PnpDevice -Class 'Display' -ErrorAction SilentlyContinue | Select-Object -First 5 FriendlyName, Status | Format-Table -AutoSize | Out-String -Width 100
Get-NetAdapter -ErrorAction SilentlyContinue | Select-Object Name, InterfaceDescription, Status, LinkSpeed | Format-Table -AutoSize | Out-String -Width 140
Write-Output '=== optional features relevant to screen extension ==='
& cmd.exe /c 'dism /online /get-capabilities' 2>&1 | Select-String -Pattern 'Wireless|Display|Miracast' | Select-Object -First 8", "description": "Identify local machine and capabilities", "timeoutMs": 240000}

