{"command": "$js = @'
// fetch-pages.js - fetch pages with node's own TLS stack and print keyword windows
// usage: node fetch-pages.js <keywordRegex> <url> [<url> ...]
const https = require('https');
const http = require('http');

function get(url, depth) {
  if ((depth || 0) > 5) return Promise.reject(new Error('too many redirects'));
  const mod = url.startsWith('http://') ? http : https;
  return new Promise((resolve, reject) => {
    const req = mod.get(url, { headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) dsh-fetch/1.0', 'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8' } }, (r) => {
      if (r.statusCode >= 300 && r.statusCode < 400 && r.headers.location) {
        r.resume();
        resolve(get(new URL(r.headers.location, url).toString(), (depth || 0) + 1));
        return;
      }
      if (r.statusCode !== 200) { r.resume(); reject(new Error('HTTP ' + r.statusCode)); return; }
      let d = ''; r.on('data', (c) => { d += c; }); r.on('end', () => resolve(d));
    });
    req.on('error', reject);
    req.setTimeout(25000, () => { req.destroy(); reject(new Error('timeout')); });
  });
}

function toText(html) {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#39;/g, "'").replace(/&quot;/g, '"')
    .replace(/\s+/g, ' ');
}

(async () => {
  const kw = new RegExp(process.argv[2], 'i');
  for (const url of process.argv.slice(3)) {
    console.log('\n===== ' + url);
    try {
      const text = toText(await get(url));
      console.log('  (text length ' + text.length + ')');
      let printed = 0;
      const parts = text.split(/(?<=[.!?。！？])\s+/);
      for (const p of parts) {
        if (kw.test(p) && p.length > 20) {
          console.log('  * ' + p.slice(0, 300));
          if (++printed >= 12) break;
        }
      }
      if (!printed) console.log('  (no keyword matches; head: ' + text.slice(0, 300) + ')');
    } catch (e) { console.log('  FETCH FAILED: ' + e.message); }
  }
})().catch((e) => { console.error('FATAL ' + e.message); process.exit(1); });
