// test-proxies.js - probe GitHub download proxies with a small ranged GET and report speed
const https = require('https');
const target = 'https://github.com/pavlobu/deskreen/releases/download/v3.2.16/deskreen-ce-3.2.16-x64.exe';
const proxies = [
  (u) => 'https://ghfast.top/' + u,
  (u) => 'https://gh-proxy.com/' + u,
  (u) => 'https://ghproxy.net/' + u,
  (u) => 'https://gh.llkk.cc/' + u,
  (u) => 'https://github.moeyy.xyz/' + u
];
function probe(url) {
  return new Promise((resolve) => {
    const t = Date.now();
    let bytes = 0;
    const req = https.get(url, { headers: { 'User-Agent': 'dsh/1.0', 'Range': 'bytes=0-1048575' } }, (r) => {
      if (r.statusCode >= 400) { r.resume(); resolve({ url, status: r.statusCode, note: 'HTTP ' + r.statusCode }); return; }
      r.on('data', (c) => { bytes += c.length; if (bytes > 1048576) r.destroy(); });
      const done = () => resolve({ url, status: r.statusCode, bytes, sec: (Date.now() - t) / 1000, kbps: Math.round(bytes / 1024 / ((Date.now() - t) / 1000)) });
      r.on('end', done);
      r.on('close', done);
    });
    req.on('error', (e) => resolve({ url, error: e.message }));
    req.setTimeout(20000, () => { req.destroy(); resolve({ url, error: 'timeout', bytes }); });
  });
}
(async () => {
  for (const make of proxies) {
    const u = make(target);
    const r = await probe(u);
    const host = new URL(u).host;
    if (r.error) console.log('  ' + host.padEnd(24) + ' FAILED  ' + r.error + (r.bytes ? ' (' + r.bytes + ' bytes)' : ''));
    else console.log('  ' + host.padEnd(24) + ' HTTP ' + r.status + '  ' + (r.bytes || 0) + ' bytes in ' + (r.sec || 0).toFixed(1) + 's  ' + (r.kbps || 0) + ' KB/s');
  }
})();
'@
