content.arguments:
{"command": "$c = @'
#Requires -Version 5.1
# finish-deskreen-install.ps1 - verify signatures and install Deskreen from the staged copy
param(
    [string]$Root = 'D:\program_runtime_environment'
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
function Step { param([string]$T) Write-Output ''; Write-Output ('=== ' + $T + ' ===') }
function Ok { param([string]$T) Write-Output ('[OK]   ' + $T) }
function Warn { param([string]$T) Write-Output ('[WARN] ' + $T) }

$exe = Join-Path $Root '_downloads\deskreen\deskreen-ce-3.2.16-x64.exe'
$vdd = Join-Path $Root 'cli\vdd-control\25.7.23'

Step '1. verify signatures of the staged packages'
$targets = @(
    $exe,
    (Join-Path $vdd 'SignedDrivers\x86\VDD\mttvdd.cat'),
    (Join-Path $vdd 'SignedDrivers\x86\VDD\MttVDD.dll'),
    (Join-Path $vdd 'Dependencies\devcon.exe')
)
$bad = 0
foreach ($f in $targets) {
    if (-not (Test-Path -LiteralPath $f)) { Warn ('missing: ' + $f); $bad++; continue }
    $sig = Get-AuthenticodeSignature -LiteralPath $f
    $who = if ($sig.SignerCertificate) { $sig.SignerCertificate.Subject } else { '(none)' }
    Write-Output ('    ' + $sig.Status.ToString().PadRight(8) + ' ' + (Split-Path -Leaf $f) + '  <- ' + $who)
    if ($sig.Status -ne 'Valid') { $bad++ }
}
if ($bad -gt 0) { Write-Output ('[FAIL] ' + $bad + ' signature problem(s)'); exit 1 }
Ok 'all signatures valid'

Step '2. install Deskreen silently'
$p = Start-Process -FilePath $exe -ArgumentList '/S' -Wait -PassThru
Write-Output ('    installer exit code: ' + $p.ExitCode)
Start-Sleep -Seconds 8

Step '3. locate the installation'
$roots = @((Join-Path $env:LOCALAPPDATA 'Programs'), $env:ProgramFiles, ${env:ProgramFiles(x86)})
$hits = @()
foreach ($r in $roots) {
    if (-not (Test-Path -LiteralPath $r)) { continue }
    $hits += Get-ChildItem -LiteralPath $r -Directory -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'deskreen' }
}
if ($hits) {
    foreach ($h in $hits) {
        Ok ('install dir: ' + $h.FullName)
        Get-ChildItem -LiteralPath $h.FullName -Recurse -Force -Filter '*.exe' -ErrorAction SilentlyContinue | Select-Object -First 4 | ForEach-Object { Write-Output ('      ' + $_.FullName) }
    }
} else { Warn 'no Deskreen install directory found (silent install may have failed or needs an interactive run)' }
Get-ChildItem -LiteralPath (Join-Path $env:APPDATA 'Microsoft\Windows\Start Menu\Programs') -Recurse -Filter '*Deskreen*' -ErrorAction SilentlyContinue | ForEach-Object { Ok ('start menu: ' + $_.FullName) }
Get-ChildItem -LiteralPath (Join-Path $env:USERPROFILE 'Desktop') -Filter '*Deskreen*' -ErrorAction SilentlyContinue | ForEach-Object { Ok ('desktop: ' + $_.FullName) }

Step 'done'
exit 0
'@
$p = 'E:\Deepseek\scripts\conv-20260928-3b54e160\finish-deskreen-install.ps1'
[System.IO.File]::WriteAllText($p, $c, (New-Object System.Text.UTF8Encoding($false)))
$errors = $null; [System.Management.Automation.Language.Parser]::ParseFile($p, [ref]$null, [ref]$errors) | Out-Null
if ($errors -and $errors.Count) { Write-Output 'PARSE ERRORS:'; $errors | ForEach-Object { $_.Message }; exit 1 }
Write-Output 'script ready, running ...'
powershell.exe -NoProfile -ExecutionPolicy Bypass -File $p
Write-Output "[exit code: $LASTEXITCODE]"", "description": "Verify signatures and install Deskreen", "justification": "Deskreen 安装包要写入 %LOCALAPPDATA%\Programs 与开始菜单，这些路径在工作区之外，workspace-write 沙箱会拒绝。", "sandbox_permissions": "danger-full-access", "run_in_background": true}

