  $sig = Get-AuthenticodeSignature -LiteralPath $proc.Path
  Write-Output ('      ' + $sig.Status + '  <- ' + ($sig.SignerCertificate.Subject))
} else { Write-Output 'process 17352 is gone' }
Write-Output ''
Write-Output '=== is Deskreen listening / serving a page? (its web server) ==='
