content.arguments:
{"command": "Write-Output '=== monitor-class devices ==='
& cmd.exe /c 'pnputil /enum-devices /class Monitor' 2>&1 | Select-String -Pattern 'Instance ID|Device Description|Status' | Select-Object -First 12
Write-Output ''
Write-Output '=== all display/monitor related PnP devices (PowerShell) ==='
foreach ($cls in 'Monitor', 'Display') {
  Write-Output ('  --- class ' + $cls)
  try {
    Get-PnpDevice -Class $cls -ErrorAction Stop | Select-Object Status, FriendlyName, InstanceId | Format-Table -AutoSize | Out-String -Width 140
  } catch { Write-Output ('      query failed: ' + $_.Exception.Message) }
}
Write-Output '=== VDD log / settings dir contents ==='
if (Test-Path -LiteralPath 'C:\VirtualDisplayDriver') {
  Get-ChildItem -LiteralPath 'C:\VirtualDisplayDriver' -Force | Select-Object Name, Length, LastWriteTime | Format-Table -AutoSize | Out-String -Width 100
} else { Write-Output '  dir missing' }
Write-Output '=== wait 10 s and re-check the screen count (monitor arrival can lag) ==='
Start-Sleep -Seconds 10
try {
  Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
  $s = [System.Windows.Forms.Screen]::AllScreens
  Write-Output ('  screens now: ' + $s.Count)
  foreach ($x in $s) { Write-Output ('    ' + $x.DeviceName + ' ' + $x.Bounds.Width + 'x' + $x.Bounds.Height + ' primary=' + $x.Primary) }
} catch { Write-Output ('  screen query failed: ' + $_.Exception.Message) }
Write-Output '=== display state via CCD API (query only) ==='
try {
  Add-Type -AssemblyName System.Drawing -ErrorAction Stop
  Write-Output '  (System.Drawing loaded; deeper CCD query needs a script — will use PowerShell + P/Invoke if needed)'
} catch { Write-Output ('  ' + $_.Exception.Message) }", "description": "Diagnose why virtual display has no monitor", "timeoutMs": 240000}

