{"command": "Write-Output '=== current screens (before) ==='
Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
[System.Windows.Forms.Screen]::AllScreens | ForEach-Object { Write-Output ('  ' + $_.DeviceName + '  ' + $_.Bounds.Width + 'x' + $_.Bounds.Height + '  primary=' + $_.Primary) }
Write-Output ''
Write-Output '=== ask Windows to extend onto the new display (built-in DisplaySwitch, no admin) ==='
$dsFile = Join-Path $env:SystemRoot 'System32\DisplaySwitch.exe'
Write-Output ('  tool: ' + $dsFile + '  exists=' + (Test-Path -LiteralPath $dsFile))
& $dsFile /extend
Start-Sleep -Seconds 5
Write-Output ''
Write-Output '=== screens (after /extend) ==='
[System.Windows.Forms.Screen]::AllScreens | ForEach-Object { Write-Output ('  ' + $_.DeviceName + '  ' + $_.Bounds.Width + 'x' + $_.Bounds.Height + '  primary=' + $_.Primary) }
Write-Output ''
Write-Output '=== enumerate all display targets via the CCD API (P/Invoke, read-only) ==='
$cs = @'
using System;
using System.Runtime.InteropServices;
public class CCD {
    [StructLayout(LayoutKind.Sequential)]
    public struct LUID { public uint LowPart; public int HighPart; }
    [StructLayout(LayoutKind.Sequential)]
    public struct DISPLAYCONFIG_PATH_SOURCE_INFO { public LUID adapterId; public uint id; public uint modeInfoIdx; public uint statusFlags; }
    [StructLayout(LayoutKind.Sequential)]
    public struct DISPLAYCONFIG_PATH_TARGET_INFO {
        public LUID adapterId; public uint id; public uint modeInfoIdx;
        public uint outputTechnology; public uint rotation; public uint scaling;
        public int refreshRateNumerator; public int refreshRateDenominator;
        public uint scanLineOrdering; public bool targetAvailable; public uint statusFlags;
    }
    [StructLayout(LayoutKind.Sequential)]
    public struct DISPLAYCONFIG_PATH_INFO { public DISPLAYCONFIG_PATH_SOURCE_INFO sourceInfo; public DISPLAYCONFIG_PATH_TARGET_INFO targetInfo; }
    [StructLayout(LayoutKind.Sequential)]
    public struct DISPLAYCONFIG_MODE_INFO { public uint infoType; public uint id; public LUID adapterId; public ulong pad1; public ulong pad2; public ulong pad3; public ulong pad4; }
    [StructLayout(LayoutKind.Sequential)]
    public struct DISPLAYCONFIG_DEVICE_INFO_HEADER { public uint type; public uint size; public LUID adapterId; public uint id; }
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    public struct DISPLAYCONFIG_TARGET_DEVICE_NAME {
        public DISPLAYCONFIG_DEVICE_INFO_HEADER header;
        public uint flags; public uint outputTechnology; public ushort edidManufactureId; public ushort edidProductCodeId;
        public uint connectorInstance;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 64)] public string monitorFriendlyDeviceName;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 128)] public string monitorDevicePath;
    }
    [DllImport("user32.dll")] public static extern int GetDisplayConfigBufferSizes(uint flags, out uint numPath, out uint numMode);
    [DllImport("user32.dll")] public static extern int QueryDisplayConfig(uint flags, ref uint numPath, [Out] DISPLAYCONFIG_PATH_INFO[] paths, ref uint numMode, [Out] DISPLAYCONFIG_MODE_INFO[] modes, IntPtr currentTopologyId);
    [DllImport("user32.dll")] public static extern int DisplayConfigGetDeviceInfo(ref DISPLAYCONFIG_TARGET_DEVICE_NAME name);
}
'@
try {
  Add-Type -TypeDefinition $cs -ErrorAction Stop
  $np = 0; $nm = 0
  [void][CCD]::GetDisplayConfigBufferSizes(2, [ref]$np, [ref]$nm)
  $paths = New-Object 'CCD+DISPLAYCONFIG_PATH_INFO[]' $np
  $modes = New-Object 'CCD+DISPLAYCONFIG_MODE_INFO[]' $nm
  $r = [CCD]::QueryDisplayConfig(2, [ref]$np, $paths, [ref]$nm, $modes, [IntPtr]::Zero)
  Write-Output ('  QueryDisplayConfig rc=' + $r + '  paths=' + $np)
  for ($i = 0; $i -lt $np; $i++) {
    $t = $paths[$i].targetInfo
    $n = New-Object 'CCD+DISPLAYCONFIG_TARGET_DEVICE_NAME'
    $n.header.type = 2
    $n.header.size = [System.Runtime.InteropServices.Marshal]::SizeOf($n)
    $n.header.adapterId = $t.adapterId
    $n.header.id = $t.id
    [void][CCD]::DisplayConfigGetDeviceInfo([ref]$n)
    $active = (($t.statusFlags -band 1) -eq 1)
    Write-Output ('    ' + $n.monitorFriendlyDeviceName.PadRight(28) + ' active=' + $active + '  avail=' + $t.targetAvailable + '  outputTech=' + $t.outputTechnology)
  }
} catch { Write-Output ('  CCD query failed: ' + $_.Exception.Message) }", "description": "Extend display and enumerate display targets", "timeoutMs": 300000}

