{"command": "$cs = @'
using System;
using System.Runtime.InteropServices;
public class DispTopo {
    [DllImport("user32.dll", SetLastError = true)]
    public static extern int SetDisplayConfig(uint numPathArrayElements, IntPtr pathArray,
        uint numModeInfoArrayElements, IntPtr modeInfoArray, uint flags);
}
'@
Add-Type -TypeDefinition $cs -ErrorAction Stop
# SDC_TOPOLOGY_EXTEND = 0x10, SDC_APPLY = 0x80, SDC_TOPOLOGY_SUPPLIED = 0x400 (not used)
$SDC_TOPOLOGY_EXTEND = 0x10
$SDC_APPLY = 0x80
Write-Output '=== before ==='
Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
[System.Windows.Forms.Screen]::AllScreens | ForEach-Object { Write-Output ('  ' + $_.DeviceName + '  ' + $_.Bounds.Width + 'x' + $_.Bounds.Height + '  primary=' + $_.Primary) }
Write-Output ''
Write-Output '=== SetDisplayConfig(SDC_TOPOLOGY_EXTEND | SDC_APPLY) ==='
$rc = [DispTopo]::SetDisplayConfig(0, [IntPtr]::Zero, 0, [IntPtr]::Zero, ($SDC_TOPOLOGY_EXTEND -bor $SDC_APPLY))
Write-Output ('  return code: ' + $rc + '  (0 = success)')
Start-Sleep -Seconds 4
Write-Output ''
Write-Output '=== after ==='
[System.Windows.Forms.Screen]::AllScreens | ForEach-Object { Write-Output ('  ' + $_.DeviceName + '  ' + $_.Bounds.Width + 'x' + $_.Bounds.Height + '  primary=' + $_.Primary) }
Write-Output ''
Write-Output '=== per-monitor effective DPI / count via WMI-free check ==='
Write-Output ('  screen count: ' + ([System.Windows.Forms.Screen]::AllScreens.Count))
Write-Output ('  virtual refresh mode (what Windows thinks):')
& cmd.exe /c 'wmic path Win32_VideoController get Name,CurrentHorizontalResolution,CurrentVerticalResolution /format:list' 2>&1 | Select-String -Pattern 'Name|Resolution' | Select-Object -First 8", "description": "Force extend topology via CCD API", "timeoutMs": 180000}

