content.arguments:
{"command": "Write-Output '=== 1) Deskreen 是否在运行 ==='
$p = Get-Process -Name 'Deskreen CE' -ErrorAction SilentlyContinue
if ($p) { $p | Select-Object Id, StartTime, @{n='WS_MB';e={[Math]::Round($_.WorkingSet64/1MB,1)}} | Format-Table -AutoSize | Out-String -Width 80 } else { Write-Output '  [未运行] 进程不存在 —— 如果它没开着，联想那边必然超时' }
Write-Output '=== 2) 它监听了哪些端口/地址（关键：是否 0.0.0.0） ==='
$pids = @($p | ForEach-Object { $_.Id })
if ($pids.Count) {
  $lines = netstat -ano 2>$null | Select-String 'LISTENING'
  $hit = $lines | Where-Object { $t = ($_.Line -replace '\s+',' ').Trim().Split(' ')[-1]; $pids -contains [int]$t }
  if ($hit) { $hit | ForEach-Object { Write-Output ('  ' + $_.Line.Trim()) } } else { Write-Output '  [无监听] Deskreen 进程存在但没有监听端口 —— 说明还没点 Allow，或服务启动失败' }
} else { Write-Output '  (跳过)' }
Write-Output '=== 3) 本机所有 IPv4 地址（联想要连的就是其中一个） ==='
& cmd.exe /c 'ipconfig | findstr /i "adapter IPv4 子网 Subnet"' 2>&1 | Select-Object -First 24
Write-Output '=== 4) 当前网络配置文件类型（公用=默认拦入站） ==='
& cmd.exe /c 'netsh advfirewall show currentprofile' 2>&1 | Select-String -Pattern 'Profile|State|Inbound|Firewall Policy|配置文件|状态|入站' | Select-Object -First 8
Write-Output '=== 5) 防火墙里有没有 Deskreen 的规则 ==='
& cmd.exe /c 'netsh advfirewall firewall show rule name=all' 2>&1 | Select-String -Pattern 'Deskreen' -Context 3,3 | Select-Object -First 12
Write-Output '=== 6) 本机自测：Deskreen 端口能否连通 ==='
if ($pids.Count) {
  $port = ($netstat -ano 2>$null | Select-String 'LISTENING' | Where-Object { $t = ($_.Line -replace '\s+',' ').Trim().Split(' ')[-1]; $pids -contains [int]$t } | ForEach-Object { [int](($_.Line -replace '\s+',' ').Trim().Split(' ')[1].Split(':')[-1]) } | Select-Object -First 1)
  if ($port) {
    Write-Output ('  探测端口 ' + $port)
    $r = Test-NetConnection -ComputerName '127.0.0.1' -Port $port -InformationLevel Quiet -WarningAction SilentlyContinue -ErrorAction SilentlyContinue
    if ($null -eq $r) { try { $t = New-Object System.Net.Sockets.TcpClient; $t.Connect('127.0.0.1', $port); Write-Output ('  127.0.0.1:' + $port + ' 连接成功'); $t.Close() } catch { Write-Output ('  127.0.0.1 连接失败: ' + $_.Exception.Message) } }
    else { Write-Output ('  本机回环连接: ' + $r) }
  }
}", "description": "Diagnose Deskreen server and firewall", "timeoutMs": 240000}

