content.arguments:
{"command": "Write-Output '=== 1) Deskreen 进程 ==='
$p = @(Get-Process -Name 'Deskreen CE' -ErrorAction SilentlyContinue)
if ($p.Count -gt 0) { $p | Select-Object Id, StartTime, @{n='WS_MB';e={[Math]::Round($_.WorkingSet64/1MB,1)}} | Format-Table -AutoSize | Out-String -Width 80 } else { Write-Output '  [未运行] —— 没开着的话联想必然超时' }
$pids = @($p | ForEach-Object { [int]$_.Id })
Write-Output ('  pids: ' + ($pids -join ', '))
Write-Output '=== 2) 监听端口（看是否 0.0.0.0 而非仅 127.0.0.1） ==='
$listen = @(netstat -ano 2>$null | Select-String 'LISTENING')
$mine = @()
foreach ($l in $listen) {
  $parts = ($l.Line -replace '\s+', ' ').Trim().Split(' ')
  $ownerPid = 0; [void][int]::TryParse($parts[$parts.Count - 1], [ref]$ownerPid)
  if ($pids -contains $ownerPid) { $mine += $parts[1]; Write-Output ('  ' + $parts[1] + '   (pid ' + $ownerPid + ')') }
}
if ($mine.Count -eq 0) { Write-Output '  [无监听] 进程在但没有监听端口 → 很可能还没点 Allow，或服务没起来' }
Write-Output '=== 3) 本机 IPv4 地址 ==='
& cmd.exe /c 'ipconfig' 2>&1 | Select-String -Pattern '适配器|adapter|IPv4|子网掩码|Subnet' | Select-Object -First 26 | ForEach-Object { Write-Output ('  ' + $_.Line.Trim()) }
Write-Output '=== 4) 防火墙当前配置 ==='
& cmd.exe /c 'netsh advfirewall show currentprofile' 2>&1 | Select-String -Pattern 'Profile Settings|State|Firewall Policy|Inbound|Outbound|配置文件设置|状态|入站|出站' | Select-Object -First 10 | ForEach-Object { Write-Output ('  ' + $_.Line.Trim()) }
Write-Output '=== 5) 是否有 Deskreen 相关防火墙规则 ==='
$rules = & cmd.exe /c 'netsh advfirewall firewall show rule name=all' 2>&1
$idx = 0; $shown = 0
foreach ($line in $rules) {
  if ($line -match 'Deskreen') { $shown++; Write-Output ('  > ' + $line.Trim()) }
}
if ($shown -eq 0) { Write-Output '  [无] 防火墙里没有任何 Deskreen 规则 —— 首次运行时若没点"允许访问"，入站就被拦' }
Write-Output '=== 6) 回环连通性自测 ==='
if ($mine.Count -gt 0) {
  $port = [int]($mine[0].Split(':')[-1])
  try {
    $t = New-Object System.Net.Sockets.TcpClient
    $t.Connect('127.0.0.1', $port)
    Write-Output ('  127.0.0.1:' + $port + ' -> 连接成功（服务本身在正常服务）')
    $t.Close()
  } catch { Write-Output ('  127.0.0.1:' + $port + ' -> 失败: ' + $_.Exception.Message) }
} else { Write-Output '  (无端口可测)' }", "description": "Diagnose Deskreen listening and firewall state", "timeoutMs": 240000}

