{"command": "Write-Output '=== 1) 本机探测 Deskreen 服务器返回什么 ==='
try {
  $r = Invoke-WebRequest -Uri 'http://127.0.0.1:3131/' -UseBasicParsing -TimeoutSec 10
  Write-Output ('  HTTP ' + $r.StatusCode + '  ' + $r.Content.Length + ' bytes')
  Write-Output ('  headers: ' + (($r.Headers.GetEnumerator() | ForEach-Object { $_.Key + '=' + $_.Value }) -join ' | '))
  Write-Output ('  body head: ' + $r.Content.Substring(0, [Math]::Min(400, $r.Content.Length)).Replace("`r", ' ').Replace("`n", ' '))
} catch { Write-Output ('  探测失败: ' + $_.Exception.Message) }
Write-Output ''
Write-Output '=== 2) 联想(192.168.71.5) 到本机 3131 的连接统计 ==='
$conns = netstat -ano 2>$null | Select-String ':3131'
$byState = @{}
foreach ($c in $conns) {
  $line = ($c.Line -replace '\s+', ' ').Trim()
  $parts = $line.Split(' ')
  $state = $parts[3]
  $peer = $parts[2]
  $key = $state + '  from ' + ($peer -replace ':\d+$', '')
  if (-not $byState.ContainsKey($key)) { $byState[$key] = 0 }
  $byState[$key]++
}
foreach ($k in ($byState.Keys | Sort-Object)) { Write-Output ('  ' + $k.PadRight(40) + ' x' + $byState[$k]) }
Write-Output ''
Write-Output '=== 3) 防火墙：Deskreen 的入站规则是否存在 ==='
try {
  $rules = Get-NetFirewallRule -ErrorAction Stop | Where-Object { $_.DisplayName -match '(?i)deskreen' }
  if ($rules) { $rules | Select-Object DisplayName, Enabled, Direction, Action, Profile | Format-Table -AutoSize | Out-String -Width 140 } else { Write-Output '  [无按名字匹配的规则]' }
} catch { Write-Output ('  Get-NetFirewallRule 失败: ' + $_.Exception.Message) }
try {
  $apps = Get-NetFirewallApplicationFilter -ErrorAction Stop | Where-Object { $_.Program -match '(?i)deskreen' }
  if ($apps) { $apps | Select-Object Program, InstanceID | Format-Table -AutoSize | Out-String -Width 160 } else { Write-Output '  [无按程序路径匹配的规则]' }
} catch { Write-Output ('  Get-NetFirewallApplicationFilter 失败: ' + $_.Exception.Message) }
Write-Output '=== 4) 防火墙各配置文件状态 ==='
try { Get-NetFirewallProfile -ErrorAction Stop | Select-Object Name, Enabled, DefaultInboundAction, DefaultOutboundAction | Format-Table -AutoSize | Out-String -Width 100 } catch { Write-Output ('  查询失败: ' + $_.Exception.Message) }
Write-Output '=== 5) 当前活动网络配置（公用/专用） ==='
try { Get-NetConnectionProfile -ErrorAction Stop | Select-Object InterfaceAlias, NetworkCategory, IPv4Connectivity | Format-Table -AutoSize | Out-String -Width 100 } catch { Write-Output ('  查询失败: ' + $_.Exception.Message) }", "description": "Probe Deskreen server and firewall rules", "timeoutMs": 240000}

