content.arguments:
{"command": "$cs = @'
using System;
using System.Runtime.InteropServices;
public class CCD2 {
    [StructLayout(LayoutKind.Sequential)] public struct LUID { public uint LowPart; public int HighPart; }
    [StructLayout(LayoutKind.Sequential)] public struct RATIONAL { public uint Numerator; public uint Denominator; }
    [StructLayout(LayoutKind.Sequential)] public struct REGION2D { public uint cx; public uint cy; }
    [StructLayout(LayoutKind.Sequential)] public struct SIGNALINFO {
        public ulong pixelRate; public RATIONAL hSyncFreq; public RATIONAL vSyncFreq;
        public REGION2D activeSize; public REGION2D totalSize; public uint videoStandard; public uint scanLineOrdering;
    }
    [StructLayout(LayoutKind.Sequential)] public struct TARGETMODE { public SIGNALINFO info; }
    [StructLayout(LayoutKind.Sequential)] public struct SOURCEMODE { public uint width; public uint height; public uint pixelFormat; public int posX; public int posY; }
    [StructLayout(LayoutKind.Sequential)] public struct MODEINFO {
        public uint infoType; public uint id; public LUID adapterId;
        public TARGETMODE target; public SOURCEMODE source;   // overlapped union, oversized on purpose
    }
    [StructLayout(LayoutKind.Sequential)] public struct PATH_SOURCE { public LUID adapterId; public uint id; public uint modeInfoIdx; public uint statusFlags; }
    [StructLayout(LayoutKind.Sequential)] public struct PATH_TARGET {
        public LUID adapterId; public uint id; public uint modeInfoIdx;
        public uint outputTechnology; public uint rotation; public uint scaling;
        public int refreshNumerator; public int refreshDenominator; public uint scanLineOrdering;
        public int targetAvailable; public uint statusFlags;
    }
    [StructLayout(LayoutKind.Sequential)] public struct PATHINFO { public PATH_SOURCE sourceInfo; public PATH_TARGET targetInfo; }
    [StructLayout(LayoutKind.Sequential)] public struct DEVICEINFOHEADER { public uint type; public uint size; public LUID adapterId; public uint id; }
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)] public struct TARGETNAME {
        public DEVICEINFOHEADER header; public uint flags; public uint outputTechnology;
        public ushort edidManufactureId; public ushort edidProductCodeId; public uint connectorInstance;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 64)] public string friendlyName;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 128)] public string devicePath;
    }
    [DllImport("user32.dll")] public static extern int GetDisplayConfigBufferSizes(uint flags, out uint numPath, out uint numMode);
    [DllImport("user32.dll")] public static extern int QueryDisplayConfig(uint flags, ref uint numPath, [Out] PATHINFO[] paths, ref uint numMode, [Out] MODEINFO[] modes, IntPtr topoId);
    [DllImport("user32.dll")] public static extern int DisplayConfigGetDeviceInfo(ref TARGETNAME name);
}
'@
Add-Type -TypeDefinition $cs -ErrorAction Stop
$np = 0; $nm = 0
[void][CCD2]::GetDisplayConfigBufferSizes(2, [ref]$np, [ref]$nm)   # QDC_ONLY_ACTIVE_PATHS
$paths = New-Object 'CCD2+PATHINFO[]' $np
$modes = New-Object 'CCD2+MODEINFO[]' $nm
$rc = [CCD2]::QueryDisplayConfig(2, [ref]$np, $paths, [ref]$nm, $modes, [IntPtr]::Zero)
Write-Output ("QueryDisplayConfig rc=$rc  active paths=$np  modes=$nm")
Write-Output ''
for ($i = 0; $i -lt $np; $i++) {
  $p = $paths[$i]
  $srcIdx = [int]$p.sourceInfo.modeInfoIdx
  $tgtIdx = [int]$p.targetInfo.modeInfoIdx
  $srcW = 0; $srcH = 0; $srcX = 0; $srcY = 0; $hz = 0
  if ($srcIdx -ge 0 -and $srcIdx -lt $nm -and $modes[$srcIdx].infoType -eq 1) {
    $srcW = $modes[$srcIdx].source.width; $srcH = $modes[$srcIdx].source.height
    $srcX = $modes[$srcIdx].source.posX; $srcY = $modes[$srcIdx].source.posY
  }
  if ($tgtIdx -ge 0 -and $tgtIdx -lt $nm -and $modes[$tgtIdx].infoType -eq 2) {
    $r = $modes[$tgtIdx].target.info.vSyncFreq
    if ($r.Denominator -ne 0) { $hz = [Math]::Round($r.Numerator / $r.Denominator, 1) }
  }
  $nmObj = New-Object 'CCD2+TARGETNAME'
  $nmObj.header.type = 2
  $nmObj.header.size = [System.Runtime.InteropServices.Marshal]::SizeOf($nmObj)
  $nmObj.header.adapterId = $p.targetInfo.adapterId
  $nmObj.header.id = $p.targetInfo.id
  [void][CCD2]::DisplayConfigGetDeviceInfo([ref]$nmObj)
  $active = (($p.sourceInfo.statusFlags -band 1) -eq 1) -and (($p.targetInfo.statusFlags -band 1) -eq 1)
  Write-Output ("  显示器: " + $(if ($nmObj.friendlyName) { $nmObj.friendlyName } else { '(名称读取失败)' }))
  Write-Output ("      分辨率   : " + $srcW + 'x' + $srcH + "   刷新率: " + $hz + " Hz   位置: (" + $srcX + ',' + $srcY + ")   活动=" + $active)
  Write-Output ("      outputTech: " + $p.targetInfo.outputTechnology + "   rotation: " + $p.targetInfo.rotation)
}
Write-Output ''
Write-Output '=== 当前生效的 VDD 配置 ==='
$xml = 'C:\VirtualDisplayDriver\vdd_settings.xml'
if (Test-Path -LiteralPath $xml) {
