Write-Output '=== 当前生效的 VDD 配置 ==='
$xml = 'C:\VirtualDisplayDriver\vdd_settings.xml'
if (Test-Path -LiteralPath $xml) {
  $x = [xml](Get-Content -LiteralPath $xml -Raw)
  Write-Output ('  虚拟屏数量: ' + $x.vdd_settings.monitors.count)
  Write-Output '  可选分辨率（顺序即 EDID 首选顺序）:'
  foreach ($r in $x.vdd_settings.resolutions.resolution) { Write-Output ('    ' + $r.width + 'x' + $r.height + ' @ ' + $r.refresh_rate) }
} else { Write-Output '  配置文件不存在' }", "description": "Read actual display resolutions via CCD", "timeoutMs": 240000}

