{"command": "$cs = @'
using System;
using System.Runtime.InteropServices;
public class CCD3 {
    [StructLayout(LayoutKind.Sequential)] public struct LUID { public uint LowPart; public int HighPart; }
    [StructLayout(LayoutKind.Sequential)] public struct PATH_SOURCE { public LUID adapterId; public uint id; public uint modeInfoIdx; public uint statusFlags; }
    [StructLayout(LayoutKind.Sequential)] public struct PATH_TARGET {
        public LUID adapterId; public uint id; public uint modeInfoIdx;
        public uint outputTechnology; public uint rotation; public uint scaling;
        public int refreshNumerator; public int refreshDenominator; public uint scanLineOrdering;
        public int targetAvailable; public uint statusFlags;
    }
    [StructLayout(LayoutKind.Sequential)] public struct PATHINFO { public PATH_SOURCE sourceInfo; public PATH_TARGET targetInfo; }
    [StructLayout(LayoutKind.Explicit, Size = 64)]
    public struct MODEINFO {
        [FieldOffset(0)]  public uint infoType;
        [FieldOffset(4)]  public uint id;
        [FieldOffset(8)]  public LUID adapterId;
        [FieldOffset(16)] public uint srcWidth;
        [FieldOffset(20)] public uint srcHeight;
        [FieldOffset(28)] public int  srcPosX;
        [FieldOffset(32)] public int  srcPosY;
        [FieldOffset(32)] public uint tgtVsyncNum;
        [FieldOffset(36)] public uint tgtVsyncDen;
        [FieldOffset(40)] public uint tgtActiveCx;
        [FieldOffset(44)] public uint tgtActiveCy;
    }
    [StructLayout(LayoutKind.Sequential)] public struct DEVICEINFOHEADER { public uint type; public uint size; public LUID adapterId; public uint id; }
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)] public struct TARGETNAME {
        public DEVICEINFOHEADER header; public uint flags; public uint outputTechnology;
        public ushort edidManufactureId; public ushort edidProductCodeId; public uint connectorInstance;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 64)] public string friendlyName;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 128)] public string devicePath;
    }
    [DllImport("user32.dll")] public static extern int GetDisplayConfigBufferSizes(uint flags, out uint numPath, out uint numMode);
    [DllImport("user32.dll")] public static extern int QueryDisplayConfig(uint flags, ref uint numPath, [Out] PATHINFO[] paths, ref uint numMode, [Out] MODEINFO[] modes, IntPtr topoId);
    [DllImport("user32.dll")] public static extern int DisplayConfigGetDeviceInfo(ref TARGETNAME name);
}
'@
Add-Type -TypeDefinition $cs -ErrorAction Stop
$np = 0; $nm = 0
[void][CCD3]::GetDisplayConfigBufferSizes(2, [ref]$np, [ref]$nm)
$paths = New-Object 'CCD3+PATHINFO[]' $np
$modes = New-Object 'CCD3+MODEINFO[]' $nm
$rc = [CCD3]::QueryDisplayConfig(2, [ref]$np, $paths, [ref]$nm, $modes, [IntPtr]::Zero)
Write-Output ("rc=$rc  活动路径=$np  模式条目=$nm   (MODEINFO 大小应为 64: " + [System.Runtime.InteropServices.Marshal]::SizeOf([type]'CCD3+MODEINFO') + ")")
Write-Output ''
for ($i = 0; $i -lt $np; $i++) {
  $p = $paths[$i]
  $si = [int]$p.sourceInfo.modeInfoIdx
  $ti = [int]$p.targetInfo.modeInfoIdx
  $nm2 = New-Object 'CCD3+TARGETNAME'
  $nm2.header.type = 2
  $nm2.header.size = [System.Runtime.InteropServices.Marshal]::SizeOf($nm2)
  $nm2.header.adapterId = $p.targetInfo.adapterId
  $nm2.header.id = $p.targetInfo.id
  [void][CCD3]::DisplayConfigGetDeviceInfo([ref]$nm2)
  Write-Output ("路径 " + ($i+1) + "  " + $(if ($nm2.friendlyName) { $nm2.friendlyName } else { '(名称不可读)' }))
  if ($si -ge 0 -and $si -lt $nm) {
    $m = $modes[$si]
    Write-Output ("    源模式  : " + $m.srcWidth + 'x' + $m.srcHeight + "  位置(" + $m.srcPosX + ',' + $m.srcPosY + ")  infoType=" + $m.infoType)
  } else { Write-Output ("    源模式索引无效: " + $si) }
  if ($ti -ge 0 -and $ti -lt $nm) {
    $m2 = $modes[$ti]
    $hz = if ($m2.tgtVsyncDen -ne 0) { [Math]::Round($m2.tgtVsyncNum / $m2.tgtVsyncDen, 1) } else { 0 }
    Write-Output ("    目标模式: " + $m2.tgtActiveCx + 'x' + $m2.tgtActiveCy + "  " + $hz + " Hz  infoType=" + $m2.infoType)
  } else { Write-Output ("    目标模式索引无效: " + $ti) }
  Write-Output ("    outputTech=" + $p.targetInfo.outputTechnology + "  rotation=" + $p.targetInfo.rotation + "  scaling=" + $p.targetInfo.scaling)
}", "description": "Read exact per-display resolutions", "timeoutMs": 180000}

