content.arguments:
{"command": "Write-Output '=== 图形驱动配置里记录的每块显示器分辨率 ==='
$base = 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers\Configuration'
$keys = Get-ChildItem -Path $base -ErrorAction SilentlyContinue
if (-not $keys) { Write-Output '  (无法枚举，可能权限不足)' }
foreach ($k in $keys) {
  foreach ($sub in (Get-ChildItem -Path $k.PSPath -Recurse -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^\d+$' })) {
    $p = Get-ItemProperty -Path $sub.PSPath -ErrorAction SilentlyContinue
    if ($p -and ($p.PSObject.Properties.Name -contains 'PrimSurfSize.cx')) {
      $cx = $p.'PrimSurfSize.cx'; $cy = $p.'PrimSurfSize.cy'
      $acx = $p.'ActiveSize.cx';  $acy = $p.'ActiveSize.cy'
      if ($cx -and $cx -gt 0) {
        Write-Output ('  ' + $k.PSChildName.Substring(0, [Math]::Min(28, $k.PSChildName.Length)) + '...  ->  ' + $cx + 'x' + $cy + '   (活动区 ' + $acx + 'x' + $acy + ')')
      }
    }
  }
}
Write-Output ''
Write-Output '=== 按显示器实例名的另一种读法 ==='
$mon = 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers\Connectivity'
Get-ChildItem -Path $mon -Recurse -ErrorAction SilentlyContinue | Select-Object -First 5 -ExpandProperty Name | ForEach-Object { Write-Output ('  ' + $_) }
Write-Output ''
Write-Output '=== 虚拟屏驱动当前启用的模式（通过 devcon 只读查询，无需提权） ==='
$devcon = 'D:\program_runtime_environment\cli\vdd-control\25.7.23\Dependencies\devcon.exe'
if (Test-Path -LiteralPath $devcon) {
  & cmd.exe /c "`"$devcon`" status Root\MttVDD" 2>&1 | Select-Object -First 6 | ForEach-Object { Write-Output ('  ' + $_) }
  & cmd.exe /c "`"$devcon`" find Root\MttVDD" 2>&1 | Select-Object -First 6 | ForEach-Object { Write-Output ('  ' + $_) }
}", "description": "Read display resolutions from registry", "timeoutMs": 240000}

