  Write-Output ('  app.asar: ' + [Math]::Round((Get-Item -LiteralPath $asar).Length/1MB,1) + ' MB')
  $bytes = [System.IO.File]::ReadAllBytes($asar)
  $txt = [System.Text.Encoding]::UTF8.GetString($bytes)
  Write-Output '  --- 含 quality / 画质 的片段 ---'
  $hits = [regex]::Matches($txt, '(?i).{70}quality.{90}')
  $seen = New-Object System.Collections.Generic.HashSet[string]
  $n = 0
  foreach ($h in $hits) {
    $s = ($h.Value -replace '\s+', ' ')
    if ($seen.Add($s)) { Write-Output ('    ' + $s); if (++$n -ge 12) { break } }
  }
  Write-Output '  --- 分辨率/码率相关片段 ---'
  $hits2 = [regex]::Matches($txt, '(?i).{50}(360p|480p|720p|1080p|bitrate|scaledWidth|thumbnailSize).{70}')
  $n2 = 0
