{"command": "$asar = 'D:\program_runtime_environment\cli\deskreen\3.2.16\resources\app.asar'
$bytes = [System.IO.File]::ReadAllBytes($asar)
$txt = [System.Text.Encoding]::UTF8.GetString($bytes)
Write-Output '=== 画质档位的 UI 文案 / 键名 ==='
$pats = @('qualityLow','qualityMedium','qualityHigh','qualityBest','qualityUltra','"low"','"medium"','"high"','"best"','画质','清晰','流畅','更低','更高')
$seen = New-Object System.Collections.Generic.HashSet[string]
foreach ($p in $pats) {
  foreach ($m in [regex]::Matches($txt, '.{0,60}' + [regex]::Escape($p) + '.{0,80}')) {
    $s = ($m.Value -replace '\s+', ' ')
    if ($seen.Add($s)) { Write-Output ('  [' + $p + '] ' + $s); break }
  }
}
Write-Output ''
Write-Output '=== 采集尺寸 / 分辨率相关代码 ==='
foreach ($m in [regex]::Matches($txt, '(?i).{0,80}(thumbnailSize|scaledWidth|scaledHeight|setThumbnailSize|maxWidth|videoWidth).{0,100}')) {
  $s = ($m.Value -replace '\s+', ' ')
  if ($seen.Add($s)) { Write-Output ('  ' + $s) }
}
Write-Output ''
Write-Output '=== 自动降质逻辑的上下文 ==='
$i = $txt.IndexOf('startOptimizationLoop')
if ($i -gt 0) {
  $seg = $txt.Substring([Math]::Max(0, $i - 1200), 2200) -replace '\s+', ' '
  Write-Output ('  ' + $seg.Substring(0, [Math]::Min(1600, $seg.Length)))
}", "description": "Extract Deskreen quality presets from app package", "timeoutMs": 300000}

