content.arguments:
{"command": "$asar = 'D:\program_runtime_environment\cli\deskreen\3.2.16\resources\app.asar'
$bytes = [System.IO.File]::ReadAllBytes($asar)
$txt = [System.Text.Encoding]::UTF8.GetString($bytes)
Write-Output ('asar 文本长度: ' + $txt.Length)

function Show-Window {
  param([string]$Needle, [int]$Before = 260, [int]$Len = 520, [int]$Max = 2)
  $from = 0; $n = 0
  while ($n -lt $Max) {
    $i = $txt.IndexOf($Needle, $from)
    if ($i -lt 0) { break }
    $s = [Math]::Max(0, $i - $Before)
    $seg = $txt.Substring($s, [Math]::Min($Len, $txt.Length - $s)) -replace '\s+', ' '
    Write-Output ('  --- ' + $Needle + ' #' + ($n+1) + ' ---')
    Write-Output ('      ' + $seg)
    $from = $i + $Needle.Length
    $n++
  }
  if ($n -eq 0) { Write-Output ('  (未找到 ' + $Needle + ')') }
}

Write-Output ''
Write-Output '=== 画质相关的关键标识 ==='
foreach ($k in 'isRequestedHalfQuality', 'thumbnailSize', 'quality', 'setGoodQuality', 'startOptimizationLoop') {
  $count = 0; $from = 0
  while (($from = $txt.IndexOf($k, $from)) -ge 0) { $count++; $from += $k.Length }
  Write-Output ('  ' + $k.PadRight(26) + ' 出现 ' + $count + ' 次')
}
Write-Output ''
Show-Window -Needle 'startOptimizationLoop' -Before 400 -Len 700 -Max 1
Write-Output ''
Show-Window -Needle 'isRequestedHalfQuality' -Before 200 -Len 380 -Max 2
Write-Output ''
Show-Window -Needle 'thumbnailSize' -Before 300 -Len 500 -Max 3", "description": "Targeted scan of Deskreen quality logic", "timeoutMs": 300000}

