{"command": "$js = @'
// inspect-viewer.js - fetch the Deskreen viewer page and scan its scripts for quality controls
const http = require('http');
function get(url) {
  return new Promise((resolve, reject) => {
    http.get(url, { headers: { 'User-Agent': 'dsh-inspect/1.0' } }, (r) => {
      if (r.statusCode >= 300 && r.statusCode < 400 && r.headers.location) { r.resume(); resolve(get(new URL(r.headers.location, url).toString())); return; }
      if (r.statusCode !== 200) { r.resume(); reject(new Error('HTTP ' + r.statusCode)); return; }
      let d = ''; r.on('data', (c) => { d += c; }); r.on('end', () => resolve(d));
    }).on('error', reject);
  });
}
(async () => {
  const base = 'http://127.0.0.1:3131';
  const html = await get(base + '/');
  const srcs = [...html.matchAll(/<script[^>]+src="([^"]+)"/g)].map((m) => m[1]);
  console.log('viewer html: ' + html.length + ' bytes; scripts: ' + srcs.length);
  for (const s of srcs) console.log('   ' + s);
  for (const s of srcs) {
    const url = s.startsWith('http') ? s : base + (s.startsWith('/') ? s : '/' + s);
    let code;
    try { code = await get(url); } catch (e) { console.log('  fetch failed ' + url + ': ' + e.message); continue; }
    console.log('\n===== ' + url + '  (' + (code.length / 1024).toFixed(0) + ' KB)');
    const keys = ['quality', 'Quality', 'HD', 'SD', 'auto', 'bitrate', 'resolution', '1080', '720', 'videoQuality', 'levels'];
    const seen = new Set();
    let printed = 0;
    for (const k of keys) {
      let idx = 0;
      while (printed < 26) {
        idx = code.indexOf(k, idx);
        if (idx < 0) break;
        const s2 = Math.max(0, idx - 90);
        const w = code.slice(s2, idx + 120).replace(/\s+/g, ' ');
        if (!seen.has(w)) { seen.add(w); console.log('  [' + k + '] ' + w); printed++; }
        idx += k.length;
      }
    }
    if (printed === 0) console.log('  (no quality-related strings)');
  }
})().catch((e) => { console.error('FATAL ' + e.message); process.exit(1); });
'@
