& 'D:\program_runtime_environment\nodejs\node.exe' --check $p
& 'D:\program_runtime_environment\nodejs\node.exe' $p 2>&1 | Select-Object -First 60", "description": "Inspect Deskreen viewer page for quality controls", "timeoutMs": 300000}

