content.arguments:
{"command": "Write-Output '=== 1) VDD 驱动包信息（用于 pnputil 删除） ==='
& cmd.exe /c 'pnputil /enum-drivers' 2>&1 | Select-String -Pattern 'Published Name|Original Name|Provider Name|Class Name' -Context 0,0 | Select-Object -First 40 | ForEach-Object { Write-Output ('  ' + $_.Line.Trim()) }
Write-Output ''
Write-Output '=== 2) 设备实例 ID（Display / Monitor 两类） ==='
& cmd.exe /c 'pnputil /enum-devices /class Display' 2>&1 | Select-String -Pattern 'Instance ID|Device Description|Status|Driver Name' | ForEach-Object { Write-Output ('  ' + $_.Line.Trim()) }
& cmd.exe /c 'pnputil /enum-devices /class Monitor' 2>&1 | Select-String -Pattern 'Instance ID|Device Description|Status' | ForEach-Object { Write-Output ('  ' + $_.Line.Trim()) }
Write-Output ''
Write-Output '=== 3) Deskreen 进程与端口 ==='
Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -match '(?i)deskreen' } | Select-Object Id, ProcessName, Path | Format-Table -AutoSize | Out-String -Width 140
$l = netstat -ano 2>$null | Select-String ':3131' | Select-String 'LISTENING'
if ($l) { Write-Output ('  3131 监听中: ' + $l[0].Line.Trim()) } else { Write-Output '  3131 未监听' }
Write-Output ''
Write-Output '=== 4) 要删除的目录/快捷方式清单 ==='
$targets = @(
  'D:\program_runtime_environment\cli\deskreen\3.2.16',
  (Join-Path $env:APPDATA 'deskreen-ce'),
  (Join-Path $env:USERPROFILE 'Desktop\Deskreen CE.lnk'),
  (Join-Path $env:APPDATA 'Microsoft\Windows\Start Menu\Programs\Deskreen CE.lnk'),
  'C:\VirtualDisplayDriver',
  'D:\program_runtime_environment\cli\vdd-control\25.7.23'
)
foreach ($t in $targets) {
  if (Test-Path -LiteralPath $t) {
    $it = Get-Item -LiteralPath $t -Force
    if ($it.PSIsContainer) {
      $s = (Get-ChildItem -LiteralPath $t -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum)
      Write-Output ('  [存在] ' + [Math]::Round($s.Sum/1MB,1).ToString().PadLeft(8) + ' MB  ' + $t)
    } else { Write-Output ('  [存在]            文件  ' + $t) }
  } else { Write-Output ('  [无]  ' + $t) }
}
Write-Output ''
Write-Output '=== 5) 保留项（安装包，便于将来恢复） ==='
foreach ($p in 'D:\program_runtime_environment\_downloads\deskreen', 'D:\program_runtime_environment\_downloads\vdd') {
  if (Test-Path -LiteralPath $p) {
    $s = (Get-ChildItem -LiteralPath $p -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum)
    Write-Output ('  ' + [Math]::Round($s.Sum/1MB,1).ToString().PadLeft(8) + ' MB  ' + $p)
  }
}
Write-Output ''
Write-Output '=== 6) 当前屏数（卸载后应回到 1） ==='
Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
[System.Windows.Forms.Screen]::AllScreens | ForEach-Object { Write-Output ('  ' + $_.DeviceName + '  ' + $_.Bounds.Width + 'x' + $_.Bounds.Height) }", "description": "Inventory everything to uninstall", "timeoutMs": 240000}

