content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
Write-Output '=== 1) 结束仍运行的 Deskreen 进程 ==='
$procs = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -match '(?i)deskreen' })
if ($procs.Count) {
  foreach ($p in $procs) { Write-Output ('  停止 ' + $p.Id + ' ' + $p.ProcessName); try { $p | Stop-Process -Force -ErrorAction SilentlyContinue } catch { } }
  Start-Sleep -Seconds 3
} else { Write-Output '  没有 Deskreen 进程在运行' }

Write-Output ''
Write-Output '=== 2) 删除 Deskreen 与 VDD 控制台的文件 ==='
$targets = @(
  'D:\program_runtime_environment\cli\deskreen\3.2.16',
  'D:\program_runtime_environment\cli\vdd-control\25.7.23',
  (Join-Path $env:APPDATA 'deskreen-ce'),
  (Join-Path $env:USERPROFILE 'Desktop\Deskreen CE.lnk'),
  (Join-Path $env:APPDATA 'Microsoft\Windows\Start Menu\Programs\Deskreen CE.lnk')
)
foreach ($t in $targets) {
  if (Test-Path -LiteralPath $t) {
    $it = Get-Item -LiteralPath $t -Force
    $size = 0
    if ($it.PSIsContainer) { $size = (Get-ChildItem -LiteralPath $t -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum }
    Remove-Item -LiteralPath $t -Recurse -Force -ErrorAction SilentlyContinue
    Write-Output ('  ' + $(if (Test-Path -LiteralPath $t) { '[失败]' } else { '[已删]' }) + ' ' + [Math]::Round($size/1MB,1) + ' MB  ' + $t)
  } else { Write-Output ('  [已无] ' + $t) }
}

Write-Output ''
Write-Output '=== 3) 清理 %TEMP% 里残留的便携版解包目录 ==='
$cleaned = 0
Get-ChildItem -LiteralPath $env:TEMP -Directory -Force -ErrorAction SilentlyContinue | ForEach-Object {
  $inner = Get-ChildItem -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '(?i)deskreen' }
  if ($inner) {
    $sz = (Get-ChildItem -LiteralPath $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
    Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction SilentlyContinue
    Write-Output ('  [已删] ' + [Math]::Round($sz/1MB,1) + ' MB  ' + $_.FullName)
    $cleaned++
  }
}
if ($cleaned -eq 0) { Write-Output '  无残留' }

Write-Output ''
Write-Output '=== 4) 从运行环境登记表移除 deskreen ==='
$regPath = 'D:\program_runtime_environment\registry.json'
$reg = [System.IO.File]::ReadAllText($regPath, [System.Text.Encoding]::UTF8) | ConvertFrom-Json
$before = @($reg.environments).Count
$kept = @($reg.environments | Where-Object { $_.name -ne 'deskreen' })
$out = [pscustomobject]@{
  version = $reg.version; root = $reg.root; layout = $reg.layout; categoryRule = $reg.categoryRule
  declaredCategories = $reg.declaredCategories; reservedFolders = $reg.reservedFolders
  updatedAt = (Get-Date).ToString('yyyy-MM-dd'); environments = $kept
}
[System.IO.File]::WriteAllText($regPath, ($out | ConvertTo-Json -Depth 8) + "`r`n", (New-Object System.Text.UTF8Encoding($false)))
Write-Output ('  登记项 ' + $before + ' -> ' + $kept.Count + ' : ' + (($kept | ForEach-Object { $_.name + ' ' + $_.version }) -join ', '))

Write-Output ''
Write-Output '=== 5) 卸载后验证 ==='
Write-Output '  残留检查（应全部为 False/空）:'
foreach ($t in 'D:\program_runtime_environment\cli\deskreen', 'D:\program_runtime_environment\cli\vdd-control', (Join-Path $env:APPDATA 'deskreen-ce'), 'C:\VirtualDisplayDriver') {
  Write-Output ('    ' + (Test-Path -LiteralPath $t).ToString().PadRight(6) + ' ' + $t)
}
$l = netstat -ano 2>$null | Select-String ':3131' | Select-String 'LISTENING'
Write-Output ('    3131 监听中: ' + [bool]$l)
Write-Output ('    Deskreen 进程: ' + @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -match '(?i)deskreen' }).Count + ' 个')
Write-Output '  VDD 设备残留:'
$d = & cmd.exe /c 'pnputil /enum-devices /class Display' 2>&1 | Out-String
if ($d -match 'MttVDD|Virtual Display') { Write-Output '    [仍有残留]'; ($d -split "`r?`n") | Where-Object { $_ -match 'MttVDD|Virtual Display' } | ForEach-Object { Write-Output ('      ' + $_.Trim()) } } else { Write-Output '    无（虚拟显示设备已清除）' }
$m = & cmd.exe /c 'pnputil /enum-devices /class Monitor' 2>&1 | Out-String
if ($m -match 'VDD by MTT') { Write-Output '    [显示器节点仍有残留]' } else { Write-Output '    无（VDD 显示器节点已清除）' }
Write-Output '  Driver store 里是否还有该驱动包:'
$drv = & cmd.exe /c 'pnputil /enum-drivers' 2>&1 | Out-String
if ($drv -match 'mttvdd|MttVDD') { Write-Output '    [仍存在]' } else { Write-Output '    已移除' }
Write-Output ''
Write-Output '=== 6) 保留的安装包（如需彻底清空告诉我） ==='
foreach ($p in 'D:\program_runtime_environment\_downloads\deskreen', 'D:\program_runtime_environment\_downloads\vdd') {
  if (Test-Path -LiteralPath $p) {
    $s = (Get-ChildItem -LiteralPath $p -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum)
    Write-Output ('    ' + [Math]::Round($s.Sum/1MB,1) + ' MB  ' + $p)
  }
}
Write-Output ''
