{"command": "Write-Output '=== 1) AGENTS.md 与工作区状态 ==='
foreach ($f in 'E:\Deepseek\AGENTS.md', 'E:\Deepseek\README.md', 'E:\Deepseek\policy\storage-policy.json', 'E:\Deepseek\policy\output-storage-policy.md', 'E:\Deepseek\policy\conversation-registry.json') {
  if (Test-Path -LiteralPath $f) {
    Write-Output ('  [存在] ' + (Get-Item -LiteralPath $f).Length.ToString().PadLeft(7) + ' B  ' + (Get-Item -LiteralPath $f).LastWriteTime + '  ' + $f)
  } else { Write-Output ('  [缺失] ' + $f) }
}
Write-Output ('  根目录条目: ' + ((Get-ChildItem -LiteralPath 'E:\Deepseek' -Force | Select-Object -ExpandProperty Name) -join ', '))
Write-Output ''
Write-Output '=== 2) 本机 dsh 是否内置 desktop/electron 支持 ==='
$dshDir = Join-Path $env:APPDATA 'npm\node_modules\@deepseek-ai\dsh'
Write-Output ('  dsh 包: ' + $dshDir)
Write-Output ('  版本: ' + (([System.IO.File]::ReadAllText((Join-Path $dshDir 'package.json'), [System.Text.Encoding]::UTF8) | ConvertFrom-Json).version))
$lib = Join-Path $dshDir 'lib'
if (Test-Path -LiteralPath $lib) {
  Get-ChildItem -LiteralPath $lib -Force -File | Select-Object Name, @{n='KB';e={[Math]::Round($_.Length/1KB,1)}} | Format-Table -AutoSize | Out-String -Width 90
}
Write-Output '  --- 在 dsh 包里搜 desktop / electron ---'
foreach ($k in 'desktop', 'electron', 'Electron') {
  $c = 0
  Get-ChildItem -LiteralPath $dshDir -Recurse -Force -File -Include '*.js','*.json','*.yml' -ErrorAction SilentlyContinue | Where-Object { $_.FullName -notmatch 'node_modules' -or $_.FullName -match 'dsh-app-boot|dsh-cmdline' } | ForEach-Object {
    $t = [System.IO.File]::ReadAllText($_.FullName, [System.Text.Encoding]::UTF8)
    $n = ([regex]::Matches($t, [regex]::Escape($k))).Count
    if ($n -gt 0) { $c += $n; Write-Output ('      ' + $k + ' x' + $n + '  ' + $_.FullName.Substring($dshDir.Length)) }
  }
  if ($c -eq 0) { Write-Output ('      ' + $k + ' : 0 命中') }
}
Write-Output '  --- profile 模板列表（是否含 desktop） ---'
$boot = Join-Path $dshDir 'node_modules\@deepseek-ai\dsh-app-boot\lib\index.js'
if (Test-Path -LiteralPath $boot) {
  $t = [System.IO.File]::ReadAllText($boot, [System.Text.Encoding]::UTF8)
  $m = [regex]::Match($t, 'PROFILE_TEMPLATES\s*=\s*\{[^}]{0,600}')
  if ($m.Success) { Write-Output ('      ' + ($m.Value -replace '\s+', ' ')) } else { Write-Output '      未找到 PROFILE_TEMPLATES 定义' }
  $i = $t.IndexOf('desktop')
  if ($i -ge 0) { Write-Output ('      desktop 上下文: ' + (($t.Substring([Math]::Max(0,$i-200), 420)) -replace '\s+',' ')) }
}", "description": "Check AGENTS.md and dsh desktop support", "timeoutMs": 300000}

