$js = @'
const https = require('https'); const fs = require('fs');
const url = 'https://download.deepseek.com/desktop/dsh-latest-windows-x64.exe';
https.get(url, { headers: { 'User-Agent': 'dsh-probe/1.0', 'Range': 'bytes=0-2097151' } }, (r) => {
  console.log('  range status: ' + r.statusCode + ' (206 = range 生效)');
  const chunks = [];
  r.on('data', (c) => { chunks.push(c); if (Buffer.concat(chunks).length > 2097152) { r.destroy(); } });
  r.on('close', () => {
    const buf = Buffer.concat(chunks).slice(0, 2097152);
    fs.writeFileSync(process.argv[2], buf);
    console.log('  saved ' + buf.length + ' bytes');
    const asc = buf.toString('latin1');
    const markers = ['Nullsoft', 'NSIS', 'NullsoftInst', 'Inno Setup', 'Squirrel', 'electron-builder', '7zS.sfx', '7-Zip', 'WiX', 'MSI', 'installer.nsi', 'app-64.7z', 'resources\\app.asar'];
    for (const m of markers) {
      const c = asc.split(m).length - 1;
      if (c > 0) console.log('    marker [' + m + '] x' + c);
    }
    const pe = asc.indexOf('PE\u0000\u0000');
    console.log('  PE header at offset: ' + (pe >= 0 ? pe : 'not found in first 2 MB'));
    const mz = asc.startsWith('MZ');
    console.log('  starts with MZ (exe): ' + mz);
  });
}).on('error', (e) => console.log('  probe failed: ' + e.message));
'@
