{"command": "$exe = 'D:\program_runtime_environment\_downloads\dsh-desktop\dsh-latest-windows-x64.exe'
Write-Output '=== 1) 文件与签名 ==='
if (Test-Path -LiteralPath $exe) {
  $f = Get-Item -LiteralPath $exe
  Write-Output ('  大小   : ' + $f.Length + ' bytes (' + [Math]::Round($f.Length/1MB,1) + ' MB)  预期 289313640 -> ' + ($f.Length -eq 289313640))
  Write-Output ('  修改   : ' + $f.LastWriteTime)
  Write-Output ('  SHA256 : ' + (Get-FileHash -LiteralPath $exe -Algorithm SHA256).Hash)
  $sig = Get-AuthenticodeSignature -LiteralPath $exe
  Write-Output ('  签名   : ' + $sig.Status)
  if ($sig.SignerCertificate) {
    Write-Output ('  签署者 : ' + $sig.SignerCertificate.Subject)
    Write-Output ('  颁发者 : ' + $sig.SignerCertificate.Issuer)
  }
  if ($sig.TimeStamperCertificate) { Write-Output ('  时间戳 : ' + $sig.TimeStamperCertificate.Subject) }
} else { Write-Output '  安装包不存在！'; exit 1 }
Write-Output ''
Write-Output '=== 2) 判断"一键式"还是"向导式"（决定能否 /D 自定义目录） ==='
$bytes = [System.IO.File]::ReadAllBytes($exe)
$ascii = [System.Text.Encoding]::GetEncoding('latin1').GetString($bytes)
$utf16 = [System.Text.Encoding]::Unicode.GetString($bytes)
$markers = @(
  @{ name='Choose Install Location'; kind='向导页' },
  @{ name='Destination Folder';      kind='向导页' },
  @{ name='选择安装位置';            kind='向导页' },
  @{ name='安装位置';                kind='向导页' },
  @{ name='Browse';                  kind='浏览按钮' },
  @{ name='浏览';                    kind='浏览按钮' },
  @{ name='All Users';               kind='全机/当前用户选择' },
  @{ name='Anyone who uses this computer'; kind='全机安装选项' },
  @{ name='LOCALAPPDATA';            kind='用户级默认目录' },
  @{ name='PROGRAMFILES';            kind='全机默认目录' },
  @{ name='$INSTDIR';                kind='安装目录变量' },
  @{ name='Uninstall';               kind='卸载器' }
)
foreach ($m in $markers) {
  $a = $ascii.Split($m.name).Length - 1
  $u = $utf16.Split($m.name).Length - 1
  if ($a -gt 0 -or $u -gt 0) { Write-Output ('  [命中] ' + $m.name.PadRight(32) + '(' + $m.kind + ')  ansi=' + $a + ' utf16=' + $u) }
}
Write-Output ''
Write-Output '=== 3) 顺带看下产品名/版本（UTF-16 里的应用名） ==='
foreach ($k in 'DeepSeek Harness', 'dsh-desktop', 'dsh desktop', 'DeepSeekHarness') {
  $u = $utf16.Split($k).Length - 1
  if ($u -gt 0) { Write-Output ('  ' + $k + ' : utf16 x' + $u) }
}", "description": "Verify installer and detect install mode", "timeoutMs": 420000}

