content.arguments:
{"command": "$h = Join-Path $env:USERPROFILE '.dsh'
Write-Output '=== ~/.dsh 各子目录体量（CLI 与桌面端共用） ==='
Get-ChildItem -LiteralPath $h -Force | ForEach-Object {
  if ($_.PSIsContainer) {
    $s = (Get-ChildItem -LiteralPath $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum)
    [pscustomobject]@{ 名称 = $_.Name + '\'; 大小MB = [Math]::Round($s.Sum/1MB,1); 文件数 = $s.Count }
  } else {
    [pscustomobject]@{ 名称 = $_.Name; 大小MB = [Math]::Round($_.Length/1KB,1).ToString() + ' KB'; 文件数 = 1 }
  }
} | Format-Table -AutoSize | Out-String -Width 70
Write-Output '=== profiles 里有什么（两边都会读到） ==='
$pf = Join-Path $h 'profiles'
if (Test-Path -LiteralPath $pf) { Get-ChildItem -LiteralPath $pf -Force | ForEach-Object { Write-Output ('  ' + $_.Name + $(if ($_.PSIsContainer) { '\' } else { '' })) } }
Write-Output ('=== 关键配置文件的最后修改时间 ===')
foreach ($f in 'settings.yaml', 'AGENTS.md', '.credentials.yaml') {
  $p = Join-Path $h $f
  if (Test-Path -LiteralPath $p) { $i = Get-Item -LiteralPath $p -Force; Write-Output ('  ' + $i.LastWriteTime + '  ' + [Math]::Round($i.Length/1KB,1) + ' KB  ' + $f) }
}", "description": "Measure shared dsh home before first launch", "timeoutMs": 240000}

