content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$conv = 'conv-20260928-3b54e160'
$ws = "E:\Deepseek\workspace\$conv"
$stamp = (Get-Date).ToString('yyyyMMdd-HHmmss')
function Size-Of($p) { if (Test-Path -LiteralPath $p) { $i = Get-Item -LiteralPath $p -Force; if ($i.PSIsContainer) { return [Math]::Round(((Get-ChildItem -LiteralPath $p -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum)/1MB,1) } else { return [Math]::Round($i.Length/1MB,2) } } else { return 0 } }
$freed = @()
$eBefore = (New-Object System.IO.DriveInfo('E')).AvailableFreeSpace
$dBefore = (New-Object System.IO.DriveInfo('D')).AvailableFreeSpace

Write-Output '=== 1) 把 463 MB 的 ~/.dsh 备份裁剪成关键配置 ==='
$bakDir = Get-ChildItem -LiteralPath $ws -Directory -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -like 'dsh-home-backup-*' } | Select-Object -First 1
$essDir = Join-Path $ws "dsh-home-essentials-$stamp"
if ($bakDir) {
  New-Item -ItemType Directory -Force -Path $essDir | Out-Null
  $keep = @('settings.yaml', 'settings.yaml.imported', 'AGENTS.md', 'AGENTS.md.bak-20260928-135256', '.credentials.yaml', 'storages')
  foreach ($k in $keep) {
    $src = Join-Path $bakDir.FullName $k
    if (Test-Path -LiteralPath $src) { Copy-Item -LiteralPath $src -Destination (Join-Path $essDir $k) -Recurse -Force -ErrorAction SilentlyContinue }
  }
  foreach ($pf in 'web', 'desktop') {
    $pp = Join-Path $bakDir.FullName "profiles\$pf"
    if (Test-Path -LiteralPath $pp) {
      $dest = Join-Path $essDir "profiles\$pf"
      New-Item -ItemType Directory -Force -Path $dest | Out-Null
      Get-ChildItem -LiteralPath $pp -Force -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -notmatch '\.log$' } | ForEach-Object { Copy-Item -LiteralPath $_.FullName -Destination $dest -Force -ErrorAction SilentlyContinue }
    }
  }
  $essFiles = @(Get-ChildItem -LiteralPath $essDir -Recurse -Force -File -ErrorAction SilentlyContinue)
  Write-Output ('  保留关键配置: ' + $essDir.Replace('E:\Deepseek\workspace\' + $conv + '\', ''))
  Write-Output ('    ' + $essFiles.Count + ' 个文件 / ' + [Math]::Round((($essFiles | Measure-Object Length -Sum).Sum)/1KB,1) + ' KB')
  $essFiles | ForEach-Object { Write-Output ('      ' + $_.FullName.Substring($essDir.Length + 1)) }
  $before = Size-Of $bakDir.FullName
  Remove-Item -LiteralPath $bakDir.FullName -Recurse -Force -ErrorAction SilentlyContinue
  $freed += [pscustomobject]@{ 对象 = 'workspace\' + $bakDir.Name; 释放MB = $before; 说明 = '463MB 备份裁剪为关键配置' }
  Write-Output ('  [已删] 完整备份 ' + $before + ' MB')
} else { Write-Output '  未找到备份目录' }

Write-Output ''
Write-Output '=== 2) 删除 Deskreen / VDD 残留安装包与探针文件 ==='
foreach ($rel in 'deskreen', 'vdd', 'viewer-bundle.js', 'head-probe.bin', 'tmp') {
  $p = Join-Path $ws $rel
  if (Test-Path -LiteralPath $p) {
    $s = Size-Of $p
    Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction SilentlyContinue
    Write-Output ('  ' + $(if (Test-Path -LiteralPath $p) { '[失败]' } else { '[已删]' }) + ' ' + $s + ' MB  workspace\' + $rel)
    $freed += [pscustomobject]@{ 对象 = 'workspace\' + $rel; 释放MB = $s; 说明 = '已卸载软件的安装包/分析中间产物' }
  } else { Write-Output ('  (已不存在) ' + $rel) }
}

Write-Output ''
Write-Output '=== 3) 删除 D 盘已无用的安装包与缓存 ==='
foreach ($p in 'D:\program_runtime_environment\_downloads\dsh-desktop', 'D:\program_runtime_environment\_downloads\python') {
  if (Test-Path -LiteralPath $p) {
    $s = Size-Of $p
    Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction SilentlyContinue
    Write-Output ('  ' + $(if (Test-Path -LiteralPath $p) { '[失败]' } else { '[已删]' } }) + ' ' + $s + ' MB  ' + $p)
    $freed += [pscustomobject]@{ 对象 = $p; 释放MB = $s; 说明 = '安装包（软件已安装，卸载/修复不需要它）' }
  } else { Write-Output ('  (已不存在) ' + $p) }
}
$caches = 'D:\program_runtime_environment\_caches'
if (Test-Path -LiteralPath $caches) {
  $s = Size-Of $caches
  Get-ChildItem -LiteralPath $caches -Force -ErrorAction SilentlyContinue | ForEach-Object { Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction SilentlyContinue }
  Write-Output ('  [已清空内容] ' + $s + ' MB  ' + $caches + '  （目录保留，缓存可再生）')
  $freed += [pscustomobject]@{ 对象 = $caches + '\*'; 释放MB = $s; 说明 = 'npm/pip 缓存，下次安装时自动重建' }
}

Write-Output ''
Write-Output '=== 4) 清理结果汇总 ==='
$freed | Where-Object { $_.释放MB -gt 0 } | Format-Table -AutoSize | Out-String -Width 110
$eAfter = (New-Object System.IO.DriveInfo('E')).AvailableFreeSpace
$dAfter = (New-Object System.IO.DriveInfo('D')).AvailableFreeSpace
Write-Output ('  E 盘: 释放 ' + [Math]::Round(($eAfter-$eBefore)/1MB,1) + ' MB   -> 现可用 ' + [Math]::Round($eAfter/1GB,2) + ' GB')
Write-Output ('  D 盘: 释放 ' + [Math]::Round(($dAfter-$dBefore)/1MB,1) + ' MB   -> 现可用 ' + [Math]::Round($dAfter/1GB,2) + ' GB')

Write-Output ''
Write-Output '=== 5) 清理后的目录全貌 ==='
Write-Output '  D:\program_runtime_environment\:'
Get-ChildItem -LiteralPath 'D:\program_runtime_environment' -Force | ForEach-Object {
  if ($_.PSIsContainer) {
    $s = (Get-ChildItem -LiteralPath $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum)
    Write-Output ('    ' + [Math]::Round($s.Sum/1MB,1).ToString().PadLeft(8) + ' MB  ' + $_.Name + '\')
  } else { Write-Output ('    ' + [Math]::Round($_.Length/1KB,1).ToString().PadLeft(8) + ' KB  ' + $_.Name) }
}
Write-Output "  E:\Deepseek\workspace\$conv\:"
Get-ChildItem -LiteralPath $ws -Force -ErrorAction SilentlyContinue | ForEach-Object {
  if ($_.PSIsContainer) { Write-Output ('              ' + $_.Name + '\') } else { Write-Output ('              ' + $_.Name) }
}
Write-Output ''
Write-Output '=== 6) 工作区自检 ==='
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File 'E:\Deepseek\tools\Test-StoragePolicy.ps1' | Select-Object -Last 3", "description": "Clean up unneeded files and caches", "justification": "清除 D:\program_runtime_environment 下已无用的安装包与缓存目录内容，该路径在工作区之外，workspace-write 沙箱会拒绝。", "sandbox_permissions": "danger-full-access", "timeoutMs": 900000}

