    [void]$report.Add([pscustomobject]@{ Target = "workspace\$($bakDir.Name)"; FreedMB = $sz; Note = 'full backup trimmed to essentials' })
} else { Write-Output '  backup dir not found' }

Write-Output ''
Write-Output '=== 2) delete leftover Deskreen / VDD installers and probe files ==='
foreach ($rel in @('deskreen', 'vdd', 'viewer-bundle.js', 'head-probe.bin', 'tmp')) {
    $p = Join-Path $ws $rel
    if (Test-Path -LiteralPath $p) {
        $sz = Get-SizeMB $p
        Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction SilentlyContinue
        if (Test-Path -LiteralPath $p) { Write-Output "  [FAILED] $rel" } else { Write-Output "  [deleted] $sz MB  workspace\$rel" }
        [void]$report.Add([pscustomobject]@{ Target = "workspace\$rel"; FreedMB = $sz; Note = 'installer of uninstalled software / analysis output' })
    } else { Write-Output "  (absent) $rel" }
}

Write-Output ''
Write-Output '=== 3) delete unused installers and caches on D: ==='
foreach ($p in @('D:\program_runtime_environment\_downloads\dsh-desktop', 'D:\program_runtime_environment\_downloads\python')) {
    if (Test-Path -LiteralPath $p) {
        $sz = Get-SizeMB $p
        Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction SilentlyContinue
        if (Test-Path -LiteralPath $p) { Write-Output "  [FAILED] $p" } else { Write-Output "  [deleted] $sz MB  $p" }
        [void]$report.Add([pscustomobject]@{ Target = $p; FreedMB = $sz; Note = 'installer archive; software already installed' })
    } else { Write-Output "  (absent) $p" }
}
$caches = 'D:\program_runtime_environment\_caches'
if (Test-Path -LiteralPath $caches) {
    $sz = Get-SizeMB $caches
    Get-ChildItem -LiteralPath $caches -Force -ErrorAction SilentlyContinue | ForEach-Object { Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction SilentlyContinue }
    $left = @(Get-ChildItem -LiteralPath $caches -Force -ErrorAction SilentlyContinue).Count
    Write-Output "  [emptied] $sz MB  $caches  (dir kept, $left items left; caches rebuild themselves)"
    [void]$report.Add([pscustomobject]@{ Target = "$caches\*"; FreedMB = $sz; Note = 'npm/pip cache, regenerated on demand' })
}

Write-Output ''
Write-Output '=== 4) summary ==='
$report | Where-Object { $_.FreedMB -gt 0 } | Format-Table -AutoSize | Out-String -Width 120
$eAfter = (New-Object System.IO.DriveInfo('E')).AvailableFreeSpace
$dAfter = (New-Object System.IO.DriveInfo('D')).AvailableFreeSpace
Write-Output "  E: freed $([Math]::Round(($eAfter - $eBefore)/1MB,1)) MB -> free now $([Math]::Round($eAfter/1GB,2)) GB"
Write-Output "  D: freed $([Math]::Round(($dAfter - $dBefore)/1MB,1)) MB -> free now $([Math]::Round($dAfter/1GB,2)) GB"

Write-Output ''
Write-Output '=== 5) layout after cleanup ==='
Write-Output '  D:\program_runtime_environment\'
Get-ChildItem -LiteralPath 'D:\program_runtime_environment' -Force | ForEach-Object {
    if ($_.PSIsContainer) {
        $s = Get-ChildItem -LiteralPath $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum
        Write-Output "    $([Math]::Round($s.Sum/1MB,1).ToString().PadLeft(8)) MB  $($_.Name)\"
    } else { Write-Output "    $([Math]::Round($_.Length/1KB,1).ToString().PadLeft(8)) KB  $($_.Name)" }
}
Write-Output "  E:\Deepseek\workspace\$conv\"
Get-ChildItem -LiteralPath $ws -Force -ErrorAction SilentlyContinue | ForEach-Object { Write-Output "    $($_.Name)" }

Write-Output ''
Write-Output '=== 6) workspace self-test ==='
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File 'E:\Deepseek\tools\Test-StoragePolicy.ps1' | Select-Object -Last 3", "description": "Clean up unneeded files and caches", "justification": "清除 D:\program_runtime_environment 下已无用的安装包与缓存内容，该路径在工作区之外，workspace-write 沙箱会拒绝。", "sandbox_permissions": "danger-full-access", "timeoutMs": 900000}

content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$h = Join-Path $env:USERPROFILE '.dsh'
Write-Output '=== 1) 线目录 ~/.dsh 是否完好 ==='
Write-Output ('  存在: ' + (Test-Path -LiteralPath $h))
Get-ChildItem -LiteralPath $h -Force | ForEach-Object {
    if ($_.PSIsContainer) {
        $s = Get-ChildItem -LiteralPath $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum
        $isLink = 'False'
        try { $isLink = ($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0 } catch { }
        Write-Output ("    $($_.Name)\  $([Math]::Round($s.Sum/1MB,1)) MB / $($s.Count) files   reparse=$isLink")
    } else {
        Write-Output ("    $($_.Name)  $([Math]::Round($_.Length/1KB,1)) KB   $($_.LastWriteTime)")
    }
}
Write-Output ''
Write-Output '=== 2) profiles 内的联接情况（解释备份为何膨胀） ==='
foreach ($sub in @('profiles', 'profiles\node_modules', 'profiles\web', 'profiles\desktop', 'profiles\web\node_modules')) {
    $p = Join-Path $h $sub
    if (Test-Path -LiteralPath $p) {
        $it = Get-Item -LiteralPath $p -Force
        $reparse = ($it.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0
        $tgt = ''
        if ($reparse) { try { $tgt = ' -> ' + $it.Target } catch { $tgt = ' -> (target unreadable)' } }
        Write-Output ("    $sub   reparse=$reparse$tgt")
    } else { Write-Output "    $sub   (absent)" }
}
Write-Output ''
Write-Output '=== 3) 清理那个空的关键配置目录 ==='
$ess = Get-ChildItem -LiteralPath 'E:\Deepseek\workspace\conv-20260928-3b54e160' -Directory -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -like 'dsh-home-essentials-*' }
foreach ($d in $ess) {
    $n = @(Get-ChildItem -LiteralPath $d.FullName -Recurse -Force -ErrorAction SilentlyContinue).Count
    if ($n -eq 0) { Remove-Item -LiteralPath $d.FullName -Recurse -Force -ErrorAction SilentlyContinue; Write-Output "    [removed empty] $($d.Name)" }
    else { Write-Output "    [kept] $($d.Name) has $n items" }
}
Write-Output ('    workspace 会话目录剩余: ' + (((Get-ChildItem -LiteralPath 'E:\Deepseek\workspace\conv-20260928-3b54e160' -Force -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Name) -join ', ') -replace '^$', '(空)'))
Write-Output ''
Write-Output '=== 4) 桌面端与 CLI 现状 ==='
Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -match '(?i)harness' } | Select-Object Id, ProcessName | Format-Table -AutoSize | Out-String -Width 60
$oldCli = Join-Path $env:APPDATA 'npm\node_modules\@deepseek-ai\dsh\package.json'
if (Test-Path -LiteralPath $oldCli) { Write-Output ('  dsh 命令 (PATH 上): v' + ([System.IO.File]::ReadAllText($oldCli, [System.Text.Encoding]::UTF8) | ConvertFrom-Json).version + '  @ %APPDATA%\npm') }
Write-Output ('  桌面端主程序: ' + (Test-Path -LiteralPath 'D:\Application\dsh\DeepSeek Harness.exe'))
Write-Output ''
Write-Output '=== 5) 各盘可用空间 ==='
[System.IO.DriveInfo]::GetDrives() | Where-Object { $_.IsReady } | ForEach-Object { Write-Output ("    $($_.Name)  $([Math]::Round($_.AvailableFreeSpace/1GB,2)) GB free / $([Math]::Round($_.TotalSize/1GB,1)) GB") }", "description": "Verify dsh home intact and finish cleanup", "timeoutMs": 300000}

