content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$h = Join-Path $env:USERPROFILE '.dsh'
Write-Output '=== 1) ~/.dsh/profiles 下有哪些 profile ==='
$pf = Join-Path $h 'profiles'
Get-ChildItem -LiteralPath $pf -Force -ErrorAction SilentlyContinue | ForEach-Object {
  if ($_.PSIsContainer) {
    $s = Get-ChildItem -LiteralPath $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum
    Write-Output ("  $($_.Name)\   $([Math]::Round($s.Sum/1MB,1)) MB / $($s.Count) files   mtime=$($_.LastWriteTime)")
  } else { Write-Output "  $($_.Name)   file" }
}
Write-Output ''
Write-Output '=== 2) 每个 profile 的 package.json（依赖=插件，dsh.profile.bundles=启用的插件） ==='
foreach ($name in @('web', 'desktop')) {
    $pj = Join-Path $pf "$name\package.json"
    Write-Output "  --- profile: $name ---"
    if (Test-Path -LiteralPath $pj) {
        $raw = [System.IO.File]::ReadAllText($pj, [System.Text.Encoding]::UTF8)
        Write-Output ('    ' + ($raw -replace "`r?`n", ' ' -replace '\s+', ' '))
        try {
            $o = $raw | ConvertFrom-Json
            $deps = @()
            if ($o.PSObject.Properties['dependencies']) { $deps = @($o.dependencies.PSObject.Properties | ForEach-Object { $_.Name + '@' + $_.Value }) }
            Write-Output ('    依赖数: ' + $deps.Count)
            $deps | ForEach-Object { Write-Output ('      dep: ' + $_) }
            if ($o.PSObject.Properties['dsh'] -and $o.dsh.PSObject.Properties['profile'] -and $o.dsh.profile.PSObject.Properties['bundles']) {
                Write-Output '    profile.bundles:'
                @($o.dsh.profile.bundles) | ForEach-Object { Write-Output ('      bundle: ' + $_) }
            }
        } catch { Write-Output ('    (JSON 解析失败: ' + $_.Exception.Message + ')') }
    } else { Write-Output '    (没有 package.json)' }
    $nm = Join-Path $pf "$name\node_modules"
    Write-Output ("    node_modules: " + (Test-Path -LiteralPath $nm))
    if (Test-Path -LiteralPath $nm) {
        $mods = @(Get-ChildItem -LiteralPath $nm -Force -ErrorAction SilentlyContinue)
        Write-Output ("    顶层模块数: " + $mods.Count + "  -> " + (($mods | Select-Object -First 10 -ExpandProperty Name) -join ', '))
    }
}
Write-Output ''
Write-Output '=== 3) settings / storages（决定用哪个 profile） ==='
foreach ($f in 'settings.yaml', 'settings.yaml.imported') {
    $p = Join-Path $h $f
    if (Test-Path -LiteralPath $p) { Write-Output "  --- $f ---"; Get-Content -LiteralPath $p -Raw | ForEach-Object { Write-Output ('    ' + $_) } }
}
$st = Join-Path $h 'storages'
if (Test-Path -LiteralPath $st) {
    Write-Output '  --- storages\ ---'
    Get-ChildItem -LiteralPath $st -Recurse -Force -File -ErrorAction SilentlyContinue | ForEach-Object { Write-Output ("    $($_.FullName.Substring($st.Length+1))  $($_.Length) B") }
}", "description": "Inspect profiles and plugin sets", "timeoutMs": 300000}

{"command": "$ErrorActionPreference = 'Continue'
Write-Output '=== 桌面端内置的 dsh 代码在哪 ==='
$un = 'D:\Application\dsh\resources\app.asar.unpacked\dsh'
Write-Output ("  app.asar.unpacked\dsh 存在: " + (Test-Path -LiteralPath $un))
if (Test-Path -LiteralPath $un) {
    Get-ChildItem -LiteralPath $un -Force | Select-Object -First 12 | ForEach-Object { Write-Output ("    $($_.Name)") }
}
Write-Output ''
Write-Output '=== 搜 desktop profile 的保留名与 boot 逻辑 ==='
$targets = @()
foreach ($base in @('D:\Application\dsh\resources\app.asar.unpacked\dsh', 'D:\Application\dsh\resources')) {
    if (Test-Path -LiteralPath $base) {
        $targets += Get-ChildItem -LiteralPath $base -Recurse -Force -File -Include '*.js', '*.mjs', '*.cjs', '*.json' -ErrorAction SilentlyContinue |
            Where-Object { $_.Length -lt 3MB -and $_.FullName -notmatch 'node_modules\\(?!@deepseek-ai)' } |
            Select-Object -First 400
    }
}
Write-Output ("  待扫描文件: " + $targets.Count)
$hits = 0
foreach ($f in $targets) {
    $t = ''
    try { $t = [System.IO.File]::ReadAllText($f.FullName, [System.Text.Encoding]::UTF8) } catch { continue }
    if ($t -match "'desktop'|""desktop""|`bdesktop`b" -and $t -match 'profile') {
        $i = $t.IndexOf('desktop')
        if ($i -ge 0) {
            $ctx = ($t.Substring([Math]::Max(0, $i - 160), [Math]::Min(360, $t.Length - [Math]::Max(0, $i - 160)))) -replace '\s+', ' '
            Write-Output ("  --- " + $f.FullName.Substring('D:\Application\dsh\resources'.Length))
            Write-Output ("      " + $ctx)
            $hits++
            if ($hits -ge 6) { break }
        }
    }
}
if ($hits -eq 0) { Write-Output '  (未在前 400 个文件中命中)' }", "description": "Find desktop profile logic in app", "timeoutMs": 300000}

