    if (Test-Path -LiteralPath $pj) {
        $raw = [System.IO.File]::ReadAllText($pj, [System.Text.Encoding]::UTF8)
        Write-Output ('    ' + ($raw -replace "`r?`n", ' ' -replace '\s+', ' '))
