Write-Output '=== 1) 桌面端自带的 @deepseek-ai 包（找插件管理器） ==='
$nm = Join-Path $appDsh 'node_modules\@deepseek-ai'
if (Test-Path -LiteralPath $nm) {
    Get-ChildItem -LiteralPath $nm -Force -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'plugin|market|ui|frontend|host' } | ForEach-Object {
        $pj = Join-Path $_.FullName 'package.json'
        $v = ''
        if (Test-Path -LiteralPath $pj) { try { $v = ([System.IO.File]::ReadAllText($pj, [System.Text.Encoding]::UTF8) | ConvertFrom-Json).version } catch { } }
        Write-Output ("    " + $_.Name.PadRight(42) + $v)
    }
    Write-Output ('  该目录下包总数: ' + @(Get-ChildItem -LiteralPath $nm -Force -Directory -ErrorAction SilentlyContinue).Count)
} else { Write-Output '  目录不存在' }
Write-Output ''
Write-Output '=== 2) desktop profile 现状（安装成功后这里会变） ==='
$dp = Join-Path $env:USERPROFILE '.dsh\profiles\desktop'
Get-ChildItem -LiteralPath $dp -Force -ErrorAction SilentlyContinue | ForEach-Object { Write-Output ("    $($_.Name)  $($_.Length) B  $($_.LastWriteTime)") }
Write-Output '  package.json 内容:'
Write-Output ('    ' + (([System.IO.File]::ReadAllText((Join-Path $dp 'package.json'), [System.Text.Encoding]::UTF8)) -replace "`r?`n", ' ' -replace '\s+', ' '))
Write-Output ''
Write-Output '=== 3) GUI 里插件相关的路由/接口线索（看前端资源） ==='
$base = 'http://127.0.0.1:19387'
$js = @'
const http = require('http');
function get(url) {
  return new Promise((resolve, reject) => {
    http.get(url, { headers: { 'User-Agent': 'probe/1.0' } }, (r) => {
      if (r.statusCode >= 300 && r.statusCode < 400 && r.headers.location) { r.resume(); resolve(get(new URL(r.headers.location, url).toString())); return; }
      let d = ''; r.on('data', (c) => { d += c; }); r.on('end', () => resolve({ code: r.statusCode, body: d }));
    }).on('error', reject);
  });
}
(async () => {
  const home = await get('http://127.0.0.1:19387/');
  console.log('  GET / -> HTTP ' + home.code + ', ' + home.body.length + ' bytes');
  const srcs = [...home.body.matchAll(/(?:src|href)="([^"]+\.(?:js|css))"/g)].map((m) => m[1]);
  console.log('  assets: ' + srcs.join(', '));
  const apiHits = new Set();
  for (const s of srcs.filter((x) => x.endsWith('.js')).slice(0, 3)) {
    const url = s.startsWith('http') ? s : 'http://127.0.0.1:19387' + (s.startsWith('/') ? s : '/' + s);
    let r;
    try { r = await get(url); } catch (e) { console.log('  fetch fail ' + url + ': ' + e.message); continue; }
    console.log('\n  ===== ' + s + '  (' + (r.body.length / 1024).toFixed(0) + ' KB)');
    const code = r.body;
    for (const m of code.matchAll(/["'`](\/api\/[a-z0-9\-\/_.{}$:]*plugin[a-z0-9\-\/_.{}$:]*)/gi)) { apiHits.add(m[1]); }
    for (const kw of ['plugin-install', 'installPlugin', 'pluginManager', '插件', 'bundlePatch', 'market']) {
      const i = code.indexOf(kw);
      if (i >= 0) console.log('    [' + kw + '] ' + code.slice(Math.max(0, i - 90), i + 130).replace(/\s+/g, ' '));
    }
  }
  if (apiHits.size) { console.log('\n  plugin-related API paths found:'); for (const a of apiHits) console.log('    ' + a); }
})();
'@
$p = 'E:\Deepseek\scripts\conv-20260928-3b54e160\probe-gui-plugin-ui.js'
[System.IO.File]::WriteAllText($p, $js, (New-Object System.Text.UTF8Encoding($false)))
& 'D:\program_runtime_environment\nodejs\node.exe' $p 2>&1 | Select-Object -First 45", "description": "Locate plugin manager UI in desktop client", "timeoutMs": 300000}

