{"command": "$ErrorActionPreference = 'Continue'
$appDsh = 'D:\Application\dsh\resources\app.asar.unpacked\dsh'
Write-Output '=== 1) 桌面端 node_modules\@deepseek-ai 的 4 个包 ==='
$nm = Join-Path $appDsh 'node_modules\@deepseek-ai'
Get-ChildItem -LiteralPath $nm -Force -Directory -ErrorAction SilentlyContinue | ForEach-Object {
    $pj = Join-Path $_.FullName 'package.json'
    $v = ''; $d = ''
    if (Test-Path -LiteralPath $pj) { try { $o = [System.IO.File]::ReadAllText($pj, [System.Text.Encoding]::UTF8) | ConvertFrom-Json; $v = $o.version; $d = $o.description } catch { } }
    Write-Output ("    " + $_.Name.PadRight(34) + ($v + '').PadRight(14) + $d)
}
Write-Output ''
Write-Output '=== 2) profiles\node_modules 里有什么（profile 的模块解析锚点） ==='
$pnm = Join-Path $env:USERPROFILE '.dsh\profiles\node_modules'
if (Test-Path -LiteralPath $pnm) {
    $items = @(Get-ChildItem -LiteralPath $pnm -Force -ErrorAction SilentlyContinue)
    Write-Output ('  条目数: ' + $items.Count)
    $items | Select-Object -First 15 | ForEach-Object { Write-Output ("    $($_.Name)   reparse=" + ((($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0))) }
} else { Write-Output '  不存在' }
Write-Output ''
Write-Output '=== 3) 找前端静态资源（含插件管理界面） ==='
$cands = @()
foreach ($base in @('D:\Application\dsh\resources\app.asar.unpacked', 'D:\Application\dsh\resources')) {
    if (Test-Path -LiteralPath $base) {
        $cands += Get-ChildItem -LiteralPath $base -Recurse -Force -File -Include '*.js' -ErrorAction SilentlyContinue |
            Where-Object { $_.Length -gt 200KB -and $_.FullName -match 'frontend|web|assets|dist|static' } | Select-Object -First 20
    }
}
Write-Output ('  候选前端文件: ' + $cands.Count)
foreach ($f in $cands) { Write-Output ("    $([Math]::Round($f.Length/1KB)) KB  $($f.FullName.Substring('D:\Application\dsh\resources'.Length))") }
Write-Output ''
Write-Output '=== 4) 在候选里搜插件管理相关文案 ==='
$found = 0
foreach ($f in ($cands | Select-Object -First 6)) {
    $t = ''
    try { $t = [System.IO.File]::ReadAllText($f.FullName, [System.Text.Encoding]::UTF8) } catch { continue }
    foreach ($kw in @('插件市场', '安装插件', '插件管理', 'plugin-manager', 'pluginMarket', 'installPlugin')) {
        $i = $t.IndexOf($kw)
        if ($i -ge 0) {
            Write-Output ("  [" + $kw + "] in " + (Split-Path -Leaf $f.FullName))
            Write-Output ('      ' + (($t.Substring([Math]::Max(0, $i - 120), [Math]::Min(300, $t.Length - [Math]::Max(0, $i - 120)))) -replace '\s+', ' '))
            $found++
            break
        }
    }
    if ($found -ge 8) { break }
}
if ($found -eq 0) { Write-Output '  (候选里未命中，前端可能在 app.asar 内，需要解包)' }", "description": "Find plugin UI assets in desktop app", "timeoutMs": 300000}

