        if ($isLink) { try { $tgt = ' -> ' + $_.Target } catch { } }
        $mark = ''
        if ($_.Name -match 'plugin|market') { $mark = '   <<< 插件相关' }
        Write-Output ("    " + $_.Name.PadRight(46) + "link=$isLink$tgt$mark")
    }
} else { Write-Output '  目录不存在' }
Write-Output ''
