    $p = Join-Path $pa $n
    if (Test-Path -LiteralPath $p) {
        Write-Output "  [$n]"
        Get-ChildItem -LiteralPath $p -Recurse -Force -File -ErrorAction SilentlyContinue | Select-Object -First 12 | ForEach-Object { Write-Output ("      " + $_.FullName.Substring($p.Length + 1) + "   " + [Math]::Round($_.Length/1KB) + " KB") }
    } else { Write-Output "  [$n] (不存在)" }
}
Write-Output ''
