content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$base = Join-Path $env:USERPROFILE '.dsh\profiles\node_modules\@deepseek-ai'
Write-Output '=== 插件管理 UI 包（就是客户端里的入口） ==='
foreach ($n in @('dsh-client-ui-settings-plugins', 'dsh-client-ui-settings-plugin-inventory', 'dsh-host-plugin-inventory', 'dsh-plugin-package-inventory-deepseek')) {
    $p = Join-Path $base $n
    if (Test-Path -LiteralPath $p) {
        $pj = Join-Path $p 'package.json'
        $desc = ''; $ver = ''
        if (Test-Path -LiteralPath $pj) { try { $o = [System.IO.File]::ReadAllText($pj, [System.Text.Encoding]::UTF8) | ConvertFrom-Json; $desc = $o.description; $ver = $o.version } catch { } }
        Write-Output ("  [$n]  v$ver")
        Write-Output ("      $desc")
    } else { Write-Output "  [$n] (不存在)" }
}
Write-Output ''
Write-Output '=== 从这些包里提取界面文案（中文标签） ==='
foreach ($n in @('dsh-client-ui-settings-plugins', 'dsh-client-ui-settings-plugin-inventory')) {
    $p = Join-Path $base $n
    if (-not (Test-Path -LiteralPath $p)) { continue }
    $files = @(Get-ChildItem -LiteralPath $p -Recurse -Force -File -Include '*.js', '*.yaml', '*.json' -ErrorAction SilentlyContinue | Where-Object { $_.Length -lt 2MB })
    Write-Output ("  --- $n  ($($files.Count) 个文件)")
    foreach ($f in $files) {
        $t = ''
        try { $t = [System.IO.File]::ReadAllText($f.FullName, [System.Text.Encoding]::UTF8) } catch { continue }
        foreach ($kw in @('插件', 'Plugins', '安装插件', '插件市场', '不兼容', 'incompatible')) {
            $i = $t.IndexOf($kw)
            if ($i -ge 0) {
                Write-Output ("      [" + $kw + "] " + (Split-Path -Leaf $f.FullName) + " :: " + (($t.Substring([Math]::Max(0, $i - 70), [Math]::Min(190, $t.Length - [Math]::Max(0, $i - 70)))) -replace '\s+', ' '))
                break
            }
        }
    }
}
Write-Output ''
Write-Output '=== 关键疑点：profiles 的模块锚点指向旧 CLI（0.1.7） ==='
foreach ($n in @('dsh-base', 'dsh-web-app', 'dsh-client-ui-settings-plugins')) {
    $p = Join-Path $base $n
    if (Test-Path -LiteralPath $p) {
        $pj = Join-Path $p 'package.json'
        if (Test-Path -LiteralPath $pj) {
            try { Write-Output ("  " + $n.PadRight(36) + " v" + ([System.IO.File]::ReadAllText($pj, [System.Text.Encoding]::UTF8) | ConvertFrom-Json).version) } catch { Write-Output ("  " + $n + "  (读取失败)") }
        }
    }
}", "description": "Find plugin UI labels and check anchor versions", "timeoutMs": 300000}

