content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$base = Join-Path $env:APPDATA 'npm\node_modules\@deepseek-ai\dsh\node_modules\@deepseek-ai'
$pm = Join-Path $base 'dsh-client-ui-plugin-manager'
Write-Output '=== dsh-client-ui-plugin-manager ==='
Write-Output ('  存在: ' + (Test-Path -LiteralPath $pm))
if (Test-Path -LiteralPath $pm) {
    $pj = Join-Path $pm 'package.json'
    if (Test-Path -LiteralPath $pj) {
        $o = [System.IO.File]::ReadAllText($pj, [System.Text.Encoding]::UTF8) | ConvertFrom-Json
        Write-Output ('  version: ' + $o.version)
        Write-Output ('  desc   : ' + $o.description)
    }
    Get-ChildItem -LiteralPath $pm -Recurse -Force -File -ErrorAction SilentlyContinue | ForEach-Object { Write-Output ("    " + $_.FullName.Substring($pm.Length + 1) + "   " + [Math]::Round($_.Length/1KB) + " KB") }
    Write-Output ''
    Write-Output '  --- 中文界面文案（决定菜单名的就是这些） ---'
    foreach ($f in @(Get-ChildItem -LiteralPath $pm -Recurse -Force -File -Include '*.js','*.yaml','*.md' -ErrorAction SilentlyContinue)) {
        $t = ''
        try { $t = [System.IO.File]::ReadAllText($f.FullName, [System.Text.Encoding]::UTF8) } catch { continue }
        if ($t -match 'const zh\s*=\s*\{') {
            $i = $t.IndexOf('const zh')
            Write-Output ("    [" + (Split-Path -Leaf $f.FullName) + "] " + (($t.Substring($i, [Math]::Min(700, $t.Length - $i))) -replace '\s+', ' '))
        }
    }
    Write-Output ''
    Write-Output '  --- 它注册到哪个界面位置 ---'
    foreach ($f in @(Get-ChildItem -LiteralPath $pm -Recurse -Force -File -Include '*.js' -ErrorAction SilentlyContinue)) {
        $t = ''
        try { $t = [System.IO.File]::ReadAllText($f.FullName, [System.Text.Encoding]::UTF8) } catch { continue }
        foreach ($kw in @('settings', 'nav', 'register', 'section')) {
            $i = $t.IndexOf($kw)
            if ($i -ge 0) {
                Write-Output ("    [" + $kw + "] " + (($t.Substring([Math]::Max(0,$i-90), [Math]::Min(240, $t.Length - [Math]::Max(0,$i-90)))) -replace '\s+', ' '))
                break
            }
        }
    }
}
Write-Output ''
Write-Output '=== dsh-plugin-manager（宿主侧）说明 ==='
$hpm = Join-Path $base 'dsh-plugin-manager'
if (Test-Path -LiteralPath $hpm) {
    $pj = Join-Path $hpm 'package.json'
    if (Test-Path -LiteralPath $pj) { $o = [System.IO.File]::ReadAllText($pj, [System.Text.Encoding]::UTF8) | ConvertFrom-Json; Write-Output ('  v' + $o.version + '  ' + $o.description) }
    $rd = Join-Path $hpm 'README.zh.md'
    if (Test-Path -LiteralPath $rd) {
        $t = [System.IO.File]::ReadAllText($rd, [System.Text.Encoding]::UTF8)
        Write-Output ('  中文 README 前 900 字:')
        Write-Output ('    ' + (($t.Substring(0, [Math]::Min(900, $t.Length))) -replace "`r?`n", ' ' -replace '\s+', ' '))
