content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
Write-Output '=== 1) CPU (registry, no CIM needed) ==='
$cpu = 'HKLM:\HARDWARE\DESCRIPTION\System\CentralProcessor'
Get-ChildItem -Path $cpu -ErrorAction SilentlyContinue | ForEach-Object {
    $pp = Get-ItemProperty -Path $_.PSPath -ErrorAction SilentlyContinue
    Write-Output ("  [" + $_.PSChildName + "] " + $pp.ProcessorNameString + "  ~" + $pp.'~MHz' + " MHz  identifier=" + $pp.Identifier)
}
Write-Output ''
Write-Output '=== 2) OS / build ==='
$cv = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue
Write-Output ("  " + $cv.ProductName + "  DisplayVersion=" + $cv.DisplayVersion + "  Build=" + $cv.CurrentBuild + "." + $cv.UBR + "  Edition=" + $cv.EditionID)
Write-Output ''
Write-Output '=== 3) NPU / compute accelerators (pnputil) ==='
foreach ($cls in @('ComputeAccelerator', 'Display', 'SoftwareDevice')) {
    Write-Output ("  --- class: $cls")
    $o = & cmd.exe /c "pnputil /enum-devices /class $cls" 2>&1 | Out-String
    $lines = $o -split "`r?`n"
    for ($i = 0; $i -lt $lines.Count; $i++) {
        if ($lines[$i] -match 'Device Description|Instance ID|Driver Name|Status') { Write-Output ("      " + $lines[$i].Trim()) }
    }
}
Write-Output ''
Write-Output '=== 4) Intel NPU driver / related services ==='
foreach ($k in @('HKLM:\SOFTWARE\Intel\NPU', 'HKLM:\SYSTEM\CurrentControlSet\Services\IntelNpuDriver', 'HKLM:\SYSTEM\CurrentControlSet\Services\npu')) {
    Write-Output ("  " + (Test-Path $k).ToString().PadRight(6) + $k)
}
Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Services' -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '(?i)npu|vpu|ai.?boost' } | ForEach-Object { Write-Output ("    service: " + $_.PSChildName) }
Write-Output ''
Write-Output '=== 5) RAM (CIM may be denied; else systeminfo fallback) ==='
try {
    $mem = Get-CimInstance Win32_PhysicalMemory -ErrorAction Stop
    $total = 0
    foreach ($m in $mem) { $total += $m.Capacity; Write-Output ("  " + [Math]::Round($m.Capacity/1GB) + " GB  " + $m.Speed + " MT/s  " + $m.Manufacturer + "  " + $m.PartNumber) }
    Write-Output ("  total: " + [Math]::Round($total/1GB) + " GB")
} catch { Write-Output ("  CIM denied: " + $_.Exception.Message) }
try { $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction Stop; Write-Output ("  system: " + $cs.Manufacturer + " " + $cs.Model + "  RAM=" + [Math]::Round($cs.TotalPhysicalMemory/1GB,1) + " GB") } catch { Write-Output '  Win32_ComputerSystem denied' }
Write-Output ''
Write-Output '=== 6) GPU VRAM (registry) ==='
$gpuClass = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}'
Get-ChildItem -Path $gpuClass -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
    $pp = Get-ItemProperty -Path $_.PSPath -ErrorAction SilentlyContinue
    if ($pp.DriverDesc) {
        $vram = 0
        if ($pp.PSObject.Properties['HardwareInformation.qwMemorySize']) { $vram = $pp.'HardwareInformation.qwMemorySize' }
        elseif ($pp.PSObject.Properties['HardwareInformation.MemorySize']) { $vram = $pp.'HardwareInformation.MemorySize' }
        Write-Output ("  " + $pp.DriverDesc + "   VRAM=" + [Math]::Round($vram/1GB,1) + " GB   driver=" + $pp.DriverVersion + "   date=" + $pp.DriverDate)
    }
}
Write-Output ''
Write-Output '=== 7) Disks ==='
[System.IO.DriveInfo]::GetDrives() | Where-Object { $_.IsReady } | ForEach-Object { Write-Output ("  " + $_.Name + " " + $_.DriveType + " " + $_.DriveFormat + "  free " + [Math]::Round($_.AvailableFreeSpace/1GB,1) + " / " + [Math]::Round($_.TotalSize/1GB,1) + " GB") }
Write-Output ''
Write-Output '=== 8) Existing AI/dev stack ==='
foreach ($c in @('python', 'python3', 'pip', 'node', 'npm', 'pnpm', 'git', 'wsl', 'docker', 'nvcc', 'ollama', 'conda')) {
    $g = Get-Command $c -ErrorAction SilentlyContinue
    if ($g) { Write-Output ("  " + $c.PadRight(8) + $g.Source) } else { Write-Output ("  " + $c.PadRight(8) + "(not found)") }
}
Write-Output '  --- python version ---'
& cmd.exe /c 'python --version' 2>&1 | ForEach-Object { Write-Output ("    " + $_) }
Write-Output '  --- installed AI packages (if any) ---'
& cmd.exe /c 'python -m pip list' 2>&1 | Select-String -Pattern 'torch|openvino|onnx|transformers|diffusers|numpy|paddle' | Select-Object -First 15 | ForEach-Object { Write-Output ("    " + $_.Line) }
Write-Output '  --- WSL ---'
& cmd.exe /c 'wsl --status' 2>&1 | Select-Object -First 6 | ForEach-Object { Write-Output ("    " + $_) }
Write-Output ''
Write-Output '=== 9) Virtualization / Hyper-V capability ==='
try { $cs2 = Get-CimInstance Win32_Processor -ErrorAction Stop; Write-Output ("  VirtualizationFirmwareEnabled=" + $cs2.VirtualizationFirmwareEnabled + "  SecondLevelAddressTranslation=" + $cs2.SecondLevelAddressTranslationExtensions) } catch { Write-Output '  (denied)' }", "description": "Detect CPU GPU NPU RAM and AI stack", "timeoutMs": 420000}

