{"command": "$ErrorActionPreference = 'Continue'
$f = 'E:\Deepseek\workspace\conv-20260928-3b54e160\dxdiag.txt'
$bytes = [System.IO.File]::ReadAllBytes($f)
Write-Output ('dxdiag bytes: ' + $bytes.Length + '  first4: ' + ($bytes[0..3] -join ','))
# dxdiag writes UTF-16LE with BOM usually
$txt = [System.Text.Encoding]::Unicode.GetString($bytes)
$lines = $txt -split "`r?`n"
Write-Output ('lines: ' + $lines.Count)
$want = 'Processor|Memory|Card name|Chip type|Display Memory|Dedicated Memory|Shared Memory|Driver Version|Driver Model|Operating System|DirectX Version|Miracast|System Model|System Manufacturer|BIOS'
$i = 0
foreach ($l in $lines) {
    if ($l -match $want) {
        $s = $l.Trim()
        if ($s -and $s.Length -lt 160) { Write-Output ('  ' + $s) }
        $i++
        if ($i -gt 45) { break }
    }
}", "description": "Parse dxdiag for RAM and VRAM", "timeoutMs": 180000}

