function httpGet(url, headers) {
  return new Promise((resolve) => {
    const req = https.get(url, { headers: Object.assign({ 'User-Agent': 'probe/1.0' }, headers || {}) }, (r) => {
      if (r.statusCode >= 300 && r.statusCode < 400 && r.headers.location) { r.resume(); resolve(httpGet(new URL(r.headers.location, url).toString(), headers)); return; }
      const chunks = [];
      r.on('data', (c) => { chunks.push(c); });
      r.on('end', () => resolve({ code: r.statusCode, buf: Buffer.concat(chunks), headers: r.headers }));
    });
    req.on('error', (e) => resolve({ code: 0, buf: Buffer.from('ERR ' + e.message), headers: {} }));
    req.setTimeout(30000, () => { req.destroy(); resolve({ code: 0, buf: Buffer.from('TIMEOUT'), headers: {} }); });
  });
}
(async () => {
  const api = await httpGet('https://hf-mirror.com/api/models/helenai/Qwen2.5-VL-3B-Instruct-ov-int4-npu?blobs=true');
  let total = 0, rows = [];
  try {
    const j = JSON.parse(api.buf.toString());
    for (const s of j.siblings) {
      const size = s.size || 0;
      total += size;
      rows.push([s.rfilename, size]);
    }
  } catch (e) { console.log('parse failed: ' + e.message); }
  rows.sort((a, b) => b[1] - a[1]);
  console.log('=== model files (largest first) ===');
  for (const [n, s] of rows) console.log('  ' + (s / 1048576).toFixed(1).padStart(9) + ' MB  ' + n);
