  const big = rows.length ? rows[0][0] : 'openvino_language_model.bin';
  const url = 'https://hf-mirror.com/helenai/Qwen2.5-VL-3B-Instruct-ov-int4-npu/resolve/main/' + encodeURIComponent(big);
  console.log('\n=== speed test on ' + big + ' (8 MB range) ===');
  const t0 = Date.now();
  const r = await httpGet(url, { Range: 'bytes=0-8388607' });
  const secs = (Date.now() - t0) / 1000;
  console.log('  HTTP ' + r.code + '  got ' + r.buf.length + ' bytes in ' + secs.toFixed(1) + ' s = ' + (r.buf.length / 1048576 / secs).toFixed(2) + ' MB/s');
  console.log('  content-length(header): ' + (r.headers['content-length'] || '?'));
})();
