// parallel-download2.js <url> <out> [totalBytes] [connections]
// fetch-based multi-connection ranged download: fetch follows redirects and keeps the Range header.
const fs = require('fs');
const path = require('path');
const { Readable } = require('stream');
const { pipeline } = require('stream/promises');

function parseArgs(argv) {
  return {
    url: argv[2],
    out: argv[3],
    total: argv[4] ? parseInt(argv[4], 10) : 0,
    conns: argv[5] ? parseInt(argv[5], 10) : 16,
  };
}

async function getTotal(url) {
  const res = await fetch(url, { method: 'HEAD', headers: { 'User-Agent': 'parallel-dl/1.0' }, redirect: 'follow' });
  return parseInt(res.headers.get('content-length') || '0', 10);
}

async function downloadRange(url, start, end, partPath) {
  const expected = end - start + 1;
  const res = await fetch(url, {
    headers: { 'User-Agent': 'parallel-dl/1.0', Range: 'bytes=' + start + '-' + end },
    redirect: 'follow',
  });
  if (res.status !== 200 && res.status !== 206) {
    throw new Error('HTTP ' + res.status + ' for range ' + start + '-' + end);
  }
  await pipeline(Readable.fromWeb(res.body), fs.createWriteStream(partPath));
  const got = fs.statSync(partPath).size;
  if (got !== expected) { throw new Error('short part ' + got + '/' + expected); }
  return got;
}

async function main() {
  const { url, out, total, conns } = parseArgs(process.argv);
  if (!url || !out) { console.error('usage: node parallel-download2.js <url> <out> [total] [conns]'); process.exit(2); }
  const size = total || (await getTotal(url));
  if (!size) { console.error('cannot determine size'); process.exit(3); }
