  if (!fs.existsSync(dir)) { fs.mkdirSync(dir, { recursive: true }); }
  console.log('total ' + (size / 1048576).toFixed(1) + ' MB over ' + conns + ' connections');
  const chunk = Math.ceil(size / conns);
  const parts = [];
  const t0 = Date.now();
  const jobs = [];
  for (let i = 0; i < conns; i++) {
    const start = i * chunk;
    if (start >= size) break;
    const end = Math.min(start + chunk - 1, size - 1);
    const partPath = out + '.part' + i;
    parts.push(partPath);
    const expected = end - start + 1;
    if (fs.existsSync(partPath) && fs.statSync(partPath).size === expected) { continue; }
    jobs.push(
      downloadRange(url, start, end, partPath)
        .then((n) => console.log('  part ' + i + ' ok ' + (n / 1048576).toFixed(1) + ' MB'))
        .catch((e) => { console.error('  part ' + i + ' FAILED: ' + e.message); throw e; })
    );
  }
  await Promise.all(jobs);
  const ws = fs.createWriteStream(out, { flags: 'w' });
  for (const p of parts) {
    await new Promise((resolve, reject) => {
      const rs = fs.createReadStream(p);
      rs.on('error', reject);
      rs.on('end', resolve);
      rs.pipe(ws, { end: false });
    });
  }
  await new Promise((r) => ws.end(r));
  const finalSize = fs.statSync(out).size;
  const secs = (Date.now() - t0) / 1000;
  console.log('merged ' + finalSize + ' / ' + size + '  match=' + (finalSize === size));
  console.log('elapsed ' + secs.toFixed(1) + ' s   avg ' + (finalSize / 1048576 / secs).toFixed(2) + ' MB/s');
  if (finalSize === size) { for (const p of parts) fs.unlinkSync(p); }
  process.exit(finalSize === size ? 0 : 1);
}
