const { Readable } = require('stream');
const { pipeline } = require('stream/promises');

function parseArgs(argv) {
  return {
    url: argv[2],
    out: argv[3],
    total: argv[4] ? parseInt(argv[4], 10) : 0,
    conns: argv[5] ? parseInt(argv[5], 10) : 16,
  };
}

async function getTotal(url) {
  const res = await fetch(url, { method: 'HEAD', headers: { 'User-Agent': 'parallel-dl/1.0' }, redirect: 'follow' });
  return parseInt(res.headers.get('content-length') || '0', 10);
}

async function downloadRange(url, start, end, partPath) {
  const expected = end - start + 1;
  const res = await fetch(url, {
    headers: { 'User-Agent': 'parallel-dl/1.0', Range: 'bytes=' + start + '-' + end },
    redirect: 'follow',
  });
  if (res.status !== 200 && res.status !== 206) {
    throw new Error('HTTP ' + res.status + ' for range ' + start + '-' + end);
  }
  await pipeline(Readable.fromWeb(res.body), fs.createWriteStream(partPath));
  const got = fs.statSync(partPath).size;
  if (got !== expected) { throw new Error('short part ' + got + '/' + expected); }
  return got;
}

async function main() {
  const { url, out, total, conns } = parseArgs(process.argv);
  if (!url || !out) { console.error('usage: node parallel-download2.js <url> <out> [total] [conns]'); process.exit(2); }
  const size = total || (await getTotal(url));
  if (!size) { console.error('cannot determine size'); process.exit(3); }
  const dir = path.dirname(out);
  if (!fs.existsSync(dir)) { fs.mkdirSync(dir, { recursive: true }); }
  console.log('total ' + (size / 1048576).toFixed(1) + ' MB over ' + conns + ' connections');
  const chunk = Math.ceil(size / conns);
  const parts = [];
  const t0 = Date.now();
  const jobs = [];
  for (let i = 0; i < conns; i++) {
    const start = i * chunk;
    if (start >= size) break;
    const end = Math.min(start + chunk - 1, size - 1);
    const partPath = out + '.part' + i;
    parts.push(partPath);
    const expected = end - start + 1;
    if (fs.existsSync(partPath) && fs.statSync(partPath).size === expected) { continue; }
    jobs.push(
      downloadRange(url, start, end, partPath)
        .then((n) => console.log('  part ' + i + ' ok ' + (n / 1048576).toFixed(1) + ' MB'))
        .catch((e) => { console.error('  part ' + i + ' FAILED: ' + e.message); throw e; })
    );
  }
  await Promise.all(jobs);
  const ws = fs.createWriteStream(out, { flags: 'w' });
  for (const p of parts) {
    await new Promise((resolve, reject) => {
      const rs = fs.createReadStream(p);
      rs.on('error', reject);
      rs.on('end', resolve);
      rs.pipe(ws, { end: false });
    });
  }
  await new Promise((r) => ws.end(r));
  const finalSize = fs.statSync(out).size;
  const secs = (Date.now() - t0) / 1000;
  console.log('merged ' + finalSize + ' / ' + size + '  match=' + (finalSize === size));
  console.log('elapsed ' + secs.toFixed(1) + ' s   avg ' + (finalSize / 1048576 / secs).toFixed(2) + ' MB/s');
  if (finalSize === size) { for (const p of parts) fs.unlinkSync(p); }
  process.exit(finalSize === size ? 0 : 1);
}
main().catch((e) => { console.error('FATAL ' + e.message); process.exit(1); });
