{"command": "$js = @'
// fetch-hf-mirror-model.js <repoId> <destDir> [maxConns]
// Pulls a whole HuggingFace repo through hf-mirror.com with per-file multi-connection ranged download.
const fs = require('fs');
const path = require('path');
const { Readable } = require('stream');
const { pipeline } = require('stream/promises');

const ENDPOINT = process.env.HF_ENDPOINT || 'https://hf-mirror.com';

function connsFor(size, maxConns) {
  if (size > 200 * 1048576) return maxConns;
  if (size > 20 * 1048576) return Math.min(8, maxConns);
  if (size > 2 * 1048576) return Math.min(4, maxConns);
  return 1;
}

async function downloadFile(url, dest, size, maxConns) {
  if (fs.existsSync(dest) && fs.statSync(dest).size === size) {
    console.log('  [skip] ' + path.basename(dest) + ' already complete');
    return 'skipped';
  }
  const conns = Math.min(connsFor(size, maxConns), Math.max(1, Math.ceil(size / 65536)));
  const dir = path.dirname(dest);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  console.log('  [get ] ' + path.basename(dest) + '  ' + (size / 1048576).toFixed(2) + ' MB  conns=' + conns);
  if (conns === 1) {
    const res = await fetch(url, { headers: { 'User-Agent': 'fetch-model/1.0' }, redirect: 'follow' });
    if (!res.ok) throw new Error('HTTP ' + res.status + ' for ' + url);
    await pipeline(Readable.fromWeb(res.body), fs.createWriteStream(dest));
  } else {
    const chunk = Math.ceil(size / conns);
    const parts = [];
    const jobs = [];
    for (let i = 0; i < conns; i++) {
      const start = i * chunk;
      if (start >= size) break;
      const end = Math.min(start + chunk - 1, size - 1);
      const part = dest + '.part' + i;
      parts.push(part);
      const expected = end - start + 1;
      if (fs.existsSync(part) && fs.statSync(part).size === expected) continue;
      jobs.push((async () => {
        const res = await fetch(url, { headers: { 'User-Agent': 'fetch-model/1.0', Range: 'bytes=' + start + '-' + end }, redirect: 'follow' });
        if (res.status !== 200 && res.status !== 206) throw new Error('HTTP ' + res.status + ' range ' + start + '-' + end);
        await pipeline(Readable.fromWeb(res.body), fs.createWriteStream(part));
        const got = fs.statSync(part).size;
        if (got !== expected) throw new Error('short part ' + got + '/' + expected);
      })());
    }
    await Promise.all(jobs);
    const ws = fs.createWriteStream(dest, { flags: 'w' });
    for (const p of parts) {
      await new Promise((resolve, reject) => {
        const rs = fs.createReadStream(p);
        rs.on('error', reject); rs.on('end', resolve); rs.pipe(ws, { end: false });
      });
    }
    await new Promise((r) => ws.end(r));
    for (const p of parts) fs.unlinkSync(p);
  }
  const got = fs.statSync(dest).size;
  if (got !== size) throw new Error('size mismatch for ' + dest + ': ' + got + ' != ' + size);
  return 'ok';
}

async function main() {
  const repo = process.argv[2];
  const destDir = process.argv[3];
  const maxConns = process.argv[4] ? parseInt(process.argv[4], 10) : 16;
  const api = await (await fetch(ENDPOINT + '/api/models/' + repo + '?blobs=true', { headers: { 'User-Agent': 'fetch-model/1.0' } })).json();
  const files = (api.siblings || [])
    .filter((s) => !s.rfilename.startsWith('.git'))
    .map((s) => ({ name: s.rfilename, size: s.size || 0 }))
    .filter((f) => f.size > 0)
    .sort((a, b) => b.size - a.size);
  const total = files.reduce((acc, f) => acc + f.size, 0);
  console.log('repo    : ' + repo);
  console.log('files   : ' + files.length + '   total ' + (total / 1073741824).toFixed(2) + ' GB');
  console.log('dest    : ' + destDir);
  console.log('');
  const t0 = Date.now();
  let done = 0;
  for (const f of files) {
    const url = ENDPOINT + '/' + repo + '/resolve/main/' + f.name.split('/').map(encodeURIComponent).join('/');
    const dest = path.join(destDir, ...f.name.split('/'));
    try {
      await downloadFile(url, dest, f.size, maxConns);
      done += f.size;
    } catch (e) {
      console.error('  [FAIL] ' + f.name + ' -> ' + e.message);
    }
  }
  const secs = (Date.now() - t0) / 1000;
  console.log('');
  console.log('downloaded ' + (done / 1073741824).toFixed(2) + ' GB in ' + (secs / 60).toFixed(1) + ' min');
  const onDisk = files.reduce((acc, f) => {
    const p = path.join(destDir, ...f.name.split('/'));
    return acc + (fs.existsSync(p) ? fs.statSync(p).size : 0);
  }, 0);
  console.log('on disk    ' + (onDisk / 1073741824).toFixed(2) + ' GB / expected ' + (total / 1073741824).toFixed(2) + ' GB');
  process.exit(onDisk === total ? 0 : 1);
}
main().catch((e) => { console.error('FATAL ' + e.message); process.exit(1); });
