// fetch-hf-mirror-model2.js <repoId> <destDir> [maxConns]
// Robust variant: authoritative size comes from the server (HEAD / Content-Range), not the API.
// Every part retries on failure; the merge is verified against the server size.
const fs = require('fs');
const path = require('path');
const { Readable } = require('stream');
const { pipeline } = require('stream/promises');

const ENDPOINT = process.env.HF_ENDPOINT || 'https://hf-mirror.com';
const UA = { 'User-Agent': 'fetch-model/2.0' };

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function serverSize(url) {
  try {
    const res = await fetch(url, { method: 'HEAD', redirect: 'follow', headers: UA });
    const len = parseInt(res.headers.get('content-length') || '0', 10);
    if (len > 0) return len;
  } catch (e) { /* fall through */ }
  const res = await fetch(url, { headers: Object.assign({ Range: 'bytes=0-0' }, UA), redirect: 'follow' });
  const cr = res.headers.get('content-range') || '';
  const m = /\/(\d+)\s*$/.exec(cr);
  return m ? parseInt(m[1], 10) : 0;
}

function connsFor(size, maxConns) {
  if (size > 200 * 1048576) return maxConns;
  if (size > 20 * 1048576) return Math.min(6, maxConns);
  if (size > 2 * 1048576) return Math.min(3, maxConns);
  return 1;
}

async function fetchRange(url, start, end, part) {
  const expected = end - start + 1;
  const res = await fetch(url, {
    headers: Object.assign({ Range: 'bytes=' + start + '-' + end }, UA),
    redirect: 'follow',
  });
  if (res.status !== 200 && res.status !== 206) throw new Error('HTTP ' + res.status);
  await pipeline(Readable.fromWeb(res.body), fs.createWriteStream(part));
  const got = fs.statSync(part).size;
  if (got !== expected) throw new Error('short part ' + got + '/' + expected);
}

async function withRetry(fn, label, attempts) {
  let last;
  for (let i = 1; i <= attempts; i++) {
    try { return await fn(); } catch (e) {
      last = e;
      console.log('    retry ' + i + '/' + attempts + ' for ' + label + ': ' + e.message);
      await sleep(1500 * i);
    }
  }
  throw last;
}

async function downloadFile(url, dest, size, maxConns) {
  const dir = path.dirname(dest);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  if (fs.existsSync(dest) && fs.statSync(dest).size === size) {
    console.log('  [skip] ' + path.basename(dest) + ' (' + (size / 1048576).toFixed(2) + ' MB already complete)');
    return size;
  }
  const conns = Math.min(connsFor(size, maxConns), Math.max(1, Math.ceil(size / 65536)));
  console.log('  [get ] ' + path.basename(dest) + '  ' + (size / 1048576).toFixed(2) + ' MB  conns=' + conns);
  const t0 = Date.now();
  if (conns === 1) {
    await withRetry(() => fetchRange(url, 0, size - 1, dest), path.basename(dest), 4);
  } else {
    const chunk = Math.ceil(size / conns);
    const parts = [];
    const jobs = [];
    for (let i = 0; i < conns; i++) {
      const start = i * chunk;
      if (start >= size) break;
      const end = Math.min(start + chunk - 1, size - 1);
      const part = dest + '.part' + i;
      parts.push(part);
      const expected = end - start + 1;
      if (fs.existsSync(part) && fs.statSync(part).size === expected) continue;
      jobs.push(withRetry(() => fetchRange(url, start, end, part), path.basename(part), 4));
    }
    await Promise.all(jobs);
    const ws = fs.createWriteStream(dest, { flags: 'w' });
    for (const p of parts) {
      await new Promise((resolve, reject) => {
        const rs = fs.createReadStream(p);
        rs.on('error', reject);
        rs.on('end', resolve);
        rs.pipe(ws, { end: false });
      });
    }
    await new Promise((r) => ws.end(r));
    for (const p of parts) { if (fs.existsSync(p)) fs.unlinkSync(p); }
  }
  const got = fs.statSync(dest).size;
  if (got !== size) throw new Error('final size mismatch ' + got + ' != ' + size);
  console.log('        done in ' + ((Date.now() - t0) / 1000).toFixed(1) + ' s');
  return size;
}

async function main() {
  const repo = process.argv[2];
  const destDir = process.argv[3];
  const maxConns = process.argv[4] ? parseInt(process.argv[4], 10) : 12;
  const api = await (await fetch(ENDPOINT + '/api/models/' + repo, { headers: UA })).json();
  const names = (api.siblings || []).map((s) => s.rfilename).filter((n) => !n.startsWith('.git'));
  console.log('repo  : ' + repo);
  console.log('files : ' + names.length);
  console.log('dest  : ' + destDir);
  console.log('');
  const t0 = Date.now();
  let total = 0;
  const failed = [];
  for (const name of names) {
    const url = ENDPOINT + '/' + repo + '/resolve/main/' + name.split('/').map(encodeURIComponent).join('/');
    const dest = path.join(destDir, ...name.split('/'));
    try {
      const size = await serverSize(url);
      if (!size) { console.log('  [skip] ' + name + ' (no size from server)'); continue; }
      total += await downloadFile(url, dest, size, maxConns);
    } catch (e) {
      console.error('  [FAIL] ' + name + ' -> ' + e.message);
      failed.push(name);
    }
  }
  console.log('');
  console.log('verified on disk: ' + (total / 1073741824).toFixed(2) + ' GB in ' + ((Date.now() - t0) / 60000).toFixed(1) + ' min');
  if (failed.length) { console.log('FAILED: ' + failed.join(', ')); process.exit(1); }
}
main().catch((e) => { console.error('FATAL ' + e.message); process.exit(1); });
