content.arguments:
{"command": "$py = @'
"""dsh-vision: local vision-language MCP server (Qwen2.5-VL-3B INT4 via OpenVINO GenAI).

Runs on the Intel NPU by default. The NPU accepts at most ~1024 visual tokens (about 800k pixels)
per request, so large images are automatically tiled and the per-tile answers are concatenated.
Protocol: MCP over stdio; nothing except the protocol stream is written to stdout.
"""
from __future__ import annotations

import math
import os
import sys
import threading
import time
from datetime import datetime

MODEL_DIR = os.environ.get("DSH_VISION_MODEL", r"D:\AI_file\models\qwen2.5-vl-3b-ov-int4-npu")
DEFAULT_DEVICE = os.environ.get("DSH_VISION_DEVICE", "NPU")
CACHE_DIR = os.environ.get("DSH_VISION_CACHE", r"D:\AI_file\_caches\openvino-model-cache")
LOG_PATH = os.environ.get("DSH_VISION_LOG", r"D:\AI_file\logs\vision-mcp.log")

# NPU refuses input embeddings beyond its compiled prompt length; measured limit is 1024 tokens.
DEVICE_TOKEN_LIMIT = {"NPU": 1024, "GPU": 8192, "CPU": 4096}
TOKENS_PER_PIXEL = 1.0 / 784.0  # Qwen2.5-VL: one visual token per 28x28 patch

_lock = threading.Lock()
_pipes: dict[str, object] = {}


def log(message: str) -> None:
    line = "%s  %s" % (datetime.now().strftime("%Y-%m-%d %H:%M:%S"), message)
    try:
        os.makedirs(os.path.dirname(LOG_PATH), exist_ok=True)
        with open(LOG_PATH, "a", encoding="utf-8") as fh:
            fh.write(line + "\n")
    except Exception:
        pass
    print(line, file=sys.stderr, flush=True)


def pipeline(device: str):
    with _lock:
        pipe = _pipes.get(device)
        if pipe is None:
            import openvino_genai

            t0 = time.perf_counter()
            pipe = openvino_genai.VLMPipeline(MODEL_DIR, device, CACHE_DIR=CACHE_DIR)
            _pipes[device] = pipe
            log("loaded pipeline device=%s in %.1fs" % (device, time.perf_counter() - t0))
        return pipe


def visual_tokens(size) -> int:
    return int(size[0] * size[1] * TOKENS_PER_PIXEL)


def to_tensor(image):
    import numpy as np
    import openvino as ov

    image = image.convert("RGB")
    arr = np.asarray(image, dtype=np.uint8).reshape(1, image.size[1], image.size[0], 3)
    return ov.Tensor(arr)


def load_image(path: str):
    from PIL import Image

    if not os.path.isfile(path):
        raise FileNotFoundError("image not found: %s" % path)
    return Image.open(path)


def fit_single(image, limit: int):
    """Downscale the image so it fits the token limit; returns (image, scale)."""
    tokens = visual_tokens(image.size)
    if tokens <= limit:
        return image, 1.0
    scale = math.sqrt(limit / float(tokens)) * 0.98
    new_size = (max(64, int(image.size[0] * scale)), max(64, int(image.size[1] * scale)))
    return image.resize(new_size), scale


def tile_grid(image, limit: int):
    """Split the image into the smallest n x n grid whose tiles each fit the limit."""
    if visual_tokens(image.size) <= limit:
        return None
    w, h = image.size
    for n in range(2, 7):
        tw, th = math.ceil(w / n), math.ceil(h / n)
        if visual_tokens((tw, th)) <= limit:
            tiles = []
            for r in range(n):
                for c in range(n):
                    box = (c * tw, r * th, min((c + 1) * tw, w), min((r + 1) * th, h))
                    if box[2] - box[0] > 8 and box[3] - box[1] > 8:
                        tiles.append((r, c, box, image.crop(box)))
            return n, tiles
    return None


def generate(image, prompt: str, device: str, max_new_tokens: int) -> tuple[str, float]:
    pipe = pipeline(device)
    tensor = to_tensor(image)
    t0 = time.perf_counter()
    result = pipe.generate(prompt, image=tensor, max_new_tokens=max_new_tokens)
    elapsed = time.perf_counter() - t0
    text = result.texts[0] if getattr(result, "texts", None) else str(result)
    return text.strip(), elapsed


def analyse(image_path: str, prompt: str, device: str, max_new_tokens: int, allow_tiling: bool) -> str:
    image = load_image(image_path)
    limit = DEVICE_TOKEN_LIMIT.get(device.upper(), 1024)
    tokens = visual_tokens(image.size)
    parts: list[str] = []

    if tokens > limit and allow_tiling:
        grid = tile_grid(image, limit)
        if grid:
            n, tiles = grid
            parts.append("[image %dx%d = %d visual tokens exceeds the %s limit of %d; split into a %dx%d grid of %d tiles]"
                         % (image.size[0], image.size[1], tokens, device, limit, n, n, len(tiles)))
            for r, c, box, tile in tiles:
                text, elapsed = generate(tile, prompt, device, max_new_tokens)
                log("tile r%dc%d %dx%d %.1fs chars=%d" % (r, c, box[2] - box[0], box[3] - box[1], elapsed, len(text)))
