from mcp.server.mcpserver import MCPServer  # noqa: E402

server = MCPServer(
    name="dsh-vision",
    version="1.1.0",
    instructions=(
        "Local vision-language model (Qwen2.5-VL-3B, INT4) running offline on this machine's Intel NPU "
        "through OpenVINO. Use it to look at image and PDF files on disk: extracting text (OCR), "
        "describing content, reading charts/diagrams/documents, answering questions about a picture, "
        "and reasoning about object positions. Pass absolute Windows paths. The NPU accepts at most "
        "1024 visual tokens per request, so large images are automatically split into tiles and the "
        "per-tile results are concatenated; PDFs are rendered per page. Everything runs locally: no "
        "network access, no data leaves the machine. Expect 10-20 seconds per tile."
    ),
)


@server.tool(description="Extract all visible text from a local image file (OCR). Large images are automatically tiled to respect the NPU token limit. Set tiling=false to force a single downscaled pass.")
def vision_ocr(image_path: str, device: str = DEFAULT_DEVICE, max_new_tokens: int = 512, tiling: bool = True) -> str:
    return analyse(image_path, "Read all the text in this image exactly as written, preserving line breaks.", device, max_new_tokens, tiling)


@server.tool(description="Describe a local image file in detail: objects, colors, layout, text, anything unusual.")
def vision_describe(image_path: str, device: str = DEFAULT_DEVICE, max_new_tokens: int = 320, tiling: bool = False) -> str:
    return analyse(image_path, "Describe this image in detail: objects, colors, layout, any visible text, and anything unusual.", device, max_new_tokens, tiling)


@server.tool(description="Ask an arbitrary question about a local image file: visual QA, counting, chart or diagram reading, spatial relations, defect questions.")
def vision_ask(image_path: str, question: str, device: str = DEFAULT_DEVICE, max_new_tokens: int = 320, tiling: bool = False) -> str:
    return analyse(image_path, question, device, max_new_tokens, tiling)


@server.tool(description="Render pages of a local PDF and read them with the vision model. pages accepts '1', '1,3', or '2-5'. Returns the extracted text per page. Use for datasheets, papers, scanned documents.")
def vision_read_pdf(pdf_path: str, pages: str = "1", dpi: int = 150, device: str = DEFAULT_DEVICE, max_new_tokens: int = 512) -> str:
    if not os.path.isfile(pdf_path):
        raise FileNotFoundError("pdf not found: %s" % pdf_path)
    out_dir = os.path.join(os.path.dirname(os.path.abspath(pdf_path)), "_vision_pages") if False else r"D:\AI_file\workspace\pdf-pages"
    rendered = pdf_pages(pdf_path, pages, dpi, out_dir)
    if not rendered:
        return "no pages rendered for pages=%r" % pages
    blocks = []
    for image_path in rendered:
        text = analyse(image_path, "Read all the text in this image exactly as written, preserving line breaks.", device, max_new_tokens, True)
        blocks.append("===== %s =====\n%s" % (os.path.basename(image_path), text))
    return "\n\n".join(blocks)


@server.tool(description="Report the local vision server status: model path, default device, loaded pipelines, token limits, and the OpenVINO devices available.")
def vision_status() -> str:
    lines = [
        "model    : %s" % MODEL_DIR,
        "default  : %s" % DEFAULT_DEVICE,
        "loaded   : %s" % (sorted(_pipes) or "none"),
        "limits   : %s" % ", ".join("%s<=%d tokens" % (k, v) for k, v in DEVICE_TOKEN_LIMIT.items()),
    ]
    try:
        import openvino as ov

        core = ov.Core()
        for dev in core.available_devices:
            try:
                lines.append("device   : %-4s -> %s" % (dev, core.get_property(dev, "FULL_DEVICE_NAME")))
            except Exception:
                lines.append("device   : %s" % dev)
    except Exception as exc:  # noqa: BLE001
        lines.append("devices  : unavailable (%s)" % exc)
    return "\n".join(lines)


if __name__ == "__main__":
    log("starting dsh-vision MCP server v1.1 (model=%s device=%s)" % (MODEL_DIR, DEFAULT_DEVICE))
    server.run("stdio")
