content.arguments:
{"command": "$f = 'C:\Users\徐丰哲\.dsh\profiles\web\cordis.patch.yml'
$lines = [System.IO.File]::ReadAllLines($f, [System.Text.Encoding]::UTF8)
$start = -1
for ($i = 0; $i -lt $lines.Count; $i++) { if ($lines[$i] -match '^-\s+id:\s*mcp-vision\s*$') { $start = $i; break } }
if ($start -lt 0) { Write-Output '未找到 mcp-vision 条目（可能已是 insert 形式）' } else {
    $end = $lines.Count - 1
    for ($i = $start + 1; $i -lt $lines.Count; $i++) { if ($lines[$i] -match '^-\s') { $end = $i - 1; break } }
    Write-Output ("条目位于行 $($start+1)..$($end+1)：")
    for ($i = $start; $i -le $end; $i++) { Write-Output ('    ' + $lines[$i]) }
    $bak = $f + '.bak2-' + (Get-Date).ToString('yyyyMMdd-HHmmss')
    Copy-Item -LiteralPath $f -Destination $bak -Force
    $before = @()
    if ($start -gt 0) { $before = $lines[0..($start - 1)] }
    $entry = $lines[$start..$end]
    $after = @()
    if ($end + 1 -lt $lines.Count) { $after = $lines[($end + 1)..($lines.Count - 1)] }
    $newBlock = @('- insert:')
    foreach ($l in $entry) { $newBlock += ('    ' + $l) }
    $all = @($before) + $newBlock + @($after)
    [System.IO.File]::WriteAllLines($f, $all, (New-Object System.Text.UTF8Encoding($false)))
    Write-Output ('[OK] 已包装为 insert，备份: ' + (Split-Path -Leaf $bak))
}
Write-Output ''
Write-Output '=== 复验组合树（web profile） ==='
$out = & cmd.exe /c 'dsh --profile web --dump-config' 2>&1 | Out-String
$lines2 = $out -split "`r?`n"
$err = @($lines2 | Where-Object { $_ -match 'not found|patch:' })
if ($err.Count) { Write-Output '  报错:'; $err | Select-Object -First 4 | ForEach-Object { Write-Output ('    ' + $_) } } else { Write-Output '  无 patch 报错 ✓' }
for ($i = 0; $i -lt $lines2.Count; $i++) {
    if ($lines2[$i] -match 'mcp-vision') {
        Write-Output ('  组合树中的条目（行 ' + ($i + 1) + '）:')
        for ($j = [Math]::Max(0, $i - 1); $j -le [Math]::Min($lines2.Count - 1, $i + 11); $j++) { Write-Output ('    ' + $lines2[$j]) }
        break
    }
}", "description": "Wrap web profile entry in insert and verify", "justification": "需要修改工作区之外的 web profile 配置并运行 CLI 校验。", "sandbox_permissions": "danger-full-access", "timeoutMs": 300000}

