{"command": "$asar = 'D:\Application\dsh\resources\app.asar'
$txt = [System.Text.Encoding]::GetEncoding('latin1').GetString([System.IO.File]::ReadAllBytes($asar))
Write-Output '=== additionalDirectories / writableRoots 的用户可见文案（中英） ==='
$patterns = @('additionalDirectories', 'writableRoots', '额外目录', '附加目录', '工作区目录', 'additional folders', 'Additional folders', 'sandboxMode')
foreach ($p in $patterns) {
    $f = 0; $n = 0
    while ($n -lt 2) {
        $i = $txt.IndexOf($p, $f); if ($i -lt 0) { break }
        $seg = ($txt.Substring([Math]::Max(0, $i - 200), [Math]::Min(420, $txt.Length - [Math]::Max(0, $i - 200)))) -replace '\s+', ' '
        Write-Output ('  [' + $p + '] ' + $seg)
        Write-Output ''
        $f = $i + $p.Length; $n++
    }
}
Write-Output '=== 沙箱模式的取值 ==='
$f = 0; $n = 0
while ($n -lt 3) {
    $i = $txt.IndexOf('sandboxMode', $f); if ($i -lt 0) { break }
    $seg = ($txt.Substring($i, [Math]::Min(300, $txt.Length - $i))) -replace '\s+', ' '
    Write-Output ('  ' + $seg)
    $f = $i + 11; $n++
}", "description": "Find user-facing multi-root settings", "justification": "需要读取工作区之外的桌面端程序包以确认多根目录如何配置。", "sandbox_permissions": "danger-full-access", "timeoutMs": 600000}

