{"command": "$js = @'
// Repo downloader for huggingface mirrors: lists files, skips safetensors, parallel ranges per file.
const https = require('https');
const fs = require('fs');
const path = require('path');

const REPO = process.argv[2];
const DEST = process.argv[3];
const CONNS = parseInt(process.argv[4] || '8', 10);
const SKIP = /\.safetensors$|\.msgpack$|\.h5$|\.ckpt$|\.onnx$/i;

function request(url, opts) {
  return new Promise((resolve, reject) => {
    const req = https.get(url, { headers: { 'User-Agent': 'repo-fetch/1.0', ...(opts && opts.headers) }, ...opts }, (r) => {
      if (r.statusCode >= 300 && r.statusCode < 400 && r.headers.location) {
        r.resume();
        resolve(request(new URL(r.headers.location, url).toString(), opts));
        return;
      }
      resolve(r);
    });
    req.on('error', reject);
    req.setTimeout(120000, () => req.destroy(new Error('timeout')));
  });
}

function rangeDownload(url, out, size, conns) {
  return new Promise(async (resolve, reject) => {
    const part = Math.ceil(size / conns);
    const tmpDir = out + '.parts';
    fs.mkdirSync(tmpDir, { recursive: true });
    const jobs = [];
    for (let i = 0; i < conns; i++) {
      const start = i * part;
      const end = Math.min(size - 1, start + part - 1);
      if (start > end) break;
      const p = path.join(tmpDir, 'p' + i);
      jobs.push((async () => {
        for (let attempt = 1; attempt <= 3; attempt++) {
          try {
            const r = await request(url, { headers: { Range: `bytes=${start}-${end}` } });
            if (r.statusCode !== 206 && r.statusCode !== 200) throw new Error('HTTP ' + r.statusCode);
            const ws = fs.createWriteStream(p);
            await new Promise((res, rej) => { r.pipe(ws); ws.on('finish', res); ws.on('error', rej); r.on('error', rej); });
            if (fs.statSync(p).size === end - start + 1) return;
            throw new Error('short part');
          } catch (e) {
            if (attempt === 3) throw e;
            await new Promise((r) => setTimeout(r, 2000 * attempt));
          }
        }
      })());
    }
    try {
      await Promise.all(jobs);
      const final = fs.createWriteStream(out);
      for (let i = 0; i < conns; i++) {
        const p = path.join(tmpDir, 'p' + i);
        if (!fs.existsSync(p)) continue;
        await new Promise((res, rej) => { const rs = fs.createReadStream(p); rs.pipe(final, { end: false }); rs.on('end', res); rs.on('error', rej); });
      }
      final.end();
      await new Promise((res) => final.on('finish', res));
      fs.rmSync(tmpDir, { recursive: true, force: true });
      resolve(fs.statSync(out).size);
    } catch (e) { reject(e); }
  });
}

function simpleDownload(url, out) {
  return new Promise(async (resolve, reject) => {
    try {
      const r = await request(url);
      if (r.statusCode !== 200) throw new Error('HTTP ' + r.statusCode);
      fs.mkdirSync(path.dirname(out), { recursive: true });
      const ws = fs.createWriteStream(out);
      r.pipe(ws);
      ws.on('finish', () => resolve(fs.statSync(out).size));
      ws.on('error', reject);
      r.on('error', reject);
    } catch (e) { reject(e); }
  });
}

(async () => {
  const r = await request('https://hf-mirror.com/api/models/' + REPO + '?blobs=true');
  let body = '';
  r.on('data', (c) => (body += c));
  await new Promise((res) => r.on('end', res));
  const info = JSON.parse(body);
  const files = (info.siblings || []).filter((s) => !SKIP.test(s.rfilename));
  const total = files.reduce((a, s) => a + (s.size || 0), 0);
  console.log(`repo ${REPO}: ${files.length} files to fetch, ${(total / 1073741824).toFixed(2)} GB`);
  let done = 0;
  for (const f of files) {
    const out = path.join(DEST, f.rfilename);
    if (fs.existsSync(out) && (!f.size || fs.statSync(out).size === f.size)) { done += f.size || 0; continue; }
    fs.mkdirSync(path.dirname(out), { recursive: true });
    const url = 'https://hf-mirror.com/' + REPO + '/resolve/main/' + f.rfilename;
    const t0 = Date.now();
    try {
      const got = f.size && f.size > 16 * 1024 * 1024 ? await rangeDownload(url, out, f.size, CONNS) : await simpleDownload(url, out);
      done += got;
      console.log(`  ok ${f.rfilename}  ${(got / 1048576).toFixed(1)} MB  ${((Date.now() - t0) / 1000).toFixed(0)}s  [${(done / 1073741824).toFixed(2)}/${(total / 1073741824).toFixed(2)} GB]`);
    } catch (e) {
      console.log(`  FAIL ${f.rfilename}: ${e.message}`);
    }
  }
  console.log('DONE ' + REPO);
})();
