T2I_KIND = os.environ.get("DSH_T2I_KIND", "latent_consistency_model")
_t2i: dict[str, object] = {}


def t2i_pipeline(device: str):
    with _lock:
        pipe = _t2i.get(device)
        if pipe is None:
            import openvino_genai

            if not os.path.isdir(T2I_DIR):
                raise FileNotFoundError("text-to-image model directory not found: %s" % T2I_DIR)
            factory = getattr(openvino_genai.Text2ImagePipeline, T2I_KIND, None)
            if factory is None:
                raise ValueError("unknown Text2ImagePipeline factory: %s" % T2I_KIND)
            t0 = time.perf_counter()
            pipe = factory(T2I_DIR, device)
            _t2i[device] = pipe
            log("text-to-image loaded on %s in %.1fs (%s)" % (device, time.perf_counter() - t0, T2I_KIND))
        return pipe


def t2i_generate(prompt: str, device: str, negative: str, width: int, height: int,
                 steps: int, guidance: float, seed: int):
    import numpy as np
    import openvino_genai

    pipe = t2i_pipeline(device)
    config = openvino_genai.ImageGenerationConfig()
    config.width = int(width)
    config.height = int(height)
    config.num_inference_steps = int(steps)
    if guidance is not None:
        config.guidance_scale = float(guidance)
    if negative:
        config.negative_prompt = negative
    if seed is not None and int(seed) >= 0:
        config.rng_seed = int(seed)
    t0 = time.perf_counter()
    result = pipe.generate(prompt, config)
    elapsed = time.perf_counter() - t0
    if hasattr(result, "data"):
        image = np.array(result.data)
    elif isinstance(result, (list, tuple)) and result:
        image = np.array(result[0].data if hasattr(result[0], "data") else result[0])
    else:
        image = np.array(result)
    image = np.squeeze(image)
    if image.dtype != np.uint8:
        image = np.clip(image, 0, 255).astype(np.uint8)
    return image, elapsed

