        image = np.array(result[0].data if hasattr(result[0], "data") else result[0])
    else:
        image = np.array(result)
    image = np.squeeze(image)
    if image.dtype != np.uint8:
        image = np.clip(image, 0, 255).astype(np.uint8)
    return image, elapsed

