@server.tool(description="Generate an image locally from a text prompt with a Latent Consistency Model (SD1.5-based, 4-8 steps) running on the Intel iGPU via OpenVINO. Nothing leaves the machine. Use it to create illustrations, textures, diagrams or synthetic training data. steps defaults to 6, guidance to 1.5, size to 512x512. The PNG is written to D:\\AI_file\\outputs and its path is returned.")
def image_generate(prompt: str, negative_prompt: str = "", width: int = 512, height: int = 512,
                   steps: int = 6, guidance: float = 1.5, seed: int = -1, device: str = "GPU") -> str:
    import numpy as np

    if not str(prompt).strip():
        raise ValueError("prompt must not be empty")
    image, elapsed = t2i_generate(str(prompt), device, negative_prompt, width, height, steps, guidance, seed)
    if image.ndim != 3 or image.shape[2] < 3:
        raise RuntimeError("unexpected image tensor shape: %s" % (image.shape,))
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    slug = "".join(c if c.isalnum() else "-" for c in str(prompt)[:40].lower()).strip("-") or "image"
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S-%f")[:-3]
    path = os.path.join(OUTPUT_DIR, "image-%s-%s.png" % (slug, stamp))
    PILImage.fromarray(image[:, :, :3]).save(path)
    metric = ""
    try:
        metrics = t2i_pipeline(device).get_performance_metrics()
        parts = []
        for name in ("get_generate_duration", "get_inference_duration", "get_unet_infer_duration"):
            if hasattr(metrics, name):
                value = getattr(metrics, name)()
                if isinstance(value, (int, float)):
                    parts.append("%s=%.2fs" % (name.replace("get_", "").replace("_duration", ""), value))
        metric = "  " + ", ".join(parts)
    except Exception:
        metric = ""
    log("image_generate %s %dx%d steps=%d %.1fs -> %s" % (device, width, height, steps, elapsed, os.path.basename(path)))
    return "\n".join([
        "[LCM text-to-image %s, %dx%d, %d steps, guidance=%.1f, %.1fs%s]" % (device, width, height, steps, guidance, elapsed, metric),
        "prompt  : %s" % prompt,
        "seed    : %s" % ("random" if seed is None or int(seed) < 0 else seed),
        "image   : " + path,
        "note    : generated locally, no network, no API cost",
