{"command": "$docx = 'E:\Deepseek\deliverables\conv-20260928-3b54e160\local-ai-toolset-guide-v1.docx'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$zip = [System.IO.Compression.ZipFile]::OpenRead($docx)
$entry = $zip.Entries | Where-Object { $_.FullName -eq 'word/document.xml' }
$sr = New-Object System.IO.StreamReader($entry.Open())
$xml = $sr.ReadToEnd(); $sr.Close(); $zip.Dispose()
Write-Output ('document.xml 长度: ' + $xml.Length)
Write-Output ''
Write-Output '=== 第一个表格的 tblPr 与 tblGrid ==='
$m = [regex]::Match($xml, '<w:tbl>.*?</w:tblGrid>')
if ($m.Success) {
    $seg = $m.Value
    Write-Output ('  tblW  : ' + ([regex]::Match($seg, '<w:tblW[^/]*/>')).Value)
    Write-Output ('  tblInd: ' + ([regex]::Match($seg, '<w:tblInd[^/]*/>')).Value)
    Write-Output ('  layout: ' + ([regex]::Match($seg, '<w:tblLayout[^/]*/>')).Value)
    $cols = [regex]::Matches($seg, '<w:gridCol w:w="(\d+)"')
    $sum = 0
    foreach ($c in $cols) { $sum += [int]$c.Groups[1].Value }
    Write-Output ('  列宽(twips): ' + (($cols | ForEach-Object { $_.Groups[1].Value }) -join ', '))
    Write-Output ('  合计: ' + $sum + ' twips = ' + [Math]::Round($sum/1440,2) + ' 英寸（可用宽度 6.00 英寸）')
} else { Write-Output '  未找到表格' }
Write-Output ''
Write-Output '=== 样式里的默认表格缩进/宽度（如有） ==='
$m2 = [regex]::Match($xml, '<w:tblStyle[^/]*/>')
Write-Output ('  首个表格样式: ' + $m2.Value)
$zip2 = [System.IO.Compression.ZipFile]::OpenRead($docx)
$st = $zip2.Entries | Where-Object { $_.FullName -eq 'word/styles.xml' }
$sr2 = New-Object System.IO.StreamReader($st.Open()); $styles = $sr2.ReadToEnd(); $sr2.Close(); $zip2.Dispose()
foreach ($nm in 'TableGrid', 'TableNormal') {
    $mm = [regex]::Match($styles, '<w:style [^>]*w:styleId="' + $nm + '".*?</w:style>')
    if ($mm.Success) {
        $tblPr = [regex]::Match($mm.Value, '<w:tblPr>.*?</w:tblPr>').Value
        Write-Output ('  ' + $nm + ': ' + ($tblPr -replace '\s+', ' '))
    }
}", "description": "Inspect DOCX table XML dimensions", "timeoutMs": 300000}

