content.arguments:
{"command": "$py = @'
import os
import openvino as ov

D = r"D:\AI_file\models\lcm-dreamshaper-v7-fp16-ov"
core = ov.Core()
total = 0
print("=== 各子模型权重参数量（遍历 IR 常量节点求和） ===")
for name in ("text_encoder", "unet", "vae_decoder", "vae_encoder"):
    xml = os.path.join(D, name, "openvino_model.xml")
    if not os.path.isfile(xml):
        continue
    m = core.read_model(xml)
    count = 0
    for op in m.get_ordered_ops():
        if op.get_type_name() == "Constant":
            try:
                count += int(op.get_shape().get_shape_size() if hasattr(op.get_shape(), "get_shape_size") else __import__("math").prod(op.get_shape()))
            except Exception:
                pass
    size_mb = os.path.getsize(xml.replace(".xml", ".bin")) / 1048576
    print("  %-14s %12s 参数  (%6.1f MB fp16 -> %.1f MB 若 fp32)" % (name, format(count, ","), size_mb, size_mb * 2))
    total += count
print("  " + "-" * 58)
print("  %-14s %12s 参数  ≈ %.2f B" % ("合计", format(total, ","), total / 1e9))
print()
print("  对照：Stable Diffusion 1.5 官方总参数约 1.06 B（UNet 0.86 B + CLIP 文本 0.12 B + VAE 0.08 B）")
'@
$p = 'E:\Deepseek\scripts\conv-20260928-3b54e160\count-lcm-params.py'
[System.IO.File]::WriteAllText($p, $py, (New-Object System.Text.UTF8Encoding($false)))
$env:PYTHONIOENCODING = 'utf-8'
& 'D:\AI_file\envs\openvino\Scripts\python.exe' $p 2>&1 | Select-Object -First 20
Write-Output ''
Write-Output '=== 原始模型卡（SimianLuo/LCM_Dreamshaper_v7）关于基座与蒸馏的说法 ==='
$js = @'
const https = require('https');
function get(url) {
  return new Promise((resolve) => {
    const req = https.get(url, { headers: { 'User-Agent': 'probe/1.0' } }, (r) => {
      if (r.statusCode >= 300 && r.statusCode < 400 && r.headers.location) { r.resume(); resolve(get(new URL(r.headers.location, url).toString())); return; }
      let d = ''; r.on('data', (c) => { d += c; }); r.on('end', () => resolve({ code: r.statusCode, body: d }));
    });
    req.on('error', (e) => resolve({ code: 0, body: 'ERR ' + e.message }));
    req.setTimeout(25000, () => { req.destroy(); resolve({ code: 0, body: 'TIMEOUT' }); });
  });
}
(async () => {
  for (const repo of ['SimianLuo/LCM_Dreamshaper_v7', 'Lykon/dreamshaper-7']) {
    const r = await get('https://hf-mirror.com/' + repo + '/raw/main/README.md');
    console.log('--- ' + repo + '  HTTP ' + r.code + '  (' + r.body.length + ' chars)');
    if (r.code !== 200) continue;
    const lines = r.body.split('\n').filter((l) => l.trim());
    const keep = lines.filter((l) => /base|distill|laion|train|dataset|dreamshaper|license|step|latent consistency|aesthetic|prompt/i.test(l));
    for (const l of keep.slice(0, 22)) console.log('   | ' + l.trim().slice(0, 190));
    console.log();
  }
})();
'@
$pp = 'E:\Deepseek\scripts\conv-20260928-3b54e160\fetch-model-cards.js'
[System.IO.File]::WriteAllText($pp, $js, (New-Object System.Text.UTF8Encoding($false)))
& 'D:\program_runtime_environment\nodejs\node.exe' $pp 2>&1 | Select-Object -First 45", "description": "Count parameters and fetch model cards", "justification": "需读取工作区之外的模型文件并访问模型卡以核实训练数据来源。", "sandbox_permissions": "danger-full-access", "timeoutMs": 600000}

