const https = require('https');
function get(url) {
  return new Promise((resolve) => {
    const req = https.get(url, { headers: { 'User-Agent': 'probe/1.0' } }, (r) => {
      if (r.statusCode >= 300 && r.statusCode < 400 && r.headers.location) { r.resume(); resolve(get(new URL(r.headers.location, url).toString())); return; }
      let d = ''; r.on('data', (c) => { d += c; if (d.length > 4000000) r.destroy(); }); r.on('end', () => resolve({ code: r.statusCode, body: d }));
    });
    req.on('error', (e) => resolve({ code: 0, body: 'ERR ' + e.message }));
    req.setTimeout(30000, () => { req.destroy(); resolve({ code: 0, body: 'TIMEOUT' }); });
  });
}
(async () => {
  console.log('=== A) 搜索 OpenVINO 组织下的文生图模型 ===');
  for (const q of ['stable-diffusion-xl', 'stable-diffusion-3', 'flux', 'sd-turbo', 'lcm']) {
    const r = await get('https://hf-mirror.com/api/models?author=OpenVINO&search=' + encodeURIComponent(q) + '&limit=12');
    if (r.code !== 200) { console.log('  [' + q + '] HTTP ' + r.code); continue; }
    let arr = [];
    try { arr = JSON.parse(r.body); } catch (e) { console.log('  [' + q + '] parse fail'); continue; }
    console.log('  [' + q + '] ' + arr.length + ' 个:');
    for (const m of arr) console.log('      ' + m.modelId);
  }
  console.log();
  console.log('=== B) 逐个查体积与许可 ===');
  const cands = [
    'OpenVINO/stable-diffusion-xl-base-1.0-int8-ov',
    'OpenVINO/stable-diffusion-xl-base-1.0-fp16-ov',
    'OpenVINO/stable-diffusion-3-medium-int4-ov',
    'OpenVINO/stable-diffusion-3.5-medium-int4-ov',
    'OpenVINO/sd-turbo-fp16-ov',
    'OpenVINO/sdxl-turbo-fp16-ov',
    'OpenVINO/FLUX.1-schnell-int4-ov'
  ];
  for (const r0 of cands) {
    const r = await get('https://hf-mirror.com/api/models/' + r0 + '?blobs=true');
    if (r.code !== 200) { console.log('  HTTP ' + r.code + '  ' + r0); continue; }
    let j = null;
    try { j = JSON.parse(r.body); } catch (e) { console.log('  parse fail ' + r0); continue; }
    const files = (j.siblings || []).filter((s) => s.size);
    const total = files.reduce((a, s) => a + s.size, 0);
    const noCkpt = files.filter((s) => !/\.(safetensors|ckpt|onnx|msgpack|h5)$/i.test(s.rfilename)).reduce((a, s) => a + s.size, 0);
    const lic = (j.cardData && j.cardData.license) || (j.tags || []).find((t) => t.startsWith('license:')) || '?';
    console.log('  %s  全部=%s GB  仅IR=%s GB  许可=%s', r0.replace('OpenVINO/', '').padEnd(44), (total / 1073741824).toFixed(2), (noCkpt / 1073741824).toFixed(2), lic);
  }
})();
