content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$target = 'D:\AI_file\models\lcm-dreamshaper-v7-fp16-ov'
Write-Output '=== 1) 删除前的安全检查 ==='
$full = [System.IO.Path]::GetFullPath($target)
Write-Output ('  传入路径      : ' + $target)
Write-Output ('  解析后绝对路径: ' + $full)
Write-Output ('  是否为预期目标: ' + ($full -eq 'D:\AI_file\models\lcm-dreamshaper-v7-fp16-ov'))
Write-Output ('  是否存在      : ' + (Test-Path -LiteralPath $full))
$files = @(Get-ChildItem -LiteralPath $full -Recurse -File -ErrorAction SilentlyContinue)
$sum = ($files | Measure-Object -Property Length -Sum).Sum
Write-Output ('  内容          : ' + $files.Count + ' 文件, ' + [Math]::Round($sum/1MB,0) + ' MB')
Write-Output ('  上级目录      : ' + (Split-Path -Parent $full) + '（应位于 D:\AI_file\models）')
Write-Output ''
Write-Output '  是否有进程占用该目录下的文件:'
$procs = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -match '(?i)python' })
if ($procs.Count -eq 0) { Write-Output '    （无 python 进程运行）' } else {
    foreach ($pr in $procs) { Write-Output ('    PID ' + $pr.Id + ' ' + $pr.ProcessName + ' 启动于 ' + $pr.StartTime) }
}

Write-Output ''
Write-Output '=== 2) 执行删除 ==='
if ($full -eq 'D:\AI_file\models\lcm-dreamshaper-v7-fp16-ov' -and (Test-Path -LiteralPath $full)) {
    try {
        Remove-Item -LiteralPath $full -Recurse -Force -ErrorAction Stop
        Write-Output '  删除命令执行成功'
    } catch {
        Write-Output ('  删除失败: ' + $_.Exception.Message)
    }
} else { Write-Output '  路径校验未通过，已中止' }

Write-Output ''
Write-Output '=== 3) 删除后核对 ==='
Write-Output ('  目标目录仍存在: ' + (Test-Path -LiteralPath $full))
Write-Output ('  释放空间: ' + [Math]::Round($sum/1MB,0) + ' MB')
Write-Output ''
Write-Output '=== 4) models 目录现状（为文档更新采集准确体积） ==='
$root = 'D:\AI_file\models'
Get-ChildItem -LiteralPath $root -Directory | ForEach-Object {
    $s = (Get-ChildItem -LiteralPath $_.FullName -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
    Write-Output ('  ' + $_.Name.PadRight(34) + [Math]::Round($s/1MB,0).ToString().PadLeft(8) + ' MB')
}
$all = (Get-ChildItem -LiteralPath $root -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
Write-Output ('  ' + 'models 合计'.PadRight(34) + [Math]::Round($all/1024,2).ToString().PadLeft(8) + ' GB')
Write-Output ''
Write-Output '=== 5) D:\AI_file 总体积 ==='
$ai = 'D:\AI_file'
foreach ($d in @('runtime','tools','envs','models','datasets','outputs','logs','workspace','_downloads','_caches')) {
    $p = Join-Path $ai $d
    if (Test-Path -LiteralPath $p) {
        $s = (Get-ChildItem -LiteralPath $p -Recurse -File -Force -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        Write-Output ('  ' + $d.PadRight(12) + [Math]::Round($s/1MB,1).ToString().PadLeft(10) + ' MB')
    }
}
$total = (Get-ChildItem -LiteralPath $ai -Recurse -File -Force -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
Write-Output ('  ' + 'TOTAL'.PadRight(12) + [Math]::Round($total/1GB,2).ToString().PadLeft(10) + ' GB')
Write-Output ('  D 盘可用: ' + [Math]::Round((Get-PSDrive -Name D).Free/1GB,1) + ' GB')", "description": "Delete LCM model with path verification", "justification": "按用户确认删除工作区之外的 D:\AI_file\models 下的 LCM 模型目录。", "sandbox_permissions": "danger-full-access", "timeoutMs": 600000}

