Write-Output '=== 1) 服务端日志（最近 40 行） ==='
if (Test-Path -LiteralPath $log) {
    $lines = @(Get-Content -LiteralPath $log -Encoding UTF8)
    Write-Output ('  总行数: ' + $lines.Count + '   最后写入: ' + (Get-Item -LiteralPath $log).LastWriteTime)
    $lines | Select-Object -Last 40 | ForEach-Object { Write-Output ('  ' + $_) }
} else { Write-Output '  (日志不存在)' }
Write-Output ''
