    $procs | ForEach-Object {
        $mem = [Math]::Round($_.WorkingSet64/1MB, 0)
        Write-Output ('  PID ' + $_.Id.ToString().PadLeft(6) + '  内存 ' + $mem.ToString().PadLeft(6) + ' MB  启动 ' + $_.StartTime)
    }
}
Write-Output ''
Write-Output '=== 3) 服务端文件状态 ==='
$p = 'D:\AI_file\mcp\vision-server.py'
$f = Get-Item -LiteralPath $p
Write-Output ('  ' + $f.FullName + '  ' + $f.Length + ' B  修改于 ' + $f.LastWriteTime)
& 'D:\AI_file\envs\openvino\Scripts\python.exe' -c "import ast; ast.parse(open(r'$p', encoding='utf-8').read()); print('  语法: OK')" 2>&1 | Select-Object -First 3
$t = [System.IO.File]::ReadAllText($p, [System.Text.Encoding]::UTF8)
Write-Output ('  版本: ' + ([regex]::Match($t, 'version="[\d.]+"').Value))
Write-Output ('  默认模型: ' + ([regex]::Match($t, 'T2I_DIR = os\.environ\.get\("DSH_T2I_MODEL", r"([^"]+)"').Groups[1].Value))
