{"command": "$ErrorActionPreference = 'Continue'
Write-Output '=== 1) 终止旧服务端进程（v1.9 → 让宿主拉起 v1.10） ==='
$v = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -match '(?i)python' })
foreach ($x in $v) {
    $cmd = ''
