{"command": "$py = @'
import inspect
import openvino_genai as ovg

print("=== 1) 本机 OpenVINO GenAI 对 Z-Image 的支持程度 ===")
print("  版本:", getattr(ovg, "__version__", "?"))
z = [n for n in dir(ovg) if "Z" == n[0] and "mage" in n.lower()]
print("  Z-Image 相关类:", z or "无")
for name in z:
    obj = getattr(ovg, name)
    print("    %s: %s" % (name, (obj.__doc__ or "").strip()[:200].replace("\n", " ")))
tp = ovg.Text2ImagePipeline
print("  可用工厂方法:", [m for m in dir(tp) if not m.startswith("_") and m in
      ("flux", "stable_diffusion", "stable_diffusion_xl", "stable_diffusion_3", "latent_consistency_model",
       "z_image", "qwen_image", "pixart", "image2image")])
try:
    tp.z_image(None, None, None, None)
except TypeError as exc:
    print("  z_image 工厂签名:", str(exc).split("\n")[1].strip()[:200] if "\n" in str(exc) else str(exc)[:200])
except AttributeError as exc:
    print("  z_image 工厂: 不存在（%s）" % exc)
except Exception as exc:
    print("  z_image 工厂: %s: %s" % (type(exc).__name__, str(exc)[:120]))

print()
print("=== 2) 可用的推理设备与内存上限（判断能否装下 Z-Image） ===")
import openvino as ov
core = ov.Core()
for dev in core.available_devices:
    try:
        mem = core.get_property(dev, "GPU_DEVICE_TOTAL_MEM_SIZE")
    except Exception:
        mem = None
    print("  %-4s %s%s" % (dev, core.get_property(dev, "FULL_DEVICE_NAME"),
                           ("  可用显存 %.1f GB" % (mem / 1073741824)) if mem else ""))
'@
$p = 'E:\Deepseek\scripts\conv-20260928-3b54e160\probe-zimage-support.py'
[System.IO.File]::WriteAllText($p, $py, (New-Object System.Text.UTF8Encoding($false)))
$js = @'
const https = require('https');
function get(u) { return new Promise((res) => { const r = https.get(u, { headers: { 'User-Agent': 'p/1' } }, (x) => { if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(get(new URL(x.headers.location, u).toString())); return; } let d = ''; x.on('data', (c) => d += c); x.on('end', () => res({ code: x.statusCode, body: d })); }); r.on('error', () => res({ code: 0, body: '' })); r.setTimeout(30000, () => { r.destroy(); res({ code: 0, body: '' }); }); }); }
(async () => {
  console.log('=== 3) hf-mirror 上的 Z-Image 仓库 ===');
  for (const q of ['Z-Image', 'z-image']) {
    const r = await get('https://hf-mirror.com/api/models?search=' + encodeURIComponent(q) + '&limit=20&sort=downloads&direction=-1');
    if (r.code !== 200) { console.log('  search ' + q + ' HTTP ' + r.code); continue; }
    let arr = []; try { arr = JSON.parse(r.body); } catch (e) { continue; }
    for (const m of arr) console.log('  %s  downloads=%s likes=%s', m.modelId.padEnd(52), m.downloads || 0, m.likes || 0);
  }
  console.log();
  console.log('=== 4) 重点仓库体积与许可 ===');
  for (const repo of ['Tongyi-MAI/Z-Image-Turbo', 'Tongyi-MAI/Z-Image', 'OpenVINO/Z-Image-Turbo-int4-ov', 'OpenVINO/Z-Image-Turbo-fp16-ov']) {
    const r = await get('https://hf-mirror.com/api/models/' + repo + '?blobs=true');
    if (r.code !== 200) { console.log('  HTTP %s  %s', r.code, repo); continue; }
    const j = JSON.parse(r.body);
    const files = (j.siblings || []).filter((s) => s.size);
    const total = files.reduce((a, s) => a + s.size, 0);
    const lic = (j.cardData && j.cardData.license) || (j.tags || []).find((t) => t.startsWith('license:')) || '?';
    console.log('  %s  %s GB  files=%d  license=%s', repo.padEnd(38), (total / 1073741824).toFixed(2), files.length, lic);
    const big = files.filter((f) => f.size > 300 * 1048576).map((f) => f.rfilename.split('/')[0] + ':' + (f.size / 1048576).toFixed(0) + 'MB');
    if (big.length) console.log('       ' + big.join(', '));
  }
})();
'@
$pp = 'E:\Deepseek\scripts\conv-20260928-3b54e160\probe-zimage-mirror.js'
[System.IO.File]::WriteAllText($pp, $js, (New-Object System.Text.UTF8Encoding($false)))
$env:PYTHONIOENCODING = 'utf-8'
& 'D:\AI_file\envs\openvino\Scripts\python.exe' $p 2>&1 | Select-Object -First 14
Write-Output ''
& 'D:\program_runtime_environment\nodejs\node.exe' $pp 2>&1 | Select-Object -First 30", "description": "Probe Z-Image support and mirror availability", "justification": "需读取工作区之外的库能力与镜像信息以核实 Z-Image 可用性。", "sandbox_permissions": "danger-full-access", "timeoutMs": 600000}

