(async () => {
  console.log('=== A) Z-Image 的文本编码器是什么 ===');
  const r = await get('https://hf-mirror.com/Tongyi-MAI/Z-Image-Turbo/raw/main/text_encoder/config.json');
  if (r.code === 200) {
    try {
      const c = JSON.parse(r.body);
      for (const k of ['architectures', '_name_or_path', 'hidden_size', 'num_hidden_layers', 'num_attention_heads',
