        if (k in c) console.log('     %-24s %s', k, JSON.stringify(c[k]));
      }
    } catch (e) { console.log('     parse fail: ' + r.body.slice(0, 120)); }
  } else console.log('     HTTP ' + r.code);

  console.log();
  console.log('=== B) 是否有官方 OpenVINO 转换版 ===');
  for (const q of ['Z-Image', 'z-image']) {
    const r2 = await get('https://hf-mirror.com/api/models?author=OpenVINO&search=' + encodeURIComponent(q) + '&limit=20');
    if (r2.code !== 200) { console.log('  author=OpenVINO search HTTP ' + r2.code); continue; }
