    console.log('  author=OpenVINO [' + q + '] -> ' + (arr.length ? arr.map((m) => m.modelId).join(', ') : '无'));
  }

  console.log();
  console.log('=== C) 第三方 OpenVINO 版的实际文件构成（判断能否直接跑） ===');
  const r3 = await get('https://hf-mirror.com/api/models/RobertHerman/Z-Image-Turbo-ov?blobs=true');
  if (r3.code === 200) {
    const j = JSON.parse(r3.body);
    for (const f of (j.siblings || []).filter((s) => s.size).sort((a, b) => b.size - a.size).slice(0, 14)) {
      console.log('     %8.1f MB  %s', f.size / 1048576, f.rfilename);
    }
  } else console.log('     HTTP ' + r3.code);
  const r4 = await get('https://hf-mirror.com/RobertHerman/Z-Image-Turbo-ov/raw/main/README.md');
  if (r4.code === 200) {
    console.log('     --- README 要点 ---');
    for (const l of r4.body.split('\n').filter((l) => /optimum|pipeline|openvino|device|GPU|int4|steps|usage|from_pretrained/i.test(l)).slice(0, 10)) {
      console.log('     | ' + l.trim().slice(0, 160));
    }
  }
})();
