    $exts[$e]++
}
$exts.GetEnumerator() | Sort-Object Value -Descending | Select-Object -First 18 | ForEach-Object {
    Write-Output ('  ' + $_.Key.PadRight(10) + $_.Value.ToString().PadLeft(7) + ' 个')
}
Write-Output ''
Write-Output '=== 3) 是否有保留原名的文件（含 deepseek/policy/AGENTS 等字样） ==='
