content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
Write-Output '=== 1) C:\Users\徐丰哲\.dsh 里的规则文件与备份 ==='
Get-ChildItem -LiteralPath "$env:USERPROFILE\.dsh" -Force -ErrorAction SilentlyContinue | ForEach-Object {
    Write-Output ('  ' + $(if ($_.PSIsContainer) { '[目录]' } else { '[文件]' }) + ' ' + $_.Name.PadRight(34) + $(if (-not $_.PSIsContainer) { [Math]::Round($_.Length/1KB,1).ToString() + ' KB' }) + '  ' + $_.LastWriteTime)
}
Write-Output ''
Write-Output '=== 2) 全局 AGENTS.md 及其历史备份（最可信来源） ==='
Get-ChildItem -LiteralPath "$env:USERPROFILE\.dsh" -Filter 'AGENTS.md*' -Force -ErrorAction SilentlyContinue | ForEach-Object {
    Write-Output ('  ' + $_.Name.PadRight(46) + [Math]::Round($_.Length/1KB,1).ToString().PadLeft(7) + ' KB  ' + $_.LastWriteTime)
}
Write-Output ''
Write-Output '=== 3) MCP 注册是否还在（profile 配置） ==='
foreach ($prof in 'desktop', 'web') {
    $f = "$env:USERPROFILE\.dsh\profiles\$prof\cordis.patch.yml"
    if (Test-Path -LiteralPath $f) {
        $t = [System.IO.File]::ReadAllText($f, [System.Text.Encoding]::UTF8)
        Write-Output ('  ' + $prof.PadRight(10) + ' 大小 ' + $t.Length + ' 字符  含 mcp-vision: ' + ($t -match 'mcp-vision') + '  insert 包裹: ' + ($t -match '- insert:'))
    } else { Write-Output ('  ' + $prof + ' 配置文件缺失') }
}
Write-Output ''
Write-Output '=== 4) 会话记录（可用于提取我写过的文件内容） ==='
$sess = "$env:USERPROFILE\.dsh\sessions"
if (Test-Path -LiteralPath $sess) {
    Get-ChildItem -LiteralPath $sess -Force -Directory | ForEach-Object {
        $n = @(Get-ChildItem -LiteralPath $_.FullName -Force -Directory -ErrorAction SilentlyContinue).Count
        $sz = (Get-ChildItem -LiteralPath $_.FullName -Recurse -File -Force -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        Write-Output ('  ' + $_.Name.PadRight(24) + '会话 ' + $n + ' 个, ' + [Math]::Round($sz/1MB,1) + ' MB')
    }
} else { Write-Output '  sessions 目录不存在' }
Write-Output ''
Write-Output '=== 5) D:\AI_file 关键文件是否完好 ==='
foreach ($p in 'D:\AI_file\mcp\vision-server.py', 'D:\AI_file\registry.json', 'D:\AI_file\logs\vision-mcp.log') {
    if (Test-Path -LiteralPath $p) {
        $i = Get-Item -LiteralPath $p
        Write-Output ('  [有] ' + $p.PadRight(40) + [Math]::Round($i.Length/1KB,1).ToString().PadLeft(8) + ' KB  ' + $i.LastWriteTime)
    } else { Write-Output ('  [无] ' + $p) }
}
$v = [regex]::Match([System.IO.File]::ReadAllText('D:\AI_file\mcp\vision-server.py', [System.Text.Encoding]::UTF8), 'version="([\d.]+)"').Groups[1].Value
Write-Output ('  服务端版本: ' + $v + '（应为 1.11.0）')", "description": "Check surviving rule files on C drive", "timeoutMs": 600000}

