$py = @'
import re

P = r"E:\deepseek\tools\New-ConversationWorkspace.ps1"
t = open(P, encoding="utf-8").read()

old = """# 2) 解析本对话的 conv-id
$sid = $env:DSH_SESSION_ID
if ($sid -and ($sid -match '([0-9a-fA-F]{8})-')) {
