$regPath = Join-Path $Root 'policy\\conversation-registry.json'
if (Test-Path -LiteralPath $regPath) {
    $reg = Read-Utf8Json -Path $regPath
"""
new2 = """# 4) 登记（已存在则复用，不另建）
if ($registry) {
    $reg = $registry
"""
if old2 in t:
    t = t.replace(old2, new2, 1)
    print("[OK] 登记段改用已读出的 registry")
else:
    print("[FAIL] 登记段锚点未找到")

open(P, "w", encoding="utf-8", newline="\r\n").write(t)
'@
$p = 'E:\deepseek\workspace\_recovery\fix-convid-reuse.py'
[System.IO.File]::WriteAllText($p, $py, (New-Object System.Text.UTF8Encoding($false)))
$env:PYTHONIOENCODING = 'utf-8'
& 'D:\AI_file\envs\openvino\Scripts\python.exe' $p 2>&1 | ForEach-Object { Write-Output ('  ' + $_) }

Write-Output ''
Write-Output '=== 2) 把目录恢复为原 ID，并清理错误登记条目 ==='
foreach ($c in 'deliverables', 'logs', 'scripts', 'workspace', 'data', 'archive') {
    $wrong = Join-Path $root "$c\conv-20261011-3b54e160"
    $right = Join-Path $root "$c\conv-20260928-3b54e160"
    if (Test-Path -LiteralPath $wrong) {
        if (Test-Path -LiteralPath $right) { Remove-Item -LiteralPath $wrong -Recurse -Force }
        else { Move-Item -LiteralPath $wrong -Destination $right -Force }
    } elseif (-not (Test-Path -LiteralPath $right)) {
        New-Item -ItemType Directory -Force -Path $right | Out-Null
    }
}
Write-Output '  目录已统一为 conv-20260928-3b54e160'

$py2 = @'
import json
P = r"E:\deepseek\policy\conversation-registry.json"
reg = json.load(open(P, encoding="utf-8"))
before = len(reg["conversations"])
reg["conversations"] = [c for c in reg["conversations"] if c["folder"] != "conv-20261011-3b54e160"]
json.dump(reg, open(P, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
print("  登记表 %d -> %d 条（移除误建的 ID）" % (before, len(reg["conversations"])))
act = [c for c in reg["conversations"] if c.get("status") == "active"]
print("  active 条目:", ", ".join(c["folder"] for c in act))
'@
$p2 = 'E:\deepseek\workspace\_recovery\clean-registry.py'
[System.IO.File]::WriteAllText($p2, $py2, (New-Object System.Text.UTF8Encoding($false)))
& 'D:\AI_file\envs\openvino\Scripts\python.exe' $p2 2>&1 | ForEach-Object { Write-Output $_ }

Write-Output ''
Write-Output '=== 3) 复跑自检（期望 FAIL=0 WARN=0） ==='
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File 'E:\deepseek\tools\Test-StoragePolicy.ps1' 2>&1 | Select-Object -Last 6 | ForEach-Object { Write-Output ('  ' + $_) }
Write-Output ''
