$py = @'
import os, re, sys
sys.stdout.reconfigure(encoding='utf-8', errors='replace')
root = 'E:\\deepseek'

def read(p):
    try:
        return open(p, encoding='utf-8', errors='replace').read()
    except Exception:
        return None

DOCS = ['AGENTS.md', 'README.md', 'policy\\output-storage-policy.md', 'policy\\ai-tool-policy.md',
        'policy\\deploy\\global-agents.md', 'policy\\storage-policy.json', 'policy\\ai-tools.json']

print('=== 2) active references inside rule documents (relative + absolute) ===')
pat = re.compile(r'(?:[A-Ea-e]:\\[^\s`"\'\)\|,;]+|(?:scripts|tools|policy|deliverables|logs|workspace|data|archive|reference_file)\\[^\s`"\'\)\|,;]+)')
problems, ok = [], 0
for rel in DOCS:
    t = read(os.path.join(root, rel))
    if t is None:
        print('  MISSING DOC: ' + rel)
        continue
    for m in set(pat.findall(t)):
        raw = m.strip().rstrip('.,;:')
        if raw.endswith('\\') or len(raw) < 5:
            continue
        # 排除显然是通配/占位/说明性的
        if any(x in raw for x in ('<conv-id>', '<category>', '<name>', '<family>', '<version>', '<purpose>', '...', '<tool>', '<ext>', '<topic>')):
            continue
        q = raw
        q = q.replace('E:\\Deepseek', root).replace('E:\\deepseek', root)
        if not q.startswith(root) and not q.startswith('D:') and not q.startswith('C:'):
            q = os.path.join(root, raw)
        if os.path.exists(q):
            ok += 1
        else:
            problems.append((rel, raw))
print('  references resolving OK: %d' % ok)
print('  references NOT found  : %d' % len(problems))
for rel, raw in sorted(set(problems)):
    print('    [MISSING] %-52s  <- %s' % (raw, rel))
