import os, sys
sys.stdout.reconfigure(encoding='utf-8', errors='replace')

print('=== 15) search C:\\huifu for download-file.js (missing reference in AGENTS.md) ===')
hits = []
for dirpath, _dirs, files in os.walk(r'C:\huifu'):
    for name in files:
        p = os.path.join(dirpath, name)
        try:
            if os.path.getsize(p) > 200 * 1024:
                continue
            t = open(p, 'rb').read(60 * 1024).decode('utf-8', errors='ignore')
        except Exception:
            continue
        if 'download-file' in t or ('--resume' in t and 'createWriteStream' in t):
            first = next((l.strip() for l in t.splitlines() if l.strip()), '')
            hits.append((p, os.path.getsize(p), first[:70]))
print('  candidates: %d' % len(hits))
for p, s, f in sorted(hits, key=lambda x: -x[1])[:8]:
    print('    %-56s %7.1f KB  %s' % (p, s / 1024, f))

print()
print('=== 16) workspace/_recovery contents (29 files) ===')
rec = r'E:\deepseek\workspace\_recovery'
total = 0
for dirpath, _dirs, files in os.walk(rec):
    for name in files:
        p = os.path.join(dirpath, name)
        total += os.path.getsize(p)
print('  %d files, %.1f KB total' % (
    sum(len(f) for _d, _s, f in os.walk(rec)), total / 1024))
for dirpath, _dirs, files in os.walk(rec):
    for name in sorted(files)[:40]:
        p = os.path.join(dirpath, name)
        print('    %-52s %7.1f KB' % (os.path.relpath(p, rec), os.path.getsize(p) / 1024))

print()
print('=== 17) deliverables / logs / scripts inventory ===')
for kind in ('deliverables', 'logs', 'scripts'):
    d = os.path.join(r'E:\deepseek', kind)
    for dirpath, _dirs, files in os.walk(d):
        for name in sorted(files):
            p = os.path.join(dirpath, name)
            print('  %-11s %-56s %7.1f KB' % (kind, os.path.relpath(p, d), os.path.getsize(p) / 1024))
