const fs = require('fs');
const root = 'E:\\deepseek';

function patch(rel, transform, label) {
  const p = root + '\\' + rel;
  if (!fs.existsSync(p)) { console.log('  [SKIP] ' + rel + ' 不存在'); return; }
  const before = fs.readFileSync(p, 'utf8');
  const after = transform(before);
  if (after === before) { console.log('  [SKIP] ' + label + '（无需改动）'); return; }
  fs.writeFileSync(p, after, 'utf8');
  console.log('  [OK] ' + label + '  (' + before.length + ' -> ' + after.length + ' 字符)');
}

