const root = 'E:\\deepseek';

function patch(rel, transform, label) {
  const p = root + '\\' + rel;
  if (!fs.existsSync(p)) { console.log('  [SKIP] ' + rel + ' 不存在'); return; }
  const before = fs.readFileSync(p, 'utf8');
  const after = transform(before);
  if (after === before) { console.log('  [SKIP] ' + label + '（无需改动）'); return; }
  fs.writeFileSync(p, after, 'utf8');
  console.log('  [OK] ' + label + '  (' + before.length + ' -> ' + after.length + ' 字符)');
}

console.log('=== P3) 给 3 个 tools 脚本补「重建」标注 ===');
const MARK = '# 说明：本脚本为 2026-10-11 重建版（原件随 E: 盘清空丢失）；结构与功能按原版语义重建，\r\n#       并经语法校验与实际运行验证。\r\n';
for (const f of ['New-ConversationWorkspace.ps1', 'Install-GlobalPolicy.ps1', 'Test-StoragePolicy.ps1']) {
  patch('tools\\' + f, (t) => t.includes('重建版') ? t : t.replace(/\r\n/, '\r\n' + MARK), 'tools\\' + f);
}

console.log();
console.log('=== P4) README 里的相对日志路径补全 ===');
patch('README.md', (t) => t.replace('`registry.json`、`logs\\vision-mcp.log`', '`registry.json`、`logs\\vision-mcp.log`（即 `D:\\AI_file\\logs\\vision-mcp.log`）'),
      'README.md 日志路径');
'@
$p = 'E:\deepseek\workspace\_recovery\apply-minor-fixes.js'
