{"command": "$js = @'
const fs = require('fs');
const path = require('path');
const os = require('os');
const root = 'E:\\deepseek';

// 1) take the new fact row straight out of AGENTS.md (no CJK passes through the shell)
const agPath = path.join(root, 'AGENTS.md');
const agLines = fs.readFileSync(agPath, 'utf8').split('\n');
const row = agLines.find((l) => l.startsWith('| DSH '));
