content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
Write-Output '=== 部署全局副本（工作区之外，需提权）==='
$src = 'E:\deepseek\policy\deploy\global-agents.md'
$dst = Join-Path $env:USERPROFILE '.dsh\AGENTS.md'
$new = [System.IO.File]::ReadAllText($src, [System.Text.Encoding]::UTF8)
Write-Output ('  源: ' + $src + '  (' + $new.Length + ' 字符)')
if (Test-Path -LiteralPath $dst) {
    $old = [System.IO.File]::ReadAllText($dst, [System.Text.Encoding]::UTF8)
    Write-Output ('  目标现有: ' + $old.Length + ' 字符')
    if ($old -eq $new) {
        Write-Output '  已是最新，无需部署'
    } else {
        $bak = $dst + '.bak-' + (Get-Date).ToString('yyyyMMdd-HHmmss')
        Copy-Item -LiteralPath $dst -Destination $bak -Force
        Write-Output ('  备份: ' + (Split-Path -Leaf $bak))
        Copy-Item -LiteralPath $src -Destination $dst -Force
        $chk = [System.IO.File]::ReadAllText($dst, [System.Text.Encoding]::UTF8)
        Write-Output ('  部署完成，校验一致: ' + ($chk -eq $new) + '  (' + $chk.Length + ' 字符)')
    }
} else {
    Copy-Item -LiteralPath $src -Destination $dst -Force
    Write-Output '  部署完成（首次）'
}", "description": "Deploy global rules copy with escalation", "justification": "规则 6 要求改动后重新部署全局副本，而目标文件在工作区之外的 %USERPROFILE%\.dsh，只读沙箱拒绝写入。", "sandbox_permissions": "danger-full-access", "timeoutMs": 300000}

