content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$root = 'E:\deepseek'
$conv = 'conv-20260928-3b54e160'
$src = Join-Path $root 'workspace\_recovery'
$dst = Join-Path $root "archive\$conv\_recovery"

Write-Output '=== 1) 归档 workspace\_recovery -> archive\<conv-id>\_recovery ==='
if (-not (Test-Path -LiteralPath $src)) {
    Write-Output '  源目录不存在（可能已移动）'
} else {
    $n = @(Get-ChildItem -LiteralPath $src -Recurse -File -Force -ErrorAction SilentlyContinue).Count
    $s = (Get-ChildItem -LiteralPath $src -Recurse -File -Force -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
    Write-Output ('  源: ' + $src + '  (' + $n + ' 文件, ' + [Math]::Round($s/1KB,1) + ' KB)')
    Write-Output ('  目标: ' + $dst)
    if (Test-Path -LiteralPath $dst) {
        Write-Output '  目标已存在，先合并内容后删除源'
        Copy-Item -LiteralPath (Join-Path $src '*') -Destination $dst -Recurse -Force
        Remove-Item -LiteralPath $src -Recurse -Force
    } else {
        Move-Item -LiteralPath $src -Destination $dst -Force
    }
    Write-Output ('  结果: 源存在=' + (Test-Path -LiteralPath $src) + '  目标存在=' + (Test-Path -LiteralPath $dst))
}

Write-Output ''
Write-Output '=== 2) 归档后清点 ==='
foreach ($d in 'workspace', 'archive') {
    $p = Join-Path $root $d
    Write-Output ('  ' + $d + '\ :')
    Get-ChildItem -LiteralPath $p -Force -Recurse -ErrorAction SilentlyContinue | Where-Object { $_.PSIsContainer -or $_.PSIsContainer -eq $false } | Select-Object -First 8 | ForEach-Object {
        $rel = $_.FullName.Substring($p.Length + 1)
        Write-Output ('      ' + $(if ($_.PSIsContainer) { '[目录] ' } else { '[文件] ' }) + $rel)
    }
    $total = @(Get-ChildItem -LiteralPath $p -Recurse -File -Force -ErrorAction SilentlyContinue)
    Write-Output ('      合计 ' + $total.Count + ' 文件, ' + [Math]::Round((($total | Measure-Object -Property Length -Sum).Sum)/1KB,1) + ' KB')
}", "description": "Archive recovery folder", "timeoutMs": 300000}

