content.arguments:
{"command": "$ErrorActionPreference = 'Stop'
$root = 'E:\deepseek'
$enc = New-Object System.Text.UTF8Encoding($false)

Write-Output '=== 1) README 插入备份命令 ==='
$p = Join-Path $root 'README.md'
$lines = [System.IO.File]::ReadAllLines($p, [System.Text.Encoding]::UTF8)
$idx = -1
for ($i = 0; $i -lt $lines.Count; $i++) {
    if ($lines[$i] -match 'Install-GlobalPolicy\.ps1' -and $lines[$i] -match '^-{0,2}\s*powershell') { $idx = $i }
}
if ($idx -lt 0) { Write-Output '  [FAIL] 未找到部署命令所在行' }
elseif (($lines -join "`n") -match 'Backup-Rules\.ps1') { Write-Output '  [SKIP] 已含备份命令' }
else {
    $ins = @('', '# 改完规则后刷新灾备（规则 8；与 E 盘物理分离，保留最近 5 份）',
             'powershell.exe -NoProfile -ExecutionPolicy Bypass -File E:\Deepseek\tools\Backup-Rules.ps1')
    $before = @()
    if ($idx -ge 0) { $before = $lines[0..$idx] }
    $after = @()
    if ($idx + 1 -le $lines.Count - 1) { $after = $lines[($idx + 1)..($lines.Count - 1)] }
    [System.IO.File]::WriteAllLines($p, ($before + $ins + $after), $enc)
    Write-Output ('  [OK] 已在第 ' + ($idx + 2) + ' 行后插入备份命令')
}

Write-Output ''
Write-Output '=== 2) 运行首次备份（tools\Backup-Rules.ps1） ==='
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'tools\Backup-Rules.ps1') 2>&1 | ForEach-Object { Write-Output ('  ' + $_) }
Write-Output ('  退出码: ' + $LASTEXITCODE)

Write-Output ''
Write-Output '=== 3) 备份目录清单 ==='
$base = Join-Path $env:USERPROFILE 'Documents\Deepseek-rules-backup'
if (Test-Path -LiteralPath $base) {
    Get-ChildItem -LiteralPath $base -Directory | Sort-Object Name -Descending | ForEach-Object {
        $x = @(Get-ChildItem -LiteralPath $_.FullName -Recurse -File)
        Write-Output ('  ' + $_.Name + '  ' + $x.Count + ' 文件  ' + [Math]::Round((($x | Measure-Object -Property Length -Sum).Sum)/1KB,1) + ' KB')
    }
}

Write-Output ''
Write-Output '=== 4) 自检 ==='
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'tools\Test-StoragePolicy.ps1') 2>&1 | Select-Object -Last 2 | ForEach-Object { Write-Output ('  ' + $_) }", "description": "Insert backup command and run first backup", "justification": "用户要求把备份写成规则；需补全 README 命令并运行新备份脚本写入 C 盘 Documents。", "sandbox_permissions": "danger-full-access", "timeoutMs": 900000}

