Write-Output ('  4) output-storage-policy.md 含 §12: ' + ([System.IO.File]::ReadAllText((Join-Path $root 'policy\output-storage-policy.md'), [System.Text.Encoding]::UTF8) -match '## 12\.'))
Write-Output ('  5) tools\Backup-Rules.ps1 存在: ' + (Test-Path -LiteralPath (Join-Path $root 'tools\Backup-Rules.ps1')))
