        $hit = Select-String -LiteralPath $f -Pattern 'maxTokens|max_tokens|token' -ErrorAction SilentlyContinue
        Write-Output ('  ' + (Split-Path -Leaf (Split-Path -Parent $f)) + '\' + (Split-Path -Leaf $f) + '  -> ' + $(if ($hit) { ($hit | ForEach-Object { $_.Line.Trim() }) -join ' | ' } else { '（未配置 token 上限）' }))
    }
}
Write-Output ''
