if (Test-Path -LiteralPath $s) {
    Get-Content -LiteralPath $s -Encoding UTF8 | ForEach-Object { Write-Output ('  ' + $_) }
} else { Write-Output '  （无 settings.yaml）' }

Write-Output ''
Write-Output '=== 3) 完成上次被中断的首次备份 ==='
