content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$root = 'E:\deepseek'

Write-Output '=== 1) 确认新备份完整性 + 清理失败的两份 ==='
$base = Join-Path $env:USERPROFILE 'Documents\Deepseek-rules-backup'
foreach ($d in @(Get-ChildItem -LiteralPath $base -Directory | Sort-Object Name -Descending)) {
    $x = @(Get-ChildItem -LiteralPath $d.FullName -Recurse -File)
    $hasDoc = Test-Path -LiteralPath (Join-Path $d.FullName 'BACKUP-README.md')
    Write-Output ('  ' + $d.Name + '  ' + $x.Count + ' 文件  ' + [Math]::Round((($x | Measure-Object -Property Length -Sum).Sum)/1KB,1) + ' KB  说明: ' + $hasDoc)
    if (-not $hasDoc) {
        Remove-Item -LiteralPath $d.FullName -Recurse -Force
        Write-Output '     → 已删除（失败备份，缺说明文件）'
    }
}
Write-Output '  保留:'
Get-ChildItem -LiteralPath $base -Directory | ForEach-Object { Write-Output ('    ' + $_.Name) }

Write-Output ''
Write-Output '=== 2) 把 BOM 教训写进三处规则 ==='
$utf8bom = New-Object System.Text.UTF8Encoding($true)
$row = '| `tools\*.ps1` 存成 **UTF-8 无 BOM** 会导致中文乱码 | PowerShell 5.1 把无 BOM 的 UTF-8 脚本按 ANSI/GB2312 解析 → 中文注释乱码 → **语法解析错乱**（报错行号与磁盘内容不符、变量莫名为 null） | **PowerShell 脚本必须存为 UTF-8 带 BOM**：`[System.IO.File]::WriteAllText($p,$t,(New-Object System.Text.UTF8Encoding($true)))`；数据文件（md/json）仍用**无 BOM** |'

# 2a) 工作区 AGENTS.md 规则 0
$agp = Join-Path $root 'AGENTS.md'
$ag = [System.IO.File]::ReadAllText($agp, [System.Text.Encoding]::UTF8)
if ($ag -notmatch 'PowerShell 脚本必须存为 UTF-8 带 BOM') {
    $anchor = '| DSH 处于**只读**（read-only）模式时'
    $i = $ag.IndexOf($anchor)
    if ($i -ge 0) {
        $eol = $ag.IndexOf("`n", $i)
        $ag = $ag.Substring(0, $eol + 1) + $row + "`r`n" + $ag.Substring($eol + 1)
        [System.IO.File]::WriteAllText($agp, $ag, $utf8bom)
        Write-Output '  [OK] AGENTS.md 规则 0 已加入 BOM 事实'
    } else { Write-Output '  [FAIL] AGENTS.md 锚点未找到' }
} else { Write-Output '  [SKIP] AGENTS.md 已含' }

# 2b) output-storage-policy.md §10
$osp = Join-Path $root 'policy\output-storage-policy.md'
$os = [System.IO.File]::ReadAllText($osp, [System.Text.Encoding]::UTF8)
if ($os -notmatch 'PowerShell 脚本必须存为 UTF-8 带 BOM') {
    $anchor2 = '| `pip`/`venv` 报 `WinError 5`'
    $i2 = $os.IndexOf($anchor2)
    if ($i2 -ge 0) {
        $eol2 = $os.IndexOf("`n", $i2)
        $os = $os.Substring(0, $eol2 + 1) + $row + "`r`n" + $os.Substring($eol2 + 1)
        [System.IO.File]::WriteAllText($osp, $os, $utf8bom)
        Write-Output '  [OK] output-storage-policy.md §10 已加入'
    } else { Write-Output '  [FAIL] §10 锚点未找到' }
} else { Write-Output '  [SKIP] 已含' }

# 2c) global-agents.md 规则 7
$gap = Join-Path $root 'policy\deploy\global-agents.md'
$ga = [System.IO.File]::ReadAllText($gap, [System.Text.Encoding]::UTF8)
if ($ga -notmatch 'PowerShell 脚本必须存为 UTF-8 带 BOM') {
    $anchor3 = '| 用户 PATH 前置仍压不过'
    $i3 = $ga.IndexOf($anchor3)
    if ($i3 -ge 0) {
        $eol3 = $ga.IndexOf("`n", $i3)
        $ga = $ga.Substring(0, $eol3 + 1) + $row + "`r`n" + $ga.Substring($eol3 + 1)
        [System.IO.File]::WriteAllText($gap, $ga, $utf8bom)
        Write-Output '  [OK] global-agents.md 规则 7 已加入'
    } else { Write-Output '  [FAIL] 规则 7 锚点未找到' }
} else { Write-Output '  [SKIP] 已含' }

Write-Output ''
Write-Output '=== 3) 重新部署全局副本 ==='
$new = [System.IO.File]::ReadAllText($gap, [System.Text.Encoding]::UTF8)
$dst = Join-Path $env:USERPROFILE '.dsh\AGENTS.md'
$old = [System.IO.File]::ReadAllText($dst, [System.Text.Encoding]::UTF8)
if ($old -eq $new) { Write-Output '  已是最新' }
else {
    Copy-Item -LiteralPath $dst -Destination ($dst + '.bak-' + (Get-Date).ToString('yyyyMMdd-HHmmss')) -Force
    [System.IO.File]::WriteAllText($dst, $new, $utf8bom)
    Write-Output ('  已部署（' + $old.Length + ' -> ' + $new.Length + ' 字符，带 BOM）')
    Write-Output ('  校验一致: ' + ([System.IO.File]::ReadAllText($dst, [System.Text.Encoding]::UTF8) -eq $new))
}

Write-Output ''
Write-Output '=== 4) 再跑一次备份（纳入新规则） ==='
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'tools\Backup-Rules.ps1') 2>&1 | ForEach-Object { Write-Output ('  ' + $_) }", "description": "Add BOM rule and refresh backup", "timeoutMs": 900000}

