{"command": "$ErrorActionPreference = 'Continue'
Write-Output '=== 1) ~/.dsh 全貌（找 plugins / marketplace 痕迹） ==='
Get-ChildItem -LiteralPath (Join-Path $env:USERPROFILE '.dsh') -Force | ForEach-Object {
    Write-Output ('  ' + $(if ($_.PSIsContainer) { '[目录]' } else { '[文件]' }) + ' ' + $_.Name.PadRight(34) + $(if (-not $_.PSIsContainer) { [Math]::Round($_.Length/1KB,1).ToString() + ' KB' }))
}
Write-Output ''
foreach ($sub in 'plugins', 'packages', 'extensions', 'marketplace', 'storages\plugins') {
    $p = Join-Path $env:USERPROFILE ".dsh\$sub"
    if (Test-Path -LiteralPath $p) {
        Write-Output ('  [' + $sub + '] 存在:')
        Get-ChildItem -LiteralPath $p -Force -Depth 1 -ErrorAction SilentlyContinue | Select-Object -First 20 | ForEach-Object {
            Write-Output ('     ' + $_.FullName.Substring($p.Length + 1))
        }
    }
}
Write-Output ''
Write-Output '=== 2) 配置里是否提到 marketplace / plugin 源 ==='
foreach ($f in (Join-Path $env:USERPROFILE '.dsh\settings.yaml.imported'), (Join-Path $env:USERPROFILE '.dsh\.credentials.yaml')) {
    if (Test-Path -LiteralPath $f) {
        Write-Output ('  -- ' + (Split-Path -Leaf $f))
        Get-Content -LiteralPath $f -Encoding UTF8 | ForEach-Object { Write-Output ('     ' + $_) }
    }
}
Write-Output ''
Write-Output '=== 3) profile patch 内容（之前给两个 profile 加过什么） ==='
foreach ($prof in 'desktop', 'web') {
    $f = Join-Path $env:USERPROFILE ".dsh\profiles\$prof\cordis.patch.yml"
    if (Test-Path -LiteralPath $f) {
        Write-Output ('  -- ' + $prof + '\cordis.patch.yml')
        Get-Content -LiteralPath $f -Encoding UTF8 | ForEach-Object { Write-Output ('     ' + $_) }
    }
}", "description": "Explore DSH plugin and marketplace locations", "timeoutMs": 300000}

