const fs = require('fs');
const flat = JSON.parse(fs.readFileSync('E:\\deepseek\\workspace\\conv-20260928-3b54e160\\asar-flat.json', 'utf8'));
const fd = fs.openSync('D:\\Application\\dsh\\resources\\app.asar', 'r');
const head = Buffer.alloc(16);
