const jsonSize = head.readUInt32LE(12);
const base = 16 + jsonSize;
function read(e) { if (e.unpacked) return null; const b = Buffer.alloc(e.size); fs.readSync(fd, b, 0, e.size, base + e.offset); return b.toString('utf8'); }

console.log('=== 本机 DSH 版本与关键依赖版本 ===');
