  const e = flat.find((f) => f.path === p);
  if (e) {
    const j = JSON.parse(read(e));
    console.log('  ' + p);
    console.log('    name    : ' + j.name);
    console.log('    version : ' + j.version);
  }
}
const wanted = ['dsh-llm', 'dsh-agent', 'dsh-agent-loop', 'dsh-base', 'dsh-session', 'dsh-tools', 'schemastery', 'cordis'];
