  const e = flat.find((f) => f.path === '/dsh/node_modules/@deepseek-ai/' + w + '/package.json');
  if (e) {
    const j = JSON.parse(read(e));
    console.log('  @deepseek-ai/' + w.padEnd(18) + 'v' + j.version);
  } else {
    console.log('  @deepseek-ai/' + w.padEnd(18) + '(未在 asar 内)');
  }
}
