{"command": "$ErrorActionPreference = 'Continue'
$dest = 'E:\deepseek\data\conv-20260928-3b54e160'
New-Item -ItemType Directory -Force -Path $dest | Out-Null

Write-Output '=== 1) 下载插件包（tarball） ==='
Push-Location $dest
& npm pack dsh-guard-repeat-output --registry=https://registry.npmmirror.com 2>&1 | Select-Object -Last 8 | ForEach-Object { Write-Output ('  ' + $_) }
Pop-Location

Write-Output ''
Write-Output '=== 2) 下载结果 ==='
Get-ChildItem -LiteralPath $dest -Filter '*.tgz' | ForEach-Object {
    Write-Output ('  ' + $_.Name + '  ' + [Math]::Round($_.Length/1KB,1) + ' KB')
}

Write-Output ''
Write-Output '=== 3) 解包并检查（依赖 / 构建脚本 / 版本要求） ==='
$tgz = Get-ChildItem -LiteralPath $dest -Filter 'dsh-guard-repeat-output*.tgz' | Select-Object -First 1
if ($tgz) {
    $ex = Join-Path $dest 'extracted'
    if (Test-Path -LiteralPath $ex) { Remove-Item -LiteralPath $ex -Recurse -Force }
    New-Item -ItemType Directory -Force -Path $ex | Out-Null
    & tar -xzf $tgz.FullName -C $ex 2>&1 | Select-Object -First 3 | ForEach-Object { Write-Output ('  ' + $_) }
    $pkgDir = Join-Path $ex 'package'
    if (Test-Path -LiteralPath $pkgDir) {
        Write-Output '  包内容:'
        Get-ChildItem -LiteralPath $pkgDir -Recurse -File | Select-Object -First 20 | ForEach-Object {
            Write-Output ('    ' + $_.FullName.Substring($pkgDir.Length + 1).PadRight(46) + [Math]::Round($_.Length/1KB,1) + ' KB')
        }
        Write-Output ''
        Write-Output '  package.json 关键字段:'
        $j = [System.IO.File]::ReadAllText((Join-Path $pkgDir 'package.json'), [System.Text.Encoding]::UTF8) | ConvertFrom-Json
        Write-Output ('    name        : ' + $j.name)
        Write-Output ('    version     : ' + $j.version)
        Write-Output ('    main        : ' + $j.main)
        Write-Output ('    dependencies: ' + ($j.dependencies | ConvertTo-Json -Compress))
        Write-Output ('    peerDeps    : ' + ($j.peerDependencies | ConvertTo-Json -Compress))
        Write-Output ('    scripts     : ' + ($j.scripts | ConvertTo-Json -Compress))
        Write-Output ('    engines     : ' + ($j.engines | ConvertTo-Json -Compress))
        Write-Output ('    cordis 字段 : ' + ($j.cordis | ConvertTo-Json -Compress -Depth 5))
    }
}", "description": "Download and inspect the plugin package", "timeoutMs": 900000}

