content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$prof = Join-Path $env:USERPROFILE '.dsh\profiles\desktop'

Write-Output '=== 1) desktop profile 目录现状 ==='
Get-ChildItem -LiteralPath $prof -Force -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | ForEach-Object {
    Write-Output ('  ' + $(if ($_.PSIsContainer) { '[目录]' } else { '[文件]' }) + ' ' + $_.Name.PadRight(32) + $(if (-not $_.PSIsContainer) { [Math]::Round($_.Length/1KB,1).ToString() + ' KB' }) + '  ' + $_.LastWriteTime)
}

Write-Output ''
Write-Output '=== 2) cordis.patch.yml 是否已加入该插件 ==='
$patchFile = Join-Path $prof 'cordis.patch.yml'
if (Test-Path -LiteralPath $patchFile) {
    $t = [System.IO.File]::ReadAllText($patchFile, [System.Text.Encoding]::UTF8)
    Write-Output ('  文件大小: ' + $t.Length + ' 字符   修改时间: ' + (Get-Item $patchFile).LastWriteTime)
    Write-Output ('  含 guard-repeat-output: ' + ($t -match 'guard-repeat-output'))
    $lines = $t -split "`r?`n"
    for ($i = 0; $i -lt $lines.Count; $i++) {
        if ($lines[$i] -match 'guard-repeat-output|truncateChannels|maxDegenerationRetries|modelIncludes|windowChars') {
            Write-Output ('    L' + ($i+1) + ': ' + $lines[$i])
        }
    }
} else { Write-Output '  cordis.patch.yml 不存在' }

Write-Output ''
Write-Output '=== 3) package.json 依赖清单 ==='
$pj = Join-Path $prof 'package.json'
if (Test-Path -LiteralPath $pj) {
    $j = [System.IO.File]::ReadAllText($pj, [System.Text.Encoding]::UTF8) | ConvertFrom-Json
    Write-Output ('  name: ' + $j.name)
    Write-Output ('  dependencies:')
    $j.dependencies.PSObject.Properties | ForEach-Object { Write-Output ('    ' + $_.Name + ' : ' + $_.Value) }
} else { Write-Output '  package.json 不存在' }

Write-Output ''
Write-Output '=== 4) 插件包是否落地到 node_modules ==='
$nm = Join-Path $prof 'node_modules\dsh-guard-repeat-output'
if (Test-Path -LiteralPath $nm) {
    $f = @(Get-ChildItem -LiteralPath $nm -Recurse -File)
    Write-Output ('  [有] ' + $nm + '  (' + $f.Count + ' 文件)')
    $f | Select-Object -First 8 | ForEach-Object { Write-Output ('      ' + $_.Name.PadRight(30) + [Math]::Round($_.Length/1KB,1) + ' KB') }
} else {
    Write-Output ('  [无] ' + $nm)
    Write-Output '  搜索其他可能的落地位置:'
    Get-ChildItem -LiteralPath $prof -Recurse -Directory -Filter '*guard*' -ErrorAction SilentlyContinue | Select-Object -First 5 | ForEach-Object { Write-Output ('      ' + $_.FullName) }
}

Write-Output ''
Write-Output '=== 5) DSH 进程启动时间（判断是否重启过） ==='
Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -match '(?i)DeepSeek|dsh' } | ForEach-Object {
    Write-Output ('  PID ' + $_.Id + '  ' + $_.ProcessName.PadRight(28) + '启动 ' + $_.StartTime + '  内存 ' + [Math]::Round($_.WorkingSet64/1MB) + ' MB')
}
Write-Output ('  当前时间: ' + (Get-Date))", "description": "Verify plugin installed in desktop profile", "timeoutMs": 600000}

