content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$prof = Join-Path $env:USERPROFILE '.dsh\profiles\desktop'

Write-Output '=== 1) cordis.yml（profile 入口，21:50:50 刚被改过） ==='
Get-Content -LiteralPath (Join-Path $prof 'cordis.yml') -Encoding UTF8 | ForEach-Object { Write-Output ('  ' + $_) }

Write-Output ''
Write-Output '=== 2) .plugin-manager 目录（启用状态可能记在这里） ==='
Get-ChildItem -LiteralPath (Join-Path $prof '.plugin-manager') -Recurse -Force -ErrorAction SilentlyContinue | ForEach-Object {
    Write-Output ('  ' + $(if ($_.PSIsContainer) { '[目录] ' } else { '       ' }) + $_.FullName.Substring((Join-Path $prof '.plugin-manager').Length + 1).PadRight(40) + $(if (-not $_.PSIsContainer) { [Math]::Round($_.Length/1KB,1).ToString() + ' KB  ' + $_.LastWriteTime }))
}

Write-Output ''
Write-Output '=== 3) .plugin-manager 里的文件内容（若为配置） ==='
Get-ChildItem -LiteralPath (Join-Path $prof '.plugin-manager') -Recurse -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Length -lt 200000 } | ForEach-Object {
    Write-Output ('  -- ' + $_.Name)
    if ($_.Extension -match '\.(json|yml|yaml|txt|log)$') {
        Get-Content -LiteralPath $_.FullName -Encoding UTF8 -TotalCount 30 | ForEach-Object { Write-Output ('     ' + $_) }
    }
}

Write-Output ''
Write-Output '=== 4) pnpm-workspace.yaml 与 lock 是否提到插件 ==='
foreach ($f in 'pnpm-workspace.yaml', 'pnpm-lock.yaml') {
    $p = Join-Path $prof $f
    if (Test-Path -LiteralPath $p) {
        $t = [System.IO.File]::ReadAllText($p, [System.Text.Encoding]::UTF8)
        Write-Output ('  ' + $f + '  含 guard-repeat-output: ' + ($t -match 'guard-repeat-output'))
    }
}

Write-Output ''
Write-Output '=== 5) 找 DSH 运行日志（宿主日志才是验证依据） ==='
$cands = @(
    (Join-Path $env:USERPROFILE '.dsh\logs'),
    (Join-Path $env:APPDATA 'DeepSeek Harness\logs'),
    (Join-Path $env:APPDATA 'dsh\logs'),
    (Join-Path $env:LOCALAPPDATA 'DeepSeek Harness\logs'),
    (Join-Path $env:USERPROFILE '.dsh\profiles\desktop\.dsh-market\logs')
)
foreach ($c in $cands) {
    if (Test-Path -LiteralPath $c) {
        Write-Output ('  [有] ' + $c)
        Get-ChildItem -LiteralPath $c -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 5 | ForEach-Object {
            Write-Output ('        ' + $_.Name.PadRight(46) + [Math]::Round($_.Length/1KB,1).ToString().PadLeft(9) + ' KB  ' + $_.LastWriteTime)
        }
    } else { Write-Output ('  [无] ' + $c) }
}", "description": "Check profile entry and plugin manager state", "timeoutMs": 600000}

