Write-Output '=== 1) package.json 全文（重点：dsh 字段里的 bundles） ==='
Get-Content -LiteralPath (Join-Path $prof 'package.json') -Encoding UTF8 | ForEach-Object { Write-Output ('  ' + $_) }

Write-Output ''
Write-Output '=== 2) 应用数据目录（Electron user-data-dir） ==='
$appData = Join-Path $env:APPDATA '@deepseek-ai\dsh-desktop'
if (Test-Path -LiteralPath $appData) {
    Get-ChildItem -LiteralPath $appData -Force | Sort-Object LastWriteTime -Descending | Select-Object -First 20 | ForEach-Object {
        Write-Output ('  ' + $(if ($_.PSIsContainer) { '[目录] ' } else { '[文件] ' }) + $_.Name.PadRight(34) + $(if (-not $_.PSIsContainer) { [Math]::Round($_.Length/1KB,1).ToString() + ' KB' }) + '  ' + $_.LastWriteTime)
    }
    Write-Output ''
    Write-Output '  找日志文件:'
    Get-ChildItem -LiteralPath $appData -Recurse -File -Include '*.log', '*.txt' -ErrorAction SilentlyContinue |
        Sort-Object LastWriteTime -Descending | Select-Object -First 8 | ForEach-Object {
            Write-Output ('    ' + $_.FullName.Substring($appData.Length + 1).PadRight(50) + [Math]::Round($_.Length/1KB,1) + ' KB  ' + $_.LastWriteTime)
        }
} else { Write-Output ('  [无] ' + $appData) }

Write-Output ''
Write-Output '=== 3) 搜索最近 1 天内提到 guard-repeat-output 的文件（找启用证据） ==='
$bases = @((Join-Path $env:USERPROFILE '.dsh'), $appData)
foreach ($b in $bases) {
    if (-not (Test-Path -LiteralPath $b)) { continue }
    Get-ChildItem -LiteralPath $b -Recurse -File -Force -ErrorAction SilentlyContinue |
        Where-Object { $_.Length -lt 3MB -and $_.LastWriteTime -gt (Get-Date).AddDays(-1) -and $_.Extension -match '\.(yml|yaml|json|log|txt|js)$' } |
        ForEach-Object {
            try {
                $c = [System.IO.File]::ReadAllText($_.FullName, [System.Text.Encoding]::UTF8)
                if ($c -match 'guard-repeat-output|guard_repeat_output') {
                    Write-Output ('  [命中] ' + $_.FullName + '  (' + [Math]::Round($_.Length/1KB,1) + ' KB, ' + $_.LastWriteTime + ')')
                }
            } catch {}
        }
}", "description": "Check bundles field and find enable evidence", "timeoutMs": 900000}

