content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$pkg = 'C:\Users\徐丰哲\.dsh\profiles\desktop\node_modules\dsh-guard-repeat-output'

Write-Output '=== 1) 插件自带 patch 的剩余部分（看 copyDir / 观测项） ==='
$t = [System.IO.File]::ReadAllText((Join-Path $pkg 'cordis.patch.yml'), [System.Text.Encoding]::UTF8)
$lines = $t -split "`r?`n"
$start = -1
for ($i = 0; $i -lt $lines.Count; $i++) { if ($lines[$i] -match 'copyDir|Sidecar|copyMaxChars') { $start = [Math]::Max(0, $i - 12); break } }
if ($start -ge 0) {
    for ($i = $start; $i -lt [Math]::Min($start + 40, $lines.Count); $i++) { Write-Output ('  L' + ($i+1) + ': ' + $lines[$i]) }
} else { Write-Output '  （未找到 copyDir 段，打印末尾 25 行）'; $lines[([Math]::Max(0,$lines.Count-25))..($lines.Count-1)] | ForEach-Object { Write-Output ('  ' + $_) } }

Write-Output ''
Write-Output '=== 2) 插件是否已产生 sidecar 副本（= 真的在工作过） ==='
$cands = @(
    (Join-Path $env:USERPROFILE '.dsh\logs\dsh-guard-repeat-output'),
    (Join-Path $env:USERPROFILE '.dsh\guard-repeat-output'),
    (Join-Path $env:USERPROFILE '.dsh\profiles\desktop\.dsh-guard-repeat-output'),
    (Join-Path $env:USERPROFILE '.dsh\logs')
)
foreach ($c in $cands) {
    if (Test-Path -LiteralPath $c) {
        $f = @(Get-ChildItem -LiteralPath $c -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '(?i)guard|repeat|discard|collapse' })
        Write-Output ('  [有] ' + $c + '  命中文件 ' + $f.Count)
        $f | Select-Object -First 6 | ForEach-Object { Write-Output ('       ' + $_.Name + '  ' + $_.LastWriteTime) }
    } else { Write-Output ('  [无] ' + $c) }
}

Write-Output ''
Write-Output '=== 3) 全盘搜插件产物（今天之后、名字含 guard/repeat 的目录） ==='
Get-ChildItem -LiteralPath (Join-Path $env:USERPROFILE '.dsh') -Recurse -Directory -Force -ErrorAction SilentlyContinue |
    Where-Object { $_.Name -match '(?i)guard|repeat' } | Select-Object -First 10 | ForEach-Object {
        Write-Output ('  ' + $_.FullName + '   ' + $_.LastWriteTime)
    }

Write-Output ''
Write-Output '=== 4) 插件加载自检：包内 index.js 是否声明 cordis 插件标识 ==='
$idx = [System.IO.File]::ReadAllText((Join-Path $pkg 'index.js'), [System.Text.Encoding]::UTF8)
foreach ($kw in 'export const name', 'export const inject', "name = 'guard-repeat-output'", 'guard-repeat-output') {
    Write-Output ('  含 "' + $kw + '": ' + ($idx -match [regex]::Escape($kw)))
}
$m = [regex]::Matches($idx, "(?m)^\s*(export const (name|inject|Config|reusable)\s*=.{0,90})")
foreach ($x in $m | Select-Object -First 6) { Write-Output ('    ' + $x.Value.Trim()) }", "description": "Verify plugin sidecar and identity", "timeoutMs": 600000}

