    }
    Write-Output ('  ' + $(if ($_.PSIsContainer) { '[目录]' } else { '[文件]' }) + ' ' + $_.Name.PadRight(30) + $n.PadLeft(10) + $s.PadLeft(12) + '  ' + $_.LastWriteTime)
}

Write-Output ''
Write-Output '=== 各目录的内容（深度 2，判断哪些是工作区） ==='
Get-ChildItem -LiteralPath 'E:\' -Directory -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne 'System Volume Information' } | ForEach-Object {
    Write-Output ('  ── ' + $_.FullName)
    Get-ChildItem -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue | Select-Object -First 14 | ForEach-Object {
        Write-Output ('      ' + $(if ($_.PSIsContainer) { '[目录] ' } else { '[文件] ' }) + $_.Name + $(if (-not $_.PSIsContainer) { '  (' + [Math]::Round($_.Length/1KB,1) + ' KB)' }))
    }
    $more = @(Get-ChildItem -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue).Count
    if ($more -gt 14) { Write-Output ('      …（共 ' + $more + ' 项）') }
}", "description": "Survey E drive for new workspaces", "timeoutMs": 600000}

