content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$tools = 'E:\deepseek\tools'
$bom = New-Object System.Text.UTF8Encoding($true)

Write-Output '=== 改动前各脚本的 $Root 声明 ==='
foreach ($f in 'New-ConversationWorkspace.ps1', 'Test-StoragePolicy.ps1', 'Install-GlobalPolicy.ps1', 'Backup-Rules.ps1') {
    $p = Join-Path $tools $f
    $hit = Select-String -LiteralPath $p -Pattern '\[string\]\$Root' | Select-Object -First 1
    Write-Output ('  ' + $f.PadRight(32) + $(if ($hit) { $hit.Line.Trim() } else { '（未找到）' }))
}

Write-Output ''
Write-Output '=== 改为「从脚本自身位置推断」，支持多工作区 ==='
foreach ($f in 'New-ConversationWorkspace.ps1', 'Test-StoragePolicy.ps1', 'Install-GlobalPolicy.ps1', 'Backup-Rules.ps1') {
    $p = Join-Path $tools $f
    $t = [System.IO.File]::ReadAllText($p, [System.Text.Encoding]::UTF8)
    $orig = $t

    # 把 [string]$Root = 'E:\Deepseek' 换成空默认值 + param 块后推断
    $t = $t -replace "\[string\]\`$Root = 'E:\\Deepseek'", "[string]`$Root = ''"
    $t = $t -replace "\[string\]\`$Root = 'E:\\deepseek'", "[string]`$Root = ''"

    # 在 param 块之后插入推断逻辑（幂等）
    if ($t -notmatch [regex]::Escape('$PSScriptRoot')) {
        $anchor = "`$ErrorActionPreference = 'Stop'"
        $inject = @"
# 工作区根目录：默认从本脚本位置推断（tools\ 的上一级），因此本脚本可从任意工作区运行。
# 显式传入 -Root 仍可覆盖，向后兼容。
if (-not `$Root) { `$Root = Split-Path -Parent `$PSScriptRoot }

"@ + $anchor
        $idx = $t.IndexOf($anchor)
        if ($idx -ge 0) { $t = $t.Substring(0, $idx) + $inject + $t.Substring($idx + $anchor.Length) }
    }

    if ($t -ne $orig) {
        [System.IO.File]::WriteAllText($p, $t, $bom)
        Write-Output ('  [OK] ' + $f + ' 已改为按脚本位置推断 Root')
    } else {
        Write-Output ('  [SKIP] ' + $f + ' 无需改动')
    }
}

Write-Output ''
Write-Output '=== 校验：语法 + BOM + 推断行 ==='
foreach ($f in 'New-ConversationWorkspace.ps1', 'Test-StoragePolicy.ps1', 'Install-GlobalPolicy.ps1', 'Backup-Rules.ps1') {
    $p = Join-Path $tools $f
    $b = [System.IO.File]::ReadAllBytes($p)
    $h = ($b[0..2] | ForEach-Object { $_.ToString('X2') }) -join ' '
    $syn = & powershell.exe -NoProfile -Command "`$e=`$null; [void][System.Management.Automation.Language.Parser]::ParseFile('$p',[ref]`$null,[ref]`$e); if(`$e.Count -eq 0){'OK'}else{`$e[0].Message}"
    $hasInfer = ((Select-String -LiteralPath $p -Pattern 'PSScriptRoot' | Measure-Object).Count -gt 0)
    Write-Output ('  ' + $f.PadRight(32) + 'BOM=' + $h + '  语法=' + $syn + '  含推断=' + $hasInfer)
}", "description": "Make tools scripts workspace-agnostic", "timeoutMs": 600000}

