content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$tools = 'E:\deepseek\tools'
Write-Output '=== 1) 4 个脚本的中文完好度检查（统计"?"占比与中文行数） ==='
foreach ($f in 'New-ConversationWorkspace.ps1', 'Test-StoragePolicy.ps1', 'Install-GlobalPolicy.ps1', 'Backup-Rules.ps1') {
    $p = Join-Path $tools $f
    $t = [System.IO.File]::ReadAllText($p, [System.Text.Encoding]::UTF8)
    $cjk = ([regex]::Matches($t, '[\u4e00-\u9fff]')).Count
    $q = ([regex]::Matches($t, '\?')).Count
    Write-Output ('  ' + $f.PadRight(32) + '中文字符 ' + $cjk.ToString().PadLeft(5) + '   问号 ' + $q.ToString().PadLeft(4) + '   ' + $(if ($cjk -eq 0 -and $q -gt 20) { '✗ 中文已损坏' } elseif ($cjk -gt 20) { '✓ 正常' } else { '? 需人工看' }))
}

Write-Output ''
Write-Output '=== 2) 抽样：每个脚本前 6 行 ==='
foreach ($f in 'New-ConversationWorkspace.ps1', 'Test-StoragePolicy.ps1') {
    $p = Join-Path $tools $f
    Write-Output ('  -- ' + $f)
    Get-Content -LiteralPath $p -Encoding UTF8 -TotalCount 6 | ForEach-Object { Write-Output ('     ' + $_) }
}

Write-Output ''
Write-Output '=== 3) 这些脚本是否有 $ErrorActionPreference 行（插入锚点） ==='
foreach ($f in 'New-ConversationWorkspace.ps1', 'Test-StoragePolicy.ps1', 'Install-GlobalPolicy.ps1', 'Backup-Rules.ps1') {
    $p = Join-Path $tools $f
    $has = (Select-String -LiteralPath $p -Pattern 'ErrorActionPreference' | Measure-Object).Count
    Write-Output ('  ' + $f.PadRight(32) + 'ErrorActionPreference 出现 ' + $has + ' 次')
}

Write-Output ''
Write-Output '=== 4) 对照：工作区里其他带中文的文件是否正常 ==='
foreach ($f in 'E:\deepseek\AGENTS.md', 'E:\deepseek\policy\ai-tool-policy.md') {
    $t = [System.IO.File]::ReadAllText($f, [System.Text.Encoding]::UTF8)
    $cjk = ([regex]::Matches($t, '[\u4e00-\u9fff]')).Count
    Write-Output ('  ' + (Split-Path -Leaf $f).PadRight(32) + '中文字符 ' + $cjk)
}", "description": "Check Chinese text integrity in scripts", "timeoutMs": 300000}

