$bom = New-Object System.Text.UTF8Encoding($true)

$fixLine1 = '# 说明：本脚本为 2026-10-11 重建版（原件随 E: 盘清空丢失）；结构与功能按原版语义重建，'
$fixLine2 = '#       并经语法校验与实际运行验证。'

foreach ($f in 'New-ConversationWorkspace.ps1', 'Test-StoragePolicy.ps1', 'Install-GlobalPolicy.ps1') {
    $p = Join-Path $tools $f
    $lines = [System.IO.File]::ReadAllLines($p, [System.Text.Encoding]::UTF8)
    $changed = $false
    for ($i = 0; $i -lt $lines.Count; $i++) {
        # 定位被破坏的标注行：含 '2026-10-11' 且含连续问号
        if ($lines[$i] -match '2026-10-11' -and $lines[$i] -match '\?\?\?') {
            $lines[$i] = $fixLine1
            if (($i + 1) -lt $lines.Count -and $lines[$i + 1] -match '^\s*#\s*\?+') { $lines[$i + 1] = $fixLine2 }
            $changed = $true
            break
        }
    }
    if ($changed) {
        [System.IO.File]::WriteAllLines($p, $lines, $bom)
        Write-Output ('  [OK] ' + $f + ' 标注行已修复')
    } else {
        Write-Output ('  [SKIP] ' + $f + ' 未找到损坏行')
    }
}

Write-Output ''
Write-Output '=== 给 Test-StoragePolicy.ps1 补 $Root 推断（它没有 ErrorActionPreference 锚点） ==='
$p2 = Join-Path $tools 'Test-StoragePolicy.ps1'
$t = [System.IO.File]::ReadAllText($p2, [System.Text.Encoding]::UTF8)
if ($t -notmatch '\$PSScriptRoot') {
    $anchor = '$findings = New-Object System.Collections.ArrayList'
    $inject = @"
# 工作区根目录：默认从本脚本位置推断（tools\ 的上一级），因此本脚本可从任意工作区运行。
# 显式传入 -Root 仍可覆盖。
if (-not `$Root) { `$Root = Split-Path -Parent `$PSScriptRoot }

$anchor
"@
    $idx = $t.IndexOf($anchor)
    if ($idx -ge 0) {
        $t = $t.Substring(0, $idx) + $inject + $t.Substring($idx + $anchor.Length)
        [System.IO.File]::WriteAllText($p2, $t, $bom)
        Write-Output '  [OK] 已插入 $Root 推断'
    } else { Write-Output '  [FAIL] 锚点未找到' }
} else { Write-Output '  [SKIP] 已含推断' }

Write-Output ''
Write-Output '=== 校验：中文恢复 / 问号清零 / 语法 / BOM / Root 推断 ==='
foreach ($f in 'New-ConversationWorkspace.ps1', 'Test-StoragePolicy.ps1', 'Install-GlobalPolicy.ps1', 'Backup-Rules.ps1') {
    $p = Join-Path $tools $f
    $t = [System.IO.File]::ReadAllText($p, [System.Text.Encoding]::UTF8)
    $cjk = ([regex]::Matches($t, '[\u4e00-\u9fff]')).Count
    $q = ([regex]::Matches($t, '\?')).Count
    $b = [System.IO.File]::ReadAllBytes($p)
    $h = ($b[0..2] | ForEach-Object { $_.ToString('X2') }) -join ' '
    $syn = & powershell.exe -NoProfile -Command "`$e=`$null; [void][System.Management.Automation.Language.Parser]::ParseFile('$p',[ref]`$null,[ref]`$e); if(`$e.Count -eq 0){'OK'}else{`$e[0].Message}"
    $infer = ((Select-String -LiteralPath $p -Pattern 'PSScriptRoot' | Measure-Object).Count -gt 0)
    Write-Output ('  ' + $f.PadRight(32) + '中文 ' + $cjk.ToString().PadLeft(4) + '  问号 ' + $q.ToString().PadLeft(3) + '  BOM=' + $h + '  语法=' + $syn + '  推断=' + $infer)
}

Write-Output ''
Write-Output '=== 实跑验证：在 E:\deepseek 里跑自检（应仍正常） ==='
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $tools 'Test-StoragePolicy.ps1') 2>&1 | Select-Object -Last 3 | ForEach-Object { Write-Output ('  ' + $_) }", "description": "Fix corrupted comments and add Root inference", "timeoutMs": 600000}

