content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$root = 'E:\deepseek'
$mdEnc = New-Object System.Text.UTF8Encoding($false)   # md 数据文件：无 BOM
$bomEnc = New-Object System.Text.UTF8Encoding($true)   # ps1 脚本：带 BOM

# ============ 1) storage-policy.json → v1.5.0，白名单加 eim_config.toml ============
$js = @'
const fs = require('fs');
const p = 'E:\\deepseek\\policy\\storage-policy.json';
const o = JSON.parse(fs.readFileSync(p, 'utf8'));
o.policyVersion = '1.5.0';
o.updatedAt = '2026-10-14';
if (!o.rootAllowList.includes('eim_config.toml')) o.rootAllowList.push('eim_config.toml');
o.rootAllowListNotes = Object.assign({}, o.rootAllowListNotes, {
  'eim_config.toml': 'ESP-IDF installer (EIM) configuration; the installer expects it in the project root, so the root allow list admits it (added 2026-10-14 by user decision)'
});
fs.writeFileSync(p, JSON.stringify(o, null, 2) + '\n', 'utf8');
console.log('[OK] storage-policy.json v' + o.policyVersion + ' | rootAllowList: ' + o.rootAllowList.length + ' entries (incl. eim_config.toml)');
'@
$js | & 'D:\program_runtime_environment\nodejs\node.exe' - 2>&1 | ForEach-Object { Write-Output ('  ' + $_) }

# ============ 2) output-storage-policy.md §4 ============
$osp = Join-Path $root 'policy\output-storage-policy.md'
$t = [System.IO.File]::ReadAllText($osp, [System.Text.Encoding]::UTF8)
$old = @'
根目录**只允许**出现：`AGENTS.md`、`README.md`、`policy\`、`tools\`、`reference_file\`
以及六个类别目录（`deliverables\` `logs\` `scripts\` `workspace\` `data\` `archive\`）。
'@
$new = @'
根目录**只允许**出现：`AGENTS.md`、`README.md`、`policy\`、`tools\`、`reference_file\`
以及六个类别目录（`deliverables\` `logs\` `scripts\` `workspace\` `data\` `archive\`）。

另外允许**工具自生成的根目录配置文件**，目前是 `eim_config.toml`（ESP-IDF 安装器 EIM 的配置，
该工具要求在项目根读写它；2026-10-14 按用户决定加入白名单）。
将来若再有同类文件，应同样在 `policy\storage-policy.json` 的 `rootAllowList` 里登记并注明理由。
'@
$t2 = $t.Replace($old.TrimEnd("`r","`n"), $new.TrimEnd("`r","`n"))
if ($t2 -ne $t) { [System.IO.File]::WriteAllText($osp, $t2, $mdEnc); Write-Output '  [OK] output-storage-policy.md §4 已更新' }
else { Write-Output '  [SKIP] output-storage-policy.md 锚点未命中（可能已更新）' }

# ============ 3) AGENTS.md 规则 2 ============
$agp = Join-Path $root 'AGENTS.md'
$a = [System.IO.File]::ReadAllText($agp, [System.Text.Encoding]::UTF8)
$oldA = '工作区根目录只允许出现：`AGENTS.md`、`README.md`、`policy\`、`tools\`、`reference_file\` 以及上述 6 个类别目录。'
$newA = '工作区根目录只允许出现：`AGENTS.md`、`README.md`、`policy\`、`tools\`、`reference_file\`、上述 6 个类别目录，以及**工具自生成的配置文件**（目前为 ESP-IDF 安装器的 `eim_config.toml`，2026-10-14 加入白名单；新增同类文件须在 `policy\storage-policy.json` 的 `rootAllowList` 登记）。'
$a2 = $a.Replace($oldA, $newA)
if ($a2 -ne $a) { [System.IO.File]::WriteAllText($agp, $a2, $mdEnc); Write-Output '  [OK] AGENTS.md 规则 2 已更新' }
else { Write-Output '  [SKIP] AGENTS.md 锚点未命中' }

# ============ 4) tools\Test-StoragePolicy.ps1 的 fallback 白名单 ============
$tsp = Join-Path $root 'tools\Test-StoragePolicy.ps1'
$s = [System.IO.File]::ReadAllText($tsp, [System.Text.Encoding]::UTF8)
$oldS = "foreach (`$a in @('AGENTS.md', 'README.md', 'policy', 'tools', 'reference_file'))"
$newS = "foreach (`$a in @('AGENTS.md', 'README.md', 'policy', 'tools', 'reference_file', 'eim_config.toml'))"
$s2 = $s.Replace($oldS, $newS)
if ($s2 -ne $s) { [System.IO.File]::WriteAllText($tsp, $s2, $bomEnc); Write-Output '  [OK] Test-StoragePolicy.ps1 fallback 白名单已更新（带 BOM）' }
else { Write-Output '  [SKIP] Test-StoragePolicy.ps1 锚点未命中' }

# ============ 5) global-agents.md 规则 3（泛化说明，不点名具体文件） ============
$gap = Join-Path $root 'policy\deploy\global-agents.md'
$g = [System.IO.File]::ReadAllText($gap, [System.Text.Encoding]::UTF8)
$oldG = '工作区根目录只放 `AGENTS.md`、`README.md`、`policy\`、`tools\`、`reference_file\` 与上述类别目录；'
$newG = '工作区根目录只放 `AGENTS.md`、`README.md`、`policy\`、`tools\`、`reference_file\`、上述类别目录，以及工具自生成的配置文件（须在该工作区 `policy\storage-policy.json` 的 `rootAllowList` 登记）；'
$g2 = $g.Replace($oldG, $newG)
if ($g2 -ne $g) { [System.IO.File]::WriteAllText($gap, $g2, $bomEnc); Write-Output '  [OK] global-agents.md 规则 3 已更新（带 BOM）' }
else { Write-Output '  [SKIP] global-agents.md 锚点未命中' }

Write-Output ''
Write-Output '=== 校验 ==='
$j = [System.IO.File]::ReadAllText((Join-Path $root 'policy\storage-policy.json'), [System.Text.Encoding]::UTF8) | ConvertFrom-Json
Write-Output ('  storage-policy.json v' + $j.policyVersion + '  rootAllowList ' + @($j.rootAllowList).Count + ' 项，含 eim_config.toml: ' + ($j.rootAllowList -contains 'eim_config.toml'))
foreach ($f in 'policy\output-storage-policy.md', 'AGENTS.md', 'policy\deploy\global-agents.md') {
    $p = Join-Path $root $f
    $c = [System.IO.File]::ReadAllText($p, [System.Text.Encoding]::UTF8)
    Write-Output ('  ' + $f.PadRight(38) + '含 eim_config.toml 提及: ' + ($c -match 'eim_config\.toml'))
}
$syn = & powershell.exe -NoProfile -Command "`$e=`$null; [void][System.Management.Automation.Language.Parser]::ParseFile('$tsp',[ref]`$null,[ref]`$e); if(`$e.Count -eq 0){'OK'}else{`$e[0].Message}"
Write-Output ('  Test-StoragePolicy.ps1 语法: ' + $syn)", "description": "Add EIM config to root allow list", "timeoutMs": 600000}

