content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$prof = Join-Path $env:USERPROFILE '.dsh\profiles\desktop'

Write-Output '=== 1) profile 的 cordis.patch.yml 是否也含 groupchat（判断双重注册） ==='
$pp = Join-Path $prof 'cordis.patch.yml'
$t = [System.IO.File]::ReadAllText($pp, [System.Text.Encoding]::UTF8)
Write-Output ('  大小 ' + $t.Length + ' 字符，含 groupchat: ' + ($t -match 'groupchat'))
Get-Content -LiteralPath $pp -Encoding UTF8 | ForEach-Object { Write-Output ('  ' + $_) }

Write-Output ''
Write-Output '=== 2) dsh-groupchat 自带的 cordis.patch.yml ==='
$gp = Join-Path $prof 'node_modules\dsh-groupchat\cordis.patch.yml'
Get-Content -LiteralPath $gp -Encoding UTF8 | ForEach-Object { Write-Output ('  ' + $_) }

Write-Output ''
Write-Output '=== 3) 是否存在多个 groupchat 副本（重复挂载的常见原因） ==='
Get-ChildItem -LiteralPath (Join-Path $env:USERPROFILE '.dsh') -Recurse -Directory -Filter '*groupchat*' -ErrorAction SilentlyContinue | ForEach-Object {
    Write-Output ('  ' + $_.FullName)
}
Write-Output ''
Write-Output '  在 .dsh\profiles 下的所有 groupchat 实例:'
Get-ChildItem -LiteralPath (Join-Path $env:USERPROFILE '.dsh\profiles') -Recurse -Directory -Filter 'dsh-groupchat' -ErrorAction SilentlyContinue | ForEach-Object {
    $pj = Join-Path $_.FullName 'package.json'
    $v = '?'
    if (Test-Path -LiteralPath $pj) { $v = ([System.IO.File]::ReadAllText($pj, [System.Text.Encoding]::UTF8) | ConvertFrom-Json).version }
    Write-Output ('    v' + $v + '  ' + $_.FullName)
}

Write-Output ''
Write-Output '=== 4) 路由注册代码：groupchat 在哪里注册 /groupchat ==='
$idx = Join-Path $prof 'node_modules\dsh-groupchat\lib\index.js'
$lines = [System.IO.File]::ReadAllLines($idx, [System.Text.Encoding]::UTF8)
$n = 0
for ($i = 0; $i -lt $lines.Count; $i++) {
    if ($lines[$i] -match '/groupchat' -and $n -lt 12) {
        Write-Output ('  L' + ($i+1) + ': ' + $lines[$i].Trim().Substring(0, [Math]::Min(130, $lines[$i].Trim().Length)))
        $n++
    }
}

Write-Output ''
Write-Output '=== 5) dshmarket 最新版与 peerDeps 兼容性 ==='
$js = @'
const https = require('https');
function get(u) { return new Promise((res) => { const r = https.get(u, { headers: { 'User-Agent': 'dsh-research' } }, (x) => { if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(get(new URL(x.headers.location, u).toString())); return; } let d = ''; x.on('data', (c) => d += c); x.on('end', () => res({ code: x.statusCode, body: d })); }); r.on('error', (e) => res({ code: 0, body: String(e.message) })); r.setTimeout(25000, () => { r.destroy(); res({ code: 0, body: 'timeout' }); }); }); }
(async () => {
  const r = await get('https://registry.npmmirror.com/dshmarket');
  if (r.code !== 200) { console.log('  registry HTTP ' + r.code); return; }
  const j = JSON.parse(r.body);
  console.log('  latest tag : ' + j['dist-tags'].latest);
  const v = j.versions[j['dist-tags'].latest];
  console.log('  peers      : ' + JSON.stringify(v.peerDependencies || {}));
  const vs = Object.keys(j.versions);
  console.log('  total vers : ' + vs.length + '  (recent: ' + vs.slice(-6).join(', ') + ')');
})();
'@
$js | & 'D:\program_runtime_environment\nodejs\node.exe' 2>&1 | ForEach-Object { Write-Output $_ }", "description": "Find duplicate groupchat route source", "timeoutMs": 600000}

