content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$js = @'
const fs = require('fs');
const P = 'D:\\Application\\dsh\\resources\\app.asar';
const fd = fs.openSync(P, 'r');
const head = Buffer.alloc(16);
fs.readSync(fd, head, 0, 16, 0);
const jsonSize = head.readUInt32LE(12);
const jb = Buffer.alloc(jsonSize);
fs.readSync(fd, jb, 0, jsonSize, 16);
const tree = JSON.parse(jb.toString('utf8'));
const base = 16 + jsonSize;
const flat = [];
(function collect(node, prefix) {
  for (const [name, val] of Object.entries(node.files || {})) {
    const p = prefix + '/' + name;
    if (val.files) collect(val, p);
    else flat.push({ path: p, size: val.size, offset: Number(val.offset), unpacked: !!val.unpacked });
  }
})(tree, '');
function read(e) { if (e.unpacked) return null; const b = Buffer.alloc(e.size); fs.readSync(fd, b, 0, e.size, base + e.offset); return b.toString('utf8'); }

console.log('=== 桌面版内置包的版本（决定 peerDeps 是否满足） ===');
for (const pkg of ['dsh-settings', 'dsh', 'dsh-web-app', 'dsh-agent-loop', 'dsh-base']) {
  const e = flat.find((f) => f.path === '/dsh/node_modules/@deepseek-ai/' + pkg + '/package.json');
  if (e) {
    const j = JSON.parse(read(e));
    const nm = pkg === 'dsh' ? '@deepseek-ai/dsh' : '@deepseek-ai/' + pkg;
    console.log('  ' + nm.padEnd(32) + 'v' + j.version);
  } else {
    console.log('  @deepseek-ai/' + pkg.padEnd(18) + '(未找到)');
  }
}
const rt = flat.find((f) => f.path === '/dsh/package.json');
if (rt) {
  const j = JSON.parse(read(rt));
  console.log('  ' + j.name.padEnd(32) + 'v' + j.version + '   <-- 桌面运行时');
}
'@
$js | & 'D:\program_runtime_environment\nodejs\node.exe' 2>&1 | ForEach-Object { Write-Output ('  ' + $_) }

Write-Output ''
Write-Output '=== peerDeps 判定 ==='
Write-Output '  dshmarket 1.66.7  要求 dsh-settings: ^0.1.0-rc.7 || ^0.1.1-rc.2 || ^0.1.2-alpha.2 || ^0.2.0-rc.1'
Write-Output '  dshmarket 1.66.44 要求 dsh-settings: ... || ^0.2.1-alpha.3 || ^0.2.1-rc.1'
Write-Output '  （上面查到的实际版本决定哪一版才满足）'", "description": "Check built-in dsh-settings version", "timeoutMs": 600000}

