const https = require('https');
function get(u) { return new Promise((res) => { const r = https.get(u, { headers: { 'User-Agent': 'dsh-research' } }, (x) => { if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(get(new URL(x.headers.location, u).toString())); return; } let d = ''; x.on('data', (c) => d += c); x.on('end', () => res({ code: x.statusCode, body: d })); }); r.on('error', (e) => res({ code: 0, body: String(e.message) })); r.setTimeout(25000, () => { r.destroy(); res({ code: 0, body: 'timeout' }); }); }); }
(async () => {
  const r = await get('https://registry.npmmirror.com/dsh-guard-repeat-output');
  if (r.code !== 200) { console.log('registry HTTP ' + r.code); return; }
  const j = JSON.parse(r.body);
  const latest = j['dist-tags'].latest;
  console.log('=== dsh-guard-repeat-output ===');
  console.log('  dist-tags.latest : ' + latest);
  const v = j.versions[latest];
  console.log('  peerDependencies : ' + JSON.stringify(v.peerDependencies || {}));
  console.log('  dependencies     : ' + JSON.stringify(v.dependencies || {}));
  console.log('  engines          : ' + JSON.stringify(v.engines || {}));
  console.log('  license          : ' + (v.license || '?'));
  console.log('  unpackedSize     : ' + ((v.dist && v.dist.unpackedSize) || '?'));
  const times = j.time || {};
  console.log('');
  console.log('  版本时间线（最近 8 个）:');
  const vs = Object.keys(j.versions);
  for (const k of vs.slice(-8)) console.log('    ' + k.padEnd(12) + (times[k] || ''));
  console.log('');
  console.log('  当前已装 2.1.7 发布时间 : ' + (times['2.1.7'] || '?'));
  const p2 = j.versions['2.1.7'];
  if (p2) console.log('  2.1.7 peerDeps          : ' + JSON.stringify(p2.peerDependencies || {}));
})();
