{"command": "$ErrorActionPreference = 'Continue'
$js = @'
const https = require('https');
function get(u) { return new Promise((res) => { const r = https.get(u, { headers: { 'User-Agent': 'dsh-research' } }, (x) => { if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(get(new URL(x.headers.location, u).toString())); return; } let d = ''; x.on('data', (c) => d += c); x.on('end', () => res({ code: x.statusCode, body: d })); }); r.on('error', (e) => res({ code: 0, body: String(e.message) })); r.setTimeout(25000, () => { r.destroy(); res({ code: 0, body: 'timeout' }); }); }); }
(async () => {
  console.log('=== npm 上所有 dist-tags（看是否 next/alpha 有更高版） ===');
  const r = await get('https://registry.npmmirror.com/dsh-guard-repeat-output');
  if (r.code === 200) {
    const j = JSON.parse(r.body);
    for (const [tag, ver] of Object.entries(j['dist-tags'])) {
      console.log('  ' + tag.padEnd(10) + '-> ' + ver + '   (' + ((j.time || {})[ver] || '?') + ')');
    }
    const vs = Object.keys(j.versions);
    console.log('  版本总数: ' + vs.length + '，最高版: ' + vs[vs.length - 1]);
  } else console.log('  HTTP ' + r.code);

  console.log('');
  console.log('=== GitHub 仓库是否有未发版的新提交/tag ===');
  for (const u of ['https://api.github.com/repos/Mcd0LUO/dsh-guard-repeat-output/tags',
                   'https://api.github.com/repos/Mcd0LUO/dsh-guard-repeat-output/commits?per_page=3']) {
    const g = await get(u);
    console.log('-- ' + u.replace('https://api.github.com', '') + '  HTTP ' + g.code);
    if (g.code === 200) {
      try {
        const a = JSON.parse(g.body);
        if (Array.isArray(a)) {
          for (const it of a.slice(0, 5)) {
            if (it.name) console.log('   tag ' + it.name);
            else if (it.commit) console.log('   ' + it.commit.author.date + '  ' + String(it.commit.message).split('\n')[0].slice(0, 80));
          }
        }
      } catch (e) { console.log('   parse fail'); }
    }
  }
})();
'@
$js | & 'D:\program_runtime_environment\nodejs\node.exe' 2>&1 | ForEach-Object { Write-Output ('  ' + $_) }

Write-Output ''
Write-Output '=== 它这一周有没有真的拦过（关键：日志与丢弃副本） ==='
$h = Join-Path $env:USERPROFILE '.dsh'
foreach ($p in (Join-Path $h 'logs\dsh-guard-repeat-output.log'), (Join-Path $h 'logs\guard-repeat-output-pruned')) {
    if (Test-Path -LiteralPath $p) {
        $item = Get-Item -LiteralPath $p
        if ($item.PSIsContainer) {
            $files = @(Get-ChildItem -LiteralPath $p -File -ErrorAction SilentlyContinue)
            Write-Output ('  [存在] ' + $p + '  → ' + $files.Count + ' 个副本')
            $files | Sort-Object LastWriteTime -Descending | Select-Object -First 5 | ForEach-Object {
                Write-Output ('       ' + $_.Name.PadRight(46) + [Math]::Round($_.Length/1KB,1) + ' KB  ' + $_.LastWriteTime)
            }
        } else {
            Write-Output ('  [存在] ' + $p + '  → ' + [Math]::Round($item.Length/1KB,1) + ' KB, 最后写入 ' + $item.LastWriteTime)
            Get-Content -LiteralPath $p -Encoding UTF8 -Tail 8 | ForEach-Object { Write-Output ('       ' + $_) }
        }
    } else {
        Write-Output ('  [尚无] ' + $p)
    }
}", "description": "Check all version channels and whether plugin fired", "timeoutMs": 600000}

