    console.log('-- raw/' + br + '/package.json  HTTP ' + r.code);
    if (r.code === 200) {
      try {
        const j = JSON.parse(r.body);
        console.log('   version : ' + j.version);
        console.log('   name    : ' + j.name);
        console.log('   peers   : ' + JSON.stringify(j.peerDependencies || {}));
        console.log('   dsh     : ' + JSON.stringify(j.dsh || {}).slice(0, 200));
      } catch (e) { console.log('   parse fail: ' + r.body.slice(0, 80)); }
      break;
    }
  }
  console.log('');
  console.log('=== gitee 公开 API：最近 6 次提交 ===');
  const a = await get('https://gitee.com/api/v5/repos/jaxleon/dsh-groupchat/commits?per_page=6');
  console.log('-- commits HTTP ' + a.code);
  if (a.code === 200) {
    try {
      const arr = JSON.parse(a.body);
      for (const c of arr) {
        console.log('   ' + (c.commit.author.date || '?') + '  ' + String(c.sha || '').slice(0, 8) + '  ' + String(c.commit.message || '').split('\n')[0].slice(0, 90));
      }
    } catch (e) { console.log('   parse fail'); }
  }
  console.log('');
  console.log('=== 有无 CHANGELOG ===');
  for (const n of ['CHANGELOG.md', 'CHANGELOG.zh.md', 'RELEASE.md']) {
    const c = await get('https://gitee.com/jaxleon/dsh-groupchat/raw/main/' + n);
    console.log('   ' + n.padEnd(16) + 'HTTP ' + c.code);
    if (c.code === 200) { console.log(c.body.split('\n').slice(0, 20).map((l) => '      ' + l).join('\n')); break; }
  }
})();
