$remote = Join-Path $tmp 'lib__index.js'
$local = Join-Path $env:USERPROFILE '.dsh\profiles\desktop\node_modules\dsh-groupchat\lib\index.js'

Write-Output '=== 本地 v0.6.0 的 L36-62 ==='
$ll = [System.IO.File]::ReadAllLines($local, [System.Text.Encoding]::UTF8)
for ($i = 35; $i -lt 62 -and $i -lt $ll.Count; $i++) { Write-Output ('  L' + ($i+1) + ': ' + $ll[$i]) }

Write-Output ''
Write-Output '=== 远端 v0.6.5 的 L36-63 ==='
$rl = [System.IO.File]::ReadAllLines($remote, [System.Text.Encoding]::UTF8)
for ($i = 35; $i -lt 63 -and $i -lt $rl.Count; $i++) { Write-Output ('  L' + ($i+1) + ': ' + $rl[$i]) }

Write-Output ''
Write-Output '=== 远端如何持有 disposer（搜 live 赋值处） ==='
$n = 0
for ($i = 0; $i -lt $rl.Count; $i++) {
    if ($rl[$i] -match '^\s*live\s*=|live\.disposeRoute\s*=|disposeRoute\s*:' -and $n -lt 12) {
        $s = [Math]::Max(0, $i - 2); $e = [Math]::Min($rl.Count - 1, $i + 4)
        Write-Output ('  --- 附近 L' + ($i+1))
        for ($j = $s; $j -le $e; $j++) { if ($rl[$j].Trim()) { Write-Output ('    L' + ($j+1) + ': ' + $rl[$j].Trim().Substring(0, [Math]::Min(115, $rl[$j].Trim().Length))) } }
        $n++
    }
}", "description": "Compare reactivation comments local vs remote", "timeoutMs": 300000}

