content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$tmp = Join-Path $env:TEMP 'groupchat-remote'
$remote = Join-Path $tmp 'lib__index.js'
$local = Join-Path $env:USERPROFILE '.dsh\profiles\desktop\node_modules\dsh-groupchat\lib\index.js'

Write-Output '=== 1) 两版导出的函数/常量差异（看新增了什么能力） ==='
function Get-Symbols($p) {
    $lines = [System.IO.File]::ReadAllLines($p, [System.Text.Encoding]::UTF8)
    $out = New-Object System.Collections.ArrayList
    foreach ($l in $lines) {
        if ($l -match '^(export )?(async )?function ([A-Za-z_$][\w$]*)') { [void]$out.Add($Matches[3]) }
        elseif ($l -match '^(export )?const ([A-Z][A-Z0-9_]{2,})\s*=') { [void]$out.Add($Matches[2]) }
    }
    return $out
}
$ls = Get-Symbols $local
$rs = Get-Symbols $remote
$added = @($rs | Where-Object { $ls -notcontains $_ })
$removed = @($ls | Where-Object { $rs -notcontains $_ })
Write-Output ('  本地符号 ' + $ls.Count + ' 个，远端 ' + $rs.Count + ' 个')
Write-Output ('  远端新增 (' + $added.Count + '): ' + ($added -join ', '))
Write-Output ('  远端移除 (' + $removed.Count + '): ' + ($removed -join ', '))

Write-Output ''
Write-Output '=== 2) 远端 README 的版本/变更段落 ==='
$js = @'
const https = require('https');
function get(u) { return new Promise((res) => { const r = https.get(u, { headers: { 'User-Agent': 'dsh-research' } }, (x) => { if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(get(new URL(x.headers.location, u).toString())); return; } let d = ''; x.on('data', (c) => d += c); x.on('end', () => res({ code: x.statusCode, body: d })); }); r.on('error', (e) => res({ code: 0, body: '' })); r.setTimeout(25000, () => { r.destroy(); res({ code: 0, body: 'timeout' }); }); }); }
(async () => {
  const r = await get('https://gitee.com/jaxleon/dsh-groupchat/raw/main/README.md');
  if (r.code !== 200) { console.log('  README HTTP ' + r.code); return; }
  const lines = r.body.split('\n');
  console.log('  README 行数: ' + lines.length);
  let n = 0;
  for (let i = 0; i < lines.length && n < 30; i++) {
    if (/0\.6\.[1-9]|变更|更新|修复|changelog|版本历史|##\s*更新/i.test(lines[i])) {
      console.log('    L' + (i + 1) + ': ' + lines[i].slice(0, 140));
      n++;
    }
  }
  if (n === 0) console.log('    （README 未提及版本变更）');
})();
'@
$js | & 'D:\program_runtime_environment\nodejs\node.exe' 2>&1 | ForEach-Object { Write-Output $_ }

Write-Output ''
Write-Output '=== 3) 关键行数差异定位（哪些大段落变长了） ==='
$ll = @([System.IO.File]::ReadAllLines($local, [System.Text.Encoding]::UTF8)).Count
$rl = @([System.IO.File]::ReadAllLines($remote, [System.Text.Encoding]::UTF8)).Count
Write-Output ('  本地 ' + $ll + ' 行 → 远端 ' + $rl + ' 行 (+' + ($rl - $ll) + ')')
$rj = Get-Content -LiteralPath (Join-Path $tmp 'package.json') -Encoding UTF8 -Raw | ConvertFrom-Json
$lj = Get-Content -LiteralPath (Join-Path $env:USERPROFILE '.dsh\profiles\desktop\node_modules\dsh-groupchat\package.json') -Encoding UTF8 -Raw | ConvertFrom-Json
Write-Output ('  本地 files 字段: ' + ($lj.files -join ', '))
Write-Output ('  远端 files 字段: ' + ($rj.files -join ', '))", "description": "Compare exported symbols and README changelog", "timeoutMs": 600000}

