Write-Output '=== 1) 下载仓库（codeload tarball，绕开不可用的 raw.githubusercontent） ==='
$js = @'
const https = require('https');
const fs = require('fs');
const OUT = 'D:\\AI_file\\_downloads\\dsh-qwen-paint-main.tgz';
function get(u, depth) {
  return new Promise((res) => {
    const r = https.get(u, { headers: { 'User-Agent': 'dsh-research' } }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location && depth < 6) {
        x.resume(); res(get(new URL(x.headers.location, u).toString(), depth + 1)); return;
      }
      const chunks = [];
      let total = 0;
      x.on('data', (c) => { chunks.push(c); total += c.length; });
      x.on('end', () => res({ code: x.statusCode, buf: Buffer.concat(chunks), total }));
    });
    r.on('error', (e) => res({ code: 0, buf: Buffer.from(String(e.message)), total: 0 }));
    r.setTimeout(60000, () => { r.destroy(); res({ code: 0, buf: Buffer.from('timeout'), total: 0 }); });
  });
}
(async () => {
  const r = await get('https://codeload.github.com/yanfei0725/dsh-qwen-paint/tar.gz/refs/heads/main', 0);
  console.log('  HTTP ' + r.code + '  bytes ' + r.total);
  if (r.code === 200 && r.total > 10000) {
    fs.writeFileSync(OUT, r.buf);
    console.log('  saved: ' + OUT + '  (' + (r.total / 1048576).toFixed(2) + ' MB)');
  } else {
    console.log('  failed: ' + r.buf.toString('utf8').slice(0, 200));
  }
})();
'@
