Write-Output ''
Write-Output '=== 2) 解压 ==='
if (Test-Path -LiteralPath $tgz) {
    if (Test-Path -LiteralPath $dest) { Remove-Item -LiteralPath $dest -Recurse -Force }
    New-Item -ItemType Directory -Force -Path $dest | Out-Null
    & tar -xzf $tgz -C $dest --strip-components=1 2>&1 | Select-Object -First 5 | ForEach-Object { Write-Output ('  ' + $_) }
    Write-Output ('  解压到: ' + $dest)
    Write-Output '  根目录内容:'
    Get-ChildItem -LiteralPath $dest -Force | Sort-Object { -not $_.PSIsContainer }, Name | ForEach-Object {
        Write-Output ('    ' + $(if ($_.PSIsContainer) { '[dir] ' } else { '      ' }) + $_.Name + $(if (-not $_.PSIsContainer) { '  (' + $_.Length + ' B)' }))
    }
    Write-Output '  scripts\ 内容:'
    Get-ChildItem -LiteralPath (Join-Path $dest 'scripts') -Force -ErrorAction SilentlyContinue | ForEach-Object { Write-Output ('    ' + $_.Name) }
} else { Write-Output '  tarball 未下载成功' }", "description": "Download and extract the qwen-paint plugin repo", "timeoutMs": 900000}

