content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$js = @'
const https = require('https');
function get(u) { return new Promise((res) => { const r = https.get(u, { headers: { 'User-Agent': 'dsh-research' } }, (x) => { if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(get(new URL(x.headers.location, u).toString())); return; } let d = ''; x.on('data', (c) => d += c); x.on('end', () => res({ code: x.statusCode, body: d })); }); r.on('error', (e) => res({ code: 0, body: String(e.message) })); r.setTimeout(25000, () => { r.destroy(); res({ code: 0, body: 'timeout' }); }); }); }
(async () => {
  console.log('=== 1) hf 上所有 Qwen-Image 仓库（找 OpenVINO 转换版） ===');
  for (const q of ['Qwen-Image', 'Qwen-Image-Uncensored']) {
    const r = await get('https://hf-mirror.com/api/models?search=' + encodeURIComponent(q) + '&limit=30&sort=downloads&direction=-1');
    console.log('-- search "' + q + '" HTTP ' + r.code);
    if (r.code === 200) {
      const arr = JSON.parse(r.body);
      for (const m of arr) console.log('   ' + String(m.modelId).padEnd(62) + 'dl=' + String(m.downloads || 0).padStart(9));
    }
  }
  console.log('');
  console.log('=== 2) 官方 OpenVINO 组织下是否有 Qwen 系列 ===');
  for (const q of ['Qwen', 'qwen-image']) {
    const r = await get('https://hf-mirror.com/api/models?author=OpenVINO&search=' + encodeURIComponent(q) + '&limit=20');
    console.log('-- author=OpenVINO search "' + q + '" HTTP ' + r.code);
    if (r.code === 200) {
      const arr = JSON.parse(r.body);
      console.log('   ' + (arr.length ? arr.map((m) => m.modelId).join(', ') : '(无)'));
    }
  }
  console.log('');
  console.log('=== 3) optimum-intel 是否支持 Qwen-Image ===');
  const oi = await get('https://api.github.com/search/code?q=QwenImage+repo:huggingface/optimum-intel');
  console.log('-- code search HTTP ' + oi.code + (oi.code === 403 ? '（需要认证，改用 commits 列表）' : ''));
  const cm = await get('https://api.github.com/repos/huggingface/optimum-intel/commits?per_page=15');
  if (cm.code === 200) {
    const arr = JSON.parse(cm.body);
    for (const c of arr) {
      const msg = String(c.commit.message).split('\n')[0];
      if (/qwen/i.test(msg)) console.log('   ' + c.commit.author.date + '  ' + msg.slice(0, 100));
    }
    console.log('   （上面只列出提及 Qwen 的提交，共查了 ' + arr.length + ' 条）');
  }
})();
'@
$js | & 'D:\program_runtime_environment\nodejs\node.exe' 2>&1 | ForEach-Object { Write-Output $_ }", "description": "Search for Qwen-Image OpenVINO conversions", "timeoutMs": 600000}

