$js = @'
const https = require('https');
const fs = require('fs');
const OUT = 'D:\\AI_file\\_downloads\\sd-vulkan.zip';
const URL0 = 'https://github.com/leejet/stable-diffusion.cpp/releases/download/master-975-95b3090/sd-master-95b3090-bin-win-vulkan-x64.zip';
function get(u, depth, redirects) {
  return new Promise((res) => {
    const r = https.get(u, { headers: { 'User-Agent': 'dsh-research', 'Accept': '*/*' } }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location && depth < 8) {
        x.resume();
        const nx = new URL(x.headers.location, u).toString();
        redirects.push(x.statusCode + ' -> ' + nx.slice(0, 90));
        res(get(nx, depth + 1, redirects));
        return;
      }
      const chunks = [];
      let total = 0;
      x.on('data', (c) => { chunks.push(c); total += c.length; });
      x.on('end', () => res({ code: x.statusCode, buf: Buffer.concat(chunks), total, redirects }));
    });
    r.on('error', (e) => res({ code: 0, buf: Buffer.from(String(e.message)), total: 0, redirects }));
    r.setTimeout(90000, () => { r.destroy(); res({ code: 0, buf: Buffer.from('timeout'), total: 0, redirects }); });
  });
}
(async () => {
  const redirects = [];
  const r = await get(URL0, 0, redirects);
  console.log('  HTTP ' + r.code + '  bytes ' + r.total);
  if (redirects.length) console.log('  redirects: ' + redirects.join(' | '));
  if (r.code === 200 && r.total > 5000000) {
    fs.writeFileSync(OUT, r.buf);
    console.log('  saved: ' + OUT + '  (' + (r.total / 1048576).toFixed(1) + ' MB)');
  } else {
    console.log('  body: ' + r.buf.toString('utf8').slice(0, 300));
  }
})();
