        Write-Output ('    ' + $_.FullName.Substring($toolDir.Length + 1) + $(if (-not $_.PSIsContainer) { '  (' + [Math]::Round($_.Length/1MB,1) + ' MB)' } else { '\' }))
    }
} else { Write-Output '  下载未成功' }", "description": "Download sd.cpp vulkan build and extract", "timeoutMs": 900000}

