{"command": "$ErrorActionPreference = 'Continue'
$toolDir = 'D:\AI_file\tools\stable-diffusion-cpp'
$dl = 'D:\AI_file\_downloads\sd-vulkan.zip'
New-Item -ItemType Directory -Force -Path $toolDir | Out-Null

$js = @'
const https = require('https');
const fs = require('fs');
const OUT = 'D:\\AI_file\\_downloads\\sd-vulkan.zip';
const RAW = 'https://github.com/leejet/stable-diffusion.cpp/releases/download/master-975-95b3090/sd-master-95b3090-bin-win-vulkan-x64.zip';
const MIRRORS = ['https://gh-proxy.com/' + RAW, 'https://ghfast.top/' + RAW];
function get(u, depth) {
  return new Promise((res) => {
    const r = https.get(u, { headers: { 'User-Agent': 'dsh-research' } }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location && depth < 8) {
        x.resume(); res(get(new URL(x.headers.location, u).toString(), depth + 1)); return;
      }
      const chunks = []; let total = 0;
      x.on('data', (c) => { chunks.push(c); total += c.length; });
      x.on('end', () => res({ code: x.statusCode, buf: Buffer.concat(chunks), total }));
    });
    r.on('error', (e) => res({ code: 0, buf: Buffer.from(String(e.message)), total: 0 }));
    r.setTimeout(180000, () => { r.destroy(); res({ code: 0, buf: Buffer.from('timeout'), total: 0 }); });
  });
}
(async () => {
  for (const m of MIRRORS) {
    const host = m.split('/')[2];
    process.stdout.write('  ' + host.padEnd(18) + ' ... ');
    const r = await get(m, 0);
    const isZip = r.buf && r.buf.length > 4 && r.buf[0] === 0x50 && r.buf[1] === 0x4B;
    console.log('HTTP ' + r.code + '  ' + (r.total / 1048576).toFixed(1) + ' MB  zip=' + isZip);
    if (isZip && r.total > 5000000) {
      fs.writeFileSync(OUT, r.buf);
      console.log('  saved: ' + OUT);
      return;
    }
  }
  console.log('  all failed');
})();
'@
$js | & 'D:\program_runtime_environment\nodejs\node.exe' 2>&1 | ForEach-Object { Write-Output $_ }

Write-Output ''
Write-Output '=== 解压 ==='
if (Test-Path -LiteralPath $dl) {
    & tar -xf $dl -C $toolDir 2>&1 | Select-Object -First 3 | ForEach-Object { Write-Output ('  ' + $_) }
    Get-ChildItem -LiteralPath $toolDir -Recurse | Where-Object { -not $_.PSIsContainer } | Select-Object -First 15 | ForEach-Object {
        Write-Output ('    ' + $_.FullName.Substring($toolDir.Length + 1) + '  (' + [Math]::Round($_.Length/1MB,2) + ' MB)')
    }
    $exe = Get-ChildItem -LiteralPath $toolDir -Recurse -Filter 'sd-cli.exe' -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($exe) {
        Write-Output ''
        Write-Output ('=== 验证可执行 + Vulkan 设备识别 (' + $exe.FullName + ') ===')
        Push-Location $exe.DirectoryName
        & $exe.FullName --help 2>&1 | Select-Object -First 18 | ForEach-Object { Write-Output ('  ' + $_) }
        Write-Output ''
        Write-Output '  ---- 设备列表 ----'
        & $exe.FullName --list-devices 2>&1 | Select-Object -First 12 | ForEach-Object { Write-Output ('  ' + $_) }
        Pop-Location
    }
} else { Write-Output '  未下载' }", "description": "Download sd.cpp via working mirror and test Vulkan", "timeoutMs": 900000}

