$js = @'
// download-qwen-image-models.mjs
// Resumable downloader for the uncensored Qwen-Image 2.1 set.
// Why a custom one: huggingface.co is unreachable from this network (ECONNRESET) and
// hf-mirror.com only delivers ~136 KB/s, so a 9.6 GB pull takes many hours and MUST survive
// interruptions. Uses Range requests + .part files + per-file retry.
//
// usage: node download-qwen-image-models.mjs [--only vae|diffusion|encoder]
import https from 'node:https';
import fs from 'node:fs';
import path from 'node:path';

const ROOT = 'D:\\AI_file\\models\\qwen-image-2.1-uncensored';
const LOG = 'D:\\AI_file\\logs\\qwen-image-download.log';
const BASE = 'https://hf-mirror.com';
const FILES = [
  { key: 'vae', repo: 'abenzerps/Qwen-Image-2.1-Uncensored-Quantized', file: 'vae/qwen_image_2.1_vae_bf16.safetensors', out: 'vae/qwen_image_2.1_vae_bf16.safetensors', gb: 0.63 },
  { key: 'diffusion', repo: 'abenzerps/Qwen-Image-2.1-Uncensored-Quantized', file: 'qwen-image-2.1-UC-Q4_K_M.gguf', out: 'diffusion/qwen-image-2.1-UC-Q4_K_M.gguf', gb: 4.29 },
  { key: 'encoder', repo: 'pottokao/Qwen-Image-2.1-Text-Encoder-Heretic-GGUF', file: 'qwen3vl_8b_heretic-Q4_K_M.gguf', out: 'text_encoder/qwen3vl_8b_heretic-Q4_K_M.gguf', gb: 4.68 },
];
const only = process.argv.includes('--only') ? process.argv[process.argv.indexOf('--only') + 1] : null;

fs.mkdirSync(path.dirname(LOG), { recursive: true });
function log(msg) {
  const line = new Date().toISOString() + '  ' + msg;
  console.log(line);
  try { fs.appendFileSync(LOG, line + '\r\n', 'utf8'); } catch (e) {}
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function request(url, headers, ms) {
  return new Promise((res) => {
    const req = https.get(url, { headers: Object.assign({ 'User-Agent': 'dsh-research' }, headers || {}) }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) {
        x.resume();
        res(request(new URL(x.headers.location, url).toString(), headers, ms));
        return;
      }
      res({ stream: x, code: x.statusCode, headers: x.headers });
    });
    req.on('error', (e) => res({ code: 0, err: String(e.code || e.message) }));
    req.setTimeout(ms || 60000, () => { req.destroy(); res({ code: 'timeout' }); });
  });
}

async function sizeOf(url) {
  const r = await request(url, { Range: 'bytes=0-0' }, 60000);
  if (!r.stream) return null;
  r.stream.resume();
  const cr = r.headers['content-range'] || '';
  const m = /\/(\d+)$/.exec(cr);
  if (m) return Number(m[1]);
  const cl = r.headers['content-length'];
  return cl ? Number(cl) : null;
}

async function downloadOne(item) {
  const url = BASE + '/' + item.repo + '/resolve/main/' + item.file;
  const dest = path.join(ROOT, item.out);
  const part = dest + '.part';
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.mkdirSync(path.dirname(LOG), { recursive: true });

  const total = await sizeOf(url);
  log('[' + item.key + '] remote size = ' + (total ? (total / 1073741824).toFixed(2) + ' GB' : 'unknown'));
  if (!total) { log('[' + item.key + '] cannot determine size, skipped'); return false; }

  for (let attempt = 1; attempt <= 6; attempt++) {
    let have = fs.existsSync(part) ? fs.statSync(part).size : 0;
    if (have === total) break;
    if (have > total) { fs.truncateSync(part, 0); have = 0; }
    log('[' + item.key + '] attempt ' + attempt + ' from ' + (have / 1048576).toFixed(1) + ' MB');
    const r = await request(url, { Range: 'bytes=' + have + '-' }, 120000);
    if (!r.stream) { log('[' + item.key + '] request failed: ' + r.code + ' ' + (r.err || '')); await sleep(5000 * attempt); continue; }
    if (r.code !== 206 && r.code !== 200) { r.stream.resume(); log('[' + item.key + '] HTTP ' + r.code); await sleep(5000 * attempt); continue; }

    const ws = fs.createWriteStream(part, { flags: 'a' });
    let got = have;
    let lastLog = Date.now();
    try {
      await new Promise((resolve, reject) => {
        r.stream.on('data', (c) => {
          got += c.length;
          if (Date.now() - lastLog > 30000) {
            lastLog = Date.now();
            const pct = ((got / total) * 100).toFixed(1);
            log('[' + item.key + '] ' + pct + '%  ' + (got / 1048576).toFixed(0) + ' / ' + (total / 1048576).toFixed(0) + ' MB');
          }
        });
        r.stream.on('end', resolve);
        r.stream.on('error', reject);
        r.stream.pipe(ws);
      });
    } catch (e) {
      log('[' + item.key + '] stream error: ' + e.message);
    }
    await new Promise((res) => ws.end(res));
    const now = fs.existsSync(part) ? fs.statSync(part).size : 0;
    log('[' + item.key + '] wrote up to ' + (now / 1048576).toFixed(1) + ' MB');
    if (now >= total) { fs.renameSync(part, dest); log('[' + item.key + '] DONE ' + dest); return true; }
    await sleep(3000 * attempt);
  }
  log('[' + item.key + '] gave up for now; .part kept for the next run');
  return false;
}

(async () => {
  log('=== qwen-image uncensored downloader start (only=' + (only || 'all') + ') ===');
  const list = only ? FILES.filter((f) => f.key === only) : FILES;
  for (const item of list) {
    try { await downloadOne(item); } catch (e) { log('[' + item.key + '] fatal: ' + e.message); }
  }
  log('=== downloader finished ===');
})();
