            log('[' + item.key + '] ' + pct + '%  ' + (got / 1048576).toFixed(0) + ' / ' + (total / 1048576).toFixed(0) + ' MB');
          }
        });
        r.stream.on('end', resolve);
        r.stream.on('error', reject);
        r.stream.pipe(ws);
      });
    } catch (e) {
      log('[' + item.key + '] stream error: ' + e.message);
    }
    await new Promise((res) => ws.end(res));
    const now = fs.existsSync(part) ? fs.statSync(part).size : 0;
    log('[' + item.key + '] wrote up to ' + (now / 1048576).toFixed(1) + ' MB');
    if (now >= total) { fs.renameSync(part, dest); log('[' + item.key + '] DONE ' + dest); return true; }
    await sleep(3000 * attempt);
  }
  log('[' + item.key + '] gave up for now; .part kept for the next run');
  return false;
}

