{"command": "$ErrorActionPreference = 'Continue'
$root = 'E:\deepseek'
$conv = 'conv-20260928-3b54e160'
$bomEnc = [System.Text.UTF8Encoding]::new($true)

Write-Output '=== A) 命名合规检查（ASCII、小写、无空格） ==='
$bad = @()
foreach ($cat in 'deliverables', 'logs', 'scripts', 'workspace', 'archive') {
    Get-ChildItem -LiteralPath (Join-Path $root "$cat\$conv") -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object {
        $n = $_.Name
        if ($n -notmatch '^[A-Za-z0-9][A-Za-z0-9._-]*$' -or $n -cne $n.ToLower()) {
            $bad += ($cat + '\' + $_.FullName.Substring((Join-Path $root "$cat\$conv").Length + 1))
        }
    }
}
if ($bad.Count -eq 0) { Write-Output '  ✓ 全部合规' } else { $bad | ForEach-Object { Write-Output ('  ✗ ' + $_) } }

Write-Output ''
Write-Output '=== B) 编码检查（md/json 应无 BOM；ps1/mjs 规则） ==='
foreach ($f in (Get-ChildItem -LiteralPath (Join-Path $root "deliverables\$conv") -File) + (Get-ChildItem -LiteralPath (Join-Path $root 'policy') -File) + (Get-ChildItem -LiteralPath (Join-Path $root 'tools') -File)) {
    $b = [System.IO.File]::ReadAllBytes($f.FullName)
    $hasBom = ($b.Length -ge 3 -and $b[0] -eq 0xEF -and $b[1] -eq 0xBB -and $b[2] -eq 0xBF)
    $ext = $f.Extension.ToLower()
    $want = if ($ext -in '.ps1') { 'BOM' } elseif ($ext -in '.md', '.json', '.mjs', '.js', '.docx') { 'noBOM' } else { 'skip' }
    if ($want -eq 'skip') { continue }
    $ok = if ($want -eq 'BOM') { $hasBom } else { -not $hasBom }
    Write-Output ('  ' + $(if ($ok) { '✓' } else { '✗' }) + ' ' + $f.Name.PadRight(48) + $(if ($hasBom) { 'BOM' } else { 'noBOM' }) + '  期望 ' + $want)
}

Write-Output ''
Write-Output '=== C) deliverables 里 md 的路径引用有效性 ==='
foreach ($f in Get-ChildItem -LiteralPath (Join-Path $root "deliverables\$conv") -Filter '*.md') {
    $t = [System.IO.File]::ReadAllText($f.FullName, [System.Text.Encoding]::UTF8)
    $refs = [regex]::Matches($t, '(?:E:\\deepseek|E:\\Deepseek|D:\\AI_file)[^\s`"''\)\|,;]*') | ForEach-Object { $_.Value -replace '[\.,;:]$', '' } | Sort-Object -Unique
    $miss = @()
    foreach ($r in $refs) {
        $q = $r -replace '^E:\\[Dd]eepseek', $root
        if (-not (Test-Path -LiteralPath $q)) { $miss += $r }
    }
    Write-Output ('  ' + $f.Name.PadRight(48) + '引用 ' + $refs.Count + ' 个' + $(if ($miss.Count) { '，失效 ' + $miss.Count + ': ' + ($miss -join ' | ') } else { ' ✓' }))
}

Write-Output ''
Write-Output '=== D) DOCX 可读性 ==='
$docx = Join-Path $root "deliverables\$conv\local-ai-toolset-guide-v1.docx"
$py = 'C:\Users\徐丰哲\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe'
& $py -c "from docx import Document; d=Document(r'$docx'); print('  ✓ 可打开: 段落', len(d.paragraphs), '表格', len(d.tables))" 2>&1 | ForEach-Object { Write-Output $_ }

Write-Output ''
Write-Output '=== E) 空文件 / 异常小文件 ==='
Get-ChildItem -LiteralPath (Join-Path $root "$conv") -Recurse -File -ErrorAction SilentlyContinue | Out-Null
foreach ($cat in 'deliverables', 'logs', 'scripts', 'workspace') {
    Get-ChildItem -LiteralPath (Join-Path $root "$cat\$conv") -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.Length -lt 200 } | ForEach-Object {
        Write-Output ('  ⚠ ' + $cat + '\' + $_.Name + '  (' + $_.Length + ' B)')
    }
}
Write-Output '  （以上为小于 200 字节的文件，逐个确认是否为空壳）'", "description": "Comprehensive document check", "timeoutMs": 600000}

