{"command": "$ErrorActionPreference = 'Continue'
$root = 'E:\deepseek'
$conv = 'conv-20260928-3b54e160'
$ws = Join-Path $root "workspace\$conv"
$arc = Join-Path $root "archive\$conv\analysis-artifacts-20261020"

Write-Output '=== 1) DOCX 重测（纯 ASCII 输出） ==='
$py = 'C:\Users\徐丰哲\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe'
$docx = Join-Path $root "deliverables\$conv\local-ai-toolset-guide-v1.docx"
& $py -c "from docx import Document; d=Document(r'$docx'); print('  OK paragraphs=%d tables=%d' % (len(d.paragraphs), len(d.tables)))" 2>&1 | ForEach-Object { Write-Output $_ }
& $py -c "import zipfile; z=zipfile.ZipFile(r'$docx'); print('  zip test:', z.testzip() is None and 'OK' or 'FAIL'); print('  parts:', len(z.namelist()))" 2>&1 | ForEach-Object { Write-Output $_ }

Write-Output ''
Write-Output '=== 2) 归档 workspace 中间产物（同时把大写名转小写） ==='
New-Item -ItemType Directory -Force -Path $arc | Out-Null
$moved = 0
Get-ChildItem -LiteralPath $ws -File -ErrorAction SilentlyContinue | ForEach-Object {
    $newName = $_.Name.ToLower()
    $dest = Join-Path $arc $newName
    if (Test-Path -LiteralPath $dest) { Remove-Item -LiteralPath $dest -Force }
    Move-Item -LiteralPath $_.FullName -Destination $dest -Force
    Write-Output ('  ' + $_.Name + '  ->  analysis-artifacts-20261020\' + $newName)
    $moved++
}
Write-Output ('  共移动 ' + $moved + ' 个')
Write-Output ('  workspace 剩余: ' + @(Get-ChildItem -LiteralPath $ws -File -ErrorAction SilentlyContinue).Count + ' 个文件')

Write-Output ''
Write-Output '=== 3) 复查命名合规（归档后） ==='
$bad = @()
foreach ($cat in 'deliverables', 'logs', 'scripts', 'workspace', 'archive') {
    Get-ChildItem -LiteralPath (Join-Path $root "$cat\$conv") -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object {
        $n = $_.Name
        if ($n -notmatch '^[A-Za-z0-9][A-Za-z0-9._-]*$' -or $n -cne $n.ToLower()) { $bad += ($cat + '\' + $n) }
    }
}
if ($bad.Count -eq 0) { Write-Output '  ALL CLEAN - no non-compliant names' } else { $bad | ForEach-Object { Write-Output ('  BAD: ' + $_) } }

Write-Output ''
Write-Output '=== 4) 归档后各目录规模 ==='
foreach ($cat in 'deliverables', 'logs', 'scripts', 'workspace', 'archive') {
    $d = Join-Path $root "$cat\$conv"
    $f = @(Get-ChildItem -LiteralPath $d -Recurse -File -ErrorAction SilentlyContinue)
    $s = ($f | Measure-Object -Property Length -Sum).Sum
    Write-Output ('  ' + $cat.PadRight(14) + $f.Count.ToString().PadLeft(3) + ' files   ' + [Math]::Round($s/1KB,1).ToString().PadLeft(9) + ' KB')
}", "description": "Archive workspace artifacts and verify", "timeoutMs": 600000}

