{"command": "$ErrorActionPreference = 'Continue'
$dir = 'D:\AI_file\tools'
$js = @'
// download-qwen-image-models-v2.mjs
// Segmented parallel downloader. Benchmark on this network:
//   hf-mirror 1 conn = 208 KB/s, 4 = 279, 8 = 341-348  -> the ceiling is the cross-border link,
//   not the mirror, so the win comes from opening several ranges at once.
// Each file is split into 8 segments, each segment has its own .segN file and its own retry loop,
// so an interruption loses at most one segment's tail. Finished segments are concatenated and removed.
//
// usage: node download-qwen-image-models-v2.mjs [--only vae|diffusion|encoder] [--segs 8]
import https from 'node:https';
import fs from 'node:fs';
import path from 'node:path';

const ROOT = 'D:\\AI_file\\models\\qwen-image-2.1-uncensored';
const LOG = 'D:\\AI_file\\logs\\qwen-image-download.log';
const BASE = 'https://hf-mirror.com';
const FILES = [
  { key: 'vae', repo: 'abenzerps/Qwen-Image-2.1-Uncensored-Quantized', file: 'vae/qwen_image_2.1_vae_bf16.safetensors', out: 'vae/qwen_image_2.1_vae_bf16.safetensors' },
  { key: 'diffusion', repo: 'abenzerps/Qwen-Image-2.1-Uncensored-Quantized', file: 'qwen-image-2.1-UC-Q4_K_M.gguf', out: 'diffusion/qwen-image-2.1-UC-Q4_K_M.gguf' },
  { key: 'encoder', repo: 'pottokao/Qwen-Image-2.1-Text-Encoder-Heretic-GGUF', file: 'qwen3vl_8b_heretic-Q4_K_M.gguf', out: 'text_encoder/qwen3vl_8b_heretic-Q4_K_M.gguf' },
];
const argv = process.argv.slice(2);
const only = argv.includes('--only') ? argv[argv.indexOf('--only') + 1] : null;
const segs = argv.includes('--segs') ? Math.max(1, Math.min(16, Number(argv[argv.indexOf('--segs') + 1]) || 8)) : 8;

fs.mkdirSync(path.dirname(LOG), { recursive: true });
function log(msg) {
  const line = new Date().toISOString() + '  ' + msg;
  console.log(line);
  try { fs.appendFileSync(LOG, line + '\r\n', 'utf8'); } catch (e) {}
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function raw(url, headers, ms, onData) {
  return new Promise((res) => {
    const req = https.get(url, { headers: Object.assign({ 'User-Agent': 'dsh-research' }, headers) }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) {
        x.resume();
        res(raw(new URL(x.headers.location, url).toString(), headers, ms, onData));
        return;
      }
      x.on('data', (c) => { try { onData(c); } catch (e) {} });
      x.on('end', () => res({ code: x.statusCode, ended: true }));
      x.on('close', () => res({ code: x.statusCode, ended: true }));
    });
    req.on('error', (e) => res({ code: 0, err: String(e.code || e.message) }));
    req.setTimeout(ms, () => { req.destroy(); res({ code: 'timeout' }); });
  });
}

async function totalSize(url) {
  let out = null;
  await raw(url, { Range: 'bytes=0-0' }, 60000, () => {});
  const r = await new Promise((res) => {
    const req = https.get(url, { headers: { 'User-Agent': 'dsh-research', Range: 'bytes=0-0' } }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(totalSize(new URL(x.headers.location, url).toString())); return; }
      const cr = x.headers['content-range'] || '';
      const cl = x.headers['content-length'];
      x.resume();
      const m = /\/(\d+)$/.exec(cr);
      res(m ? Number(m[1]) : (cl ? Number(cl) : null));
    });
    req.on('error', () => res(null));
    req.setTimeout(60000, () => { req.destroy(); res(null); });
  });
  return r;
}

async function segDownload(url, start, end, file, label) {
  const want = end - start + 1;
  for (let attempt = 1; attempt <= 8; attempt++) {
    let have = fs.existsSync(file) ? fs.statSync(file).size : 0;
    if (have >= want) return true;
    if (have > want) { fs.truncateSync(file, 0); have = 0; }
    const ws = fs.createWriteStream(file, { flags: 'a' });
    const r = await raw(url, { Range: 'bytes=' + (start + have) + '-' + end }, 90000, (c) => {
      if (fs.existsSync(file) && fs.statSync(file).size < want) ws.write(c);
    });
    await new Promise((res) => ws.end(res));
    const now = fs.existsSync(file) ? fs.statSync(file).size : 0;
    if (now >= want) return true;
    log('  ' + label + ' attempt ' + attempt + ' -> ' + (now / 1048576).toFixed(1) + '/' + (want / 1048576).toFixed(1) + ' MB (' + (r.code || r.err || '?') + ')');
    await sleep(2000 * attempt);
  }
  return false;
}

async function downloadOne(item) {
  const url = BASE + '/' + item.repo + '/resolve/main/' + item.file;
  const dest = path.join(ROOT, item.out);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  const total = await totalSize(url);
  log('[' + item.key + '] size=' + (total ? (total / 1073741823).toFixed(2) + ' GB' : 'unknown') + ' segs=' + segs);
  if (!total) { log('[' + item.key + '] size unknown, skipped'); return false; }

  const segLen = Math.ceil(total / segs);
  const jobs = [];
  for (let i = 0; i < segs; i++) {
    const start = i * segLen;
    const end = Math.min(total - 1, start + segLen - 1);
    if (start > end) continue;
    jobs.push({ i, start, end, file: dest + '.seg' + i });
  }
  log('[' + item.key + '] downloading ' + jobs.length + ' segments in parallel ...');
  const t0 = Date.now();
  const results = await Promise.all(jobs.map((j) => segDownload(url, j.start, j.end, j.file, item.key + '/seg' + j.i)));
  const okCount = results.filter(Boolean).length;
  const mbps = ((total / 1048576) / ((Date.now() - t0) / 1000)).toFixed(0);
  log('[' + item.key + '] segments done ' + okCount + '/' + jobs.length + '  avg ' + mbps + ' KB/s');
  if (okCount !== jobs.length) { log('[' + item.key + '] incomplete; segments kept for resume'); return false; }

  const ws = fs.createWriteStream(dest);
  for (const j of jobs) {
    await new Promise((resolve, reject) => {
      const rs = fs.createReadStream(j.file);
      rs.on('end', resolve);
      rs.on('error', reject);
      rs.pipe(ws, { end: false });
    });
  }
  await new Promise((res) => ws.end(res));
  for (const j of jobs) { try { fs.unlinkSync(j.file); } catch (e) {} }
  const finalSize = fs.statSync(dest).size;
  log('[' + item.key + '] DONE ' + dest + '  ' + (finalSize / 1073741823).toFixed(2) + ' GB  expected ' + (total / 1073741823).toFixed(2) + ' GB  match=' + (finalSize === total));
  return finalSize === total;
}

(async () => {
  log('=== v2 segmented downloader start (only=' + (only || 'all') + ', segs=' + segs + ') ===');
  const list = only ? FILES.filter((f) => f.key === only) : FILES;
  for (const item of list) {
    try { await downloadOne(item); } catch (e) { log('[' + item.key + '] fatal: ' + e.message); }
  }
  log('=== v2 finished ===');
})();
