# 根因：close 与 end 都会 resolve；close 先到 -> Promise 提前结束 -> ws.end() 截断写入。
$old = @'
function raw(url, headers, ms, onData) {
  return new Promise((res) => {
    const req = https.get(url, { headers: Object.assign({ 'User-Agent': 'dsh-research' }, headers) }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) {
        x.resume();
        res(raw(new URL(x.headers.location, url).toString(), headers, ms, onData));
        return;
      }
      x.on('data', (c) => { try { onData(c); } catch (e) {} });
      x.on('end', () => res({ code: x.statusCode, ended: true }));
      x.on('close', () => res({ code: x.statusCode, ended: true }));
    });
    req.on('error', (e) => res({ code: 0, err: String(e.code || e.message) }));
    req.setTimeout(ms, () => { req.destroy(); res({ code: 'timeout' }); });
  });
}
'@
$new = @'
function raw(url, headers, ms, onData) {
  return new Promise((res) => {
    let settled = false;
    const done = (v) => { if (!settled) { settled = true; res(v); } };
    const req = https.get(url, { headers: Object.assign({ 'User-Agent': 'dsh-research' }, headers) }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) {
        x.resume();
        done(raw(new URL(x.headers.location, url).toString(), headers, ms, onData));
        return;
      }
      // 关键：只在 end / error / aborted 时收尾，绝不在 close 时收尾。
      // 否则 close 先到会让 Promise 提前 resolve，调用方随即 ws.end()，把后续数据全部截断。
      x.on('data', (c) => { try { onData(c); } catch (e) { log('onData error: ' + e.message); } });
      x.on('end', () => done({ code: x.statusCode, ended: true }));
      x.on('error', (e) => done({ code: x.statusCode, err: String(e.message) }));
      x.on('aborted', () => done({ code: x.statusCode, err: 'aborted' }));
    });
    req.on('error', (e) => done({ code: 0, err: String(e.code || e.message) }));
    req.setTimeout(ms, () => { req.destroy(); done({ code: 'timeout' }); });
  });
}
