$js = @'
const fs = require('fs');
const path = require('path');
const BASE = 'D:\\AI_file\\models\\qwen-image-2.1-uncensored';
function total() {
  let s = 0;
  const walk = (d) => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) walk(p);
      else s += fs.statSync(p).size;
    }
  };
  walk(BASE);
  return s;
}
function files() {
  const out = [];
  const walk = (d) => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) walk(p);
      else out.push({ p: path.relative(BASE, p), size: fs.statSync(p).size });
    }
  };
  walk(BASE);
  return out;
}
const a = total();
console.log('  t0 total: ' + (a / 1048576).toFixed(1) + ' MB');
setTimeout(() => {
  const b = total();
  const kbs = (b - a) / 1024 / 60;
  console.log('  t+60s total: ' + (b / 1048576).toFixed(1) + ' MB');
  console.log('  speed: ' + kbs.toFixed(0) + ' KB/s  (' + (kbs / 1024).toFixed(2) + ' MB/s)');
  const remainGb = 9.6 - b / 1073741824;
  console.log('  remaining: ' + remainGb.toFixed(2) + ' GB');
  if (kbs > 0) console.log('  ETA: ' + (remainGb * 1024 * 1024 / kbs / 60).toFixed(0) + ' minutes');
  console.log('');
  for (const f of files().sort((x, y) => y.size - x.size)) {
    console.log('    ' + f.p.padEnd(52) + (f.size / 1048576).toFixed(1).padStart(8) + ' MB');
  }
}, 60000);
