content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$root = 'E:\deepseek'
$conv = 'conv-20260928-3b54e160'
$bom = New-Object System.Text.UTF8Encoding($true)

Write-Output '=== 1) 更新 D:\AI_file\registry.json ==='
$js = @'
const fs = require('fs');
const P = 'D:\\AI_file\\registry.json';
let reg = {};
try { reg = JSON.parse(fs.readFileSync(P, 'utf8')); } catch (e) { console.log('  cannot parse: ' + e.message); process.exit(0); }
console.log('  top-level keys: ' + Object.keys(reg).join(', '));
// 找到放模型与工具的容器（结构未知，按常见命名探测）
const toolsKey = Object.keys(reg).find((k) => /^tools$/i.test(k));
const modelsKey = Object.keys(reg).find((k) => /^models$/i.test(k));
console.log('  tools key: ' + toolsKey + '  models key: ' + modelsKey);
if (modelsKey) {
  reg[modelsKey] = reg[modelsKey] || [];
  if (Array.isArray(reg[modelsKey])) {
    const exists = reg[modelsKey].some((m) => JSON.stringify(m).includes('qwen-image-2.1-uncensored'));
    if (!exists) {
      reg[modelsKey].push({
        name: 'qwen-image-2.1-uncensored',
        family: 'Qwen-Image 2.1 (uncensored)',
        path: 'D:\\AI_file\\models\\qwen-image-2.1-uncensored',
        components: {
          diffusion: 'diffusion/qwen-image-2.1-UC-Q4_K_M.gguf (4.29 GB, Q4_K_M)',
          text_encoder: 'text_encoder/qwen3vl_8b_heretic-Q4_K_M.gguf (4.68 GB, Heretic uncensored)',
          vae: 'vae/qwen_image_2.1_vae_bf16.safetensors (0.63 GB)'
        },
        runtime: 'stable-diffusion.cpp sd-cli.exe (Vulkan backend)',
        license: 'Qwen Research License - research/evaluation only, no commercial use',
        note: 'uncensored variant; no vision weights so text-to-image only',
        measured: '512x512 20 steps = 84 s on Intel Arc B370 iGPU; 9.3 GB in RAM with --offload-to-cpu',
        addedAt: new Date().toISOString().slice(0, 10)
      });
      console.log('  added model entry');
    } else console.log('  model entry already present');
  }
}
if (toolsKey && Array.isArray(reg[toolsKey])) {
  const exists = reg[toolsKey].some((t) => JSON.stringify(t).includes('stable-diffusion-cpp'));
  if (!exists) {
    reg[toolsKey].push({
      name: 'stable-diffusion-cpp',
      version: 'master-975-95b3090',
      path: 'D:\\AI_file\\tools\\stable-diffusion-cpp',
      binary: 'sd-cli.exe',
      backend: 'Vulkan (also ships CPU backends)',
      license: 'MIT',
      source: 'leejet/stable-diffusion.cpp releases',
      addedAt: new Date().toISOString().slice(0, 10)
    });
    console.log('  added tool entry');
  } else console.log('  tool entry already present');
}
fs.writeFileSync(P, JSON.stringify(reg, null, 2) + '\n', 'utf8');
console.log('  written back');
'@
$js | & 'D:\program_runtime_environment\nodejs\node.exe' 2>&1 | ForEach-Object { Write-Output $_ }

Write-Output ''
Write-Output '=== 2) 存放准则自检 ==='
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'tools\Test-StoragePolicy.ps1') 2>&1 | Select-String -Pattern 'FAIL|Summary' | ForEach-Object { Write-Output ('  ' + $_.Line) }

Write-Output ''
Write-Output '=== 3) 更新归档索引 ==='
$idxPath = Join-Path $root "archive\$conv\archive-index.md"
$t = [System.IO.File]::ReadAllText($idxPath, [System.Text.Encoding]::UTF8)
$add = @'

## qwen-image-verification/（2026-10-21 追加）

| 文件 | 内容 |
|---|---|
| `qwen-uncensored-512-s4.png` | Qwen-Image 2.1 无审查版，512×512、**4 步**的产物。模糊噪点、无结构，用于证明**步数下限真实存在** |
| `qwen-uncensored-512-s20.png` | 同模型 **20 步**的产物："猫举木牌，牌上写 hello"，文字清晰、构图正常，**首图验证通过** |

安装与使用详见 `deliverables\conv-20260928-3b54e160\local-uncensored-imagegen-install-v1.md`。
'@
if ($t -notmatch 'qwen-image-verification') {
    [System.IO.File]::WriteAllText($idxPath, ($t.TrimEnd() + $add + "`r`n"), (New-Object System.Text.UTF8Encoding($false)))
    Write-Output '  [OK] 归档索引已追加 qwen-image-verification 一节'
} else { Write-Output '  [SKIP] 已存在' }

Write-Output ''
Write-Output '=== 4) 最终目录状态 ==='
foreach ($cat in 'deliverables', 'logs', 'scripts', 'workspace', 'archive') {
    $d = Join-Path $root "$cat\$conv"
    $f = @(Get-ChildItem -LiteralPath $d -Recurse -File -ErrorAction SilentlyContinue)
    Write-Output ('  ' + $cat.PadRight(14) + $f.Count.ToString().PadLeft(3) + ' files')
}
Write-Output ''
Write-Output '  deliverables:'
Get-ChildItem -LiteralPath (Join-Path $root "deliverables\$conv") -File | Sort-Object Name | ForEach-Object { Write-Output ('    ' + $_.Name) }", "description": "Update registry, selftest, archive index", "timeoutMs": 600000}

