{"command": "$ErrorActionPreference = 'Continue'
Write-Output '=== 1) 关机重启后环境是否健在 ==='
foreach ($p in 'D:\AI_file\tools\stable-diffusion-cpp\sd-cli.exe', 'D:\AI_file\models\qwen-image-2.1-uncensored\diffusion\qwen-image-2.1-UC-Q4_K_M.gguf', 'D:\AI_file\models\qwen-image-2.1-uncensored\text_encoder\qwen3vl_8b_heretic-Q4_K_M.gguf', 'D:\AI_file\models\qwen-image-2.1-uncensored\vae\qwen_image_2.1_vae_bf16.safetensors') {
    Write-Output ('  [' + $(if (Test-Path -LiteralPath $p) { '有' } else { '无' }) + '] ' + $p)
}

Write-Output ''
Write-Output '=== 2) sd-cli 是否支持 server/API 模式（决定要不要每次加载 9.3 GB） ==='
$exe = 'D:\AI_file\tools\stable-diffusion-cpp\sd-cli.exe'
Push-Location (Split-Path $exe)
& $exe --help 2>&1 | Select-String -Pattern 'server|listen|port|api|http|daemon|watch|interactive' | ForEach-Object { Write-Output ('  ' + $_.Line.Trim()) }
Write-Output '  --- 若有 server 子命令/SDK，模型可常驻 ---'
& $exe --help 2>&1 | Select-Object -First 3 | ForEach-Object { Write-Output ('  ' + $_) }
Pop-Location

Write-Output ''
Write-Output '=== 3) 现有 vision-server.py 的工具注册方式 ==='
$vs = 'D:\AI_file\mcp\vision-server.py'
if (Test-Path -LiteralPath $vs) {
    Write-Output ('  文件: ' + [Math]::Round((Get-Item $vs).Length/1KB,1) + ' KB')
    Select-String -LiteralPath $vs -Pattern '^\s*(@|def |TOOLS|async def |server\.|mcp\.)' | Select-Object -First 24 | ForEach-Object {
        Write-Output ('  L' + $_.LineNumber + ': ' + $_.Line.Trim().Substring(0, [Math]::Min(100, $_.Line.Trim().Length)))
    }
}

Write-Output ''
Write-Output '=== 4) MCP 配置与超时 ==='
$patch = Join-Path $env:USERPROFILE '.dsh\profiles\desktop\cordis.patch.yml'
if (Test-Path -LiteralPath $patch) {
    Select-String -LiteralPath $patch -Pattern 'mcp-vision|toolCallTimeoutMs|command|args|serverName' | ForEach-Object { Write-Output ('  L' + $_.LineNumber + ': ' + $_.Line.Trim()) }
}", "description": "Survey feasibility of toolifying Qwen-Image generation", "timeoutMs": 300000}

