{"command": "$ErrorActionPreference = 'Continue'
$root = 'E:\deepseek'
Write-Output '=== 搜索工具数量与生成工具的引用点 ==='
foreach ($f in 'AGENTS.md', 'README.md', 'policy\ai-tool-policy.md', 'policy\ai-tools.json', 'policy\output-storage-policy.md', 'policy\deploy\global-agents.md') {
    $p = Join-Path $root $f
    if (-not (Test-Path -LiteralPath $p)) { continue }
