$noBom = New-Object System.Text.UTF8Encoding($false)

Write-Output '=== 1) global-agents.md 实际相关行 ==='
$p = Join-Path $root 'policy\deploy\global-agents.md'
Select-String -LiteralPath $p -Pattern '生成图片|image_generate' | ForEach-Object { Write-Output ('  L' + $_.LineNumber + ': [' + $_.Line + ']') }

Write-Output ''
Write-Output '=== 2) 用正则在其后插入新工具行 ==='
$t = [System.IO.File]::ReadAllText($p, [System.Text.Encoding]::UTF8)
if ($t -notmatch 'image_generate_uncensored') {
    $nl = "`r`n"
    $addition = '- **生成无审查图片** → `image_generate_uncensored`（**Qwen-Image 2.1 无审查权重** + stable-diffusion.cpp，iGPU Vulkan；512²/20 步约 85 s，1024² 约 5–6 分钟；**步数 ≥20**、宽高为 32 的倍数且 ≤1024；**许可 Qwen Research License：仅研究/评估，禁止商用**）。**仅在用户明确要求无审查或换模型时使用**，默认仍走 FLUX'
    $pattern = '(?m)^(- \*\*生成图片\*\* → `image_generate`[^\r\n]*)$'
    if ($t -match $pattern) {
        $t = [regex]::Replace($t, $pattern, ('$1' + $nl + $addition), 1)
        [System.IO.File]::WriteAllText($p, $t, $bom)
        Write-Output '  [OK] 已插入（正则定位）'
    } else {
        Write-Output '  [FAIL] 正则仍未命中，需手工处理'
    }
} else { Write-Output '  [SKIP] 已存在' }
Select-String -LiteralPath $p -Pattern 'image_generate_uncensored' | ForEach-Object { Write-Output ('    L' + $_.LineNumber + ': ' + $_.Line.Trim().Substring(0, [Math]::Min(100, $_.Line.Trim().Length))) }

Write-Output ''
Write-Output '=== 3) 更新 ai-tools.json（工具条目 + 路由 + 生图预算） ==='
$jp = Join-Path $root 'policy\ai-tools.json'
$j = [System.IO.File]::ReadAllText($jp, [System.Text.Encoding]::UTF8) | ConvertFrom-Json
$names = @($j.tools | ForEach-Object { $_.name })
if ($names -notcontains 'image_generate_uncensored') {
    $newTool = [pscustomobject]@{
        name = 'image_generate_uncensored'
        backend = 'Qwen-Image 2.1 uncensored (Q4_K_M GGUF) via stable-diffusion.cpp, Vulkan backend'
        device = 'iGPU'
        latencyMs = @{ warm = 84000; note = '512x512 at 20 steps; 1024x1024 is about 5-6 minutes' }
        useFor = '无内容审查的文生图；仅在用户明确要求无审查或换模型时使用'
        limits = @{
            minSteps = 20
            dimensionMultiple = 32
            maxDimension = 1024
            license = 'Qwen Research License - research/evaluation only, NO commercial use'
            reloadPerCall = 'engine has no daemon mode; each call re-reads 9.3 GB of weights (about 4 s warm, about 1 min cold)'
        }
        prefer = 'image_generate (14-18x faster, Apache-2.0) for anything publishable or commercial'
    }
    $j.tools = @($j.tools) + $newTool
    Write-Output '  [OK] 已加工具条目'
} else { Write-Output '  [SKIP] 工具条目已存在' }

$routing = [string]$j.routing
if ($routing -notmatch 'image_generate_uncensored') {
    if ($routing -match '9\)[^\r\n]*image_generate') {
        $j.routing = $routing + "`n10) need uncensored output -> image_generate_uncensored (85 s - 6 min; only when explicitly asked)"
        Write-Output '  [OK] 已加路由条目'
    } else {
        $j.routing = $routing + "`n10) need uncensored output -> image_generate_uncensored (85 s - 6 min; only when explicitly asked)"
        Write-Output '  [OK] 已追加路由条目'
    }
} else { Write-Output '  [SKIP] 路由已存在' }

if ($j.imageGenerationBudget) {
    $budget = $j.imageGenerationBudget
    if (($budget.PSObject.Properties.Name) -notcontains 'appliesToUncensored') {
        $budget | Add-Member -NotePropertyName appliesToUncensored -NotePropertyValue 'same one-image default and 4-image ceiling, but each image takes 85 s - 6 min, so be stricter' -Force
        Write-Output '  [OK] 生图预算已加 uncensored 说明'
    }
}

$j.updatedAt = (Get-Date).ToString('yyyy-MM-dd')
if ($j.policyVersion) { $j.policyVersion = '1.10.0' }
[System.IO.File]::WriteAllText($jp, ($j | ConvertTo-Json -Depth 20), $noBom)
Write-Output ('  [OK] ai-tools.json 已写回（tools=' + @($j.tools).Count + ', version=' + $j.policyVersion + '）')

Write-Output ''
Write-Output '=== 4) 校验 ==='
$j2 = [System.IO.File]::ReadAllText($jp, [System.Text.Encoding]::UTF8) | ConvertFrom-Json
Write-Output ('  tools 数量: ' + @($j2.tools).Count)
Write-Output ('  含新工具: ' + (@($j2.tools | ForEach-Object { $_.name }) -contains 'image_generate_uncensored'))
Write-Output ('  路由含新工具: ' + ([string]$j2.routing -match 'image_generate_uncensored'))", "description": "Fix global agents and update ai-tools.json", "timeoutMs": 300000}

