content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$root = 'E:\deepseek'
$p = Join-Path $root 'policy\deploy\global-agents.md'
$bom = New-Object System.Text.UTF8Encoding($true)

$lines = [System.IO.File]::ReadAllLines($p, [System.Text.Encoding]::UTF8)
Write-Output ('  原始行数: ' + $lines.Count)

$addition = '- **生成无审查图片** → `image_generate_uncensored`（**Qwen-Image 2.1 无审查权重** + stable-diffusion.cpp，iGPU Vulkan；512²/20 步约 85 s，1024² 约 5–6 分钟；**步数 ≥20**、宽高为 32 的倍数且 ≤1024；**许可 Qwen Research License：仅研究/评估，禁止商用**）。**仅在用户明确要求无审查或换模型时使用**，默认仍走 FLUX'

$inserted = $false
$out = New-Object System.Collections.Generic.List[string]
foreach ($line in $lines) {
    $out.Add($line)
    if (-not $inserted -and $line -like '*生成图片*' -and $line -like '*image_generate*' -and $line -notlike '*uncensored*') {
        $out.Add($addition)
        $inserted = $true
    }
}
if ($inserted) {
    [System.IO.File]::WriteAllLines($p, $out.ToArray(), $bom)
    Write-Output ('  [OK] 已插入，新行数: ' + $out.Count)
} else {
    Write-Output '  [FAIL] 未找到插入点'
}

Write-Output ''
Write-Output '  插入点上下文:'
$nl = [System.IO.File]::ReadAllLines($p, [System.Text.Encoding]::UTF8)
for ($i = 0; $i -lt $nl.Count; $i++) {
    if ($nl[$i] -like '*生成图片*') {
        $s = [Math]::Max(0, $i - 1); $e = [Math]::Min($nl.Count - 1, $i + 2)
        for ($j = $s; $j -le $e; $j++) { Write-Output ('    L' + ($j+1) + ': ' + $nl[$j].Substring(0, [Math]::Min(110, $nl[$j].Length))) }
    }
}

Write-Output ''
Write-Output '=== 部署全局副本（规则 6） ==='
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'tools\Install-GlobalPolicy.ps1') 2>&1 | ForEach-Object { Write-Output ('  ' + $_) }

Write-Output ''
Write-Output '=== 一致性校验 ==='
$s = [System.IO.File]::ReadAllText($p, [System.Text.Encoding]::UTF8)
$d = [System.IO.File]::ReadAllText((Join-Path $env:USERPROFILE '.dsh\AGENTS.md'), [System.Text.Encoding]::UTF8)
Write-Output ('  来源与全局副本一致: ' + ($s -eq $d))
Write-Output ('  全局副本含新工具: ' + ($d -match 'image_generate_uncensored'))", "description": "Insert tool line into global agents by line matching", "timeoutMs": 300000}

