content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$root = 'E:\deepseek'
$base = Join-Path $env:USERPROFILE 'Documents\Deepseek-rules-backup'

Write-Output '=== 1) 备份目录清单（最近 3 份） ==='
Get-ChildItem -LiteralPath $base -Directory | Sort-Object Name -Descending | Select-Object -First 3 | ForEach-Object {
    $files = @(Get-ChildItem -LiteralPath $_.FullName -Recurse -File)
    Write-Output ('  ' + $_.Name + '  ' + $files.Count + ' 文件  ' + $_.LastWriteTime)
}

$latest = (Get-ChildItem -LiteralPath $base -Directory | Sort-Object Name -Descending | Select-Object -First 1).FullName
Write-Output ''
Write-Output ('=== 2) 最新备份内容: ' + (Split-Path $latest -Leaf) + ' ===')
Get-ChildItem -LiteralPath $latest -Recurse -File | Sort-Object FullName | ForEach-Object {
    Write-Output ('  ' + $_.FullName.Substring($latest.Length + 1).PadRight(48) + [Math]::Round($_.Length/1KB,1).ToString().PadLeft(8) + ' KB')
