content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$root = 'E:\deepseek\policy'
foreach ($f in 'lceda-eda-policy.md', 'lceda-eda.json') {
    $p = Join-Path $root $f
    if (Test-Path -LiteralPath $p) {
        $it = Get-Item -LiteralPath $p
        $lines = @([System.IO.File]::ReadAllLines($p, [System.Text.Encoding]::UTF8)).Count
        Write-Output ('  [有] ' + $f.PadRight(26) + [Math]::Round($it.Length/1KB,1).ToString().PadLeft(8) + ' KB  ' + $lines + ' 行  ' + $it.LastWriteTime)
    } else {
        Write-Output ('  [无] ' + $f)
    }
}
Write-Output ''
Write-Output '=== policy 目录现有文件 ==='
Get-ChildItem -LiteralPath $root -File | Sort-Object Name | ForEach-Object {
    Write-Output ('  ' + $_.Name.PadRight(30) + [Math]::Round($_.Length/1KB,1).ToString().PadLeft(8) + ' KB')
}
Write-Output ''
Write-Output '=== JSON 可解析性 ==='
$jp = Join-Path $root 'lceda-eda.json'
if (Test-Path -LiteralPath $jp) {
    try {
        $j = [System.IO.File]::ReadAllText($jp, [System.Text.Encoding]::UTF8) | ConvertFrom-Json
        Write-Output '  [OK] JSON 解析成功'
        Write-Output ('  顶层键: ' + (($j.PSObject.Properties | ForEach-Object { $_.Name }) -join ', '))
    } catch {
        Write-Output ('  [FAIL] ' + $_.Exception.Message)
    }
}", "description": "Check LCEDA policy files existence and parseability", "timeoutMs": 180000}

