content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$exe = 'D:\Application\lceda-pro\lceda-pro.exe'

Write-Output '=== doctor 完整重试（已清除 ELECTRON_RUN_AS_NODE） ==='
$old = $env:ELECTRON_RUN_AS_NODE
Remove-Item Env:\ELECTRON_RUN_AS_NODE -Force -ErrorAction SilentlyContinue
Write-Output ('  清除前: [' + $old + ']  清除后: [' + $env:ELECTRON_RUN_AS_NODE + ']')
Write-Output ''
$job = Start-Job -ScriptBlock {
    param($e)
    Remove-Item Env:\ELECTRON_RUN_AS_NODE -Force -ErrorAction SilentlyContinue
    $o = & $e doctor 2>&1
    [pscustomobject]@{ Out = ($o | Out-String); Code = $LASTEXITCODE }
} -ArgumentList $exe
$done = Wait-Job $job -Timeout 90
if ($done) {
    $r = Receive-Job $job
    Write-Output ('  退出码: ' + $r.Code)
    Write-Output '  输出:'
    ($r.Out -split "`r?`n") | Where-Object { $_ -ne '' } | Select-Object -First 8 | ForEach-Object { Write-Output ('    ' + $_) }
} else {
    Write-Output '  [超时] doctor 90 秒未返回'
    Stop-Job $job -ErrorAction SilentlyContinue
}
Remove-Job $job -Force -ErrorAction SilentlyContinue

Write-Output ''
Write-Output '=== 对照：不清除变量时的表现（验证规则第 2 节的说法） ==='
$env:ELECTRON_RUN_AS_NODE = '1'
$job2 = Start-Job -ScriptBlock {
    param($e)
    $env:ELECTRON_RUN_AS_NODE = '1'
    $o = & $e doctor 2>&1
    [pscustomobject]@{ Out = ($o | Out-String); Code = $LASTEXITCODE }
} -ArgumentList $exe
$done2 = Wait-Job $job2 -Timeout 60
if ($done2) {
    $r2 = Receive-Job $job2
    Write-Output ('  退出码: ' + $r2.Code)
    ($r2.Out -split "`r?`n") | Where-Object { $_ -ne '' } | Select-Object -First 6 | ForEach-Object { Write-Output ('    ' + $_) }
} else {
    Write-Output '  [超时]'
    Stop-Job $job2 -ErrorAction SilentlyContinue
}
Remove-Job $job2 -Force -ErrorAction SilentlyContinue
Remove-Item Env:\ELECTRON_RUN_AS_NODE -Force -ErrorAction SilentlyContinue

Write-Output ''
Write-Output '=== 既有测试工程（规则第 10 节要求用测试工程） ==='
$proj = Join-Path $env:USERPROFILE 'Documents\LCEDA-Pro\projects'
Get-ChildItem -LiteralPath $proj -Force -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | ForEach-Object {
    Write-Output ('  ' + $(if ($_.PSIsContainer) { '[dir] ' } else { '      ' }) + $_.Name.PadRight(38) + $_.LastWriteTime)
}", "description": "Retry doctor with and without env var", "timeoutMs": 300000}

