content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$js = @'
const https = require('https');
function get(u) {
  return new Promise((res) => {
    const r = https.get(u, { headers: { 'User-Agent': 'dsh-research', 'Accept': 'application/vnd.github+json' } }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(get(new URL(x.headers.location, u).toString())); return; }
      let d = ''; x.on('data', (c) => d += c); x.on('end', () => res({ code: x.statusCode, body: d }));
    });
    r.on('error', (e) => res({ code: 0, body: String(e.message) }));
    r.setTimeout(30000, () => { r.destroy(); res({ code: 0, body: 'timeout' }); });
  });
}
(async () => {
  console.log('=== 1) openvino_notebooks 里是否有 qwen3-tts ===');
  const r = await get('https://api.github.com/repos/openvinotoolkit/openvino_notebooks/contents/notebooks');
  console.log('  HTTP ' + r.code);
  if (r.code === 200) {
    const arr = JSON.parse(r.body).filter((e) => e.type === 'dir');
    console.log('  子目录总数: ' + arr.length);
    const hits = arr.filter((e) => /qwen|tts|speech|audio|voice/i.test(e.name));
    console.log('  含 qwen/tts/speech/audio/voice 的目录:');
    for (const h of hits) console.log('    ' + h.name);
    if (hits.length === 0) console.log('    (none)');
  } else {
    console.log('  ' + r.body.slice(0, 200));
  }

  console.log('');
  console.log('=== 2) 专门找 qwen3-tts 路径 ===');
  for (const p of ['notebooks/qwen3-tts', 'notebooks/qwen3_tts', 'notebooks/qwen-tts', 'notebooks/qwen3-tts-speech']) {
    const c = await get('https://api.github.com/repos/openvinotoolkit/openvino_notebooks/contents/' + p);
    console.log('  ' + p.padEnd(34) + 'HTTP ' + c.code);
  }

  console.log('');
  console.log('=== 3) HF 上 Qwen3-TTS 是否存在 ===');
  for (const q of ['Qwen3-TTS', 'Qwen3-TTS-GGUF', 'Qwen-TTS']) {
    const m = await get('https://hf-mirror.com/api/models?search=' + encodeURIComponent(q) + '&limit=10&sort=downloads&direction=-1');
    console.log('-- search "' + q + '" HTTP ' + m.code);
    if (m.code === 200) {
      const arr = JSON.parse(m.body);
      if (!arr.length) console.log('     (no result)');
      for (const x of arr.slice(0, 8)) console.log('     ' + String(x.modelId).padEnd(58) + 'dl=' + (x.downloads || 0));
    }
  }
})();
'@
$js | & 'D:\program_runtime_environment\nodejs\node.exe' 2>&1 | ForEach-Object { Write-Output $_ }

Write-Output ''
Write-Output '=== 4) 本机 openvino_genai 是否具备 TTS 能力 ==='
$py = @'
import openvino_genai as ovg
names = [n for n in dir(ovg) if any(k in n.lower() for k in ('speech', 'tts', 'audio', 'voice', 'vocoder'))]
print('  openvino_genai:', getattr(ovg, '__version__', '?'))
print('  TTS-related classes:', names or '(none)')
print('  Text2SpeechPipeline present:', hasattr(ovg, 'Text2SpeechPipeline'))
if hasattr(ovg, 'Text2SpeechPipeline'):
    f = [m for m in dir(ovg.Text2SpeechPipeline) if not m.startswith('_')]
    print('  factories:', f)
'@
$tmp = Join-Path $env:TEMP 'check-tts.py'
[System.IO.File]::WriteAllText($tmp, $py, (New-Object System.Text.UTF8Encoding($false)))
& 'D:\AI_file\envs\openvino\Scripts\python.exe' $tmp 2>&1 | ForEach-Object { Write-Output $_ }", "description": "Verify Qwen3-TTS notebook and model existence", "timeoutMs": 600000}

