  const r = await get('https://api.github.com/repos/wangtong10086/qwen3-tts-openvino');
  console.log('  HTTP ' + r.code);
  if (r.code === 200) {
    const j = JSON.parse(r.body);
    console.log('  full_name   : ' + j.full_name);
    console.log('  description : ' + (j.description || '(none)'));
