    console.log('  size KB     : ' + j.size);
    console.log('');
    console.log('  --- releases ---');
    const rel = await get('https://api.github.com/repos/wangtong10086/qwen3-tts-openvino/releases?per_page=5');
    console.log('  HTTP ' + rel.code);
