      }
      if (!arr.length) console.log('   (no releases)');
    }
  }

  console.log('');
  console.log('=== A-1: official notebook README (qwen3-tts) ===');
  const nb = await get('https://api.github.com/repos/openvinotoolkit/openvino_notebooks/contents/notebooks/qwen3-tts');
  if (nb.code === 200) {
    const files = JSON.parse(nb.body);
    console.log('  files:');
    for (const f of files) console.log('    ' + f.name + '  (' + (f.size || 0) + ' B)');
    const rd = files.find((f) => /readme/i.test(f.name));
    if (rd) {
      const c = await get('https://api.github.com/repos/openvinotoolkit/openvino_notebooks/contents/notebooks/qwen3-tts/' + rd.name);
      if (c.code === 200) {
        const txt = Buffer.from(JSON.parse(c.body).content, 'base64').toString('utf8');
        console.log('  README (first 60 lines):');
        for (const line of txt.split('\n').slice(0, 60)) console.log('   ' + line.slice(0, 150));
      }
    }
  }
})();
