const https = require('https');
const fs = require('fs');
const OUT = 'D:\\\\AI_file\\\\_downloads\\\\qwen3-tts-ov-windows.zip';
const URL0 = 'https://gh-proxy.com/https://github.com/wangtong10086/qwen3-tts-openvino/releases/download/v0.1.4/qwen3-tts-ov-server-windows-x64-0.1.4-runtime-minimal.zip';
function get(u, d) {
  return new Promise((res) => {
    const r = https.get(u, { headers: { 'User-Agent': 'dsh-research' } }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location && d < 8) { x.resume(); res(get(new URL(x.headers.location, u).toString(), d + 1)); return; }
      const chunks = []; let total = 0;
      x.on('data', (c) => { chunks.push(c); total += c.length; });
      x.on('end', () => res({ code: x.statusCode, buf: Buffer.concat(chunks), total }));
    });
    r.on('error', (e) => res({ code: 0, buf: Buffer.from(String(e.message)), total: 0 }));
    r.setTimeout(300000, () => { r.destroy(); res({ code: 0, buf: Buffer.from('timeout'), total: 0 }); });
  });
}
(async () => {
  const r = await get(URL0, 0);
  console.log('  HTTP ' + r.code + '  bytes ' + r.total);
  if (r.code === 200 && r.total > 10000000) {
    fs.writeFileSync(OUT, r.buf);
    console.log('  saved: ' + OUT);
  } else { console.log('  body: ' + r.buf.toString('utf8').slice(0, 200)); }
})();
