content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$zip = 'D:\AI_file\_downloads\qwen3-tts-ov-windows.zip'
$dest = 'D:\AI_file\tools\qwen3-tts-ov'

Write-Output '=== 1) top-level entries (outside _internal) ==='
$listing = & tar -tf $zip 2>&1
@($listing) | Where-Object { $_ -notmatch '_internal/' -and $_ -notmatch '/$' } | ForEach-Object { Write-Output ('    ' + $_) }

Write-Output ''
Write-Output '=== 2) extract ==='
if (Test-Path -LiteralPath $dest) { Remove-Item -LiteralPath $dest -Recurse -Force }
New-Item -ItemType Directory -Force -Path $dest | Out-Null
& tar -xf $zip -C $dest --strip-components=1 2>&1 | Select-Object -First 5 | ForEach-Object { Write-Output ('  ' + $_) }
Write-Output ('  extracted to: ' + $dest)
$files = @(Get-ChildItem -LiteralPath $dest -Recurse -File -ErrorAction SilentlyContinue)
$size = ($files | Measure-Object -Property Length -Sum).Sum
Write-Output ('  files: ' + $files.Count + '   size: ' + [Math]::Round($size/1MB,1) + ' MB')

Write-Output ''
Write-Output '=== 3) top-level after extract ==='
Get-ChildItem -LiteralPath $dest -Force | Sort-Object { -not $_.PSIsContainer }, Name | ForEach-Object {
    Write-Output ('  ' + $(if ($_.PSIsContainer) { '[dir] ' } else { '      ' }) + $_.Name + $(if (-not $_.PSIsContainer) { '  (' + [Math]::Round($_.Length/1MB,2) + ' MB)' } else { '' }))
}

Write-Output ''
Write-Output '=== 4) main executable ==='
$exe = Get-ChildItem -LiteralPath $dest -File -Filter '*.exe' -ErrorAction SilentlyContinue | Select-Object -First 5
if ($exe) {
    $exe | ForEach-Object { Write-Output ('  ' + $_.Name + '  (' + [Math]::Round($_.Length/1MB,1) + ' MB)   version=' + $_.VersionInfo.FileVersion) }
} else {
    Write-Output '  no .exe at top level'
}

Write-Output ''
Write-Output '=== 5) bundled docs ==='
Get-ChildItem -LiteralPath $dest -Recurse -File -Include '*.md', '*.txt', '*.json' -ErrorAction SilentlyContinue | Where-Object { $_.FullName -notmatch '_internal\\(numpy|huggingface_hub|click)' } | Select-Object -First 12 | ForEach-Object {
    Write-Output ('  ' + $_.FullName.Substring($dest.Length + 1) + '  (' + $_.Length + ' B)')
}", "description": "Extract runtime and inspect structure", "timeoutMs": 600000}

