content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$js = @'
const https = require('https');
function probe(u, ms) {
  const t0 = Date.now();
  return new Promise((res) => {
    const req = https.get(u, { headers: { 'User-Agent': 'dsh-research', Range: 'bytes=0-2097151' } }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(probe(new URL(x.headers.location, u).toString(), ms)); return; }
      let got = 0;
      x.on('data', (c) => { got += c.length; if (got >= 2097152) x.destroy(); });
      x.on('close', () => res({ code: x.statusCode, got, ms: Date.now() - t0 }));
      x.on('end', () => res({ code: x.statusCode, got, ms: Date.now() - t0 }));
    });
    req.on('error', (e) => res({ code: 0, err: String(e.code || e.message), got: 0, ms: Date.now() - t0 }));
    req.setTimeout(ms, () => { req.destroy(); res({ code: 'timeout', got: 0, ms: Date.now() - t0 }); });
  });
}
(async () => {
  const F = 'Qwen/Qwen3-TTS-12Hz-0.6B-Base/resolve/main/model.safetensors';
  for (const [label, base] of [['huggingface.co direct', 'https://huggingface.co'], ['hf-mirror', 'https://hf-mirror.com']]) {
    const r = await probe(base + '/' + F, 15000);
    const kbs = r.got ? (r.got / 1024 / (r.ms / 1000)).toFixed(0) : '-';
    console.log('  ' + label.padEnd(24) + 'HTTP ' + String(r.code).padEnd(10) + (r.err || ((r.got / 1048576).toFixed(1) + ' MB / ' + (r.ms / 1000).toFixed(1) + 's')) + '  ' + kbs + ' KB/s');
  }
})();
'@
$js | & 'D:\program_runtime_environment\nodejs\node.exe' 2>&1 | ForEach-Object { Write-Output $_ }

Write-Output ''
Write-Output '=== start server (device NPU, auto-download enabled) ==='
$dest = 'D:\AI_file\tools\qwen3-tts-ov'
$exe = Join-Path $dest 'qwen3-tts-ov-server.exe'
$logOut = 'D:\AI_file\logs\qwen3-tts-server.out.log'
$logErr = 'D:\AI_file\logs\qwen3-tts-server.err.log'
New-Item -ItemType Directory -Force -Path 'D:\AI_file\logs' | Out-Null
Remove-Item -LiteralPath $logOut, $logErr -Force -ErrorAction SilentlyContinue
$proc = Start-Process -FilePath $exe -ArgumentList '--device', 'NPU' -WorkingDirectory $dest -RedirectStandardOutput $logOut -RedirectStandardError $logErr -PassThru -WindowStyle Hidden
Write-Output ('  started pid ' + $proc.Id)

Write-Output ''
Write-Output '=== wait 45s then inspect ==='
Start-Sleep -Seconds 45
$alive = @(Get-Process -Id $proc.Id -ErrorAction SilentlyContinue).Count -gt 0
Write-Output ('  process alive: ' + $alive)
Write-Output ''
Write-Output '  --- stdout tail ---'
if (Test-Path -LiteralPath $logOut) { Get-Content -LiteralPath $logOut -Encoding UTF8 -Tail 25 | ForEach-Object { Write-Output ('    ' + $_) } } else { Write-Output '    (no stdout yet)' }
Write-Output '  --- stderr tail ---'
if (Test-Path -LiteralPath $logErr) { Get-Content -LiteralPath $logErr -Encoding UTF8 -Tail 25 | ForEach-Object { Write-Output ('    ' + $_) } } else { Write-Output '    (no stderr yet)' }

Write-Output ''
Write-Output '=== port 17860 listening? ==='
$conn = Test-NetConnection -ComputerName '127.0.0.1' -Port 17860 -InformationLevel Quiet -WarningAction SilentlyContinue
Write-Output ('  listening: ' + $conn)", "description": "Test HF connectivity and start TTS server", "timeoutMs": 600000}

