{"command": "$ErrorActionPreference = 'Continue'
Start-Sleep -Seconds 40
Write-Output '=== process / port ==='
$p = @(Get-Process -Name 'qwen3-tts-ov-server' -ErrorAction SilentlyContinue)
Write-Output ('  processes: ' + $p.Count)
$p | ForEach-Object { Write-Output ('    pid ' + $_.Id + '  mem ' + [Math]::Round($_.WorkingSet64/1MB,0) + ' MB') }
$c = Test-NetConnection -ComputerName '127.0.0.1' -Port 17860 -InformationLevel Quiet -WarningAction SilentlyContinue
Write-Output ('  port 17860: ' + $c)

Write-Output ''
Write-Output '=== HF cache growth (is it downloading?) ==='
foreach ($d in (Join-Path $env:USERPROFILE '.cache\huggingface\hub'), (Join-Path $env:LOCALAPPDATA 'qwen3-tts-ov'), (Join-Path $env:USERPROFILE '.cache\qwen3-tts-ov')) {
    if (Test-Path -LiteralPath $d) {
        $f = @(Get-ChildItem -LiteralPath $d -Recurse -File -ErrorAction SilentlyContinue)
        $s = ($f | Measure-Object -Property Length -Sum).Sum
        Write-Output ('  [有] ' + $d + '  (' + $f.Count + ' files, ' + [Math]::Round($s/1MB,1) + ' MB)')
        $f | Sort-Object Length -Descending | Select-Object -First 4 | ForEach-Object { Write-Output ('        ' + $_.Name + '  ' + [Math]::Round($_.Length/1MB,1) + ' MB') }
    } else {
        Write-Output ('  [无] ' + $d)
    }
}

Write-Output ''
Write-Output '=== any qwen3-tts dirs recently created under user profile ==='
Get-ChildItem -LiteralPath $env:USERPROFILE -Directory -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'qwen|tts' } | ForEach-Object { Write-Output ('  ' + $_.FullName) }", "description": "Check if server started and is downloading", "timeoutMs": 300000}

