content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$js = @'
const https = require('https');
function get(u) { return new Promise((res) => { const r = https.get(u, { headers: { 'User-Agent': 'dsh' } }, (x) => { if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(get(new URL(x.headers.location, u).toString())); return; } let d = ''; x.on('data', (c) => d += c); x.on('end', () => res({ code: x.statusCode, body: d })); }); r.on('error', (e) => res({ code: 0, body: String(e.message) })); r.setTimeout(30000, () => { r.destroy(); res({ code: 0, body: 'timeout' }); }); }); }
(async () => {
  for (const repo of ['waston10086/qwen3-tts-openvino-voice-design', 'wangtong10086/qwen3-tts-openvino-voice-design']) {
    const r = await get('https://hf-mirror.com/api/models/' + repo + '?blobs=true');
    console.log('=== ' + repo + '  HTTP ' + r.code + ' ===');
    if (r.code === 200) {
      const j = JSON.parse(r.body);
      const files = (j.siblings || []).filter((s) => s.size).sort((a, b) => b.size - a.size);
      let total = 0;
      for (const f of files) total += f.size;
      console.log('  files: ' + files.length + '   total: ' + (total / 1073741824).toFixed(2) + ' GB');
      for (const f of files.slice(0, 12)) console.log('   ' + (f.size / 1048576).toFixed(1).padStart(9) + ' MB  ' + f.rfilename);
      if (files.length > 12) console.log('   ... and ' + (files.length - 12) + ' more');
    } else {
      console.log('  ' + r.body.slice(0, 120));
    }
    console.log('');
  }
  console.log('=== does the repo expose the openvino_realtime subfolder? ===');
  const t = await get('https://hf-mirror.com/api/models/waston10086/qwen3-tts-openvino-voice-design/tree/main');
  console.log('  tree HTTP ' + t.code);
