$js = @'
const https = require('https');
function get(u, tries) {
  tries = tries || 1;
  return new Promise((res) => {
    const r = https.get(u, { headers: { 'User-Agent': 'dsh' } }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(get(new URL(x.headers.location, u).toString(), tries)); return; }
      let d = ''; x.on('data', (c) => d += c); x.on('end', () => res({ code: x.statusCode, body: d }));
    });
    r.on('error', (e) => { if (tries < 3) res(get(u, tries + 1)); else res({ code: 0, body: String(e.message) }); });
    r.setTimeout(25000, () => { r.destroy(); if (tries < 3) res(get(u, tries + 1)); else res({ code: 0, body: 'timeout' }); });
  });
}
async function walk(path, depth) {
  if (depth > 3) return { files: [], dirs: [] };
  const r = await get('https://hf-mirror.com/api/models/waston10086/qwen3-tts-openvino-voice-design/tree/main/' + path);
  const out = { files: [], dirs: [] };
  if (r.code !== 200) { console.log('  tree ' + path + ' HTTP ' + r.code); return out; }
  let arr;
  try { arr = JSON.parse(r.body); } catch (e) { return out; }
  for (const e of arr) {
    if (e.type === 'directory') {
      out.dirs.push(e.path);
      const sub = await walk(e.path, depth + 1);
      out.files = out.files.concat(sub.files);
      out.dirs = out.dirs.concat(sub.dirs);
    } else if (e.size) {
      out.files.push({ path: e.path, size: e.size });
    }
  }
  return out;
}
(async () => {
  console.log('=== openvino_realtime tree (recursive, depth<=3) ===');
  const r = await walk('openvino_realtime', 0);
  let total = 0;
  for (const f of r.files) total += f.size;
  console.log('  dirs : ' + r.dirs.length);
  console.log('  files: ' + r.files.length);
  console.log('  TOTAL: ' + (total / 1048576).toFixed(1) + ' MB (' + (total / 1073741824).toFixed(2) + ' GB)');
  console.log('');
  console.log('  directories:');
  for (const d of r.dirs.slice(0, 20)) console.log('    ' + d);
  console.log('');
  console.log('  top 15 files by size:');
  for (const f of r.files.sort((a, b) => b.size - a.size).slice(0, 15)) console.log('   ' + (f.size / 1048576).toFixed(1).padStart(9) + ' MB  ' + f.path);
})();
