$dest = 'D:\AI_file\tools\qwen3-tts-ov'
Set-Location $dest
Start-Process -FilePath (Join-Path $dest 'qwen3-tts-ov-server.exe') -ArgumentList '--device','NPU' -WorkingDirectory $dest -WindowStyle Hidden | Out-Null
Write-Output '=== server relaunched (hidden window) ==='
Start-Sleep -Seconds 5
Write-Output ('  process: ' + @(Get-Process -Name 'qwen3-tts-ov-server' -ErrorAction SilentlyContinue).Count)

Write-Output ''
Write-Output '=== concurrency test on huggingface.co (4 x 6MB ranges) ==='
$js = @'
const https = require('https');
const F = 'waston10086/qwen3-tts-openvino-voice-design/resolve/main/openvino_realtime/base/talker_stateful_batch_sdpa_paged_gqa_seed_int8_sym_batch_fused_gqa.bin';
const CHUNK = 6 * 1024 * 1024;
function one(start, ms) {
  const t0 = Date.now();
  return new Promise((res) => {
    const req = https.get('https://huggingface.co/' + F, { headers: { 'User-Agent': 'Mozilla/5.0 dsh', Range: 'bytes=' + start + '-' + (start + CHUNK - 1) } }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(one(start, ms)); return; }
      let got = 0;
      x.on('data', (c) => { got += c.length; if (got >= CHUNK) x.destroy(); });
      x.on('close', () => res({ code: x.statusCode, got, ms: Date.now() - t0 }));
      x.on('end', () => res({ code: x.statusCode, got, ms: Date.now() - t0 }));
    });
    req.on('error', (e) => res({ code: 0, err: String(e.code || e.message), got: 0, ms: Date.now() - t0 }));
    req.setTimeout(ms, () => { req.destroy(); res({ code: 'timeout', got: 0, ms: Date.now() - t0 }); });
  });
}
async function bench(conns) {
  const t0 = Date.now();
  const tasks = [];
  for (let i = 0; i < conns; i++) tasks.push(one(i * CHUNK, 45000));
  const rs = await Promise.all(tasks);
  const ms = Date.now() - t0;
  const got = rs.reduce((a, r) => a + (r.got || 0), 0);
  const codes = [...new Set(rs.map((r) => r.code))].join(',');
  const kbs = got ? (got / 1024 / (ms / 1000)).toFixed(0) : '-';
  console.log('  conns=' + conns + '  ' + (got / 1048576).toFixed(1) + ' MB in ' + (ms / 1000).toFixed(1) + 's  =>  ' + kbs + ' KB/s  [HTTP ' + codes + ']');
}
(async () => {
  await bench(1);
  await bench(4);
  await bench(8);
})();
'@
$js | & 'D:\program_runtime_environment\nodejs\node.exe' 2>&1 | ForEach-Object { Write-Output $_ }", "description": "Relaunch server and benchmark concurrency", "timeoutMs": 600000}

