{"command": "$ErrorActionPreference = 'Continue'
$js = @'
const http = require('http');
function req(method, path, body, ms) {
  return new Promise((res) => {
    const t0 = Date.now();
    const opts = { host: '127.0.0.1', port: 17860, path: path, method: method, headers: { 'Content-Type': 'application/json' } };
    const r = http.request(opts, (x) => {
      let d = '';
      x.on('data', (c) => d += c);
      x.on('end', () => res({ code: x.statusCode, ctype: x.headers['content-type'], len: d.length, body: d.slice(0, 600), ms: Date.now() - t0 }));
    });
    r.on('error', (e) => res({ code: 0, err: String(e.code || e.message), ms: Date.now() - t0 }));
    r.setTimeout(ms || 15000, () => { r.destroy(); res({ code: 'timeout', ms: Date.now() - t0 }); });
    if (body) r.write(typeof body === 'string' ? body : JSON.stringify(body));
    r.end();
  });
}
(async () => {
  for (const [m, p] of [['GET', '/'], ['GET', '/health'], ['GET', '/docs'], ['GET', '/openapi.json'], ['GET', '/api/health'], ['GET', '/status']]) {
    const r = await req(m, p, null, 8000);
    const tag = r.err ? ('ERR ' + r.err) : ('HTTP ' + r.code + '  ct=' + (r.ctype || '-') + '  len=' + r.len);
    console.log('  ' + m + ' ' + p.padEnd(16) + ' ' + tag + '  ' + r.ms + 'ms');
    if (r.body && r.code === 200) console.log('      ' + r.body.replace(/\s+/g, ' ').slice(0, 220));
  }
})();
