{"command": "$ErrorActionPreference = 'Continue'
$js = @'
const http = require('http');
function get(p) {
  return new Promise((res) => {
    const r = http.request({ host: '127.0.0.1', port: 17860, path: p, method: 'GET' }, (x) => {
      let d = ''; x.on('data', (c) => d += c); x.on('end', () => res({ code: x.statusCode, body: d }));
    });
    r.on('error', (e) => res({ code: 0, body: String(e.message) }));
    r.setTimeout(15000, () => { r.destroy(); res({ code: 'timeout', body: '' }); });
    r.end();
  });
}
(async () => {
  const o = await get('/openapi.json');
  const j = JSON.parse(o.body);
  console.log('=== API paths ===');
  for (const [p, methods] of Object.entries(j.paths)) {
    const detail = Object.entries(methods).map(([m, v]) => m.toUpperCase() + (v.summary ? ' (' + v.summary + ')' : '')).join(', ');
    console.log('  ' + p.padEnd(30) + detail);
  }
  console.log('');
  console.log('=== request schemas ===');
  const comps = (j.components && j.components.schemas) || {};
  for (const [name, s] of Object.entries(comps)) {
    const props = s.properties ? Object.keys(s.properties) : [];
    console.log('  ' + name + ': ' + props.join(', ').slice(0, 200));
  }
  console.log('');
  const h = await get('/health');
  const hj = JSON.parse(h.body);
  console.log('=== health: top-level keys ===');
  console.log('  ' + Object.keys(hj).join(', '));
  console.log('');
  console.log('=== health: warmup detail ===');
  console.log('  ' + JSON.stringify(hj.warmup || {}, null, 2).slice(0, 1200));
  if (hj.models) console.log('\n  models: ' + JSON.stringify(hj.models).slice(0, 800));
  if (hj.variants) console.log('\n  variants: ' + JSON.stringify(hj.variants).slice(0, 800));
})();
