$js = @'
const http = require('http');
function call(method, path, body, ms) {
  return new Promise((res) => {
    const payload = body ? JSON.stringify(body) : null;
    const r = http.request({ host: '127.0.0.1', port: 17860, path: path, method: method, headers: Object.assign({ 'Content-Type': 'application/json' }, payload ? { 'Content-Length': Buffer.byteLength(payload) } : {}) }, (x) => {
      let d = ''; x.on('data', (c) => d += c); x.on('end', () => res({ code: x.statusCode, body: d }));
    });
    r.on('error', (e) => res({ code: 0, body: String(e.message) }));
    r.setTimeout(ms || 20000, () => { r.destroy(); res({ code: 'timeout', body: '' }); });
    if (payload) r.write(payload);
    r.end();
  });
}
(async () => {
  console.log('=== POST /v1/models/download  body={mode:voice_design} ===');
  let r = await call('POST', '/v1/models/download', { mode: 'voice_design' }, 30000);
  console.log('  HTTP ' + r.code);
  console.log('  ' + r.body.slice(0, 700));

  if (r.code === 422 || r.code === 400) {
    console.log('');
    console.log('=== retry with query param ===');
    r = await call('POST', '/v1/models/download?mode=voice_design', null, 30000);
    console.log('  HTTP ' + r.code + '  ' + r.body.slice(0, 400));
  }

  console.log('');
  console.log('=== poll download status after 15s ===');
  await new Promise((s) => setTimeout(s, 15000));
  const m = await call('GET', '/v1/models');
  try {
    const j = JSON.parse(m.body);
    for (const [k, v] of Object.entries(j.available_modes || {})) {
      const dl = v.download || {};
      console.log('  ' + k.padEnd(14) + 'available=' + String(v.available).padEnd(6) + ' dl.status=' + String(dl.status).padEnd(10) + ' msg=' + String(dl.message || '').slice(0, 60));
    }
    if (j.downloads) console.log('  downloads: ' + JSON.stringify(j.downloads).slice(0, 300));
  } catch (e) { console.log('  parse fail'); }
})();
'@
