const http = require('http');
function call(method, path, body, ms) {
  return new Promise((res) => {
    const payload = body ? JSON.stringify(body) : null;
    const r = http.request({ host: '127.0.0.1', port: 17860, path: path, method: method, headers: Object.assign({ 'Content-Type': 'application/json' }, payload ? { 'Content-Length': Buffer.byteLength(payload) } : {}) }, (x) => {
      let d = ''; x.on('data', (c) => d += c); x.on('end', () => res({ code: x.statusCode, body: d }));
    });
    r.on('error', (e) => res({ code: 0, body: String(e.message) }));
    r.setTimeout(ms || 30000, () => { r.destroy(); res({ code: 'timeout', body: '' }); });
    if (payload) r.write(payload);
    r.end();
  });
}
(async () => {
  console.log('=== current status before retrigger ===');
  const m0 = await call('GET', '/v1/models');
  const j0 = JSON.parse(m0.body);
  for (const [k, v] of Object.entries(j0.available_modes || {})) {
    console.log('  ' + k.padEnd(14) + 'available=' + String(v.available).padEnd(6) + ' status=' + String((v.download || {}).status).padEnd(12) + ' err=' + String((v.download || {}).error || '').slice(0, 60));
  }

  console.log('');
  console.log('=== retrigger voice_design download ===');
  const r = await call('POST', '/v1/models/download', { mode: 'voice_design' }, 60000);
  console.log('  HTTP ' + r.code);
  const jr = JSON.parse(r.body || '{}');
  const vd = (jr.available_modes || {}).voice_design || {};
  console.log('  available=' + vd.available + '  status=' + ((vd.download || {}).status) + '  msg=' + String((vd.download || {}).message || '').slice(0, 120));
  console.log('  err=' + String((vd.download || {}).error || '').slice(0, 200));

  console.log('');
  console.log('=== poll status every 10s for 40s ===');
  for (let i = 0; i < 4; i++) {
    await new Promise((s) => setTimeout(s, 10000));
    const m = await call('GET', '/v1/models');
    const j = JSON.parse(m.body);
    const v = (j.available_modes || {}).voice_design || {};
    console.log('  +' + ((i + 1) * 10) + 's  status=' + String((v.download || {}).status).padEnd(12) + ' available=' + v.available);
  }
})();
