{"command": "$ErrorActionPreference = 'Continue'
$js = @'
const http = require('http');
const fs = require('fs');
function call(method, path, body, ms) {
  return new Promise((res) => {
    const payload = body ? JSON.stringify(body) : null;
    const r = http.request({ host: '127.0.0.1', port: 17860, path: path, method: method, headers: Object.assign({ 'Content-Type': 'application/json' }, payload ? { 'Content-Length': Buffer.byteLength(payload) } : {}) }, (x) => {
      const chunks = [];
      x.on('data', (c) => chunks.push(c));
      x.on('end', () => res({ code: x.statusCode, ctype: x.headers['content-type'], buf: Buffer.concat(chunks) }));
    });
    r.on('error', (e) => res({ code: 0, err: String(e.message) }));
    r.setTimeout(ms || 120000, () => { r.destroy(); res({ code: 'timeout' }); });
    if (payload) r.write(payload);
    r.end();
  });
}
(async () => {
  console.log('=== GET /v1/audio/voices ===');
  const v = await call('GET', '/v1/audio/voices', null, 20000);
  try {
    const j = JSON.parse(v.buf.toString('utf8'));
    console.log('  voices: ' + JSON.stringify(j.voices || []));
    if (j.voice_details) console.log('  details: ' + JSON.stringify(j.voice_details).slice(0, 300));
  } catch (e) { console.log('  parse fail'); }

  console.log('');
  console.log('=== POST /v1/audio/speech (OpenAI compatible) ===');
  const body = { input: '你好，我是DSH，蓝色大肥鱼。', response_format: 'wav' };
  let r = await call('POST', '/v1/audio/speech', body, 180000);
  console.log('  HTTP ' + r.code + '  ctype=' + (r.ctype || '-') + '  bytes=' + (r.buf ? r.buf.length : 0));
  if (r.code === 200 && r.ctype && /audio|octet/.test(r.ctype)) {
    const out = 'D:\\AI_file\\outputs\\tts-first.wav';
    fs.writeFileSync(out, r.buf);
    console.log('  saved: ' + out);
  } else {
    console.log('  body: ' + (r.buf ? r.buf.toString('utf8').slice(0, 600) : '(none)'));
    console.log('');
    console.log('=== fallback: POST /v1/tts ===');
    r = await call('POST', '/v1/tts', { text: '你好，我是DSH，蓝色大肥鱼。' }, 180000);
    console.log('  HTTP ' + r.code + '  ctype=' + (r.ctype || '-') + '  bytes=' + (r.buf ? r.buf.length : 0));
    if (r.code === 200 && r.buf.length > 10000) {
      const out = 'D:\\AI_file\\outputs\\tts-first.wav';
      fs.writeFileSync(out, r.buf);
      console.log('  saved: ' + out);
    } else {
      console.log('  body: ' + (r.buf ? r.buf.toString('utf8').slice(0, 600) : '(none)'));
    }
  }
})();
