{"command": "$ErrorActionPreference = 'Continue'
Write-Output '=== 1) 立即关闭显示器（SC_MONITORPOWER = 2） ==='
$code = @"
using System;
using System.Runtime.InteropServices;
public class MonitorCtl {
    [DllImport("user32.dll")]
    public static extern IntPtr SendMessage(IntPtr hWnd, uint Msg, IntPtr wParam, IntPtr lParam);
}
"@
try {
    Add-Type -TypeDefinition $code -ErrorAction Stop
    $r = [MonitorCtl]::SendMessage([IntPtr]0xffff, 0x0112, [IntPtr]0xF170, [IntPtr]2)
    Write-Output ('  SendMessage 返回: ' + $r + '  (0 = 成功发出)')
} catch {
    Write-Output ('  Add-Type 失败: ' + $_.Exception.Message)
}

Write-Output ''
Write-Output '=== 2) 确认关屏定时器仍生效 ==='
$o = & powercfg /query SCHEME_CURRENT SUB_VIDEO VIDEOIDLE 2>&1
$ac = ($o | Where-Object { $_ -match '当前交流电源设置索引' } | Select-Object -First 1)
