{"content": """"
Segmented puller for the Qwen3-TTS voice_design OpenVINO IR.

Why this exists: a single long-lived HTTPS connection to HuggingFace gets cut on this link
after a few hours (observed twice: attempt 1 died at 00:29, attempt 2 at 04:29, both after
exactly four hours, having transferred only a fraction of a 1.35 GB file). Small range probes
against the same host succeed at 300-400 KB/s, so the fix is to never hold a connection for
long: split every file into 8 MB segments, fetch a few segments concurrently, and retry each
segment independently. Progress is per-segment (.segN files), so an interrupted run resumes
exactly where it stopped.

Usage:
    python pull-voice-design-segmented.py            # download everything
    python pull-voice-design-segmented.py --only talker   # single file (substring match)
    python pull-voice-design-segmented.py --dry-run
"""
import io, json, os, ssl, sys, threading, time, urllib.request, urllib.error

REPO = "waston10086/qwen3-tts-openvino-voice-design"
SUBDIR = "openvino_realtime/voice_design"
DEST_ROOT = os.path.join(
    os.environ.get("LOCALAPPDATA", ""),
    "qwen3-tts-openvino", "models",
    "waston10086--qwen3-tts-openvino-voice-design--main",
    "openvino_realtime", "voice_design",
)
LOG = r"D:\AI_file\logs\qwen3-tts-pull-seg.log"
MIRRORS = ["https://huggingface.co", "https://hf-mirror.com"]
SEG_SIZE = 8 * 1024 * 1024      # 8 MB per segment: ~25 s at 330 KB/s, well inside the timeout
CONCURRENCY = 4                 # segments in flight
SEG_TIMEOUT = 90                # seconds per segment request
SEG_RETRIES = 6

DRY = "--dry-run" in sys.argv
ONLY = None
if "--only" in sys.argv:
    i = sys.argv.index("--only")
    if i + 1 < len(sys.argv):
        ONLY = sys.argv[i + 1]

ctx = ssl.create_default_context()

_log_lock = threading.Lock()


def log(msg):
    line = time.strftime("%H:%M:%S ") + msg
    with _log_lock:
        print(line, flush=True)
        try:
            os.makedirs(os.path.dirname(LOG), exist_ok=True)
            with io.open(LOG, "a", encoding="utf-8") as f:
                f.write(line + "\n")
        except Exception:
            pass


def http_get(url, headers=None, timeout=60):
    req = urllib.request.Request(url, headers=headers or {})
    req.add_header("User-Agent", "dsh-tts-seg/1.0")
    return urllib.request.urlopen(req, timeout=timeout, context=ctx)


def human(n):
    for unit in ("B", "KB", "MB", "GB"):
        if n < 1024:
            return "%.1f %s" % (n, unit)
        n /= 1024.0
    return "%.1f TB" % n


def list_tree(path):
    last = None
    for base in MIRRORS:
        try:
            with http_get("%s/api/models/%s/tree/main/%s" % (base, REPO, path), timeout=30) as r:
                return json.loads(r.read().decode("utf-8"))
        except Exception as e:
            last = e
            log("  tree via %s failed: %s" % (base, e))
    raise RuntimeError("cannot list tree: %s" % last)


def fetch_segment(rel_path, idx, start, end, dest_part):
    """Fetch bytes [start, end] into dest_part, resuming if it already has bytes."""
    want = end - start + 1
    for attempt in range(1, SEG_RETRIES + 1):
        have = os.path.getsize(dest_part) if os.path.exists(dest_part) else 0
        if have >= want:
            return True
        if have > want:
            os.remove(dest_part)
            have = 0
        base = MIRRORS[(idx + attempt) % len(MIRRORS)]
        url = "%s/%s/resolve/main/%s" % (base, REPO, rel_path)
        try:
            headers = {"Range": "bytes=%d-%d" % (start + have, end)}
            t0 = time.time()
            with http_get(url, headers=headers, timeout=SEG_TIMEOUT) as r:
                with io.open(dest_part, "ab") as f:
                    while True:
                        chunk = r.read(64 * 1024)
                        if not chunk:
                            break
                        f.write(chunk)
            got = os.path.getsize(dest_part)
            if got >= want:
                return True
            log("    seg%03d partial %s/%s (%.1fs, attempt %d)" % (idx, human(got), human(want), time.time() - t0, attempt))
        except Exception as e:
            log("    seg%03d error attempt %d: %s: %s" % (idx, attempt, type(e).__name__, str(e)[:80]))
            time.sleep(2 * attempt)
    return False


def pull_file(rel_path, total):
    name = os.path.basename(rel_path)
    dest = os.path.join(DEST_ROOT, name)
    if os.path.exists(dest) and os.path.getsize(dest) == total:
        log("  [skip] %s complete" % name)
        return True

    nseg = (total + SEG_SIZE - 1) // SEG_SIZE
    seg_paths = [dest + ".seg%03d" % i for i in range(nseg)]
    remaining = []
    for i in range(nseg):
        start = i * SEG_SIZE
        end = min(total - 1, start + SEG_SIZE - 1)
        want = end - start + 1
        have = os.path.getsize(seg_paths[i]) if os.path.exists(seg_paths[i]) else 0
        if have < want:
            remaining.append((i, start, end, want))

    if not remaining:
        log("  [merge] %s all segments present" % name)
    else:
        done_already = nseg - len(remaining)
        log("  [start] %s  %s  segments=%d (have %d, need %d)" % (name, human(total), nseg, done_already, len(remaining)))

        lock = threading.Lock()
        queue = list(remaining)
        completed = [done_already]
        failed = []

        def worker():
            while True:
                with lock:
                    if not queue:
                        return
                    item = queue.pop(0)
                i, start, end, want = item
                ok = fetch_segment(rel_path, i, start, end, seg_paths[i])
                with lock:
                    if ok:
                        completed[0] += 1
                        pct = completed[0] * 100.0 / nseg
                        log("  [seg] %s %d/%d (%.1f%%)" % (name, completed[0], nseg, pct))
                    else:
                        failed.append(i)

        threads = [threading.Thread(target=worker, daemon=True) for _ in range(CONCURRENCY)]
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=None)

        if failed:
            log("  [fail] %s: %d segments incomplete -> %s" % (name, len(failed), failed[:10]))
            return False

    # merge segments in order
    tmp = dest + ".merging"
    with io.open(tmp, "wb") as out:
        for i in range(nseg):
            with io.open(seg_paths[i], "rb") as f:
                while True:
                    chunk = f.read(1024 * 1024)
                    if not chunk:
                        break
                    out.write(chunk)
    size = os.path.getsize(tmp)
    if size != total:
        log("  [fail] %s merged size %s != %s" % (name, human(size), human(total)))
        os.remove(tmp)
        return False
    if os.path.exists(dest):
        os.remove(dest)
    os.rename(tmp, dest)
    for p in seg_paths:
        try:
            os.remove(p)
        except Exception:
            pass
    log("  [done] %s  %s" % (name, human(size)))
    return True


def main():
    log("=== segmented pull -> %s" % DEST_ROOT)
    entries = list_tree(SUBDIR)
    files = [(e["path"], e.get("size") or 0) for e in entries if e.get("type") == "file" and e.get("size")]
    if ONLY:
        files = [f for f in files if ONLY in f[0]]
    total = sum(s for _, s in files)
    log("  files=%d total=%s seg=%s conc=%d only=%s dry=%s" % (len(files), human(total), human(SEG_SIZE), CONCURRENCY, ONLY, DRY))
    if DRY:
        for p, s in sorted(files, key=lambda x: -x[1]):
            log("    %10s  %s" % (human(s), os.path.basename(p)))
        return 0

    os.makedirs(DEST_ROOT, exist_ok=True)
    ok = 0
    for p, s in sorted(files, key=lambda x: -x[1]):
        try:
            if pull_file(p, s):
                ok += 1
        except Exception as e:
            log("  [fatal] %s: %s: %s" % (os.path.basename(p), type(e).__name__, e))
    log("=== finished: %d/%d files complete" % (ok, len(files)))
    return 0 if ok == len(files) else 1


if __name__ == "__main__":
    sys.exit(main())
", "file_path": "D:\AI_file\tools\pull-voice-design-segmented.py"}

