$js = @'
const https = require('https');
function quick(u, ms) {
  const t0 = Date.now();
  return new Promise((res) => {
    const req = https.get(u, { headers: { 'User-Agent': 'dsh', Range: 'bytes=0-524287' } }, (x) => {
      let got = 0;
      x.on('data', (c) => { got += c.length; if (got >= 524288) x.destroy(); });
      x.on('close', () => res({ code: x.statusCode, got, ms: Date.now() - t0 }));
      x.on('end', () => res({ code: x.statusCode, got, ms: Date.now() - t0 }));
    });
    req.on('error', (e) => res({ code: 0, err: String(e.code || e.message).slice(0, 30), got: 0, ms: Date.now() - t0 }));
    req.setTimeout(ms, () => { req.destroy(); res({ code: 'timeout', got: 0, ms: Date.now() - t0 }); });
  });
}
(async () => {
  const F = 'waston10086/qwen3-tts-openvino-voice-design/resolve/main/openvino_realtime/voice_design/text_embedding.bin';
  for (const [label, base] of [['hf direct ', 'https://huggingface.co'], ['hf-mirror ', 'https://hf-mirror.com']]) {
    const r = await quick(base + '/' + F, 8000);
    const kbs = r.got ? (r.got / 1024 / (r.ms / 1000)).toFixed(0) : '-';
    console.log('  ' + label + ' HTTP ' + String(r.code).padEnd(10) + (r.err || ((r.got / 1024).toFixed(0) + ' KB / ' + (r.ms / 1000).toFixed(1) + 's')) + '  ' + kbs + ' KB/s');
  }
})();
