content.arguments:
{"content": "// Fetch segment 022 of speech_decoder_stream_c25_t24.bin using Node's https client.
//
// Why: every urllib attempt, full 8 MB or 1 MB chunk, stops at exactly 1022087 bytes
// (26489 short) regardless of retries or mirror. That constant cut point says the transport
// or the server is truncating the body for that request shape, not that the link is flaky.
// Node's https client behaved correctly for the 28 MB sd-vulkan download earlier, so try it.
const https = require('https');
const fs = require('fs');
const path = require('path');

const REPO = 'waston10086/qwen3-tts-openvino-voice-design';
const REL = 'openvino_realtime/voice_design/speech_decoder_stream_c25_t24.bin';
const DEST = path.join(
  process.env.LOCALAPPDATA, 'qwen3-tts-openvino', 'models',
  'waston10086--qwen3-tts-openvino-voice-design--main',
  'openvino_realtime', 'voice_design',
  'speech_decoder_stream_c25_t24.bin'
);
const SEG = 8 * 1024 * 1024;
const TOTAL = 227944192;
const IDX = 22;
const MIRRORS = ['https://huggingface.co', 'https://hf-mirror.com'];

const start = IDX * SEG;
const end = Math.min(TOTAL - 1, start + SEG - 1);
const want = end - start + 1;
const outPath = DEST + '.seg0' + IDX;

function attempt(n, cb) {
  const base = MIRRORS[n % MIRRORS.length];
  const url = base + '/' + REPO + '/resolve/main/' + REL;
  const opts = {
    headers: {
      'User-Agent': 'dsh-node-repair/1.0',
      'Range': 'bytes=' + start + '-' + end,
      'Accept-Encoding': 'identity',
    },
  };
  console.log('  attempt ' + n + ' via ' + base.split('/')[2]);
  const t0 = Date.now();
  let got = 0;
  let finished = false;
  const chunks = [];
  const req = https.get(url, opts, (res) => {
    if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
      res.resume();
      console.log('    redirect -> ' + String(res.headers.location).slice(0, 80));
      return cb(false, 'redirect');
    }
    if (res.statusCode !== 200 && res.statusCode !== 206) {
      res.resume();
      return cb(false, 'HTTP ' + res.statusCode);
    }
    const declared = res.headers['content-length'];
    console.log('    HTTP ' + res.statusCode + '  content-length=' + declared + '  want=' + want);
    res.on('data', (c) => { chunks.push(c); got += c.length; });
    res.on('end', () => {
      finished = true;
      const buf = Buffer.concat(chunks);
      const secs = ((Date.now() - t0) / 1000).toFixed(1);
      if (buf.length === want) {
        fs.writeFileSync(outPath, buf);
        console.log('    OK ' + buf.length + ' bytes in ' + secs + 's -> ' + outPath);
        return cb(true);
      }
      console.log('    incomplete ' + buf.length + '/' + want + ' (' + secs + 's, missing ' + (want - buf.length) + ')');
      cb(false, 'incomplete');
    });
    res.on('error', (e) => { if (!finished) cb(false, String(e.code || e.message)); });
  });
  req.on('error', (e) => { if (!finished) cb(false, String(e.code || e.message)); });
  req.setTimeout(120000, () => { req.destroy(); if (!finished) cb(false, 'timeout'); });
}

let n = 0;
function loop() {
  n += 1;
  if (n > 12) { console.log('  GIVE UP after 12 attempts'); process.exit(1); }
