const https = require('https');
const fs = require('fs');
const path = require('path');

const REPO = 'waston10086/qwen3-tts-openvino-voice-design';
const REL = 'openvino_realtime/voice_design/speech_decoder_stream_c25_t24.bin';
const DEST_DIR = path.join(
  process.env.LOCALAPPDATA, 'qwen3-tts-openvino', 'models',
  'waston10086--qwen3-tts-openvino-voice-design--main',
  'openvino_realtime', 'voice_design'
);
const FINAL = path.join(DEST_DIR, 'speech_decoder_stream_c25_t24.bin');
const TMP = FINAL + '.whole.tmp';
const EXPECT = 227944192;
const SOURCES = [
  'https://huggingface.co/' + REPO + '/resolve/main/' + REL,
  'https://hf-mirror.com/' + REPO + '/resolve/main/' + REL,
];

function follow(url, maxHops, cb, depth) {
  depth = depth || 0;
  if (depth > maxHops) return cb(new Error('too many redirects'));
  const req = https.get(url, { headers: { 'User-Agent': 'dsh-whole/1.0', 'Accept-Encoding': 'identity' } }, (res) => {
    if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
      res.resume();
      const next = new URL(res.headers.location, url).toString();
      console.log('    hop ' + (depth + 1) + ' -> ' + next.split('/')[2]);
      return follow(next, maxHops, cb, depth + 1);
    }
    cb(null, res);
  });
  req.on('error', (e) => cb(e));
  req.setTimeout(60000, () => { req.destroy(); cb(new Error('connect timeout')); });
}

function download(srcIdx, cb) {
  const url = SOURCES[srcIdx % SOURCES.length];
  console.log('  source ' + (srcIdx + 1) + ': ' + url.split('/')[2]);
  const t0 = Date.now();
  follow(url, 6, (err, res) => {
    if (err) { console.log('    error: ' + err.message); return cb(false); }
    if (res.statusCode !== 200) {
      res.resume();
      console.log('    HTTP ' + res.statusCode);
      return cb(false);
    }
    const len = Number(res.headers['content-length'] || 0);
    console.log('    HTTP 200  content-length=' + len + '  expected=' + EXPECT);
    let got = 0;
    let lastLog = Date.now();
    const ws = fs.createWriteStream(TMP);
    res.on('data', (c) => {
      got += c.length;
      if (Date.now() - lastLog > 15000) {
        lastLog = Date.now();
        console.log('    ' + (got / 1048576).toFixed(1) + ' MB / ' + (EXPECT / 1048576).toFixed(1) + ' MB  (' + ((Date.now() - t0) / 1000).toFixed(0) + 's)');
      }
    });
    res.pipe(ws);
    ws.on('finish', () => {
      const size = fs.statSync(TMP).size;
      console.log('    finished ' + size + ' bytes in ' + ((Date.now() - t0) / 1000).toFixed(1) + 's  match=' + (size === EXPECT));
      if (size === EXPECT) {
        if (fs.existsSync(FINAL)) fs.unlinkSync(FINAL);
        fs.renameSync(TMP, FINAL);
        return cb(true);
      }
      cb(false);
    });
