function loop() {
  n += 1;
  if (n > 6) { console.log('  GIVE UP'); process.exit(1); }
  download(n - 1, (ok) => {
    if (ok) { console.log('  DONE'); process.exit(0); }
    try { if (fs.existsSync(TMP)) fs.unlinkSync(TMP); } catch (e) {}
    setTimeout(loop, 2000 * n);
  });
}
