{"command": "$ErrorActionPreference = 'Continue'
$js = @'
const http = require('http');
const fs = require('fs');
function call(method, path, body, ms) {
  return new Promise((res) => {
    const payload = body ? JSON.stringify(body) : null;
    const r = http.request({ host: '127.0.0.1', port: 17860, path: path, method: method, headers: Object.assign({ 'Content-Type': 'application/json' }, payload ? { 'Content-Length': Buffer.byteLength(payload) } : {}) }, (x) => {
      const chunks = [];
      x.on('data', (c) => chunks.push(c));
      x.on('end', () => res({ code: x.statusCode, ctype: x.headers['content-type'], buf: Buffer.concat(chunks) }));
    });
    r.on('error', (e) => res({ code: 0, err: String(e.message) }));
    r.setTimeout(ms || 300000, () => { r.destroy(); res({ code: 'timeout' }); });
    if (payload) r.write(payload);
    r.end();
  });
}
async function tryTts(label, path, body) {
  const t0 = Date.now();
  const r = await call('POST', path, body, 300000);
  const secs = ((Date.now() - t0) / 1000).toFixed(2);
  const ok = r.code === 200 && r.buf && r.buf.length > 10000 && /audio|octet/.test(r.ctype || '');
  console.log('  ' + label.padEnd(34) + 'HTTP ' + String(r.code).padEnd(5) + ' ct=' + String(r.ctype || '-').slice(0, 20).padEnd(20) + ' bytes=' + (r.buf ? r.buf.length : 0).toString().padStart(8) + '  ' + secs + 's');
  if (ok) {
    const out = 'D:\\AI_file\\outputs\\tts-' + label.replace(/[^a-z0-9]/gi, '-') + '.wav';
    fs.writeFileSync(out, r.buf);
    console.log('      SAVED ' + out);
    return out;
  }
  if (r.buf) console.log('      ' + r.buf.toString('utf8').replace(/\s+/g, ' ').slice(0, 260));
  return null;
}
(async () => {
  console.log('=== try voice_clone via /v1/tts ===');
  await tryTts('tts voice_clone', '/v1/tts', { text: '你好，我是DSH，蓝色大肥鱼。', mode: 'voice_clone' });
  console.log('');
  console.log('=== try voice_clone via /v1/audio/speech ===');
  await tryTts('speech voice_clone', '/v1/audio/speech', { input: '你好，我是DSH，蓝色大肥鱼。', mode: 'voice_clone', response_format: 'wav' });
  console.log('');
  console.log('=== try voice_design explicit (to see the exact error) ===');
  await tryTts('tts voice_design', '/v1/tts', { text: '你好。', mode: 'voice_design' });
})();
