content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
Write-Output '=== stop ==='
$procs = @(Get-Process -Name 'qwen3-tts-ov-server' -ErrorAction SilentlyContinue)
Write-Output ('  found ' + $procs.Count)
foreach ($p in $procs) { try { Stop-Process -Id $p.Id -Force -ErrorAction Stop; Write-Output ('  killed ' + $p.Id) } catch { Write-Output ('  fail ' + $p.Id) } }
Start-Sleep -Seconds 4
Write-Output ('  remaining: ' + @(Get-Process -Name 'qwen3-tts-ov-server' -ErrorAction SilentlyContinue).Count)

Write-Output ''
Write-Output '=== start (GPU) ==='
$exe = 'D:\AI_file\tools\qwen3-tts-ov\qwen3-tts-ov-server.exe'
$pinfo = Start-Process -FilePath $exe -ArgumentList '--device','GPU' -WorkingDirectory (Split-Path $exe) -PassThru -WindowStyle Hidden
Write-Output ('  pid ' + $pinfo.Id)
for ($i = 1; $i -le 24; $i++) {
    Start-Sleep -Seconds 5
    $alive = @(Get-Process -Id $pinfo.Id -ErrorAction SilentlyContinue).Count
    $port = Test-NetConnection -ComputerName '127.0.0.1' -Port 17860 -InformationLevel Quiet -WarningAction SilentlyContinue
    if ($port) { Write-Output ('  port up after ' + ($i*5) + 's (alive=' + $alive + ')'); break }
    if ($i -eq 24) { Write-Output ('  no port after 120s (alive=' + $alive + ')') }
}", "description": "Restart TTS server with patched manifest", "timeoutMs": 300000}

