{"command": "$ErrorActionPreference = 'Continue'
Start-Sleep -Seconds 25
$js = @'
const http = require('http');
const fs = require('fs');
function call(method, path, body, ms) {
  return new Promise((res) => {
    const payload = body ? JSON.stringify(body) : null;
    const r = http.request({ host: '127.0.0.1', port: 17860, path: path, method: method, headers: Object.assign({ 'Content-Type': 'application/json' }, payload ? { 'Content-Length': Buffer.byteLength(payload) } : {}) }, (x) => {
      const chunks = []; x.on('data', (c) => chunks.push(c));
      x.on('end', () => res({ code: x.statusCode, ctype: x.headers['content-type'], buf: Buffer.concat(chunks) }));
    });
    r.on('error', (e) => res({ code: 0, err: String(e.message) }));
    r.setTimeout(ms || 300000, () => { r.destroy(); res({ code: 'timeout' }); });
    if (payload) r.write(payload);
    r.end();
  });
}
(async () => {
  const h = await call('GET', '/health', null, 30000);
  try {
    const j = JSON.parse(h.buf.toString('utf8'));
    console.log('  warmup.status=' + (j.warmup||{}).status);
    console.log('  warmup.errors=' + JSON.stringify((j.warmup||{}).errors || '(none)').slice(0, 300));
  } catch (e) {}

  console.log('');
  const t0 = Date.now();
  const r = await call('POST', '/v1/tts', { text: '你好，我是DSH，蓝色大肥鱼。', mode: 'voice_design' }, 300000);
  const secs = ((Date.now() - t0) / 1000).toFixed(2);
  console.log('  TTS HTTP ' + r.code + '  ct=' + (r.ctype||'-') + '  bytes=' + (r.buf?r.buf.length:0) + '  ' + secs + 's');
  if (r.code === 200 && r.buf && r.buf.length > 10000) {
    console.log('  RIFF header: ' + (r.buf.slice(0,4).toString() === 'RIFF'));
    fs.writeFileSync('D:\\AI_file\\outputs\\tts-first.wav', r.buf);
    console.log('  SAVED D:\\AI_file\\outputs\\tts-first.wav');
  } else if (r.buf) {
    console.log('  ' + r.buf.toString('utf8').replace(/\s+/g,' ').slice(0, 500));
  }
})();
