$js = @'
const https = require('https');
function quick(u, ms) {
  const t0 = Date.now();
  return new Promise((res) => {
    const req = https.get(u, { headers: { 'User-Agent': 'dsh' } }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(quick(new URL(x.headers.location, u).toString(), ms)); return; }
      let d = ''; let n = 0;
      x.on('data', (c) => { n += c.length; if (d.length < 3000) d += c.toString(); if (n > 200000) x.destroy(); });
      x.on('close', () => res({ code: x.statusCode, len: n, body: d, ms: Date.now() - t0 }));
      x.on('end', () => res({ code: x.statusCode, len: n, body: d, ms: Date.now() - t0 }));
    });
    req.on('error', (e) => res({ code: 0, err: String(e.code || e.message).slice(0, 40), ms: Date.now() - t0 }));
    req.setTimeout(ms, () => { req.destroy(); res({ code: 'timeout', ms: Date.now() - t0 }); });
  });
}
(async () => {
  console.log('=== connectivity ===');
  for (const [l, u] of [['hf direct ', 'https://huggingface.co'], ['hf-mirror ', 'https://hf-mirror.com'], ['modelscope', 'https://modelscope.cn'], ['ms dataset', 'https://modelscope.cn/api/v1/datasets/YinZilu/da-fei-yu-girl-voice-zh']]) {
    const r = await quick(u, 12000);
    console.log('  ' + l + ' HTTP ' + String(r.code).padEnd(10) + (r.err || (r.len + ' B / ' + (r.ms/1000).toFixed(1) + 's')) + '  ' + r.ms + 'ms');
  }
  console.log('');
  console.log('=== ModelScope dataset API variants ===');
  const D = 'YinZilu/da-fei-yu-girl-voice-zh';
  const variants = [
    '/api/v1/datasets/' + D,
    '/api/v1/datasets/' + D + '/repo/tree?Revision=master',
    '/api/v1/datasets/' + D + '/repo/files?Revision=master',
    '/api/v1/datasets/' + D + '/repo/files?Revision=master&Root=%2F',
    '/api/v1/datasets/' + D + '/repo/files?Revision=master&Recursive=true',
  ];
  for (const p of variants) {
    const r = await quick('https://modelscope.cn' + p, 15000);
    console.log('  ' + p.slice(0, 78).padEnd(80) + 'HTTP ' + String(r.code));
    if (r.code === 200 && r.body) console.log('      ' + r.body.replace(/\s+/g, ' ').slice(0, 260));
  }
})();
