$js = @'
const https = require('https');
const fs = require('fs');
function get(u, ms) { return new Promise((res) => { const r = https.get(u, { headers: { 'User-Agent': 'dsh' } }, (x) => { if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(get(new URL(x.headers.location, u).toString(), ms)); return; } const cs = []; x.on('data', (c) => cs.push(c)); x.on('end', () => res({ code: x.statusCode, ctype: x.headers['content-type'], buf: Buffer.concat(cs) })); }); r.on('error', (e) => res({ code: 0, err: String(e.message) })); r.setTimeout(ms || 60000, () => { r.destroy(); res({ code: 'timeout' }); }); }); }
(async () => {
  const D = 'YinZilu/da-fei-yu-girl-voice-zh';
  const OUT = 'D:\\AI_file\\datasets\\dafeiyu-voice';
  fs.mkdirSync(OUT, { recursive: true });

  console.log('=== download one WAV reference ===');
  const f = 'train/audio/dwg_0031.wav';
  const url = 'https://modelscope.cn/api/v1/datasets/' + D + '/repo?Revision=master&FilePath=' + encodeURIComponent(f);
  const r = await get(url, 120000);
  console.log('  HTTP ' + r.code + '  ctype=' + (r.ctype || '-') + '  bytes=' + (r.buf ? r.buf.length : 0));
  if (r.code === 200 && r.buf && r.buf.length > 10000 && r.buf.slice(0, 4).toString() === 'RIFF') {
    const p = OUT + '\\ref-dwg-0031.wav';
    fs.writeFileSync(p, r.buf);
    console.log('  SAVED ' + p);
  } else {
    console.log('  head: ' + (r.buf ? r.buf.slice(0, 40).toString() : '(none)'));
  }

  console.log('');
  console.log('=== also grab metadata.csv (text per clip) ===');
  const m = await get('https://modelscope.cn/api/v1/datasets/' + D + '/repo?Revision=master&FilePath=' + encodeURIComponent('train/metadata.csv'), 60000);
  if (m.code === 200 && m.buf) {
    const p = OUT + '\\metadata.csv';
    fs.writeFileSync(p, m.buf);
    const lines = m.buf.toString('utf8').split('\n');
    console.log('  SAVED ' + p + '  (' + lines.length + ' lines)');
    console.log('  header: ' + lines[0]);
    for (const l of lines.slice(1, 4)) console.log('  ' + l.slice(0, 120));
  }

  console.log('');
  console.log('=== /v1/tts request schema (voice_clone params) ===');
  const o = await get('http://127.0.0.1:17860/openapi.json', 15000);
  if (o.code === 200) {
    const j = JSON.parse(o.buf.toString('utf8'));
    const paths = Object.keys(j.paths || {});
    console.log('  paths: ' + paths.join(', '));
    for (const p of paths) {
      if (!/tts|speech|voices/.test(p)) continue;
      for (const [mth, op] of Object.entries(j.paths[p])) {
        const rb = op.requestBody && op.requestBody.content && op.requestBody.content['application/json'];
        const schema = rb && rb.schema ? (rb.schema.$ref ? rb.schema.$ref.split('/').pop() : JSON.stringify(rb.schema)) : null;
        console.log('  ' + mth.toUpperCase() + ' ' + p + '  body=' + (schema || 'none') + '  params=' + JSON.stringify((op.parameters || []).map((x) => x.name)));
      }
    }
  }
})();
