$js = @'
const https = require('https');
const http = require('http');
const fs = require('fs');
function fetchUrl(u, ms, depth) {
  depth = depth || 0;
  return new Promise((res) => {
    const mod = u.startsWith('https') ? https : http;
    const req = mod.get(u, { headers: { 'User-Agent': 'dsh' } }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location && depth < 6) {
        x.resume();
        const nx = new URL(x.headers.location, u).toString();
        return res(fetchUrl(nx, ms, depth + 1));
      }
      const cs = []; let n = 0;
      x.on('data', (c) => { cs.push(c); n += c.length; });
      x.on('end', () => res({ code: x.statusCode, ctype: x.headers['content-type'], buf: Buffer.concat(cs), finalUrl: u }));
    });
    req.on('error', (e) => res({ code: 0, err: String(e.message).slice(0, 60) }));
    req.setTimeout(ms, () => { req.destroy(); res({ code: 'timeout' }); });
  });
}
(async () => {
  const D = 'YinZilu/da-fei-yu-girl-voice-zh';
  const OUT = 'D:\\AI_file\\datasets\\dafeiyu-voice';
  fs.mkdirSync(OUT, { recursive: true });
  const f = 'train/audio/dwg_0031.wav';

  const variants = [
    'https://modelscope.cn/api/v1/datasets/' + D + '/repo?Revision=master&FilePath=' + encodeURIComponent(f),
    'https://modelscope.cn/api/v1/datasets/' + D + '/repo/resolve/master/' + f,
    'https://modelscope.cn/models/' + D + '/resolve/master/' + f,
  ];
  for (const u of variants) {
    console.log('  try ' + u.slice(0, 100));
    const r = await fetchUrl(u, 180000);
    const ok = r.buf && r.buf.length > 10000;
    console.log('    HTTP ' + String(r.code).padEnd(9) + (r.err || (r.buf ? r.buf.length + ' B' : '-')) + (ok ? '  RIFF=' + (r.buf.slice(0, 4).toString() === 'RIFF') : ''));
    if (ok && r.buf.slice(0, 4).toString() === 'RIFF') {
      const p = OUT + '\\ref-dwg-0031.wav';
      fs.writeFileSync(p, r.buf);
      console.log('    SAVED ' + p + ' (' + r.buf.length + ' bytes)');
      break;
    }
  }

  console.log('');
  console.log('=== openapi.json via http ===');
  const o = await fetchUrl('http://127.0.0.1:17860/openapi.json', 20000);
  if (o.code === 200) {
    const j = JSON.parse(o.buf.toString('utf8'));
    const comps = (j.components && j.components.schemas) || {};
    for (const p of Object.keys(j.paths || {})) {
      if (!/tts|speech|voices/.test(p)) continue;
      for (const [m, op] of Object.entries(j.paths[p])) {
        const rb = op.requestBody && op.requestBody.content && op.requestBody.content['application/json'];
        let ref = rb && rb.schema ? (rb.schema.$ref || '').split('/').pop() : null;
        console.log('  ' + m.toUpperCase() + ' ' + p.padEnd(22) + ' schema=' + ref);
        if (ref && comps[ref]) {
          const props = comps[ref].properties || {};
          console.log('    ' + Object.entries(props).map(([k, v]) => k + ':' + (v.type || (v.anyOf ? 'any' : '?'))).join(', ').slice(0, 400));
        }
      }
    }
  } else {
    console.log('  HTTP ' + o.code + ' ' + (o.err || ''));
  }
})();
