{"command": "$ErrorActionPreference = 'Continue'
$js = @'
const http = require('http');
const fs = require('fs');
function post(path, body, ms) {
  return new Promise((res) => {
    const payload = JSON.stringify(body);
    const r = http.request({ host: '127.0.0.1', port: 17860, path: path, method: 'POST', headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) } }, (x) => {
      const cs = []; x.on('data', (c) => cs.push(c));
      x.on('end', () => res({ code: x.statusCode, ctype: x.headers['content-type'], buf: Buffer.concat(cs) }));
    });
    r.on('error', (e) => res({ code: 0, err: String(e.message) }));
    r.setTimeout(ms || 300000, () => { r.destroy(); res({ code: 'timeout' }); });
    r.write(payload); r.end();
  });
}
async function attempt(label, path, body) {
  const t0 = Date.now();
  const r = await post(path, body, 300000);
  const secs = ((Date.now() - t0) / 1000).toFixed(2);
  const ok = r.code === 200 && r.buf && r.buf.length > 10000;
  console.log('  ' + label.padEnd(40) + 'HTTP ' + String(r.code).padEnd(5) + ' ' + (ok ? r.buf.length + ' B' : (r.buf ? r.buf.toString('utf8').replace(/\s+/g,' ').slice(0, 180) : '-')) + '  ' + secs + 's');
  if (ok) {
    const isWav = r.buf.slice(0, 4).toString() === 'RIFF';
    if (isWav) {
      fs.writeFileSync('D:\\AI_file\\outputs\\tts-first.wav', r.buf);
      console.log('    >>> SAVED D:\\AI_file\\outputs\\tts-first.wav (' + r.buf.length + ' bytes, RIFF ok)');
      return true;
    }
    console.log('    (not RIFF, first bytes: ' + r.buf.slice(0, 12).toString('hex') + ')');
  }
  return false;
}
(async () => {
  const REF = 'D:/AI_file/datasets/dafeiyu-voice/ref-dwg-0031.wav';
  const TXT = '你好，我是DSH，蓝色大肥鱼。';

  console.log('=== voice_clone attempts ===');
  if (await attempt('refAudio + refText', '/v1/tts', { mode: 'voice_clone', text: TXT, refAudio: REF, refText: '这是一段用于音色克隆的参考音频。', language: 'chinese' })) return;
  if (await attempt('refAudio only', '/v1/tts', { mode: 'voice_clone', text: TXT, refAudio: REF })) return;
  if (await attempt('ref_audio (snake)', '/v1/tts', { mode: 'voice_clone', text: TXT, ref_audio: REF })) return;
  if (await attempt('speaker=path', '/v1/tts', { mode: 'voice_clone', text: TXT, speaker: REF })) return;

  console.log('');
  console.log('=== probe: what does /v1/tts want? send empty body ===');
  const r = await post('/v1/tts', {}, 20000);
  console.log('  HTTP ' + r.code + '  ' + (r.buf ? r.buf.toString('utf8').replace(/\s+/g,' ').slice(0, 400) : ''));
})();
'@
$js | & 'D:\program_runtime_environment\nodejs\node.exe' 2>&1 | ForEach-Object { Write-Output $_ }", "description": "Try voice_clone with discovered field names", "timeoutMs": 900000}

