        $d = if ($val -is [string]) { $val } else { '[' + (($val.PSObject.Properties | ForEach-Object { $_.Name + '=' + $_.Value }) -join '; ') + ']' }
        Write-Output ('    ' + $_.Name.PadRight(22) + $d)
    }
    Write-Output '  graph_variants:'
