import io, json, os, shutil
root = os.path.join(os.environ['LOCALAPPDATA'], 'qwen3-tts-openvino', 'models',
                    'waston10086--qwen3-tts-openvino-voice-design--main', 'openvino_realtime')
for variant in ('base', 'voice_design'):
    p = os.path.join(root, variant, 'manifest.json')
    if not os.path.exists(p):
        print(variant, 'missing'); continue
    shutil.copy2(p, p + '.bak2')
    with io.open(p, 'r', encoding='utf-8') as f:
        m = json.load(f)
    g = m.get('graphs', {})
    if 'talker' in g:
        print(variant, 'already has graphs.talker')
        continue
    seed = g.get('paged_kv_seed')
    if isinstance(seed, dict) and len(seed) == 1:
        target = list(seed.values())[0]
    elif isinstance(seed, str):
        target = seed
    else:
        target = 'talker_stateful_batch_sdpa_paged_gqa_seed_int8_sym_batch_fused_gqa.xml'
    g['talker'] = target
    m['graphs'] = g
    with io.open(p, 'w', encoding='utf-8') as f:
        json.dump(m, f, indent=2, ensure_ascii=False)
    print('%s: graphs.talker = %s' % (variant, target))
    with io.open(p, 'r', encoding='utf-8') as f:
        m2 = json.load(f)
    print('  verify:', 'talker' in m2['graphs'])
