{"content": "// Test every generation path against the local Qwen3-TTS server.
// Field names were read out of the web console's own JSON.stringify call, not guessed:
//   mode, text, instruct, speaker, refText, language  (+ refAudio from the upload control)
const http = require('http');
const fs = require('fs');

const OUT = 'D:\\AI_file\\outputs\\tts-first.wav';
const REF = 'D:/AI_file/datasets/dafeiyu-voice/ref-dwg-0031.wav';
const TXT = '你好，我是DSH，蓝色大肥鱼。';

function post(path, body, ms) {
  return new Promise((res) => {
    const payload = JSON.stringify(body);
    const r = http.request({
      host: '127.0.0.1', port: 17860, path, method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) },
    }, (x) => {
      const cs = [];
      x.on('data', (c) => cs.push(c));
      x.on('end', () => res({ code: x.statusCode, ctype: x.headers['content-type'], buf: Buffer.concat(cs) }));
    });
    r.on('error', (e) => res({ code: 0, err: String(e.message) }));
    r.setTimeout(ms || 300000, () => { r.destroy(); res({ code: 'timeout' }); });
    r.write(payload);
    r.end();
  });
}

async function attempt(label, path, body) {
  const t0 = Date.now();
  const r = await post(path, body, 300000);
  const secs = ((Date.now() - t0) / 1000).toFixed(2);
  if (r.code === 200 && r.buf && r.buf.length > 10000) {
    const riff = r.buf.slice(0, 4).toString() === 'RIFF';
    console.log('  ' + label.padEnd(36) + 'HTTP 200  ' + r.buf.length + ' B  RIFF=' + riff + '  ' + secs + 's');
    if (riff) {
      fs.writeFileSync(OUT, r.buf);
      console.log('    >>> SAVED ' + OUT);
      return true;
    }
  } else {
    const msg = r.buf ? r.buf.toString('utf8').replace(/\s+/g, ' ').slice(0, 230) : (r.err || '-');
    console.log('  ' + label.padEnd(36) + 'HTTP ' + String(r.code).padEnd(5) + msg + '  ' + secs + 's');
  }
  return false;
}

(async () => {
  console.log('=== voice_clone ===');
  if (await attempt('refAudio + refText + language', '/v1/tts', { mode: 'voice_clone', text: TXT, refAudio: REF, refText: '这是一段参考音频。', language: 'chinese' })) return;
  if (await attempt('refAudio only', '/v1/tts', { mode: 'voice_clone', text: TXT, refAudio: REF })) return;
  if (await attempt('refAudio + language', '/v1/tts', { mode: 'voice_clone', text: TXT, refAudio: REF, language: 'chinese' })) return;

  console.log('');
  console.log('=== voice_design (instruct) ===');
  if (await attempt('instruct 少女音', '/v1/tts', { mode: 'voice_design', text: TXT, instruct: '少女音，软一点，活泼。', language: 'chinese' })) return;

  console.log('');
  console.log('=== custom_voice (probably missing IR) ===');
  await attempt('custom_voice default', '/v1/tts', { mode: 'custom_voice', text: TXT, language: 'chinese' });

  console.log('');
  console.log('=== last resort: /v1/audio/speech with mode ===');
  await attempt('speech voice_clone', '/v1/audio/speech', { mode: 'voice_clone', input: TXT, refAudio: REF, response_format: 'wav' });
})();
", "file_path": "D:\AI_file\tools\test-tts.cjs"}

