content.arguments:
{"content": """"Dump every input/output shape of the TTS OpenVINO IR and flag unbounded dimensions.

The NPU compiler rejects a graph when any dynamic dimension lacks an upper bound
("Missing upper bound for one or more nodes"). This inspects each IR's Parameter and
Result nodes so we know exactly which dimension needs a bound and how big it must be.
"""
import glob
import os

import openvino as ov

ROOT = os.path.join(
    os.environ["LOCALAPPDATA"], "qwen3-tts-openvino", "models",
    "waston10086--qwen3-tts-openvino-voice-design--main", "openvino_realtime",
)

core = ov.Core()


def describe(dim):
    """Return (label, is_unbounded)."""
    try:
        lo = dim.get_min_length()
        hi = dim.get_max_length()
    except Exception:
        return (str(dim), False)
    if not dim.is_dynamic:
        return (str(lo), False)
    if hi >= 2**31 - 1 or hi < 0:
        return ("%d..UNBOUNDED" % lo, True)
    return ("%d..%d" % (lo, hi), True)


for variant in ("base", "voice_design"):
    d = os.path.join(ROOT, variant)
    if not os.path.isdir(d):
        continue
    print("=" * 70)
    print("VARIANT: " + variant)
    print("=" * 70)
    for xml in sorted(glob.glob(os.path.join(d, "*.xml"))):
        name = os.path.basename(xml)
        try:
            model = core.read_model(xml)
        except Exception as e:
            print("  %-58s READ FAIL: %s" % (name, str(e)[:60]))
            continue
        unbounded = []
        notes = []
        for inp in model.inputs:
            parts = []
            for i, dim in enumerate(inp.get_partial_shape()):
                label, isdyn = describe(dim)
                parts.append(label)
                if isdyn and "UNBOUNDED" in label:
                    unbounded.append((inp.get_any_name(), i, label))
            notes.append("in  %-22s [%s]" % (inp.get_any_name(), ", ".join(parts)))
        for out in model.outputs:
            parts = []
            for dim in out.get_partial_shape():
                label, _ = describe(dim)
                parts.append(label)
            notes.append("out %-22s [%s]" % (out.get_any_name(), ", ".join(parts)))
        flag = "  <<< UNBOUNDED" if unbounded else ""
        print("  " + name + flag)
        for n in notes:
            print("      " + n)
        for u in unbounded:
            print("      !! input=%s dim=%d %s" % u)
print("")
print("done")
", "file_path": "D:\AI_file\tools\inspect-ir-shapes.py"}

