        except Exception as e:
            print("  %-56s READ FAIL %s" % (name, str(e)[:50]))
            continue
        bad = []
        rows = []
        for idx, inp in enumerate(m.inputs):
            parts = []
            for i, dim in enumerate(inp.get_partial_shape()):
                s, unb = fmt_dim(dim)
