            for dim in out.get_partial_shape():
                s, _ = fmt_dim(dim)
                parts.append(s)
            rows.append("out %-20s [%s]" % (safe_name(out, "out%d" % idx), ", ".join(parts)))
        print("  " + name + ("   <<< UNBOUNDED" if bad else ""))
