{"content": """"Give every unbounded dimension an explicit upper bound, then save the IR in place.

Reasoning: the NPU compiler rejects graphs whose dynamic dims have no upper bound
("Missing upper bound for one or more nodes"). The manifest already declares the intended
bounds (max_cache_len 384, cache_buckets up to 384, chunk_frames <= 24, left_context 25), so
this reshapes each graph with those bounds and writes the IR back. Originals are copied to
*.xml.unbounded.bak first.

Bounds are deliberately conservative: an over-large bound costs NPU memory, and an over-small
one breaks long generations, so text/code lengths get 512 and the talker's sequence dimension
follows max_cache_len (384).
"""
import glob
import os
import shutil

import openvino as ov

ROOT = os.path.join(
    os.environ["LOCALAPPDATA"], "qwen3-tts-openvino", "models",
    "waston10086--qwen3-tts-openvino-voice-design--main", "openvino_realtime",
)

BATCH_MAX = 4
TEXT_MAX = 512          # token ids per call
CODE_MAX = 2048         # audio code frames per chunk
MELS_MAX = 3000         # speaker encoder mel frames
SEQ_MAX = 384           # talker cache length, matches manifest max_cache_len
AUDIO_MAX = 480000      # speech encoder raw samples (20 s @ 24 kHz)

core = ov.Core()

# per-graph bound overrides: basename -> {input_name: [bounds per dim]}
OVERRIDES = {
    "text_embedding.xml": {"input_ids": [1, TEXT_MAX]},
    "codec_embedding.xml": {"input_ids": [1, TEXT_MAX]},
    "code_frame_embedding.xml": {"107": [1, CODE_MAX, 16]},
    "speech_decoder_stream_c0_t8.xml": {"audio_codes": [1, CODE_MAX, 16]},
    "speech_decoder_stream_c25_t12.xml": {"audio_codes": [1, CODE_MAX, 16]},
    "speech_decoder_stream_c25_t24.xml": {"audio_codes": [1, CODE_MAX, 16]},
    "speaker_encoder.xml": {"mels": [1, MELS_MAX, 128]},
    "speech_encoder.xml": {"input_values": [1, AUDIO_MAX], "padding_mask": [1, AUDIO_MAX]},
    "talker_stateful_batch_sdpa_paged_gqa_seed_int8_sym_batch_fused_gqa.xml": {
        "inputs_embeds": [BATCH_MAX, 1, 2048],
        "position_ids": [3, SEQ_MAX, 1],
        "attention_mask": [BATCH_MAX, 1, 1, SEQ_MAX],
        "beam_idx": [BATCH_MAX],
    },
}


def bounded_shape(shape):
    """Turn a bounded-or-unbounded shape into a fully static one using the declared upper bound."""
    out = []
    for d in shape:
        try:
            if d.is_dynamic:
                hi = d.get_max_length()
                if hi < 0 or hi >= 2**31 - 1:
                    return None          # still unbounded, needs an override
                out.append(hi)
            else:
                out.append(d.get_length())
        except Exception:
            return None
    return out


def process(variant):
    d = os.path.join(ROOT, variant)
    if not os.path.isdir(d):
        return
    print("=" * 66)
    print("VARIANT: " + variant)
    print("=" * 66)
    for xml in sorted(glob.glob(os.path.join(d, "*.xml"))):
        name = os.path.basename(xml)
        try:
            model = core.read_model(xml)
        except Exception as e:
            print("  %-56s read fail" % name)
            continue

        target = {}
        used_override = False
        for inp in model.inputs:
            try:
                iname = inp.get_any_name()
            except Exception:
                continue
            bounds = OVERRIDES.get(name, {}).get(iname)
            if bounds is not None:
                target[iname] = bounds
                used_override = True
            else:
                static = bounded_shape(inp.get_partial_shape())
                if static is not None:
                    target[iname] = static

        if not target:
            print("  %-56s SKIP (no inputs)" % name)
            continue

        # any input still unbounded and without override?
        unresolved = []
        for inp in model.inputs:
            try:
                iname = inp.get_any_name()
            except Exception:
                continue
            if iname in target:
                continue
            if any(x.is_dynamic for x in inp.get_partial_shape()):
                hi_list = [x.get_max_length() for x in inp.get_partial_shape() if x.is_dynamic]
                if any(h < 0 or h >= 2**31 - 1 for h in hi_list):
                    unresolved.append(iname)
        if unresolved:
            print("  %-56s SKIP unresolved=%s" % (name, unresolved))
            continue

        try:
            model.reshape({k: ov.PartialShape(v) if hasattr(ov, "PartialShape") else v for k, v in target.items()})
        except Exception:
            try:
                model.reshape(target)
            except Exception as e:
                print("  %-56s reshape FAIL %s" % (name, str(e)[:70]))
                continue

        bak = xml + ".unbounded.bak"
        if not os.path.exists(bak):
            shutil.copy2(xml, bak)
            b = xml.replace(".xml", ".bin")
            if os.path.exists(b):
                shutil.copy2(b, b + ".unbounded.bak")
        ov.save_model(model, xml)
        tag = "static+override" if used_override else "static"
        print("  %-56s OK (%s)" % (name, tag))


for v in ("voice_design", "base"):
    process(v)
print("")
print("done - originals saved as *.unbounded.bak")
