const https = require('https');
function get(u, ms) {
  return new Promise((res) => {
    const r = https.get(u, { headers: { 'User-Agent': 'dsh', Accept: 'application/vnd.github+json' } }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(get(new URL(x.headers.location, u).toString(), ms)); return; }
      let d = ''; x.on('data', (c) => d += c); x.on('end', () => res({ code: x.statusCode, body: d }));
    });
    r.on('error', (e) => res({ code: 0, body: String(e.message) }));
    r.setTimeout(ms || 25000, () => { r.destroy(); res({ code: 0, body: 'timeout' }); });
  });
}
(async () => {
  const R = 'wangtong10086/qwen3-tts-openvino';
  console.log('=== repo info ===');
  const info = await get('https://api.github.com/repos/' + R);
  if (info.code === 200) {
    const j = JSON.parse(info.body);
    console.log('  stars=' + j.stargazers_count + '  license=' + (j.license && j.license.spdx_id) + '  pushed=' + j.pushed_at);
    console.log('  desc: ' + String(j.description || '').slice(0, 120));
    console.log('  default_branch: ' + j.default_branch);
  } else console.log('  HTTP ' + info.code + ' ' + info.body.slice(0, 100));

