{"command": "$ErrorActionPreference = 'Continue'
Write-Output '=== prerequisites ==='
foreach ($t in 'uv','git','node','python') {
    $c = Get-Command $t -ErrorAction SilentlyContinue
    if ($c) { Write-Output ('  ' + $t.PadRight(8) + ' OK   ' + $c.Source) }
    else { Write-Output ('  ' + $t.PadRight(8) + ' MISSING') }
}
Write-Output ''
Write-Output '=== python versions available ==='
foreach ($p in 'D:\AI_file\envs\openvino\Scripts\python.exe','D:\program_runtime_environment\python\3.12.10\python.exe') {
    if (Test-Path -LiteralPath $p) {
        $v = & $p --version 2>&1
        Write-Output ('  ' + $p + ' -> ' + $v)
    }
}
Write-Output ''
Write-Output '=== disk space ==='
foreach ($d in 'D:','E:','C:') {
    $v = Get-PSDrive -Name $d.Replace(':','') -ErrorAction SilentlyContinue
    if ($v) { Write-Output ('  ' + $d + ' free ' + [Math]::Round($v.Free/1GB,1) + ' GB / total ' + [Math]::Round(($v.Used+$v.Free)/1GB,1) + ' GB') }
}
Write-Output ''
Write-Output '=== existing envs ==='
Get-ChildItem -LiteralPath 'D:\AI_file\envs' -Directory -ErrorAction SilentlyContinue | ForEach-Object { Write-Output ('  ' + $_.Name) }
Write-Output ''
Write-Output '=== torch already installed? ==='
& 'D:\AI_file\envs\openvino\Scripts\python.exe' -c "import importlib.util as u; print('  torch:', bool(u.find_spec('torch'))); print('  optimum:', bool(u.find_spec('optimum'))); print('  transformers:', bool(u.find_spec('transformers')))" 2>&1 | ForEach-Object { Write-Output $_ }", "description": "Check prerequisites for the export build", "timeoutMs": 300000}

