content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$work = 'D:\AI_file\build\qwen3-tts'
New-Item -ItemType Directory -Path $work -Force | Out-Null
Set-Location $work

Write-Output '=== clone exporter repo ==='
if (Test-Path -LiteralPath (Join-Path $work 'qwen3-tts-openvino\.git')) {
    Write-Output '  already cloned'
} else {
    & git clone --depth 1 https://github.com/wangtong10086/qwen3-tts-openvino.git 2>&1 | Select-Object -Last 8 | ForEach-Object { Write-Output ('  ' + $_) }
}
Write-Output ''
Write-Output '=== clone official PyTorch repo ==='
if (Test-Path -LiteralPath (Join-Path $work '.cache\Qwen3-TTS\.git')) {
    Write-Output '  already cloned'
} else {
    & git clone --depth 1 https://github.com/QwenLM/Qwen3-TTS .cache/Qwen3-TTS 2>&1 | Select-Object -Last 8 | ForEach-Object { Write-Output ('  ' + $_) }
}
Write-Output ''
Write-Output '=== what we got ==='
foreach ($d in 'qwen3-tts-openvino','.cache\Qwen3-TTS') {
    $p = Join-Path $work $d
    if (Test-Path -LiteralPath $p) {
        $n = @(Get-ChildItem -LiteralPath $p -Recurse -File -ErrorAction SilentlyContinue).Count
        Write-Output ('  ' + $d + ': ' + $n + ' files')
    } else { Write-Output ('  ' + $d + ': MISSING') }
}", "description": "Clone the exporter and official PyTorch repos", "timeoutMs": 900000}

