content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$work = 'D:\AI_file\build\qwen3-tts'
Write-Output ('=== ' + (Get-Date).ToString('HH:mm:ss') + ' ===')
foreach ($d in 'qwen3-tts-openvino','.cache\Qwen3-TTS') {
    $p = Join-Path $work $d
    if (Test-Path -LiteralPath $p) {
        $n = @(Get-ChildItem -LiteralPath $p -Recurse -File -ErrorAction SilentlyContinue)
        $sz = ($n | Measure-Object -Property Length -Sum).Sum
        Write-Output ('  ' + $d.PadRight(22) + $n.Count.ToString().PadLeft(6) + ' files, ' + [Math]::Round($sz/1MB,1) + ' MB')
    } else { Write-Output ('  ' + $d + ': MISSING') }
}
Write-Output ''
Write-Output '=== git processes still running ==='
Write-Output ('  ' + @(Get-Process -Name 'git' -ErrorAction SilentlyContinue).Count)
Write-Output ''
Write-Output '=== restore GPU service while waiting ==='
if (@(Get-Process -Name 'qwen3-tts-ov-server' -ErrorAction SilentlyContinue).Count -eq 0) {
    $exe = 'D:\AI_file\tools\qwen3-tts-ov\qwen3-tts-ov-server.exe'
    Start-Process -FilePath $exe -ArgumentList '--device','GPU' -WorkingDirectory (Split-Path $exe) -WindowStyle Hidden | Out-Null
    for ($i = 1; $i -le 24; $i++) { Start-Sleep -Seconds 5; if (Test-NetConnection -ComputerName '127.0.0.1' -Port 17860 -InformationLevel Quiet -WarningAction SilentlyContinue) { Write-Output ('  GPU service up after ' + ($i*5) + 's'); break } }
} else { Write-Output '  already running' }", "description": "Check clone progress and restore GPU service", "timeoutMs": 300000}

