{"command": "$ErrorActionPreference = 'Continue'
Write-Output '=== is the clone actually progressing? ==='
$gitdir = 'D:\AI_file\build\qwen3-tts\.cache\Qwen3-TTS\.git'
if (Test-Path -LiteralPath $gitdir) {
    $n = @(Get-ChildItem -LiteralPath $gitdir -Recurse -File -ErrorAction SilentlyContinue)
    Write-Output ('  .git: ' + $n.Count + ' files, ' + [Math]::Round((($n | Measure-Object -Property Length -Sum).Sum)/1MB,1) + ' MB')
}
Write-Output ''
Write-Output '=== kill stuck clone, use zip instead ==='
Get-CimInstance Win32_Process -Filter "Name='git.exe'" -ErrorAction SilentlyContinue | Where-Object { $_.CommandLine -match 'Qwen3-TTS' } | ForEach-Object {
    Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue
    Write-Output ('  killed git ' + $_.ProcessId)
}
Start-Sleep -Seconds 2
Remove-Item -LiteralPath 'D:\AI_file\build\qwen3-tts\.cache\Qwen3-TTS' -Recurse -Force -ErrorAction SilentlyContinue
Write-Output ('  removed partial clone: ' + (-not (Test-Path -LiteralPath 'D:\AI_file\build\qwen3-tts\.cache\Qwen3-TTS')))
Write-Output ''
Write-Output '=== download zip (codeload) ==='
$js = @'
const https = require('https');
const fs = require('fs');
function follow(u, ms, depth, cb) {
  depth = depth || 0;
  if (depth > 6) return cb(new Error('too many redirects'));
  https.get(u, { headers: { 'User-Agent': 'dsh', 'Accept': 'application/zip' } }, (x) => {
    if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) {
      x.resume();
      return follow(new URL(x.headers.location, u).toString(), ms, depth + 1, cb);
    }
    cb(null, x);
  }).on('error', (e) => cb(e));
}
(async () => {
  const url = 'https://codeload.github.com/QwenLM/Qwen3-TTS/zip/refs/heads/main';
  const out = 'D:\\AI_file\\build\\qwen3-tts\\qwen3-tts-main.zip';
  await new Promise((res) => {
    follow(url, 120000, 0, (err, res) => {
      if (err) { console.log('  error: ' + err.message); return res(); }
      console.log('  HTTP ' + res.statusCode + '  len=' + (res.headers['content-length'] || '?'));
      const ws = fs.createWriteStream(out);
      let got = 0;
      res.on('data', (c) => { got += c.length; });
      res.pipe(ws);
      ws.on('finish', () => { console.log('  saved ' + (got/1048576).toFixed(1) + ' MB -> ' + out); res(); });
      res.on('error', (e) => { console.log('  stream error: ' + e.message); res(); });
    });
  });
})();
