{"command": "$ErrorActionPreference = 'Continue'
$pt = 'D:\AI_file\build\qwen3-tts\Qwen3-TTS-main\pyproject.toml'
Write-Output '=== Qwen3-TTS pyproject dependencies ==='
if (Test-Path -LiteralPath $pt) {
    $t = [System.IO.File]::ReadAllText($pt, [System.Text.Encoding]::UTF8)
    $lines = $t -split "`r?`n"
    $inDeps = $false
    for ($i = 0; $i -lt $lines.Count; $i++) {
        $l = $lines[$i]
        if ($l -match '^dependencies\s*=') { $inDeps = $true }
        if ($inDeps) {
            Write-Output ('  ' + $l)
            if ($l -match '^\s*\]') { $inDeps = $false; Write-Output '' }
        }
    }
    Write-Output '  --- requires-python ---'
    $lines | Where-Object { $_ -match 'requires-python|^\s*version\s*=' } | Select-Object -First 5 | ForEach-Object { Write-Output ('  ' + $_.Trim()) }
}
Write-Output ''
Write-Output '=== current transformers version ==='
& 'D:\AI_file\envs\openvino\Scripts\python.exe' -c "import transformers; print('  ', transformers.__version__)" 2>&1 | ForEach-Object { Write-Output $_ }", "description": "Check Qwen3-TTS required versions", "timeoutMs": 180000}

