$py = @'
import os
import openvino as ov

OUT = r'D:\AI_file\build\qwen3-tts\openvino\voice_design'
core = ov.Core()

def fmt(dim):
    try:
        if not dim.is_dynamic:
            return str(dim.get_min_length()), False
        lo, hi = dim.get_min_length(), dim.get_max_length()
        if hi >= 2**31 - 1 or hi < 0:
            return '%d..UNBOUNDED' % lo, True
        return '%d..%d' % (lo, hi), False
    except Exception:
        return str(dim), False

key = 'talker_stateful_batch_sdpa_paged_gqa_seed.xml'
path = os.path.join(OUT, key)
print('=== KEY GRAPH: ' + key + ' ===')
m = core.read_model(path)
bad = 0
for i, inp in enumerate(m.inputs):
    try:
        nm = inp.get_any_name()
    except Exception:
        nm = 'in%d' % i
    parts = []
    for dim in inp.get_partial_shape():
        s, unb = fmt(dim)
        parts.append(s)
        if unb:
            bad += 1
    print('  in  %-18s [%s]' % (nm, ', '.join(parts)))
for i, out in enumerate(m.outputs):
    parts = []
    for dim in out.get_partial_shape():
        s, _ = fmt(dim)
        parts.append(s)
    print('  out %-18s [%s]' % ('out%d' % i, ', '.join(parts)))
print('  => unbounded dims: %d' % bad)
print('')
print('=== scan all xml for unbounded dims ===')
total_bad = 0
for fn in sorted(os.listdir(OUT)):
    if not fn.endswith('.xml'):
        continue
    try:
        mm = core.read_model(os.path.join(OUT, fn))
    except Exception:
        continue
    cnt = 0
    for inp in mm.inputs:
        for dim in inp.get_partial_shape():
            if dim.is_dynamic:
                hi = dim.get_max_length()
                if hi < 0 or hi >= 2**31 - 1:
                    cnt += 1
    if cnt:
        print('  %-58s %d unbounded' % (fn, cnt))
        total_bad += cnt
print('  TOTAL unbounded dims across all graphs: %d' % total_bad)
