content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
Write-Output '=== stop old GPU service ==='
$p = @(Get-Process -Name 'qwen3-tts-ov-server' -ErrorAction SilentlyContinue)
foreach ($x in $p) { Stop-Process -Id $x.Id -Force }
Write-Output ('  stopped ' + $p.Count)
Start-Sleep -Seconds 4

Write-Output ''
Write-Output '=== start with --device NPU and the new bounded IR ==='
$exe = 'D:\AI_file\tools\qwen3-tts-ov\qwen3-tts-ov-server.exe'
$root = 'D:\AI_file\build\qwen3-tts\openvino'
Start-Process -FilePath $exe -ArgumentList '--device','NPU','--model-root',$root -WorkingDirectory (Split-Path $exe) -WindowStyle Hidden | Out-Null
for ($i = 1; $i -le 30; $i++) {
    Start-Sleep -Seconds 5
    if (Test-NetConnection -ComputerName '127.0.0.1' -Port 17860 -InformationLevel Quiet -WarningAction SilentlyContinue) { Write-Output ('  port up after ' + ($i*5) + 's'); break }
}
Start-Sleep -Seconds 20
Write-Output ''
Write-Output '=== health ==='
$js = @'
const http = require('http');
function get(p) { return new Promise((res) => { const r = http.request({ host: '127.0.0.1', port: 17860, path: p, method: 'GET' }, (x) => { let d=''; x.on('data',(c)=>d+=c); x.on('end',()=>res({code:x.statusCode,body:d})); }); r.on('error',(e)=>res({code:0,body:String(e.message)})); r.setTimeout(30000,()=>{r.destroy();res({code:'timeout',body:''})}); r.end(); }); }
(async () => {
  try {
    const h = JSON.parse((await get('/health')).body);
    console.log('  ok=' + h.ok + '  warmup=' + (h.warmup||{}).status);
    console.log('  errors=' + JSON.stringify((h.warmup||{}).errors || '(none)').slice(0, 400));
    console.log('  model_root=' + String(h.model_root || '').slice(-70));
  } catch (e) { console.log('  health parse fail'); }
  try {
    const m = JSON.parse((await get('/v1/models')).body);
    for (const [k, v] of Object.entries(m.available_modes || {})) {
      console.log('  ' + k.padEnd(14) + 'available=' + String(v.available).padEnd(6) + ' status=' + String((v.download||{}).status));
    }
  } catch (e) {}
})();
'@
& 'D:\program_runtime_environment\nodejs\node.exe' -e $js 2>&1 | ForEach-Object { Write-Output $_ }", "description": "Start NPU service with bounded IR", "timeoutMs": 600000}

