Write-Output '=== quick functional check ==='
$js = @'
const http = require('http');
const fs = require('fs');
function post(path, body, ms) {
  return new Promise((res) => {
    const payload = JSON.stringify(body);
    const r = http.request({ host: '127.0.0.1', port: 17860, path, method: 'POST', headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) } }, (x) => {
      const cs = []; x.on('data', (c) => cs.push(c));
      x.on('end', () => res({ code: x.statusCode, ctype: x.headers['content-type'], buf: Buffer.concat(cs) }));
    });
    r.on('error', (e) => res({ code: 0, err: String(e.message) }));
    r.setTimeout(ms || 300000, () => { r.destroy(); res({ code: 'timeout' }); });
    r.write(payload); r.end();
  });
}
(async () => {
  const t0 = Date.now();
  const r = await post('/v1/tts', { mode: 'voice_design', text: 'NPU 那条路走不通，但我还在。', instruct: '少女音，平静。', language: 'chinese' }, 300000);
  const secs = ((Date.now() - t0) / 1000).toFixed(2);
  if (r.code === 200 && r.buf && r.buf.length > 10000 && r.buf.slice(0,4).toString() === 'RIFF') {
    fs.writeFileSync('D:\\AI_file\\outputs\\tts-restored.wav', r.buf);
    console.log('  GPU restored: HTTP 200  ' + r.buf.length + ' B  ' + secs + 's  RIFF ok');
  } else {
    console.log('  GPU restore FAILED: HTTP ' + r.code + '  ' + (r.buf ? r.buf.toString('utf8').slice(0, 200) : r.err));
  }
})();
