$js = @'
const https = require('https');
function get(u, ms) { return new Promise((res) => { const r = https.get(u, { headers: { 'User-Agent': 'dsh' } }, (x) => { if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(get(new URL(x.headers.location, u).toString(), ms)); return; } let d = ''; x.on('data', (c) => d += c); x.on('end', () => res({ code: x.statusCode, body: d })); }); r.on('error', (e) => res({ code: 0, body: String(e.message) })); r.setTimeout(ms || 20000, () => { r.destroy(); res({ code: 0, body: 'timeout' }); }); }); }
(async () => {
  for (const m of ['Qwen/Qwen3-TTS-12Hz-0.6B-VoiceDesign', 'Qwen/Qwen3-TTS-12Hz-0.6B-Base', 'Qwen/Qwen3-TTS-12Hz-0.6B-CustomVoice']) {
    const r = await get('https://huggingface.co/api/models/' + m);
    if (r.code === 200) {
      const j = JSON.parse(r.body);
      const sf = (j.siblings || []).find((s) => s.rfilename && s.rfilename.endsWith('.safetensors'));
      console.log('  ' + m.padEnd(44) + 'OK  files=' + (j.siblings || []).length);
    } else {
      console.log('  ' + m.padEnd(44) + 'HTTP ' + r.code);
    }
  }
})();
