content.arguments:
{"content": """"Split Chinese/English text into chunks that fit a fixed token budget.

Why this exists: the NPU only accepts static shapes, so the exported IR has a hard
input_ids length of 512. Anything longer must be cut before synthesis, synthesised piece by
piece, then concatenated. This module owns that cutting.

Strategy (three levels, because real text breaks all of them):
  1. split on sentence terminators, keep the terminator with its sentence
  2. greedily merge sentences while the token count stays under budget
  3. a single sentence still too long gets bisected on character boundaries,
     preferring punctuation near the midpoint so the cut sounds natural

Counting uses the real tokenizer when available; otherwise it falls back to a conservative
character heuristic (CJK ~1 token/char, Latin ~1 token/3.5 chars), which over-estimates so we
never send something too long.
"""
from __future__ import annotations

import re
from typing import Callable, List, Optional, Tuple

__all__ = ["split_text", "count_tokens", "DEFAULT_MAX_TOKENS"]

DEFAULT_MAX_TOKENS = 512

# sentence terminators, including full-width Chinese punctuation
SENTENCE_END = re.compile(r"(?<=[。！？；!?;\n…])")
# preferred cut points inside an over-long sentence, best first
SOFT_BREAKS = ["，", "、", "：", ",", ":", " ", ""]


def count_tokens(text: str, tokenizer: Optional[Callable] = None) -> int:
    """Token count for `text`. Uses the tokenizer when given, else a safe over-estimate."""
    if not text:
        return 0
    if tokenizer is not None:
        try:
            enc = tokenizer(text)
            ids = getattr(enc, "input_ids", None)
            if ids is None and isinstance(enc, dict):
                ids = enc.get("input_ids")
            if ids is not None:
                # some tokenizers return [[...]] for a single string
                if ids and isinstance(ids[0], list):
                    ids = ids[0]
                return len(ids)
        except Exception:
            pass
    return _heuristic_count(text)


def _heuristic_count(text: str) -> int:
    cjk = sum(1 for ch in text if "\u4e00" <= ch <= "\u9fff")
    other = len(text) - cjk
    # CJK: about one token per character. Latin: about one per 3.5 chars. Over-estimate on purpose.
    return int(cjk + other / 3.0) + 1


def _bisect(sentence: str, max_tokens: int, tokenizer: Optional[Callable],
            depth: int = 0) -> List[str]:
    """Cut one over-long sentence into pieces that each fit."""
    if count_tokens(sentence, tokenizer) <= max_tokens:
        return [sentence]
    if depth > 12 or len(sentence) <= 1:
        return [sentence]          # give up splitting; caller will report an error

    mid = len(sentence) // 2
    # look for a soft break near the middle, searching outward
    best = None
    for radius in range(0, mid):
        for pos in (mid - radius, mid + radius):
            if 0 < pos < len(sentence):
                for mark in SOFT_BREAKS:
                    if mark and sentence[max(0, pos - len(mark)):pos] == mark:
                        best = pos
                        break
                if best is not None:
                    break
        if best is not None:
            break
    if best is None:
        best = mid

    left, right = sentence[:best], sentence[best:]
    if count_tokens(left, tokenizer) > max_tokens:
        return _bisect(left, max_tokens, tokenizer, depth + 1)
    return [left] + _bisect(right, max_tokens, tokenizer, depth + 1)


def split_text(text: str, max_tokens: int = DEFAULT_MAX_TOKENS,
               tokenizer: Optional[Callable] = None) -> List[Tuple[str, int]]:
    """Return [(chunk, token_count), ...] where every chunk is <= max_tokens.

    The token counts are what the caller should log; they make it obvious whether the splitter
    actually kept under budget.
    """
    if not text or not text.strip():
        return []

    sentences = [s for s in SENTENCE_END.split(text) if s]
    if not sentences:
        sentences = [text]

    # a single sentence longer than the budget gets bisected first
    expanded: List[str] = []
    for s in sentences:
        if count_tokens(s, tokenizer) > max_tokens:
            expanded.extend(_bisect(s, max_tokens, tokenizer))
        else:
            expanded.append(s)

    # then greedily merge neighbours while they still fit
    chunks: List[str] = []
    cur = ""
    for s in expanded:
        cand = cur + s
        if cur and count_tokens(cand, tokenizer) > max_tokens:
            chunks.append(cur)
            cur = s
        else:
            cur = cand
    if cur:
        chunks.append(cur)

    out: List[Tuple[str, int]] = []
    for c in chunks:
        if not c:
            continue
        out.append((c, count_tokens(c, tokenizer)))
    return out


def describe(chunks: List[Tuple[str, int]], max_tokens: int = DEFAULT_MAX_TOKENS) -> str:
    """One-line summary for logs and acceptance reports."""
    if not chunks:
        return "no chunks"
    over = [i for i, (_c, n) in enumerate(chunks) if n > max_tokens]
    total = sum(n for _c, n in chunks)
    return "chunks=%d total_tokens=%d max=%d limit=%d over_budget=%s" % (
        len(chunks), total, max(n for _c, n in chunks), max_tokens,
        over if over else "none",
    )
