content.arguments:
{"content": "// Smoke-test the sidecar: synth one sentence, validate RIFF, and report timing.
// Also dumps /health keys so we can see whether the NPU offload actually took effect.
const http = require('http');
const fs = require('fs');

function call(method, path, body, ms) {
  return new Promise((res) => {
    const payload = body ? JSON.stringify(body) : null;
    const r = http.request({
      host: '127.0.0.1', port: 17860, path, method,
      headers: Object.assign({ 'Content-Type': 'application/json' },
        payload ? { 'Content-Length': Buffer.byteLength(payload) } : {}),
    }, (x) => {
      const cs = [];
      x.on('data', (c) => cs.push(c));
      x.on('end', () => res({ code: x.statusCode, ctype: x.headers['content-type'], buf: Buffer.concat(cs) }));
    });
    r.on('error', (e) => res({ code: 0, err: String(e.message) }));
    r.setTimeout(ms || 300000, () => { r.destroy(); res({ code: 'timeout' }); });
    if (payload) r.write(payload);
    r.end();
  });
}

(async () => {
  const h = await call('GET', '/health', null, 30000);
  if (h.code === 200) {
    const j = JSON.parse(h.buf.toString('utf8'));
    console.log('=== health ===');
