{"command": "$ErrorActionPreference = 'Continue'
$js = @'
const https = require('https');
function get(u, ms) {
  return new Promise((res) => {
    const r = https.get(u, { headers: { 'User-Agent': 'dsh' } }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(get(new URL(x.headers.location, u).toString(), ms)); return; }
      let d = ''; x.on('data', (c) => d += c); x.on('end', () => res({ code: x.statusCode, body: d }));
    });
    r.on('error', (e) => res({ code: 0, body: String(e.message) }));
    r.setTimeout(ms || 25000, () => { r.destroy(); res({ code: 0, body: 'timeout' }); });
  });
}
(async () => {
  const S = ['http://fonts.googleapis.com', 'https://fonts.googleapis.com'].map((x) => x);
  const BASE = 'https://huggingface.co/api/models/';
  const MODELS = [
    'hexgrad/Kokoro-82M-v1.1-zh',
    'hexgrad/Kokoro-82M',
    'OpenVINO/Kokoro-82M-v1.1-zh-int8-ov',
    'OpenVINO/Kokoro-82M-v1.1-zh-fp16-ov',
    'OpenVINO/Kokoro-82M-int8-ov',
  ];
  for (const m of MODELS) {
    const r = await get(BASE + m);
    if (r.code === 200) {
      const j = JSON.parse(r.body);
      const sib = (j.siblings || []).map((s) => s.rfilename);
      console.log('  ' + m);
      console.log('      OK  files=' + sib.length + '  downloads=' + (j.downloads || 0) + '  likes=' + (j.likes || 0));
      const interesting = sib.filter((f) => /\.(json|bin|xml|pth|onnx|txt)$/i.test(f)).slice(0, 14);
      console.log('      ' + interesting.join(', '));
    } else {
      console.log('  ' + m + '  -> HTTP ' + r.code);
    }
  }
})();
