const https = require('https');
const fs = require('fs');
const path = require('path');
function dl(u, out, ms) {
  return new Promise((res) => {
    const r = https.get(u, { headers: { 'User-Agent': 'dsh' } }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(dl(new URL(x.headers.location, u).toString(), out, ms)); return; }
      if (x.statusCode !== 200) { x.resume(); res({ ok: false, code: x.statusCode }); return; }
      const ws = fs.createWriteStream(out);
      let n = 0;
      x.on('data', (c) => { n += c.length; });
      x.pipe(ws);
      ws.on('finish', () => res({ ok: true, size: n }));
      x.on('error', (e) => res({ ok: false, err: String(e.message) }));
    });
    r.on('error', (e) => res({ ok: false, err: String(e.message).slice(0, 60) }));
    r.setTimeout(ms || 120000, () => { r.destroy(); res({ ok: false, err: 'timeout' }); });
  });
}
(async () => {
  const BASE = 'https://gh-proxy.com/https://raw.githubusercontent.com/openvinotoolkit/openvino_notebooks/latest/notebooks/omnivoice/';
  const OUT = 'D:\\AI_file\\build\\omnivoice';
  for (const f of ['README.md', 'omnivoice_helper.py', 'gradio_helper.py']) {
    const dest = path.join(OUT, f);
    const r = await dl(BASE + f, dest);
    console.log('  ' + f.padEnd(24) + (r.ok ? ('OK  ' + r.size + ' B') : ('FAIL ' + (r.err || r.code))));
  }
  console.log('');
  console.log('  files now:');
  for (const f of fs.readdirSync(OUT)) {
    const p = path.join(OUT, f);
    if (fs.statSync(p).isFile()) console.log('    ' + f.padEnd(28) + fs.statSync(p).size + ' B');
  }
})();
