content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
$js = @'
const https = require('https');
function probe(u, ms) {
  const t0 = Date.now();
  return new Promise((res) => {
    const req = https.get(u, { headers: { 'User-Agent': 'dsh', Range: 'bytes=0-1048575' } }, (x) => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(probe(new URL(x.headers.location, u).toString(), ms)); return; }
      let got = 0;
      x.on('data', (c) => { got += c.length; if (got >= 1048576) x.destroy(); });
      x.on('close', () => res({ code: x.statusCode, got, ms: Date.now() - t0 }));
      x.on('end', () => res({ code: x.statusCode, got, ms: Date.now() - t0 }));
    });
    req.on('error', (e) => res({ code: 0, err: String(e.code || e.message).slice(0, 30), got: 0, ms: Date.now() - t0 }));
    req.setTimeout(ms, () => { req.destroy(); res({ code: 'timeout', got: 0, ms: Date.now() - t0 }); });
  });
}
(async () => {
  const F = 'k2-fsa/OmniVoice/resolve/main/model.safetensors';
  for (const [l, b] of [['hf direct ', 'https://huggingface.co'], ['hf-mirror ', 'https://hf-mirror.com']]) {
    const r = await probe(b + '/' + F, 25000);
    const kbs = r.got ? (r.got / 1024 / (r.ms / 1000)).toFixed(0) : '-';
    console.log('  ' + l + ' HTTP ' + String(r.code).padEnd(10) + (r.err || ((r.got/1048576).toFixed(2) + ' MB / ' + (r.ms/1000).toFixed(1) + 's')) + '  ' + kbs + ' KB/s');
  }
})();
'@
& 'D:\program_runtime_environment\nodejs\node.exe' -e $js 2>&1 | ForEach-Object { Write-Output $_ }
Write-Output ''
Write-Output '=== install hf_xet for Xet storage ==='
& 'D:\AI_file\envs\openvino\Scripts\uv.exe' pip install --python 'D:\AI_file\envs\tts-export\Scripts\python.exe' --quiet hf_xet 2>&1 | Select-Object -Last 5 | ForEach-Object { Write-Output ('  ' + $_) }
Write-Output ('  exit: ' + $LASTEXITCODE)", "description": "Probe HF speed and install hf_xet", "timeoutMs": 300000}

