{"command": "$ErrorActionPreference = 'Continue'
Write-Output '=== kill stuck xet download ==='
Get-CimInstance Win32_Process -Filter "Name='python.exe'" -ErrorAction SilentlyContinue | Where-Object { $_.CommandLine -match 'pull-omnivoice' } | ForEach-Object {
    Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue
    Write-Output ('  killed ' + $_.ProcessId)
}
Start-Sleep -Seconds 3
Write-Output ''
Write-Output '=== list the repo files we actually need ==='
$js = @'
const https = require('https');
function get(u, ms) { return new Promise((res) => { const r = https.get(u, { headers: { 'User-Agent': 'dsh' } }, (x) => { if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); res(get(new URL(x.headers.location, u).toString(), ms)); return; } let d=''; x.on('data',(c)=>d+=c); x.on('end',()=>res({code:x.statusCode,body:d})); }); r.on('error',(e)=>res({code:0,body:String(e.message)})); r.setTimeout(ms||25000,()=>{r.destroy();res({code:0,body:'timeout'})}); }); }
(async () => {
  const r = await get('https://hf-mirror.com/api/models/k2-fsa/OmniVoice/tree/main?recursive=true');
  if (r.code !== 200) { console.log('  HTTP ' + r.code); return; }
  const arr = JSON.parse(r.body);
  let total = 0;
  for (const f of arr) {
    if (f.type !== 'file' || !f.size) continue;
    total += f.size;
    console.log('  ' + (f.size/1048576).toFixed(1).padStart(9) + ' MB  ' + f.path);
  }
  console.log('  ---');
  console.log('  TOTAL ' + (total/1073741824).toFixed(2) + ' GB  (' + arr.filter(f=>f.type==='file').length + ' files)');
})();
'@
& 'D:\program_runtime_environment\nodejs\node.exe' -e $js 2>&1 | ForEach-Object { Write-Output $_ }", "description": "Kill stalled download and list repo files", "timeoutMs": 300000}

