content.arguments:
{"content": """"Generic segmented HuggingFace file downloader.

Built because hf_xet stalled at 628 MB with the xet cache sitting empty, and plain HTTP gave
120-150 KB/s. This is the same strategy that took Qwen3-TTS from 4 KB/s to 2.5 MB/s: never hold
a connection long, split each file into 8 MB ranges, run a few concurrently, retry each range
independently, and keep per-segment progress so an interrupted run resumes exactly.

Preserves subdirectories (audio_tokenizer/model.safetensors lands in its own folder).

Usage:
    python pull-hf-segmented.py <repo_id> <dest_dir> [--include substring] [--exclude substring]
"""
import argparse
import io
import json
import os
import ssl
import sys
import threading
import time
import urllib.request

SEG = 8 * 1024 * 1024
CONCURRENCY = 4
SEG_TIMEOUT = 90
SEG_RETRIES = 8
MIRRORS = ["https://hf-mirror.com", "https://huggingface.co"]
LOG = r"D:\AI_file\logs\hf-segmented.log"

ctx = ssl.create_default_context()
_lock = threading.Lock()


def log(msg):
    line = time.strftime("%H:%M:%S ") + msg
    with _lock:
        print(line, flush=True)
        try:
            os.makedirs(os.path.dirname(LOG), exist_ok=True)
            with io.open(LOG, "a", encoding="utf-8") as f:
                f.write(line + "\n")
        except Exception:
            pass


def human(n):
    for u in ("B", "KB", "MB", "GB"):
        if n < 1024:
            return "%.1f %s" % (n, u)
        n /= 1024.0
    return "%.1f TB" % n


def http_get(url, headers=None, timeout=60):
    req = urllib.request.Request(url, headers=headers or {})
    req.add_header("User-Agent", "dsh-seg/1.0")
    return urllib.request.urlopen(req, timeout=timeout, context=ctx)


def list_tree(repo):
    last = None
    for base in MIRRORS:
        try:
            with http_get("%s/api/models/%s/tree/main?recursive=true" % (base, repo), timeout=40) as r:
                return json.loads(r.read().decode("utf-8"))
        except Exception as e:
            last = e
            log("  tree via %s failed: %s" % (base, str(e)[:60]))
    raise RuntimeError("cannot list tree: %s" % last)


def fetch_seg(repo, rel, idx, start, end, part):
    want = end - start + 1
    for attempt in range(1, SEG_RETRIES + 1):
        have = os.path.getsize(part) if os.path.exists(part) else 0
        if have >= want:
            return True
        if have > want:
            os.remove(part)
            have = 0
        base = MIRRORS[(idx + attempt) % len(MIRRORS)]
        url = "%s/%s/resolve/main/%s" % (base, repo, rel)
        try:
            with http_get(url, {"Range": "bytes=%d-%d" % (start + have, end)}, SEG_TIMEOUT) as r:
                written = have
                with io.open(part, "ab") as f:
                    while True:
                        c = r.read(64 * 1024)
                        if not c:
                            break
                        room = want - written
                        if room <= 0:
                            break
                        piece = c if len(c) <= room else c[:room]
                        f.write(piece)
                        written += len(piece)
            if os.path.getsize(part) >= want - 2:
                return True
        except Exception as e:
            if attempt <= 2:
                log("    seg%03d a%d: %s" % (idx, attempt, str(e)[:55]))
            time.sleep(1.5 * attempt)
    return False


def pull(repo, rel, total, dest):
    os.makedirs(os.path.dirname(dest) or ".", exist_ok=True)
    if os.path.exists(dest) and abs(os.path.getsize(dest) - total) <= 2:
        log("  [skip] %s" % rel)
        return True
    nseg = (total + SEG - 1) // SEG
    parts = [dest + ".seg%03d" % i for i in range(nseg)]
    todo = []
    for i in range(nseg):
        s = i * SEG
        e = min(total - 1, s + SEG - 1)
        w = e - s + 1
        h = os.path.getsize(parts[i]) if os.path.exists(parts[i]) else 0
        if h < w - 2:
            todo.append((i, s, e))
    log("  [start] %s  %s  segs=%d need=%d" % (rel, human(total), nseg, len(todo)))
    if todo:
        q = list(todo)
        done = [nseg - len(todo)]
        failed = []

        def worker():
            while True:
                with _lock:
                    if not q:
                        return
                    it = q.pop(0)
                ok = fetch_seg(repo, rel, it[0], it[1], it[2], parts[it[0]])
                with _lock:
                    if ok:
                        done[0] += 1
                        if done[0] % 5 == 0 or done[0] == nseg:
                            log("    %s %d/%d (%.0f%%)" % (rel, done[0], nseg, done[0] * 100.0 / nseg))
                    else:
                        failed.append(it[0])

        ts = [threading.Thread(target=worker, daemon=True) for _ in range(CONCURRENCY)]
        for t in ts:
            t.start()
        for t in ts:
            t.join()
        if failed:
            log("  [fail] %s incomplete segs %s" % (rel, failed[:8]))
            return False
    tmp = dest + ".merging"
    with io.open(tmp, "wb") as out:
        for p in parts:
            with io.open(p, "rb") as f:
                while True:
                    c = f.read(1024 * 1024)
                    if not c:
                        break
                    out.write(c)
    size = os.path.getsize(tmp)
    if size != total:
        log("  [fail] %s merged %s != %s" % (rel, human(size), human(total)))
        os.remove(tmp)
        return False
    if os.path.exists(dest):
        os.remove(dest)
    os.rename(tmp, dest)
    for p in parts:
        try:
            os.remove(p)
        except Exception:
