Why: on this link, huggingface.co stalls on multi-GB files (both plain HTTP and hf_xet froze
at 628 MB / 74.9 MB), while modelscope.cn answers in a few hundred ms. ModelScope hosts an
exact mirror of k2-fsa/OmniVoice, so pull it from there instead.

ModelScope endpoints used:
  list : /api/v1/models/<owner>/<name>/repo/files?Revision=master[&Root=<dir>]
  file : /api/v1/models/<owner>/<name>/repo?Revision=master&FilePath=<path>

Range requests are attempted; if the server ignores Range (returns 200 with the whole body),
the script falls back to a single streamed download for that file.

Usage: python pull-modelscope-segmented.py <owner/name> <dest_dir>
"""
import argparse
import io
import json
import os
import ssl
import sys
import threading
import time
import urllib.request

SEG = 8 * 1024 * 1024
CONCURRENCY = 4
SEG_TIMEOUT = 120
SEG_RETRIES = 8
BASE = "https://modelscope.cn"
LOG = r"D:\AI_file\logs\modelscope-segmented.log"

ctx = ssl.create_default_context()
_lock = threading.Lock()


def log(msg):
    line = time.strftime("%H:%M:%S ") + msg
    with _lock:
        print(line, flush=True)
        try:
            os.makedirs(os.path.dirname(LOG), exist_ok=True)
            with io.open(LOG, "a", encoding="utf-8") as f:
                f.write(line + "\n")
        except Exception:
            pass


def human(n):
    for u in ("B", "KB", "MB", "GB"):
        if n < 1024:
            return "%.1f %s" % (n, u)
        n /= 1024.0
    return "%.1f TB" % n


def http_get(url, headers=None, timeout=60):
    req = urllib.request.Request(url, headers=headers or {})
    req.add_header("User-Agent", "dsh-ms/1.0")
    return urllib.request.urlopen(req, timeout=timeout, context=ctx)


def list_dir(model, root=""):
    url = "%s/api/v1/models/%s/repo/files?Revision=master" % (BASE, model)
    if root:
        url += "&Root=" + urllib.parse.quote(root)
    with http_get(url, timeout=40) as r:
        j = json.loads(r.read().decode("utf-8"))
    data = j.get("Data") or {}
    return data.get("Files") or []


def walk(model, root=""):
    """Yield (path, size) for every file, recursing into directories."""
    entries = list_dir(model, root)
    for e in entries:
        name = e.get("Path") or e.get("Name") or ""
        # ModelScope puts full paths in Path; normalise to relative
        rel = name[len(root) + 1:] if root and name.startswith(root + "/") else name
        typ = e.get("Type")
        size = e.get("Size") or 0
        if typ == "tree":
            for item in walk(model, name):
                yield item
        elif size:
            yield (name, size)


def file_url(model, path):
    return "%s/api/v1/models/%s/repo?Revision=master&FilePath=%s" % (
        BASE, model, urllib.parse.quote(path))


def fetch_seg(model, rel, idx, start, end, part):
    want = end - start + 1
    for attempt in range(1, SEG_RETRIES + 1):
        have = os.path.getsize(part) if os.path.exists(part) else 0
        if have >= want:
            return True
        if have > want:
            os.remove(part)
            have = 0
        try:
            with http_get(file_url(model, rel),
                          {"Range": "bytes=%d-%d" % (start + have, end)}, SEG_TIMEOUT) as r:
                written = have
                with io.open(part, "ab") as f:
                    while True:
                        c = r.read(64 * 1024)
                        if not c:
                            break
                        room = want - written
                        if room <= 0:
                            break
                        piece = c if len(c) <= room else c[:room]
                        f.write(piece)
                        written += len(piece)
            got = os.path.getsize(part)
            if got >= want - 2:
                return True
        except Exception as e:
            if attempt <= 2:
                log("    seg%03d a%d: %s" % (idx, attempt, str(e)[:55]))
            time.sleep(1.5 * attempt)
    return False


def pull_whole(model, rel, total, dest):
    """Fallback when Range is ignored: one streamed GET."""
    tmp = dest + ".whole"
    for attempt in range(1, 6):
        try:
            with http_get(file_url(model, rel), None, 300) as r:
                written = 0
                with io.open(tmp, "wb") as f:
                    while True:
                        c = r.read(1024 * 1024)
                        if not c:
                            break
                        f.write(c)
                        written += len(c)
            if written >= total - 2:
                if os.path.exists(dest):
                    os.remove(dest)
                os.rename(tmp, dest)
                log("  [done whole] %s %s" % (rel, human(written)))
                return True
            log("  whole attempt %d got %s of %s" % (attempt, human(written), human(total)))
        except Exception as e:
            log("  whole attempt %d: %s" % (attempt, str(e)[:60]))
            time.sleep(3 * attempt)
    return False


def pull(model, rel, total, dest):
    os.makedirs(os.path.dirname(dest) or ".", exist_ok=True)
    if os.path.exists(dest) and abs(os.path.getsize(dest) - total) <= 2:
        log("  [skip] %s" % rel)
        return True
    nseg = (total + SEG - 1) // SEG
    parts = [dest + ".seg%03d" % i for i in range(nseg)]
    todo = []
    for i in range(nseg):
        s = i * SEG
        e = min(total - 1, s + SEG - 1)
        w = e - s + 1
        h = os.path.getsize(parts[i]) if os.path.exists(parts[i]) else 0
        if h < w - 2:
            todo.append((i, s, e))
    log("  [start] %s  %s  segs=%d need=%d" % (rel, human(total), nseg, len(todo)))
    if todo:
        q = list(todo)
        done = [nseg - len(todo)]
        failed = []

        def worker():
            while True:
                with _lock:
                    if not q:
                        return
                    it = q.pop(0)
                ok = fetch_seg(model, rel, it[0], it[1], it[2], parts[it[0]])
                with _lock:
                    if ok:
                        done[0] += 1
                        if done[0] % 5 == 0 or done[0] == nseg:
                            log("    %s %d/%d (%.0f%%)" % (rel, done[0], nseg, done[0] * 100.0 / nseg))
                    else:
                        failed.append(it[0])

        ts = [threading.Thread(target=worker, daemon=True) for _ in range(CONCURRENCY)]
        for t in ts:
            t.start()
        for t in ts:
            t.join()
        if failed:
            log("  [fail] %s segs %s -> trying whole-file fallback" % (rel, failed[:6]))
            for p in parts:
                try:
                    os.remove(p)
                except Exception:
                    pass
            return pull_whole(model, rel, total, dest)
    tmp = dest + ".merging"
    with io.open(tmp, "wb") as out:
        for p in parts:
            if not os.path.exists(p):
                log("  [fail] %s missing part %s" % (rel, os.path.basename(p)))
                return False
            with io.open(p, "rb") as f:
                while True:
                    c = f.read(1024 * 1024)
                    if not c:
                        break
                    out.write(c)
    size = os.path.getsize(tmp)
    if size != total:
        log("  [fail] %s merged %s != %s" % (rel, human(size), human(total)))
        os.remove(tmp)
        return False
    if os.path.exists(dest):
        os.remove(dest)
    os.rename(tmp, dest)
    for p in parts:
        try:
            os.remove(p)
        except Exception:
            pass
    log("  [done] %s %s" % (rel, human(size)))
    return True


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("model")
    ap.add_argument("dest")
    args = ap.parse_args()

    log("=== modelscope pull %s -> %s" % (args.model, args.dest))
    files = list(walk(args.model))
    total = sum(s for _, s in files)
    log("  files=%d total=%s" % (len(files), human(total)))
    ok = 0
    for rel, sz in sorted(files, key=lambda x: -x[1]):
        dest = os.path.join(args.dest, *rel.split("/"))
        try:
            if pull(args.model, rel, sz, dest):
                ok += 1
        except Exception as e:
            log("  [fatal] %s: %s" % (rel, e))
    log("=== %d/%d complete ===" % (ok, len(files)))
    return 0 if ok == len(files) else 1


if __name__ == "__main__":
    import urllib.parse  # noqa: E402  (used inside helpers)
    sys.exit(main())
