{"command": "$ErrorActionPreference = 'Continue'
$b = 'D:\AI_file\build\omnivoice\pt_models\OmniVoice'
Write-Output ('=== ' + (Get-Date).ToString('HH:mm:ss') + ' ===')
$a = 0; Get-ChildItem -LiteralPath $b -Recurse -File -Force -ErrorAction SilentlyContinue | ForEach-Object { $a += $_.Length }
Start-Sleep -Seconds 30
$c = 0; Get-ChildItem -LiteralPath $b -Recurse -File -Force -ErrorAction SilentlyContinue | ForEach-Object { $c += $_.Length }
$kbs = ($c - $a) / 1KB / 30
Write-Output ('  当前: ' + [Math]::Round($c/1MB,1) + ' MB / 3113 MB  (' + [Math]::Round($c/1MB/31.13,1) + '%)')
Write-Output ('  30s 增量: ' + [Math]::Round(($c-$a)/1MB,2) + ' MB  =>  ' + [Math]::Round($kbs,0) + ' KB/s')
if ($kbs -gt 10) {
    Write-Output ('  剩余时间: ' + [Math]::Round((3113 - $c/1MB) / ($kbs/1024), 1) + ' 分钟')
} else {
    Write-Output '  下载似乎停滞'
}
Write-Output ''
Write-Output '  日志尾:'
Get-Content -LiteralPath 'D:\AI_file\logs\modelscope-segmented.log' -Encoding UTF8 -Tail 6 -ErrorAction SilentlyContinue | ForEach-Object { Write-Output ('    ' + $_) }
Write-Output ''
Write-Output ('  proc: ' + @(Get-CimInstance Win32_Process -Filter "Name='python.exe'" -ErrorAction SilentlyContinue | Where-Object { $_.CommandLine -match 'pull-modelscope' }).Count)", "description": "Check download speed after VPN off", "timeoutMs": 300000}

