{"command": "$ErrorActionPreference = 'Continue'
$b = 'D:\AI_file\build\omnivoice\pt_models\OmniVoice'
Write-Output '=== 权重完整性检查 ==='
foreach ($p in 'model.safetensors', 'audio_tokenizer\model.safetensors') {
    $full = Join-Path $b $p
    if (Test-Path -LiteralPath $full) {
        Write-Output ('  ' + $p.PadRight(38) + 'OK  ' + [Math]::Round((Get-Item $full).Length/1MB,1) + ' MB')
    } else {
        Write-Output ('  ' + $p.PadRight(38) + 'MISSING')
    }
}
Write-Output ''
Write-Output '=== 小文件 ==='
foreach ($p in 'config.json', 'tokenizer.json', 'tokenizer_config.json', 'chat_template.jinja', 'audio_tokenizer\config.json') {
    $full = Join-Path $b $p
    Write-Output ('  ' + $p.PadRight(38) + $(if (Test-Path -LiteralPath $full) { 'OK' } else { 'MISSING' }))
}
Write-Output ''
Write-Output '=== 残留临时文件 ==='
Get-ChildItem -LiteralPath $b -Recurse -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '\.stream$|\.seg\d+$|\.merging$' } | ForEach-Object { Write-Output ('  ' + $_.Name + '  ' + [Math]::Round($_.Length/1MB,1) + ' MB') }
Write-Output ''
Write-Output ('  总大小: ' + [Math]::Round((((Get-ChildItem -LiteralPath $b -Recurse -File -Force -ErrorAction SilentlyContinue) | Measure-Object -Property Length -Sum).Sum)/1MB,1) + ' MB')", "description": "Verify OmniVoice weights are complete", "timeoutMs": 180000}

