content.arguments:
{"command": "$ErrorActionPreference = 'Continue'
Write-Output '=== Qwen TTS 服务状态 ==='
Write-Output ('  process: ' + @(Get-Process -Name 'qwen3-tts-ov-server' -ErrorAction SilentlyContinue).Count)
Write-Output ('  port 17860: ' + (Test-NetConnection -ComputerName '127.0.0.1' -Port 17860 -InformationLevel Quiet -WarningAction SilentlyContinue))
Write-Output ''
$js = @'
const http = require('http');
function call(method, path, body, ms) {
  return new Promise((res) => {
    const payload = body ? JSON.stringify(body) : null;
    const r = http.request({ host: '127.0.0.1', port: 17860, path, method, headers: Object.assign({ 'Content-Type': 'application/json' }, payload ? { 'Content-Length': Buffer.byteLength(payload) } : {}) }, (x) => {
      const cs = []; x.on('data', (c) => cs.push(c));
      x.on('end', () => res({ code: x.statusCode, ctype: x.headers['content-type'], buf: Buffer.concat(cs) }));
    });
    r.on('error', (e) => res({ code: 0, err: String(e.message) }));
    r.setTimeout(ms || 20000, () => { r.destroy(); res({ code: 'timeout' }); });
    if (payload) r.write(payload); r.end();
  });
}
(async () => {
  const h = await call('GET', '/health', null, 20000);
  if (h.code === 200) {
    const j = JSON.parse(h.buf.toString('utf8'));
    console.log('  health ok=' + j.ok + '  warmup=' + (j.warmup||{}).status);
    console.log('  model_root=' + String(j.model_root || '').slice(-55));
  } else console.log('  health HTTP ' + h.code);
  const m = await call('GET', '/v1/models', null, 20000);
  if (m.code === 200) {
    const j = JSON.parse(m.buf.toString('utf8'));
    for (const [k, v] of Object.entries(j.available_modes || {})) {
      console.log('  ' + k.padEnd(14) + 'available=' + String(v.available));
    }
  }
  const v = await call('GET', '/v1/audio/voices', null, 20000);
  if (v.code === 200) {
    const j = JSON.parse(v.buf.toString('utf8'));
    console.log('  voices: ' + JSON.stringify(j.voices || []).slice(0, 120));
  }
})();
'@
& 'D:\program_runtime_environment\nodejs\node.exe' -e $js 2>&1 | ForEach-Object { Write-Output $_ }", "description": "Check Qwen TTS service status and capabilities", "timeoutMs": 300000}

